#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

#define UE_CONN_STATUS_SIZE 1024
#define TTL_DEFAULT 3600
#define RESIZE_FACTOR 2
#define NUM_THREADS 4

typedef struct {
    pthread_mutex_t mutex;
    pthread_cond_t cond;
    size_t capacity;
    size_t size;
    UEConnectionStatus* connections;
} ConnectionManager;

void connection_manager_init(ConnectionManager* cm, size_t initial_capacity) {
    cm->capacity = initial_capacity;
    cm->size = 0;
    cm->connections = malloc(UE_CONN_STATUS_SIZE * cm->capacity);
    pthread_mutex_init(&cm->mutex, NULL);
    pthread_cond_init(&cm->cond, NULL);
}

void connection_manager_insert(ConnectionManager* cm, UEConnectionStatus status) {
    pthread_mutex_lock(&cm->mutex);
    if (cm->size >= cm->capacity) {
        // Evict outdated entries
        size_t evicted = 0;
        for (int i = 0; i < cm->size; i++) {
            if (status.timestamp - cm->connections[i].timestamp > TTL_DEFAULT) {
                memmove(&cm->connections[i], &cm->connections[i + 1], UE_CONN_STATUS_SIZE * (cm->size - i - 1));
                evicted++;
                i--;
            }
        }
        cm->size -= evicted;
    }
    if (cm->size < cm->capacity) {
        cm->connections[cm->size++] = status;
    } else {
        // Resize connections array
        size_t new_capacity = cm->capacity * RESIZE_FACTOR;
        UEConnectionStatus* new_connections = realloc(cm->connections, UE_CONN_STATUS_SIZE * new_capacity);
        if (new_connections == NULL) {
            // Handle out-of-memory error
            perror("connection_manager_insert");
            exit(1);
        }
        cm->connections = new_connections;
        cm->capacity = new_capacity;
    }
    pthread_mutex_unlock(&cm->mutex);
}

void connection_manager_remove(ConnectionManager* cm, size_t index) {
    pthread_mutex_lock(&cm->mutex);
    if (index < cm->size) {
        memmove(&cm->connections[index], &cm->connections[index + 1], UE_CONN_STATUS_SIZE * (cm->size - index - 1));
        cm->size--;
    }
    pthread_mutex_unlock(&cm->mutex);
}

void connection_manager_evict(ConnectionManager* cm) {
    pthread_mutex_lock(&cm->mutex);
    size_t evicted = 0;
    for (int i = 0; i < cm->size; i++) {
        if (cm->connections[i].timestamp + TTL_DEFAULT < time(NULL)) {
            memmove(&cm->connections[i], &cm->connections[i + 1], UE_CONN_STATUS_SIZE * (cm->size - i - 1));
            evicted++;
            i--;
        }
    }
    cm->size -= evicted;
    pthread_mutex_unlock(&cm->mutex);
}

void connection_manager_close(ConnectionManager* cm) {
    free(cm->connections);
    pthread_mutex_destroy(&cm->mutex);
    pthread_cond_destroy(&cm->cond);
}

ConnectionManager connection_manager = connection_manager_init();

int main() {
    // Initialize and start periodic updates from external data source
    // ...
    return 0;
}
