class WeatherService {
public:
    WeatherService(int cacheExpirationHours, int refreshIntervalMinutes)
        : cacheExpiration_(cacheExpirationHours * 3600),
          refreshInterval_(refreshIntervalMinutes * 60),
          cache_(std::chrono::steady_clock::now(), std::chrono::hours(cacheExpiration_)),
          retryPolicy_(new ExponentialRetryPolicy()) {}

    void setCachedData(const std::string& location, const std::string& data) {
        auto it = cache_.find(location);
        if (it != cache_.end()) {
            it->second = data;
        } else {
            cache_[location] = data;
        }
    }

    std::optional<std::string> getWeatherData(const std::string& location, const std::string& unit) {
        auto& cachedData = getCachedData(location);
        if (cachedData.has_value()) {
            return cachedData;
        }

        try {
            // Fetch data from APIs
            auto data = fetchWeatherDataFromAPIs(location, unit);

            // Cache the fetched data
            setCachedData(location, data);

            return data;
        } catch (const std::exception& e) {
            // Retry with exponential backoff
            retryPolicy_->retry([this, location]() {
                getWeatherData(location, unit);
            });
        }
    }

private:
    int cacheExpiration_;
    int refreshInterval_;
    std::map<std::string, std::string> cache_;
    std::unique_ptr<ExponentialRetryPolicy> retryPolicy_;

    std::optional<std::string> getCachedData(const std::string& location) {
        auto it = cache_.find(location);
        if (it != cache_.end()) {
            return it->second;
        }
        return std::nullopt;
    }

    std::string fetchWeatherDataFromAPIs(const std::string& location, const std::string& unit) {
        // Implement API calls and error handling
    }
};

class ExponentialRetryPolicy {
public:
    void retry(std::function<void()> action) {
        int retries = 0;
        while (retries < 3) {
            try {
                action();
                break;
            } catch (const std::exception& e) {
                if (retries >= 2) {
                    throw; // Max retries reached, re-throw exception
                }
                std::this_thread::sleep_for(std::chrono::milliseconds(100 * (1 << retries)));
                retries++;
            }
        }
    }
};

int main() {
    WeatherService service(24, 30);
    // Use the weather service to fetch data and cache it
    return 0;
}
