// Define log levels
enum LogLevel {
    INFO,
    WARNING,
    ERROR,
    DEBUG
};

// Define log destinations
typedef enum {
    CONSOLE,
    FILE,
    REMOTE_SERVER
} LogDestination;

// Structure to represent a log destination
typedef struct {
    LogDestination type;
    char* filename; // for file logging only
    int remote_server_port; // for remote server logging only
} LogDest;

// Structure to represent a log level configuration
typedef struct {
    enum LogLevel level;
    char* format; // for console and file logging
    char* send_to; // for remote server logging
} LogLevelConf;

// Structure to represent the logging framework state
typedef struct {
    pthread_mutex_t lock; // for thread safety
    int log_level;
    LogDest* dests;
    int num_dests;
    LogLevelConf* level_cons;
    int num_level_cons;
} LogFrameworkState;

// Initialize the logging framework state
void init_log_framework(LogFrameworkState* state) {
    pthread_mutex_init(&state->lock, NULL);
    state->log_level = INFO;
    state->num_dests = 0;
    state->dests = NULL;
    state->num_level_cons = 0;
    state->level_cons = NULL;
}

// Add a log destination
void add_log_destination(LogFrameworkState* state, LogDest* dest) {
    pthread_mutex_lock(&state->lock);
    state->dests = realloc(state->dests, (state->num_dests + 1) * sizeof(LogDest));
    state->dests[state->num_dests] = *dest;
    state->num_dests++;
    pthread_mutex_unlock(&state->lock);
}

// Add a log level configuration
void add_log_level_conf(LogFrameworkState* state, LogLevelConf* conf) {
    pthread_mutex_lock(&state->lock);
    state->level_cons = realloc(state->level_cons, (state->num_level_cons + 1) * sizeof(LogLevelConf));
    state->level_cons[state->num_level_cons] = *conf;
    state->num_level_cons++;
    pthread_mutex_unlock(&state->lock);
}

// Log a message
void log_message(LogFrameworkState* state, enum LogLevel level, const char* format, ...) {
    pthread_mutex_lock(&state->lock);
    // Check if the log level is enabled for this destination
    for (int i = 0; i < state->num_dests; i++) {
        switch (state->dests[i].type) {
            case CONSOLE:
                if (level >= state->log_level && format) {
                    va_list ap;
                    va_start(ap, format);
                    vprintf(format, ap);
                    va_end(ap);
                }
                break;
            case FILE:
                // implement file logging
                break;
            case REMOTE_SERVER:
                // implement remote server logging
                break;
        }
    }
    pthread_mutex_unlock(&state->lock);
}

int main() {
    LogFrameworkState state;
    init_log_framework(&state);

    add_log_destination(&state, &(LogDest){.type = CONSOLE});
    add_log_level_conf(&state, &(LogLevelConf){.level = INFO, .format = "INFO: %s"});

    log_message(&state, INFO, "Hello, world!");

    return 0;
}
