['```python
import hashlib
import os
import time
from concurrent.futures import ThreadPoolExecutor
from loguru import logger

class FileHasher:
    def __init__(self):
        self.md5_hash = hashlib.md5()
        self.sha256_hash = hashlib.sha256()

    def hash_file(self, file_path: str, chunk_size=1024*1024) -> tuple:
        try:
            with open(file_path, 'rb') as f:
                while chunk := f.read(chunk_size):
                    self.md5_hash.update(chunk)
                    self.sha256_hash.update(chunk)
                    yield self.get_partial_hashes()
        except OSError as e:
            logger.error(f"Error reading file: {e}")
            yield None

    def get_partial_hashes(self) -> tuple:
        return (self.md5_hash.hexdigest(), self.sha256_hash.hexdigest())

class HashingGenerator:
    def __init__(self, file_path: str, interval: int):
        self.file_path = file_path
        self.interval = interval
        self.hasher = FileHasher()

    def generate(self) -> tuple:
        for partial_hashes in self.hasher.hash_file(self.file_path):
            if partial_hashes is None:
                return None
            yield partial_hashes
            time.sleep(self.interval)

class LoggingHandler:
    def __init__(self, log_level: str):
        self.log_level = log_level

    def log_progress(self, message: str) -> None:
        logger.log(self.log_level, message)

def main():
    file_path = 'example_file.txt'
    interval = 10  # in seconds
    logging_handler = LoggingHandler('INFO')

    generator = HashingGenerator(file_path, interval)
    with ThreadPoolExecutor() as executor:
        futures = [executor.submit(generator.generate)]
        for future in futures:
            partial_hashes = future.result()
            if partial_hashes is None:
                logger.error("Hashing failed")
            else:
                logging_handler.log_progress(f"Partial hashes: {partial_hashes}")
            break

if __name__ == "__main__":
    main()

