#include <pthread.h>
#include <stdlib.h>
#include <stdio.h>
#include <string.h>

// Define the semaphore structure
typedef struct {
    pthread_mutex_t mutex;
    pthread_cond_t cond;
    int value;
} semaphore_t;

// Initialize the semaphore with the initial value and adjustments for resizing
semaphore_t* init_semaphore(int initial_value) {
    semaphore_t* sem = (semaphore_t*)malloc(sizeof(semaphore_t));
    if (!sem) return NULL; // Handle memory allocation failure

    pthread_mutex_init(&sem->mutex, NULL);
    pthread_cond_init(&sem->cond, NULL);

    sem->value = initial_value;

    return sem;
}

// Acquire the semaphore (decrement and wait if necessary)
void acquire_semaphore(semaphore_t* sem) {
    pthread_mutex_lock(&sem->mutex);
    while (sem->value <= 0) {
        pthread_cond_wait(&sem->cond, &sem->mutex);
    }
    sem->value--;
    pthread_mutex_unlock(&sem->mutex);
}

// Release the semaphore (increment and notify if necessary)
void release_semaphore(semaphore_t* sem) {
    pthread_mutex_lock(&sem->mutex);
    sem->value++;
    if (sem->value <= 0) {
        pthread_cond_signal(&sem->cond);
    }
    pthread_mutex_unlock(&sem->mutex);
}

// Resize the semaphore with a new initial value
void resize_semaphore(semaphore_t* sem, int new_value) {
    // Ensure thread safety during resizing
    pthread_mutex_lock(&sem->mutex);

    sem->value = new_value;

    // Adjust the condition variable to accommodate changes in the initial value
    if (new_value == 0) {
        pthread_cond_broadcast(&sem->cond);
    } else {
        pthread_cond_signal(&sem->cond);
    }

    pthread_mutex_unlock(&sem->mutex);
}

// Example usage: concurrently access a shared resource using the semaphore
void* shared_resource_thread(void* arg) {
    int id = *(int*)arg;
    for (int i = 0; i < 5; i++) {
        acquire_semaphore();
        printf("Thread %d acquired the semaphore, accessing shared resource.\n", id);
        // Simulate actual work
        sleep(1);
        release_semaphore();
    }
    return NULL;
}

// Example usage: dynamically configure and resize the semaphore
int main() {
    int initial_value = 5; // Initial value configured from environment variables or a centralized configuration service

    // Initialize the semaphore with the initial value
    semaphore_t* sem = init_semaphore(initial_value);

    if (!sem) return 1; // Handle initialization failure

    // Spawn multiple threads to concurrently access the shared resource
    pthread_t threads[5];
    int ids[] = {0, 1, 2, 3, 4};
    for (int i = 0; i < 5; i++) {
        pthread_create(&threads[i], NULL, shared_resource_thread, &ids[i]);
    }

    // Simulate resizing the semaphore
    sleep(10); // Wait for some time before resizing
    int new_value = initial_value + 2;
    resize_semaphore(sem, new_value);

    // Wait for all threads to finish
    for (int i = 0; i < 5; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}

