// Define the maximum number of retry attempts for logging
const int MAX_LOGGING_RETRIES = 3;

void logOrInsertDependency(std::forward_list<std::pair<std::string, std::string>>& moduleList, const std::string& targetModule, const std::string& statusMessage) {
    // Find the first occurrence of the target module in the list
    auto it = moduleList.begin();
    bool foundTarget = false;
    while (!foundTarget && it != moduleList.end()) {
        if (it->first == targetModule) {
            foundTarget = true;
        }
        ++it;
    }

    // If the target module is not found, insert at the end of the list
    if (!foundTarget) {
        moduleList.push_back({targetModule, statusMessage});
        return;
    }

    // Validate the dependency status before inserting or logging
    bool isValidStatus = validateDependencyStatus(statusMessage);
    if (!isValidStatus) {
        // Log the error and append the message with a retry failure notice
        logError("Invalid dependency status: %s", statusMessage.c_str());
        moduleList.push_back({targetModule, "ERROR: Invalid dependency status"});
        return;
    }

    // Insert the status message into the list immediately after the target module
    std::string errorMessage = "";
    for (auto& pair : moduleList) {
        if (pair.first == targetModule) {
            moduleList.insert_after(it, {targetModule, statusMessage});
            return;
        }
    }

    // Append the message with an error code if insertion fails
    logError("Failed to insert dependency: %s", statusMessage.c_str());
    moduleList.push_back({targetModule, "ERROR: Failed to insert dependency"});
}

// Helper function for logging errors using the external logging service
void logError(const char* format, ...) {
    va_list args;
    va_start(args, format);
    // Retry logging up to MAX_LOGGING_RETRIES times before appending with a retry failure notice
    int retries = 0;
    while (retries < MAX_LOGGING_RETRIES) {
        // Log the error using the external service
        // ...
        if (!logErrorUsingExternalService(format, args)) {
            break; // Retry failed, append message with retry failure notice
        }
        ++retries;
    }
    if (retries == MAX_LOGGING_RETRIES) {
        logError("Logging failed after %d retries: %s", format);
    }
    va_end(args);
}

