#include <iostream>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <atomic>
#include <vector>
#include <string>
#include <memory>

class RandomService {
public:
    RandomService() : masterSeed(1), generatorPool{}, logger{} {}

    void start() {
        // Initialize generators
        std::thread generatorThread([&] {
            while (true) {
                generateRandomNumbers();
                std::this_thread::sleep_for(std::chrono::milliseconds(10));
            }
        });

        // Start listening for requests
        listenForRequests();

        // Run forever
        while (true) {}
    }

private:
    void generateRandomNumbers() {
        // Get the current master seed
        auto masterSeedCopy = masterSeed.load();

        // Initialize new generators if needed
        std::vector<std::unique_ptr<MTGenerator>> newGenerators;
        for (auto& client : clients_) {
            auto clientId = client.first;
            auto partitionId = client.second.partitionId;

            // Derive a unique seed for each generator
            auto generatorSeed = deriveSeed(clientId, masterSeedCopy);

            // Initialize or update the corresponding generator
            if (partitionId < generators_.size()) {
                generators_[partitionId]->init(generatorSeed);
            } else {
                newGenerators.emplace_back(std::make_unique<MTGenerator>(generatorSeed));
                generators_.push_back(newGenerators.back().get());
            }
        }

        // Validate and synchronize the master seed
        validateMasterSeed();
    }

    void listenForRequests() {
        while (true) {
            // Accept incoming requests and handle them concurrently
            std::thread requestThread([&] {
                acceptRequest();
            });

            // Wait for the thread to finish before accepting another request
            requestThread.join();
        }
    }

    void acceptRequest() {
        // Receive a new client request with configuration parameters
        auto clientId = receiveClientId();

        // Initialize or update the corresponding generator(s)
        auto partitionId = derivePartitionId(clientId);

        if (partitionId < generators_.size()) {
            // Reuse an existing generator for this client
            generators_[partitionId]->updateConfig(clientId);
        } else {
            // Create a new generator for this client
            std::unique_ptr<MTGenerator> generator = std::make_unique<MTGenerator>(deriveSeed(clientId, masterSeed.load()));
            generators_.push_back(generator.get());
        }

        // Handle the request and generate random numbers as needed
        handleRequest(clientId);
    }

    void validateMasterSeed() {
        // Check if all generators have the same master seed
        for (auto& generator : generators_) {
            if (!generator->validateMasterSeed(masterSeed.load())) {
                // Synchronize the master seed across all generators
                synchronizeMasterSeed();
                break;
            }
        }
    }

    void synchronizeMasterSeed() {
        // Update the master seed across all generators
        for (auto& generator : generators_) {
            generator->setMasterSeed(masterSeed.load());
        }
    }

    std::atomic<uint64_t> masterSeed;

    std::vector<std::unique_ptr<MTGenerator>> generators_;
    std::unordered_map<int, int> clients_;

    Logger logger;
};
