public void ExecuteSecureQueryWithValidation(List<object> inputValues, string connectionString, string sqlCommand, Func<IEnumerable<dynamic>, Task> callback)
{
    if (inputValues.Count == 0) throw new ArgumentException("Input list is empty");
    foreach (var value in inputValues) ValidateInputType(value);
    if (!ValidateConnectionString(connectionString)) throw new ArgumentException("Invalid connection string");
    if (!ValidateSqlCommand(sqlCommand)) throw new ArgumentException("Invalid SQL command");
    if (callback == null) throw new ArgumentNullException(nameof(callback));

    try
    {
        using var connection = new SqlConnection(connectionString);
        connection.Open();

        var parameters = inputValues.Select((value, index) => new { @param = $"@p{index}", value }).ToDictionary(x => x.@param, x => x.value);

        var queryCommand = new SqlCommand(sqlCommand, connection);
        foreach (var parameter in parameters)
            queryCommand.Parameters.AddWithValue(parameter.Key, parameter.Value);

        using var reader = queryCommand.ExecuteReader();

        callback(reader.Select(r => r).ToListAsync());
    }
    catch (Exception ex) when (ShouldRetry(ex))
