using System.Linq;
using System.Threading;
using System.Xml;

namespace XmlParserComponent
{
    public class XmlParser
    {
        private readonly AmazonS3Client _s3Client;
        private readonly ConcurrentDictionary<string, XmlDocument> _xmlCache;
        private readonly object _lock = new object();
        private readonly IConfiguration _config;

        public XmlParser(IConfiguration config)
        {
            _s3Client = new AmazonS3Client(new NetCoreAmazonS3Config { });
            _xmlCache = new ConcurrentDictionary<string, XmlDocument>();
            _config = config;
        }

        public XmlDocument GetXmlDocument(string path)
        {
            string xmlPath = GetConfiguredPath(path);
            XmlDocument document;

            if (_xmlCache.TryGetValue(xmlPath, out document))
            {
                return document;
            }

            lock (_lock)
            {
                if (_xmlCache.TryGetValue(xmlPath, out document))
                {
                    return document;
                }

                try
                {
                    using (MemoryStream stream = new MemoryStream())
                    {
                        GetS3Object(xmlPath, stream);
                        XmlReader reader = XmlReader.Create(stream, new XmlReaderSettings { });
                        XmlDocument xmlDoc = new XmlDocument();
                        xmlDoc.Load(reader);

                        _xmlCache.AddOrUpdate(xmlPath, xmlDoc, (key, value) => value);
                        return xmlDoc;
                    }
                }
                catch (Exception ex)
                {
                    LogError(ex);
                    throw;
                }
            }
        }

        private string GetConfiguredPath(string path)
        {
            try
            {
                return _config["xmlPaths"][path];
            }
            catch (KeyNotFoundException)
            {
                return path;
            }
        }

        private void GetS3Object(string key, Stream stream)
        {
            try
            {
                using (GetObjectRequest request = new GetObjectRequest(key))
                {
                    using (GetObjectResponse response = _s3Client.GetObject(request))
                    {
                        response.ResponseStream.CopyTo(stream);
                    }
                }
            }
            catch (AmazonS3Exception ex)
            {
                LogError(ex);
                throw;
            }
        }

        private void LogError(Exception ex)
        {
            // Implement logging mechanism
            Console.WriteLine($"Error: {ex.Message}");
        }
    }
}
