import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.security.authentication.AuthenticationManager;
import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;
import org.springframework.security.core.AuthenticationException;
import org.springframework.security.oauth2.client.OAuth2Client;
import org.springframework.security.oauth2.client.OAuth2RestTemplate;
import org.springframework.web.bind.annotation.DeleteMapping;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RestController;

@RestController
public class ResourceController {

    private final AuthenticationManager authenticationManager;
    private final OAuth2Client oAuth2Client;
    private final ObjectMapper objectMapper;

    @Autowired
    public ResourceController(AuthenticationManager authenticationManager, OAuth2Client oAuth2Client, ObjectMapper objectMapper) {
        this.authenticationManager = authenticationManager;
        this.oAuth2Client = oAuth2Client;
        this.objectMapper = objectMapper;
    }

    @PutMapping("/resources/{uuid}")
    public ResponseEntity<String> updateResource(@RequestHeader(HttpHeaders.AUTHORIZATION) String auth,
                                                    @RequestHeader(value = "X-UUID", required = false) String uuid,
                                                    String resourceData) throws Exception {

        // Authenticate the request
        OAuth2RestTemplate restTemplate = oAuth2Client.getOAuth2RestTemplate();
        Authentication authentication = authenticationManager.authenticate(new UsernamePasswordAuthenticationToken("username", "password"));
        restTemplate.getAccessToken().setAuthentication(authentication);

        // Validate UUID format and check if resource exists in the system
        if (!isValidUUID(uuid)) {
            return ResponseEntity.status(HttpStatus.BAD_REQUEST).body("Invalid UUID");
        }

        // Update the resource using MD5 hashing for efficient processing
        String updatedResourceData = updateResourceData(resourceData);
        restTemplate.put("https://example.com/resources/{uuid}", updatedResourceData);

        return ResponseEntity.ok("Resource updated successfully");
    }

    @DeleteMapping("/resources/{uuid}")
    public ResponseEntity<String> deleteAndReplaceResource(@RequestHeader(HttpHeaders.AUTHORIZATION) String auth,
                                                            @RequestHeader(value = "X-UUID", required = false) String uuid) throws Exception {

        // Authenticate the request
        OAuth2RestTemplate restTemplate = oAuth2Client.getOAuth2RestTemplate();
        Authentication authentication = authenticationManager.authenticate(new UsernamePasswordAuthenticationToken("username", "password"));
        restTemplate.getAccessToken().setAuthentication(authentication);

        // Validate UUID format and check if resource exists in the system
        if (!isValidUUID(uuid)) {
            return ResponseEntity.status(HttpStatus.BAD_REQUEST).body("Invalid UUID");
        }

        // Delete the resource and replace it with a new one having default values
        deleteResource(restTemplate, uuid);
        String defaultResourceData = getDefaultResourceData();
        restTemplate.put("https://example.com/resources/{uuid}", defaultResourceData);

        return ResponseEntity.ok("Resource deleted and replaced successfully");
    }
}
