        private readonly IDatabaseService _databaseService;
        private readonly IRedisCache _redisCache;
        private readonly ILogger<UpdateController> _logger;

        public UpdateController(IHttpClientFactory httpClientFactory, IDatabaseService databaseService, IRedisCache redisCache, ILogger<UpdateController> logger)
        {
            _httpClientFactory = httpClientFactory;
            _databaseService = databaseService;
            _redisCache = redisCache;
            _logger = logger;
        }

        [HttpPost]
        public async Task<IActionResult> Update([FromQuery] int pageSectionId, [FromQuery] int elementId, [FromBody] string htmlContent)
        {
            try
            {
                // Fetch and validate HTML content from external data source using database service
                var validationResult = await _databaseService.ValidateHtmlContent(htmlContent);

                if (!validationResult.IsValid)
                    return BadRequest(new { message = "Invalid HTML content" });

                // Update specific element on the page using Redis caching for optimal performance
                await _redisCache.SetAsync($"page:{pageSectionId}:{elementId}", htmlContent);

                // Cache the updated HTML content for future updates
                await _redisCache.SetAsync($"page:{pageSectionId}:cache", htmlContent);

                return Ok("Update successful");
            }
            catch (HttpRequestException ex)
            {
                _logger.LogError(ex, "Error updating page section");
                return StatusCode(500, "Internal Server Error");
            }
