const importModule = async (modulePath) => {
  try {
    const module = await import(modulePath);
    return module;
  } catch (err) {
    console.error(`Failed to load module at ${modulePath}:`, err);
    throw err;
  }
};

function runTests(tests, { timeout: globalTimeout = 30000, maxRetries = 3, alertService = null, loggingService = null, debugMode = false } = {}) {
  const blueslip = new (require('blueslip'))({
    level: 'info',
    transport: 'console',
  });

  if (!loggingService) {
    console.log('No logging service configured. Falling back to console logging.');
  }

  await Promise.all(tests.map(async ({ modulePath, testName, testFunction, timeout = globalTimeout, skip }) => {
    try {
      const module = await importModule(modulePath);

      if (skip) {
        console.log(`Skipping test ${testName} from module ${modulePath}`);
        return;
      }

      blueslip.reset();

      for (let attempt = 0; attempt <= maxRetries; attempt++) {
        try {
          await testFunction();
          break;
        } catch (err) {
          if (attempt < maxRetries) {
            console.log(`Test ${testName} from module ${modulePath} failed. Retrying...`);
            await new Promise((resolve) => setTimeout(resolve, 500));
          } else {
            throw err;
          }
        }
      }

      if (!alertService && attempt === maxRetries) {
        console.log(`Test ${testName} from module ${modulePath} timed out after ${globalTimeout}ms.`);
      }
    } catch (err) {
      if (debugMode) {
        console.error(err);
      } else {
        alertService?.sendAlert(`Test failure: ${testName} from module ${modulePath}`);
      }
    } finally {
      blueslip.close();
    }
  }));

  return;
}

export { runTests };
