function renderFooterScripts(scripts, { maxScriptLength = 5000, excludeKeys = [], debugMode = false, cdnEndpoint }) {
    const scriptTags = [];
    let warnCount = 0;

    scripts.forEach((script) => {
        if (!script.key || !script.code) return;

        if (excludeKeys.includes(script.key)) {
            if (debugMode) console.warn(`Script with key ${script.key} excluded due to configuration.`);
            return;
        }

        const code = script.code.length > maxScriptLength
            ? script.code.substring(0, maxScriptLength)
            : script.code;

        if (code !== script.code && debugMode) {
            warnCount++;
            console.warn(`Script with key ${script.key} truncated to ${maxScriptLength} characters.`);
        }

        const scriptTag = `<script src="${cdnEndpoint}/scripts/${script.url}.js"></script>`;
        scriptTags.push(scriptTag);
    });

    return scriptTags.join('');
}
