    dataProcessingServiceUrl,
    cloudStorageAPIKey,
    themeManager,
  }) {
    this.dataProcessingServiceUrl = dataProcessingServiceUrl;
    this.cloudStorageAPIKey = cloudStorageAPIKey;
    this.themeManager = themeManager;

    // Create a transform stream to handle data ingestion
    this.stream = new Transform({
      objectMode: true,

      transform(chunk, encoding, callback) {
        // Process the chunk of data
        axios.post(dataProcessingServiceUrl, chunk)
          .then((response) => {
            if (response.status === 200) {
              // Store the processed data in cloud storage
              axios.put(`${cloudStorageAPIKey}/data`, response.data);
            } else {
              throw new Error(`Failed to process data: ${response.statusText}`);
            }
          })
          .catch((error) => {
            console.error(error);
          });

        callback(null, chunk);
      },
    });
  }

  // Start the data ingestion process
  start() {
    this.stream.on('data', (chunk) => {
      // Handle data chunks as they are received
    });
    this.stream.on('end', () => {
      // Data ingestion is complete
    });
  }

  // Pause the data ingestion process for a specific stream
  pause(streamId) {
    this.stream.pause();
