            {
                using (var stream = await _s3Client.GetObjectStreamAsync(bucketName, key).ConfigureAwait(false))
                {
                    var xmlDocument = new S3XMLDocument(stream);
                    return xmlDocument;
                }
            }
            catch (AmazonS3Exception ex)
            {
                // Handle S3 errors
                throw;
            }
        }

        public async Task SaveXMLDocumentAsync(S3XMLDocument document, string bucketName, string key)
        {
            try
            {
                using (var stream = await document.GetStream().ConfigureAwait(false))
                {
                    await _s3Client.PutObjectStreamAsync(bucketName, key, stream).ConfigureAwait(false);
                }
            }
            catch (AmazonS3Exception ex)
            {
                // Handle S3 errors
                throw;
            }
        }

        private Dictionary<string, string> LoadConfigurationFromParameterStore()
        {
            try
            {
                var parameters = _ssmClient.GetParametersAsync(new List<string> { "BucketName", "DefaultXMLDocumentKey" }).Result;
                return new Dictionary<string, string>(parameters);
            }
            catch (AmazonSSMException ex)
            {
                // Handle SSM errors
                throw;
            }
        }

        public void Dispose()
