        while (true) {
            List<Integer> batch = consumeBatch(consumer);
            if (batch.isEmpty()) {
                continue;
            }

            Map<Integer, Integer> unionFindMap = new HashMap<>();
            int disjointPairsCount = 0;

            for (Integer num : batch) {
                if (!unionFindMap.containsKey(num)) {
                    unionFindMap.put(num, num);
                } else {
                    int root1 = findRoot(unionFindMap, num);
                    int root2 = findRoot(unionFindMap, unionFindMap.get(num));
                    if (root1 != root2) {
                        unionFindMap.put(root2, root1);
                        disjointPairsCount++;
                    }
                }
            }

            logBatchStats(batch.size(), disjointPairsCount);

