import java.util.*;
import java.io.*;
import com.google.common.collect.*;

public class BackgroundTaskExecutor {
    private static final int MIN_WORKER_THREADS = 5;
    private static final int MAX_WORKER_THREADS = 20;
    private static final int RETRY_ATTEMPTS = 3;

    private ExecutorService executor;
    private Map<String, WorkerThreadPool> workerPools = new HashMap<>();
    private CloudMonitoringAPI cloudApi;
    private Logger logger = LoggerFactory.getLogger(BackgroundTaskExecutor.class);

    public BackgroundTaskExecutor(CloudMonitoringAPI cloudApi) {
        this.cloudApi = cloudApi;
        initializeWorkerPools();
    }

    private void initializeWorkerPools() {
        for (String service : workerPools.keySet()) {
            workerPools.put(service, new WorkerThreadPool(MIN_WORKER_THREADS));
        }
    }

    public void executeTask(String service, Task task) {
        try {
            int availableWorkers = workerPools.get(service).getAvailableWorkers();
            if (availableWorkers > 0) {
                executor.submit(new Callable() {
                    @Override
                    public Object call() throws Exception {
                        task.execute();
                        return null;
                    }
                });
            } else {
                logger.warn("No available workers for service {}", service);
            }
        } catch (RejectedExecutionException e) {
            logger.error("Task rejected due to high load: {}", e.getMessage());
        }
    }

    public void scaleWorkers() {
        int totalTasks = cloudApi.getRealTimeWorkloadMetrics().getTotalTasks();
        int desiredWorkerCount = Math.max(MIN_WORKER_THREADS, MIN.WorkerCount(totalTasks));
        if (desiredWorkerCount != executor.getPoolSize()) {
            executor.shutdownNow();
            executor = Executors.newFixedThreadPool(desiredWorkerCount);
            workerPools.forEach((service, pool) -> {
                pool.setWorkerCount(desiredWorkerCount);
            });
        }
    }

    private class WorkerThreadPool {
        private int workerCount;
        private List<Thread> workers;

        public WorkerThreadPool(int initialWorkerCount) {
            this.workerCount = initialWorkerCount;
            this.workers = new ArrayList<>();
        }

        public void setWorkerCount(int count) {
            workerCount = count;
        }

        public int getAvailableWorkers() {
            return workerCount - workers.size();
        }
    }

    private class Task {
        public void execute() throws Exception {
            // Implementation of task execution
        }
    }
}

public interface CloudMonitoringAPI {
    Map<String, Object> getRealTimeWorkloadMetrics();
}
