CREATE PROCEDURE sp_GetEmployeeDetails
    @SupervisorID INT
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY
        DECLARE @HR_API_URL VARCHAR(255) = 'https://hr-api.com/employees';
        DECLARE @DEPARTMENT_API_URL VARCHAR(255) = 'https://department-api.com/departments';

        DECLARE @EmployeeDetails TABLE (Name VARCHAR(50), City VARCHAR(50), Address VARCHAR(100), DepartmentName VARCHAR(50));
        DECLARE @DepartmentNames TABLE (DepartmentName VARCHAR(50));

        DECLARE @SupervisorEmployeeID INT;

        BEGIN TRANSACTION;

        SELECT @SupervisorEmployeeID = EmployeeID
        FROM Employees
        WHERE SupervisorID = @SupervisorID;

        IF @@ROWCOUNT = 0
            RAISERROR('Supervisor not found', 16, 1);

        INSERT INTO @EmployeeDetails
        SELECT e.Name, e.City, e.Address, d.DepartmentName
        FROM Employees e
        JOIN Departments d ON e.DepartmentID = d.DepartmentID
        WHERE e.EmployeeID IN (
            SELECT ed.SupervisorID
            FROM EmployeeDepartmentRelationships ed
            WHERE ed.EmployeeID = @SupervisorEmployeeID
        );

        INSERT INTO @DepartmentNames
        SELECT DISTINCT DepartmentName
        FROM Departments;

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        ROLLBACK TRANSACTION;

        DECLARE @ErrorMessage NVARCHAR(4000);
        SET @ErrorMessage = ERROR_MESSAGE();
        RAISERROR(@ErrorMessage, 16, 1);

        INSERT INTO AuditLog (Timestamp, UserID, Message)
        VALUES (GETDATE(), USER_ID(), @ErrorMessage);
    END CATCH;
END;
```

Please note that you would need to replace the API URLs with your actual HR and department APIs."]

