fn sign_and_package_llvm_ir(input_file_path: &str) -> Result<String, String> {
    let mut module = Module::new(llvm::core::LLVMContext::new());
    let mut builder = Builder::new(&mut module);
    let oauth_service = OAuthService::new();
    let credential_fetcher = CredentialFetcher::new(oauth_service);

