    let llvm_ir = match parse_input_file(input_file_path) {
        Ok(ir) => ir,
        Err(err) => return Err(format!("Error parsing input file: {}", err)),
    };

    // Sign the LLVM IR code with the fetched credentials
    let signed_ir = match sign_llvm_ir(&module, &builder, llvm_ir, credential_fetcher) {
        Ok(ir) => ir,
        Err(err) => return Err(err.to_string()),
    };

    // Package the signed LLVM IR into a single binary file
    let binary_file_path = "output.bin";
    match write_binary_file(signed_ir, binary_file_path) {
        Ok(_) => Ok(String::from("Signed LLVM IR written to file")),
