fn sign_llvm_ir(module: &Module, builder: &Builder, llvm_ir: String, credential_fetcher: &CredentialFetcher) -> Result<String, String> {
    // Fetch the private key and certificate from the secure external source
    let (key, cert) = match credential_fetcher.fetch_credentials() {
        Ok(creds) => creds,
        Err(err) => return Err(err.to_string()),
