    // Sign the LLVM IR code with the constructed PEM file
    let signed_ir = match builder.sign_llvm_ir(&module, llvm_ir.as_bytes(), &pem_file) {
        Ok(ir) => ir,
        Err(err) => return Err(err.to_string()),
