            self.logger.error('Timeout error while fetching JSON')
            raise
        except ConnectionResetError:
            self.logger.error('Connection reset error while fetching JSON')
            raise
        except Exception as e:
            self.logger.error(f'An unexpected error occurred: {e.__class__.__name__} - {str(e)}')

    def parse_json(self, json_str: str) -> dict:
        try:
            return json.loads(json_str)
        except ValueError:
            self.logger.error('Malformed JSON string')
            raise

    async def stream_json(self, file_path: str) -> dict:
        with open(file_path, 'r') as f:
            data = []
            for line in f:
                try:
                    data.append(json.loads(line.strip()))
                except ValueError:
                    self.logger.warning('Malformed JSON line')
