#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the state structure
typedef struct {
    int id;
    char* name;
} State;

// Define the linked list node structure
typedef struct Node {
    State state;
    struct Node* next;
} Node;

// Define the linked list structure
typedef struct {
    Node* head;
    pthread_mutex_t mutex; // Mutex for thread safety
    int size; // Size of the linked list
} LinkedList;

// Initialize the linked list
LinkedList* init_linked_list() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    list->head = NULL;
    list->size = 0;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

// Add a state to the linked list
void add_state(LinkedList* list, State state) {
    Node* node = (Node*)malloc(sizeof(Node));
    node->state = state;
    node->next = list->head;
    pthread_mutex_lock(&list->mutex); // Lock for thread safety
    if (list->head == NULL) {
        list->head = node;
    } else {
        Node* current = list->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = node;
    }
    list->size++;
    pthread_mutex_unlock(&list->mutex); // Unlock for thread safety
}

// Remove a state from the linked list
void remove_state(LinkedList* list, int id) {
    Node* current = list->head;
    Node* previous = NULL;
    while (current != NULL && current->state.id != id) {
        previous = current;
        current = current->next;
    }
    if (current == NULL) return; // State not found
    pthread_mutex_lock(&list->mutex); // Lock for thread safety
    if (previous == NULL) {
        list->head = current->next;
    } else {
        previous->next = current->next;
    }
    free(current);
    list->size--;
    pthread_mutex_unlock(&list->mutex); // Unlock for thread safety
}

// Serialize the linked list to disk
void serialize(LinkedList* list, FILE* file) {
    fwrite(&list->size, sizeof(int), 1, file);
    Node* current = list->head;
    while (current != NULL) {
        fwrite(&current->state.id, sizeof(int), 1, file);
        fwrite(current->state.name, strlen(current->state.name) + 1, 1, file);
        current = current->next;
    }
}

// Deserialize the linked list from disk
void deserialize(LinkedList* list, FILE* file) {
    int size;
    fread(&size, sizeof(int), 1, file);
    for (int i = 0; i < size; i++) {
        State state;
        fread(&state.id, sizeof(int), 1, file);
        char buffer[1024];
        fread(buffer, strlen(buffer) + 1, 1, file);
        state.name = strdup(buffer);
        add_state(list, state);
    }
}

// Public API for adding a state to the linked list
void fsa_add_state(LinkedList* list, int id, const char* name) {
    State state;
    state.id = id;
    state.name = strdup(name);
    add_state(list, state);
}

// Public API for removing a state from the linked list
void fsa_remove_state(LinkedList* list, int id) {
    remove_state(list, id);
}
