import redis
from concurrent.futures import ThreadPoolExecutor
from enum import Enum
from typing import Dict, List

class TransactionStatus(Enum):
    PENDING = 0
    PROCESSED = 1
    FAILED = 2

class Transaction:
    def __init__(self, id: int, amount: float, age: int, frequency: int, value: float):
        self.id = id
        self.amount = amount
        self.age = age
        self.frequency = frequency
        self.value = value
        self.status = TransactionStatus.PENDING

class TransactionProcessor:
    def __init__(self, redis_client: redis.Redis):
        self.redis_client = redis_client
        self.pool = ThreadPoolExecutor(max_workers=5)

    def process_transaction(self, transaction: Transaction):
        # Filter transactions based on age, frequency, and value
        if not self.is_valid_transaction(transaction):
            return

        try:
            # Process transaction in parallel
            with self.pool as pool:
                pool.submit(self.apply_filters, transaction)
        except Exception as e:
            # Handle serialization failures
            self.redis_client.set("transaction:error", str(e))

    def apply_filters(self, transaction: Transaction):
        # Apply filters based on age, frequency, and value
        if transaction.age > 30 or transaction.frequency > 5 or transaction.value > 1000:
            return

        # Mark transaction as processed
        self.redis_client.set("transaction:%s" % transaction.id, "processed")
        self.update_metrics(transaction)

    def is_valid_transaction(self, transaction: Transaction):
        # Check if transaction meets filter criteria
        if not (transaction.age <= 30 and transaction.frequency <= 5 and transaction.value <= 1000):
            return False

        return True

    def update_metrics(self, transaction: Transaction):
        # Update metrics for throughput, error rate, and latency
        self.redis_client.incr("transactions processed")
        if transaction.status == TransactionStatus.FAILED:
            self.redis_client.incr("transactions failed")

    class MetricsCollector:
        def __init__(self, redis_client: redis.Redis):
            self.redis_client = redis_client

        def get_metrics(self) -> Dict[str, int]:
            return {
                "transactions processed": int(self.redis_client.get("transactions processed")),
                "transactions failed": int(self.redis_client.get("transactions failed")),
                # Add more metrics as needed
            }

    def start(self):
        # Start the system
        self.pool.shutdown()

class AlertManager:
    def __init__(self, metrics_collector: TransactionProcessor.MetricsCollector):
        self.metrics_collector = metrics_collector

    def check_alerts(self) -> None:
        metrics = self.metrics_collector.get_metrics()
        if metrics["transactions processed"] > 1000 or metrics["transactions failed"] > 5:
            # Trigger alert
            print("Alert: High transaction volume and error rate")

if __name__ == "__main__":
    redis_client = redis.Redis(host="localhost", port=6379, db=0)
    processor = TransactionProcessor(redis_client)
    processor.start()

    alert_manager = AlertManager(processor.MetricsCollector(redis_client))
    alert_manager.check_alerts()
