#include <thread>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <map>

class AttackSequence {
public:
    AttackSequence(const std::string& configPath) {
        readConfig(configPath);
    }

    void executeAttack(int characterId, const std::string& attackName) {
        if (cooldownMap_.count(characterId)) {
            auto& cooldown = cooldownMap_[characterId];
            if (!cooldown.wait_for(std::chrono::seconds(cooldownInterval_))) {
                // Cooldown period has expired
                processAttack(characterId, attackName);
            }
        } else {
            processAttack(characterId, attackName);
        }
    }

private:
    void readConfig(const std::string& configPath) {
        // Read cooldown interval from configuration file
        std::ifstream configFile(configPath);
        if (configFile.is_open()) {
            int cooldownInterval;
            configFile >> cooldownInterval_;
            configFile.close();
        } else {
            throw std::runtime_error("Failed to read configuration file");
        }
    }

    void processAttack(int characterId, const std::string& attackName) {
        // Log attack selection and start cooldown period
        std::cout << "Character " << characterId << " used attack: " << attackName << std::endl;
        cooldownMap_[characterId] = std::chrono::steady_clock::now() + std::chrono::seconds(cooldownInterval_);
    }

    int cooldownInterval_;
    std::map<int, std::chrono::time_point<std::chrono::steady_clock>> cooldownMap_;
};

int main() {
    AttackSequence attackModule("config.txt");

    // Simulate multiple characters executing attacks concurrently
    for (int i = 0; i < 10; i++) {
        int characterId = i;
        std::string attackName = "Attack" + std::to_string(i);
        attackModule.executeAttack(characterId, attackName);
    }

    return 0;
}

