class LoggingConfigManager {
public:
    LoggingConfigManager(const std::string& apiEndpoint, const std::string& apiKey)
        : apiEndpoint_(apiEndpoint), apiKey_(apiKey) {
        cache_.init(); // Initialize the cache
        validateApi_; // Validate API connection in a separate thread
    }

    ~LoggingConfigManager() {
        stopValidationThread(); // Stop validation thread on destruction
    }

    void startValidationThread() {
        std::thread([this]() { this->validateApi_ = true; }).detach();
    }

    void stopValidationThread() {
        validateApi_ = false;
    }

    bool loadConfigFromFile(const std::string& filename) {
        // Load configuration from file and merge with remote API config
        return parseJsonFile(filename, cache_);
    }

    void setLoggingLevel(const std::string& loggerName, int level) {
        // Set logging level for the given logger name
        logLevels_[loggerName] = level;
    }

    void setThreshold(int threshold) {
        // Set the threshold value for all loggers
        threshold_ = threshold;
    }

    void startLogging() {
        // Start logging based on the current configuration
        std::cout << "Started logging with levels: ";
        for (auto& logger : logLevels_) {
            std::cout << logger.first << ": " << logger.second << " ";
        }
        std::cout << std::endl;
    }

private:
    void validateApi() {
        while (validateApi_) {
            try {
                // Validate the API connection
                Json::Value apiResponse = requestApi(apiEndpoint_);
                if (!apiResponse["status"].asString().compare("OK")) {
                    cache_.updateFromJson(apiResponse);
                } else {
                    std::cerr << "Failed to validate API: " << apiResponse["error_message"] << std::endl;
                    stopValidationThread(); // Stop validation thread
                }
            } catch (const Json::Exception& e) {
                std::cerr << "JSON parsing error: " << e.what() << std::endl;
                stopValidationThread();
            }
        }
    }

