void process_string(char* input, int size_limit, char** output) {
    // Initialize logging library
    third_party_logging_init();

    // Check if input string exceeds size limit
    if (strlen(input) > size_limit) {
        // Log warning and truncate input string to size limit
        third_party_logging_warn("Input string truncated due to size limit");
        *output = malloc((size_limit + 1) * sizeof(char));
        strncpy(*output, input, size_limit);
        (*output)[size_limit] = '\0';
    } else {
        // Log debug message for successful input processing
        third_party_logging_dbg("Input string processed successfully");

        // Allocate memory for result string
        *output = malloc((strlen(input) + 1) * sizeof(char));
        strcpy(*output, input);
        (*output)[strlen(input)] = '\0';
    }

    // Free allocated memory in case of errors or function interruption
    if (third_party_logging_strerror()) {
        free(*output);
        *output = NULL;
    }
}
