        if (graph[i]->id == target_id) {
            target_vertex = graph[i];
            break;
        }
    }

    if (target_vertex == NULL) {
        return;
    }

    Edge *new_edge = malloc(sizeof(Edge));
    if (new_edge == NULL) {
        return;
    }
    new_edge->id = -1; // sentinel value
    new_edge->weight = weight;

    source_vertex->edges = realloc(source_vertex->edges, sizeof(Edge) * (++source_vertex->edge_count + 1));
    source_vertex->edges[source_vertex->edge_count] = *new_edge;
}

double compute_average_weight(Vertex **graph, int vertex_id) {
    // Validate the vertex existence
    // ...

    Vertex *vertex = NULL;
    for (int i = 0; graph[i]->id != -1; i++) {
        if (graph[i]->id == vertex_id) {
            vertex = graph[i];
            break;
        }
    }

    if (vertex == NULL) {
        return -1.0;
    }

    double total_weight = 0.0;
    int edge_count = 0;
    for (int i = 0; i < vertex->edge_count; i++) {
        total_weight += vertex->edges[i].weight;
        edge_count++;
    }

    if (edge_count == 0) {
        return -1.0;
    }

    return total_weight / edge_count;
}

