        free(description);
    }

    for (int i = 0; i < num_random_edges; i++) {
        int source_id = rand() % 100 + 1;
        int target_id = rand() % 100 + 1;
        double weight = (double)rand() / RAND_MAX * 10.0;

        add_edge(&graph, source_id, target_id, weight);
    }

