using Autofac;
using System;
using System.Collections.Generic;
using System.Configuration;
using System.Diagnostics;
using System.IO;
using System.Linq;
using System.Threading;

namespace ServiceRegistrationFramework
{
    public class ServiceRegistry : IServiceRegistry
    {
        private readonly ILifetimeScope _scope;
        private readonly ILogger _logger;
        private readonly Dictionary<string, Type> _serviceTypes = new();
        private readonly Dictionary<string, object> _services = new();

        public ServiceRegistry(ILifetimeScope scope, ILogger logger)
        {
            _scope = scope;
            _logger = logger;
        }

        public void RegisterService(string serviceName, Type serviceType)
        {
            if (_serviceTypes.ContainsKey(serviceName))
                throw new InvalidOperationException($"Service {serviceName} already registered");

            _serviceTypes.Add(serviceName, serviceType);
        }

        public void StartServices()
        {
            foreach (var service in _serviceTypes)
            {
                TryStartService(service.Key, service.Value);
            }
        }

        private void TryStartService(string serviceName, Type serviceType)
        {
            try
            {
                var service = _scope.Resolve(serviceType);

                if (_services.ContainsKey(serviceName))
                    throw new InvalidOperationException($"Service {serviceName} already started");

                _services.Add(serviceName, service);

                StartServiceMonitor(serviceName);
            }
            catch (Exception ex)
            {
                LogError(ex);
            }
        }

        private void StartServiceMonitor(string serviceName)
        {
            var monitor = new ServiceMonitor(_logger, serviceName);
            monitor.Start();
        }

        public void StopServices()
        {
            foreach (var service in _services)
            {
                TryStopService(service.Key, service.Value);
            }
        }

        private void TryStopService(string serviceName, object serviceObject)
        {
            try
            {
                if (_services[serviceName] == null || !(_services[serviceName] == serviceObject))
                    return;

                ((IService)serviceObject).Dispose();
                _services.Remove(serviceName);
            }
            catch (Exception ex)
            {
                LogError(ex);
            }
        }

        public void RestartService(string serviceName, TimeSpan timeout)
        {
            TryStopService(serviceName, _services[serviceName]);
            StartServiceMonitor(serviceName);

            // Wait for the service to start or timeout
            if (!WaitForServiceStart(timeout))
                throw new TimeoutException($"Service {serviceName} did not start within the given time");

            LogInfo($"Service {serviceName} restarted successfully");
        }

        private bool WaitForServiceStart(TimeSpan timeout)
        {
            var watch = Stopwatch.StartNew();

            while (watch.Elapsed < timeout)
            {
                if (_services.ContainsKey(serviceName) && _services[serviceName] != null)
                    return true;

                Thread.Sleep(100);
            }

            watch.Stop();
            return false;
        }

        private void LogError(Exception ex)
        {
            _logger.LogError(ex, $"Error starting service {ex.Message}");
        }

        private void LogInfo(string message)
        {
            _logger.LogInformation(message);
        }
    }

    public interface IServiceRegistry
    {
        void RegisterService(string serviceName, Type serviceType);

        void StartServices();

        void StopServices();

        void RestartService(string serviceName, TimeSpan timeout);
    }

    public class ServiceMonitor : IDisposable
    {
        private readonly ILogger _logger;
        private readonly string _serviceName;

        public ServiceMonitor(ILogger logger, string serviceName)
        {
            _logger = logger;
            _serviceName = serviceName;
        }

        public void Start()
        {
            // Monitor the service and restart it if it fails
        }

        public void Dispose()
        {
            // Clean up any resources used by the monitor
        }
    }

    public interface ILogger
    {
        void LogError(Exception ex, string message);

        void LogInformation(string message);
    }
}
