import java.io.*;
import java.lang.management.ManagementFactory;
import java.util.concurrent.*;

public class BatchProcessor {
    private final int NUM_WORKERS;
    private final ExecutorService executor;

    public BatchProcessor(int numWorkers) {
        this.NUM_WORKERS = numWorkers;
        this.executor = Executors.newFixedThreadPool(NUM_WORKERS);
    }

    public void startProcessing(String[] datasets, String toolPath) throws InterruptedException, ExecutionException {
        for (String dataset : datasets) {
            Future<?> future = executor.submit(() -> processDataset(dataset, toolPath));
            futures.add(future);
        }
    }

    private void processDataset(String dataset, String toolPath) {
        // Create isolated working directory
        File workDir = new File("workdir_" + dataset.hashCode());
        workDir.mkdir();

        try (ProcessBuilder builder = new ProcessBuilder(toolPath, dataset)) {
            Process process = builder.start();
            BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
            String line;
            while ((line = reader.readLine()) != null) {
                if (line.startsWith("ERROR")) {
                    // Handle error reports
                    System.out.println(line);
                } else if (line.startsWith("PROGRESS")) {
                    // Update progress indicators
                    System.out.println(line);
                }
            }
        } catch (IOException e) {
            // Handle tool execution errors
            System.err.println("Error processing dataset: " + dataset);
        }

        try (FileWriter writer = new FileWriter(new File(workDir, "results.txt"))) {
            // Write results to file
            writer.write("Processing complete for dataset: " + dataset + "\n");
        } catch (IOException e) {
            System.err.println("Error writing results: " + dataset);
        }

        // Remove working directory when processing is complete
        workDir.delete();
    }

    private void close() {
        executor.shutdown();
        while (!executor.isTerminated()) {
            Thread.sleep(1000); // Wait for pending tasks to finish
        }
    }

    public static void main(String[] args) throws InterruptedException, ExecutionException {
        int numWorkers = Runtime.getRuntime().availableProcessors(); // Dynamically allocate resources based on system load
        BatchProcessor processor = new BatchProcessor(numWorkers);
        String toolPath = "path/to/tool";
        String[] datasets = {"dataset1", "dataset2", ...}; // List of datasets to process

        try {
            processor.startProcessing(datasets, toolPath);
        } finally {
            processor.close();
        }
    }
}
```

This code implements a Java application that manages the execution of an external command-line tool for batch processing large datasets. The system supports multiple concurrent executions, with each instance operating in a separate, isolated working directory to prevent process interference.']

