#include <iostream>
#include <string>
#include <xmlrpcpp/XmlRpcException.h>
#include <curl/curl.h>
#include <boost/format.hpp>
#include <boost/log/core.hpp>
#include <boost/log/trivial.hpp>

using namespace std;
using namespace xmlrpcpp;

// Function to fetch and parse the XML document
bool isValidOAuthToken(string& apiKey, int maxRetries = 3) {
    CURL *curl;
    CURLcode res;
    string readBuffer;

    // Initialize curl
    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if (!curl) return false;

    // Set API endpoint and headers
    string url = "https://api.example.com/oauth";
    string apiUserAgent = "MyApp/1.0";
    string apiAccept = "application/xml";

    // Set API request headers
    struct curl_slist *headers = NULL;
    headers = curl_slist_append(headers, (string("Authorization: Bearer ") + apiKey).c_str());
    headers = curl_slist_append(headers, ("User-Agent: " + apiUserAgent).c_str());
    headers = curl_slist_append(headers, ("Accept: " + apiAccept).c_str());

    // Set API request
    curl_easy_setopt(curl, CURLOPT_URL, url.c_str());
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, WriteMemoryCallback);
    curl_easy_setopt(curl, CURLOPT_WRITEDATA, &readBuffer);
    curl_easy_setopt(curl, CURLOPT_MAXREDIRS, 50L);
    curl_easy_setopt(curl, CURLOPT_PRIVATE, (void*)this);
    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);

    // Perform the request
    for (int retries = 0; retries < maxRetries; ++retries) {
        res = curl_easy_perform(curl);
        if (res == CURLE_OK) break;
        else if (retries < (maxRetries - 1)) {
            // Handle timeouts and network issues with exponential backoff
            boost::this_thread::sleep_for(boost::chrono::milliseconds((int)(pow(2, retries))));
        } else return false; // Maximum retries exceeded

        // Log error message for troubleshooting
        string errorMessage = (boost::format("Failed to fetch OAuth token. Status code: %1%") % res).str();
        BOOST_LOG_TRIVIAL(error) << errorMessage;
    }

    curl_easy_cleanup(curl);

    // Parse the XML response
    XmlRpcValue xmlResponse;
    try {
        xmlResponse.parse(readBuffer);
    } catch (XmlRpcException& e) {
        return false; // Invalid XML response
    }

    // Validate JSON object fields
    string accessToken = xmlResponse["OAuthResponse"]["access_token"].str();
    int expiresIn = xmlResponse["OAuthResponse"]["expires_in"].int();
    string tokenType = xmlResponse["OAuthResponse"]["token_type"].str();

    if (accessToken.empty() || expiresIn <= 0 || tokenType != "Bearer") return false;

    // Return true indicating a valid OAuth token
    return true;
}

// Callback function to handle curl write data
size_t WriteMemoryCallback(void *ptr, size_t size, size_t nmemb, void *data) {
    ((string*)data)->append((char*)ptr, size * nmemb);
    return size * nmemb;
}
