using System;
using System.Security.Cryptography;
using System.Text;

public class SecureDataProcessor
{
    public long ProcessAndFindMax(string encryptedMessage, string key)
    {
        try
        {
            // Decrypt the message using Triple DES with the provided key and an IV extracted from the message.
            byte[] decryptedBytes = Decrypt(encryptedMessage, key);

            // Convert the decrypted string into an integer array. 
            string[] strings = Encoding.UTF8.GetString(decryptedBytes).Trim().Split(new char[] { ' ' }, StringSplitOptions.RemoveEmptyEntries);
            int[] integers = Array.ConvertAll(strings, s => int.Parse(s));

            // Identify and return the largest integer in this array.
            long maxInteger = FindMaxInteger(integers);

            return maxInteger;
        }
        catch (FormatException ex)
        {
            // Log error if decryption or string parsing fails
            System.Console.WriteLine("Error: " + ex.Message);
            return 0;
        }
    }

    private byte[] Decrypt(string encryptedMessage, string key)
    {
        try
        {
            // Base64 decode the encrypted message.
            byte[] encryptedBytes = Convert.FromBase64String(encryptedMessage);

            // Triple DES decryption using provided key and an IV extracted from the message.
            byte[] iv = new byte[8];
            Array.Copy(encryptedBytes, 0, iv, 0, 8);
            byte[] decryptedBytes = DecryptTripleDES(encryptedBytes, 8, key, iv);

            return decryptedBytes;
        }
        catch (FormatException ex)
        {
            // Log error if decryption fails
            System.Console.WriteLine("Error: " + ex.Message);
            return null;
        }
    }

    private byte[] DecryptTripleDES(byte[] encryptedBytes, int initialVectorSize, string key, byte[] iv)
    {
        try
        {
            using (TripleDESCryptoServiceProvider cryptoProvider = new TripleDESCryptoServiceProvider())
            {
                cryptoProvider.Key = Convert.FromBase64String(key);
                cryptoProvider.IV = iv;
                MemoryStream memoryStream = new MemoryStream(encryptedBytes);
                CryptoStream cryptoStream = new CryptoStream(memoryStream, cryptoProvider.CreateDecryptor());
                byte[] decryptedBytes = new byte[encryptedBytes.Length];
                cryptoStream.Read(decryptedBytes, 0, decryptedBytes.Length);
                cryptoStream.Close();
                memoryStream.Close();

                return decryptedBytes;
            }
        }
        catch (Exception ex)
        {
            // Log error if decryption fails
            System.Console.WriteLine("Error: " + ex.Message);
            return null;
        }
    }

    private long FindMaxInteger(int[] integers)
    {
        long maxInteger = 0;

        foreach (int integer in integers)
        {
            if (integer > maxInteger)
                maxInteger = integer;
        }

        return maxInteger;
    }
}
