namespace HashingLibrary
{
    public class Hasher
    {
        private readonly ILogger<Hasher> _logger;
        private readonly HashSet<string> _supportedAlgorithms = new HashSet<string>();

        public Hasher(ILogger<Hasher> logger)
        {
            _logger = logger;
            Initialize();
        }

        public void Initialize()
        {
            // Load supported algorithms from environment variables
            string[] algos = Environment.GetEnvironmentVariables("HASHING_ALGORITHMS").Select(kvp => kvp.Value).ToArray();
            foreach (string algo in algos)
            {
                _supportedAlgorithms.Add(algo);
            }
        }

        public string Hash(string input, string algorithm = "MD5")
        {
            if (input == null || input.Length > 1024 * 1024) // 1MB limit for performance
        {
            throw new ArgumentException("Input too long or null");
        }

        try
        {
            using (var hashAlgorithm = GetHashAlgorithm(algorithm))
            {
                byte[] bytes = Encoding.UTF8.GetBytes(input);
                byte[] hashedBytes = hashAlgorithm.ComputeHash(bytes);

                return Convert.ToBase64String(hashedBytes);
            }
        }
        catch (CryptographicException ex)
        {
            _logger.LogError(ex, "Error hashing input");
            throw;
        }
    }

    private HashAlgorithm GetHashAlgorithm(string algorithm)
    {
        switch (algorithm.ToLower())
        {
            case "md5":
                return MD5.Create();
            case "sha256":
                return SHA256.Create();
            // Add more algorithms as needed
            default:
                throw new ArgumentException("Unsupported hashing algorithm");
        }
    }

    public class HashingService
    {
        private readonly ILogger<HashingService> _logger;
        private readonly Hasher _hasher;

        public HashingService(ILogger<HashingService> logger, Hasher hasher)
        {
            _logger = logger;
            _hasher = hasher;
        }

        public void LogHash(string input, string algorithm, DateTime timestamp)
        {
            // Log the hashing operation to an external service
            _logger.LogInformation($"Hashed {input} using {algorithm} at {timestamp}");
        }
    }
}
