    public async Task<MyData> DecryptAsync(byte[] ciphertext)
    {
        using var aes = Aes.Create();
        aes.Key = await GetEncryptionKeyAsync();
        aes.IV = await GetInitializationVectorAsync();

        using var decryptor = aes.CreateDecryptor(aes.Key, aes.IV);

        using var ms = new MemoryStream(ciphertext);
        using var cs = new CryptoStream(ms, decryptor, CryptoStreamMode.Read);

        using var buffer = new byte[cs.Length];
        await cs.ReadAsync(buffer, 0, buffer.Length);

        return MessagePackSerializer.Deserialize<MyData>(buffer);
    }

    private async Task<byte[]> GetEncryptionKeyAsync()
    {
        try
        {
            // implement key retrieval from external service
            return await _keyService.GetKeyAsync();
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Failed to retrieve encryption key");
            throw;
        }
    }

    private async Task<byte[]> GetInitializationVectorAsync()
    {
        try
        {
            // implement IV retrieval from external service or generation
            return await _keyService.GetInitializationVectorAsync();
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Failed to retrieve initialization vector");
