import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.ObjectInputStream;
import java.io.ObjectOutputStream;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.*;
import java.util.function.Function;

public class SerializationService {

    private static final Logger logger = LoggerFactory.getLogger(SerializationService.class);

    private Map<Class<?>, Object> objectCache = new ConcurrentHashMap<>();
    private Map<String, Object> metadataCache = new ConcurrentHashMap<>();

    private ExecutorService executorService = Executors.newFixedThreadPool(5);

    public <T> T deserialize(byte[] data, Class<T> clazz) {
        try (ObjectInputStream in = new ObjectInputStream(new ByteArrayInputStream(data))) {
            return clazz.cast(in.readObject());
        } catch (Exception e) {
            throw new ContextedException("Error deserializing object", e);
        }
    }

    public <T> byte[] serialize(T obj, Class<T> clazz) {
        try (ByteArrayOutputStream bos = new ByteArrayOutputStream();
             ObjectOutputStream out = new ObjectOutputStream(bos)) {
            out.writeObject(obj);
            return bos.toByteArray();
        } catch (Exception e) {
            throw new ContextedException("Error serializing object", e);
        }
    }

    public Map<String, Object> getMetadata(String url) {
        // Implement your REST API call logic here
        // For demonstration purposes, we'll just return a sample map
        return Map.ofEntries(
                entries("key1", "value1"),
                entries("key2", "value2")
        );
    }

    private static <K, V> Map.Entry<K, V> entries(K key, V value) {
        return new SimpleEntry<>(key, value);
    }

    public void cacheMetadata(String url, Object metadata) {
        metadataCache.put(url, metadata);
    }

    public void cacheObject(Class<?> clazz, Object obj) {
        objectCache.put(clazz, obj);
    }

    public void flushCaches() {
        objectCache.clear();
        metadataCache.clear();
    }
}

class ContextedException extends Exception {

    public ContextedException(String message, Throwable cause) {
        super(message, cause);
    }
}
