    const configFileBuffer = await fs.readFile(configFilePath);

    // Parse the configuration file using the template engine
    const parsedConfig = templateEngine.parse(configFileBuffer.toString());

    // Encrypt passwords using the external encryption service API
    const encryptedPasswords = [];
    for (const password of parsedConfig.encryptedPasswords) {
