    _registry = {}
    _lock = Lock()

    @classmethod
    def register(cls, id: str, factory: Callable[[str], Any]):
        with cls._lock:
            if id in cls._registry:
                raise ValueError("Data model already registered")
            cls._registry[id] = factory

    @classmethod
    def deserialize(cls, json_str: str) -> Any:
        with cls._lock:
            try:
                data_id = json.loads(json_str).get('data_model_id')
                if not data_id:
                    raise ValueError("Invalid JSON format")
                if data_id in cls._registry:
                    return cls._registry[data_id](json_str)
                else:
                    raise ValueError(f"Unknown data model: {data_id}")
            except Exception as e:
                raise ValueError(f"Deserialization failed: {str(e)}")


