// Structure for vertex properties
typedef struct {
    int id;
    char *name;
    double weight;
} Vertex;

// Structure for edge
typedef struct {
    int source;
    int target;
    double weight;
} Edge;

// Structure for graph
typedef struct {
    int num_vertices;
    int num_edges;
    Vertex **vertices;
    Edge **edges;
} Graph;

// Function to create a new graph
Graph *create_graph(int num_vertices) {
    Graph *graph = (Graph *)malloc(sizeof(Graph));
    graph->num_vertices = num_vertices;
    graph->num_edges = 0;
    graph->vertices = (Vertex **)malloc(num_vertices * sizeof(Vertex *));
    graph->edges = (Edge **)malloc(num_vertices * sizeof(Edge *));

    for(int i = 0; i < num_vertices; i++) {
        graph->vertices[i] = (Vertex *)malloc(sizeof(Vertex));
    }

    return graph;
}

// Function to read a CSV file and load it into the graph
void read_csv(Graph *graph, char *filename) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        printf("Error opening file\n");
        return;
    }

    char line[1024];
    int i = 0;
    while (fgets(line, sizeof(line), file)) {
        Vertex *vertex = graph->vertices[i];
        sscanf(line, "%d,%s,%.2f", &vertex->id, vertex->name, &vertex->weight);
        i++;
    }

    fclose(file);
}

// Function to read a JSON file and load it into the graph
void read_json(Graph *graph, char *filename) {
    json_object *json = json_load_file(filename, 0);
    if (!json) {
        printf("Error loading JSON file\n");
        return;
    }

    int i = 0;
    json_object_object_foreach(json, key, val) {
        Vertex *vertex = graph->vertices[i];
        vertex->id = atoi(json_object_get_string(val));
        vertex->name = strdup(json_object_get_string(val));
        vertex->weight = atof(json_object_get_string(val));
        i++;
    }

    json_decref(json);
}

// Function to read a network stream and load it into the graph
void read_stream(Graph *graph, int sockfd) {
    char buffer[1024];
    int i = 0;
    while (read(sockfd, buffer, sizeof(buffer)) > 0) {
        Vertex *vertex = graph->vertices[i];
        sscanf(buffer, "%d,%s,%.2f", &vertex->id, vertex->name, &vertex->weight);
        i++;
    }

    close(sockfd);
}

// Function to compute the average weight of edges for each vertex
void compute_average_weights(Graph *graph) {
    int i;
    double total_weight = 0.0;
    for(i = 0; i < graph->num_vertices; i++) {
        Vertex *vertex = graph->vertices[i];
        if(vertex->edges) {
            for(int j = 0; j < vertex->num_edges; j++) {
                Edge *edge = vertex->edges[j];
                total_weight += edge->weight;
            }
        }
    }

    printf("Average weights: ");
    for(i = 0; i < graph->num_vertices; i++) {
        Vertex *vertex = graph->vertices[i];
        double average_weight = total_weight / (double)vertex->num_edges;
        printf("%d: %f\n", vertex->id, average_weight);
    }
}

// Function to update the graph concurrently
void update_graph(Graph *graph, int num_updates) {
