// Define a struct to hold encryption context information
typedef struct {
    EVP_CIPHER_CTX* ctx;
    unsigned char iv[EVP_MAX_IV_LENGTH];
    unsigned char salt[EVP_SALT_SIZE];
} encryption_context;

// Initialize an encryption context with given parameters
encryption_context* init_encryption_context(int num_iterations, int salt_size) {
    // Create a new EVP_CIPHER_CTX instance
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();

    // Set the cipher algorithm and mode (AES-256-CBC)
    EVP_CipherInit_ex(ctx, EVP_aes_256_cbc(), NULL, NULL, 0);

    // Generate IV using user-defined strategy or default random generation
    RAND_bytes(ctx->iv, EVP_MAX_IV_LENGTH);

    // Generate salt using user-defined strategy or default random generation
    RAND_bytes(ctx->salt, salt_size);

    return (encryption_context*)ctx;
}

// Initialize an encryption context with given configuration from the external system
encryption_context* init_encryption_context_from_config(struct config* conf) {
    // Set the number of PBKDF2 iterations based on the configuration
    int num_iterations = conf->num_iterations;

    // Set the salt size based on the configuration
    int salt_size = conf->salt_size;

    return init_encryption_context(num_iterations, salt_size);
}

// Encrypt data using an existing encryption context
void encrypt_data(encryption_context* ctx, unsigned char* input, unsigned char* output, int len) {
    // Set the input and output buffers for AES-256-CBC encryption
    EVP_CipherUpdate(ctx->ctx, output, &len, input, len);
}

// Decrypt data using an existing encryption context
void decrypt_data(encryption_context* ctx, unsigned char* input, unsigned char* output, int len) {
    // Set the input and output buffers for AES-256-CBC decryption
    EVP_CipherUpdate(ctx->ctx, output, &len, input, len);
}

// Free an encryption context when it is no longer in use
void free_encryption_context(encryption_context* ctx) {
    EVP_CIPHER_CTX_free(ctx->ctx);
    free(ctx);
}
