import logging
from abc import ABC, abstractmethod
from typing import List

class Logger(ABC):
    @abstractmethod
    def log(self, message: str) -> None:
        pass

class LogHandler(logging.Handler):
    def __init__(self, logger: Logger) -> None:
        self.logger = logger

    def emit(self, record: logging.LogRecord) -> None:
        self.logger.log(record.getMessage())

class LogAggregator:
    def __init__(self) -> None:
        self.log_handlers: List[LogHandler] = []

    def add_log_handler(self, log_handler: LogHandler) -> None:
        self.log_handlers.append(log_handler)

    def aggregate_logs(self) -> None:
        for log_handler in self.log_handlers:
            log_handler.emit(logging.LogRecord())

class RealTimeAnalyzer:
