// Define the structure for a vertex in the graph
typedef struct {
    int id;
    char *name;
    double weight;
} Vertex;

// Define the structure for an edge in the graph
typedef struct {
    Vertex *src;
    Vertex *dst;
    double weight;
} Edge;

// Define the structure for the graph itself
typedef struct {
    int num_vertices;
    int num_edges;
    Vertex **vertices;
    Edge **edges;
    pthread_mutex_t lock; // Mutex for concurrency control
} Graph;

// Function to create a new vertex
Vertex *create_vertex(int id, char *name) {
    Vertex *v = (Vertex *)malloc(sizeof(Vertex));
    v->id = id;
    v->name = strdup(name);
    v->weight = 0.0;
    return v;
}

// Function to create a new edge
Edge *create_edge(Vertex *src, Vertex *dst, double weight) {
    Edge *e = (Edge *)malloc(sizeof(Edge));
    e->src = src;
    e->dst = dst;
    e->weight = weight;
    return e;
}

// Function to initialize the graph
Graph *init_graph() {
    Graph *g = (Graph *)malloc(sizeof(Graph));
    g->num_vertices = 0;
    g->num_edges = 0;
    g->vertices = NULL;
    g->edges = NULL;
    pthread_mutex_init(&g->lock, NULL);
    return g;
}

// Function to add a vertex to the graph
void add_vertex(Graph *g, Vertex *v) {
    pthread_mutex_lock(&g->lock);
    g->num_vertices++;
    if (g->vertices == NULL) {
        g->vertices = (Vertex **)malloc(sizeof(Vertex *) * g->num_vertices);
    } else {
        g->vertices = (Vertex **)realloc(g->vertices, sizeof(Vertex *) * (g->num_vertices + 1));
    }
    g->vertices[g->num_vertices - 1] = v;
    pthread_mutex_unlock(&g->lock);
}

// Function to add an edge to the graph
void add_edge(Graph *g, Edge *e) {
    pthread_mutex_lock(&g->lock);
    g->num_edges++;
    if (g->edges == NULL) {
        g->edges = (Edge **)malloc(sizeof(Edge *) * g->num_edges);
    } else {
        g->edges = (Edge **)realloc(g->edges, sizeof(Edge *) * (g->num_edges + 1));
    }
    g->edges[g->num_edges - 1] = e;
    pthread_mutex_unlock(&g->lock);
}

// Function to calculate the average edge weight for each vertex
void calc_average_edge_weight(Graph *g) {
    int i;
    double sum = 0.0;
    Vertex **vertices = g->vertices;

    // Calculate the average edge weight for each vertex
    for (i = 0; i < g->num_vertices; i++) {
        Vertex *v = vertices[i];
        sum = 0.0;
        int j;
        Edge **edges = g->edges;
        for (j = 0; j < g->num_edges; j++) {
            if (edges[j]->src == v || edges[j]->dst == v) {
                sum += edges[j]->weight;
            }
        }
        printf("Vertex %s: Average edge weight = %.2f\n", v->name, sum / (double)(g->num_edges));
    }
}

// Function to process graph data from CSV file
