class ThreadPool {
public:
    ThreadPool(size_t numThreads) : stop(false), threads() {
        for (size_t i = 0; i < numThreads; ++i)
            threads.emplace_back([this] {
                while (!stop) {
                    std::function<void()> task;
                    {
                        std::unique_lock<std::mutex> lock(queue_mutex);
                        // Wait until a task is available
                        queue.wait(lock, [this] { return stop || !tasks.empty(); });
                        if (stop && tasks.empty())
                            break; // Exit the loop
                        task = std::move(tasks.front());
                        tasks.pop();
                    }
                    // Execute the task
                    task();
                }
            });
    }

    template <class F>
    void enqueue(F&& f) {
        {
            std::unique_lock<std::mutex> lock(queue_mutex);
            tasks.emplace([f] { f(); });
        }
        queue.notify_one();
    }

    ~ThreadPool() {
        {
            std::unique_lock<std::mutex> lock(queue_mutex);
            stop = true;
        }
        queue_condition.wait(lock, [this] { return stop && tasks.empty(); });
        for (auto &thread : threads) // Wait until all tasks are executed
            thread.join();
    }

private:
