    public class UpdateHTMLController : ControllerBase
    {
        private readonly IMongoDatabase _database;
        private readonly IConnectionMultiplexer _redisConnection;
        private readonly IHttpClientFactory _httpClientFactory;
        private readonly IConnection _rabbitMqConnection;

        public UpdateHTMLController(IMongoDatabase database, IConnectionMultiplexer redisConnection, IHttpClientFactory httpClientFactory, IConnection rabbitMqConnection)
        {
            _database = database;
            _redisConnection = redisConnection;
            _httpClientFactory = httpClientFactory;
            _rabbitMqConnection = rabbitMqConnection;
        }

        [HttpPost]
        public async Task<IActionResult> UpdateHTML([FromBody]UpdateHTMLRequest request)
        {
            // Sanitize HTML content using third-party service
            var sanitizedHtmlContent = await _httpClientFactory.CreateClient().SendAsync(new HttpRequestMessage(HttpMethod.Post, "https://third-partyservice.com/sanitize"))
                .Result.Content.ReadAsStringAsync().Result;

            // Update specified HTML elements in the database
            var filter = Builders<BsonDocument>.Filter.Eq("PageSectionID", request.PageSectionID);
            var update = Builders<BsonDocument>.Update.Set("Elements." + request.ElementID, sanitizedHtmlContent);
            await _database.GetCollection<BsonDocument>("HTMLElements").UpdateOneAsync(filter, update);

            // Cache frequently accessed data using Redis
            _redisConnection.GetDatabase().StringSet(request.PageSectionID.ToString(), sanitizedHtmlContent);

            // Asynchronously process time-sensitive updates and offload non-critical tasks to the message queue
            await _rabbitMqConnection.BasicPublish(exchange: "Updates", routingKey: request.ElementID, body: Encoding.UTF8.GetBytes(sanitizedHtmlContent));

            return Ok();
        }
