                return BadRequest("Invalid HTML content");

            try
            {
                // Call the CDN to update the cached HTML content
                await UpdateCdnCache(sectionId, elementId, htmlContent);

                // Broadcast refresh signal to all active clients
                await RefreshClients(sectionId);

                return Ok();
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error updating section");
                throw;
            }
