            try
            {
                // Call the CDN to update the cached HTML content
                await httpClient.PostAsync($"cdn/update/{sectionId}/{elementId}", new StringContent(htmlContent, Encoding.UTF8, "text/html"));

                // Handle CDN failure and retry mechanism
                if (!await CheckCdnAvailability(httpClient))
                    await RetryCdnUpdate();
            }
            catch (HttpRequestException ex)
            {
                _logger.LogError(ex, "Error updating CDN cache");
                throw;
            }
        }

        private async Task RefreshClients(int sectionId)
