            using var httpClient = _httpClientFactory.CreateClient();

            try
            {
                // Send refresh signal to all active clients
                await httpClient.PostAsync($"clients/refresh/{sectionId}", new StringContent(""));

                // Handle client-side refresh failure and fallback mechanism
                if (!await CheckClientAvailability(httpClient))
                    await FallbackRefresh();
            }
            catch (HttpRequestException ex)
            {
                _logger.LogError(ex, "Error refreshing clients");
                throw;
            }
        }

        private async Task<bool> CheckCdnAvailability(HttpClient httpClient)
