    std::map<int, Record> records;
    std::vector<long> offsets;
    std::vector<int> keys;
    std::map<std::string, std::string> tokens;

    std::mutex mtx;
    std::condition_variable cv;
    bool initialized = false;

public:
    DataManagementSystem() {
        for (int i = 0; i < 10000000; ++i) {
            Record record(i, "Record" + std::to_string(i));
            records[record.id] = record;
        }
    }

    void initialize() {
        std::unique_lock<std::mutex> lock(mtx);
        while (!initialized) {
            cv.wait_for(lock, std::chrono::milliseconds(10));
        }
        initialized = false;
        cv.notify_all();
    }

    bool validateToken(const std::string& tokenJson) {
        auto token = std::make_unique<std::map<std::string, std::string>>(std::move(tokenJson));
        if (token->at("token_type") != "Bearer" || token->at("expires_in") <= 0) {
