namespace MyAPI.Controllers
{
    [ApiController]
    [Route("api/[controller]")]
    public class UpdateController : ControllerBase
    {
        private readonly IHttpClientFactory _httpClientFactory;
        private readonly RedisCache _redisCache;

        public UpdateController(IHttpClientFactory httpClientFactory, RedisCache redisCache)
        {
            _httpClientFactory = httpClientFactory;
            _redisCache = redisCache;
        }

        [HttpPost]
        [Route("update")]
        public async Task<IActionResult> Update([FromBody]UpdateRequest request)
        {
            // Validate and process the update request
            var htmlContent = await GetHtmlContentFromCDN(request.PageSectionId, request.ElementId);
            if (htmlContent == null) return NotFound();

            try
            {
                // Perform atomic update using optimistic locking
                var updatedHtmlContent = await UpdateHtmlContentInDatabase(htmlContent);

                // Cache the updated HTML content for later use
                _redisCache.Set(request.PageSectionId, updatedHtmlContent, TimeSpan.FromDays(30));

                return Ok(updatedHtmlContent);
            }
            catch (Exception ex)
            {
                // Handle concurrent update conflicts and log errors
                _logger.LogError(ex, "Error updating HTML content");

                return Conflict("Conflict detected. Please try again.");
            }
        }

        private async Task<string> GetHtmlContentFromCDN(string pageSectionId, string elementId)
        {
            using var httpClient = _httpClientFactory.CreateClient();
            // Fetch and validate the HTML content from the CDN
            var response = await httpClient.GetAsync($"https://cdn.example.com/{pageSectionId}/{elementId}");
            if (response.IsSuccessStatusCode) return await response.Content.ReadAsStringAsync();
            else throw new Exception("Failed to fetch HTML content");
        }

        private async Task<string> UpdateHtmlContentInDatabase(string htmlContent)
        {
            // Perform atomic update using optimistic locking
            var dbResult = await Database.UpdateHtmlContent(htmlContent);
            if (dbResult != null) return dbResult;
            else throw new Exception("Failed to update HTML content");
        }
    }

    public class UpdateRequest
    {
        public string PageSectionId { get; set; }
        public string ElementId { get; set; }
        public string HtmlContent { get; set; }
    }
}
