#include <semaphore.h>
#include <stdlib.h>

void *resource_access_manager(void *ptr) {
    sem_t *sem = (sem_t *) ptr;
    int count = 0;

    while (1) {
        if (sem_wait(sem) == -1) {
            // error handling for semaphore creation
            return NULL;
        }
        // access shared resource here
        count++;
        sem_post(sem);
    }
}

int main() {
    sem_t *sem = sem_open("/my_semaphore", O_CREAT, 0644, 0);
    if (sem == SEM_FAILED) {
        // error handling for semaphore creation
        return -1;
    }

    pthread_t thread;
    pthread_create(&thread, NULL, resource_access_manager, sem);

    while (1) {
        sleep(1); // example usage
    }
}
