    // Dynamically determine the appropriate LLVM version based on the input file's characteristics
    let llvm_version = determine_llvm_version(input_file_path)?;
    log_service.log_info(&format!("Using LLVM version {}", llvm_version));

    // Load the LLVM IR from the input file
    let mut input_file = File::open(input_file_path)?;
    let mut ir_data = BufReader::new(input_file);
    let llvm_ir = llvmlib::load_llvm_ir(ir_data)?;

    // Sign the LLVM IR using the fetched private keys and certificates
    let signed_ir = sign_llvm_ir(&keys, &certs, &llvm_ir)?;

    // Construct a combined PEM file using the signed LLVM IR and the certificates
    let mut pem_file = File::create("signed_llvmlib.pem")?;
