// Define constants for error handling and logging
const int MAX_ATTEMPTS = 5;
const int RETRY_DELAY = 1000; // in milliseconds

// Function to update clinic status
int updateClinicStatus(const std::string& clinicId, const std::string& status) {
    // Initialize attempt counter and timer
    int attempts = 0;
    int lastErrorTime = 0;

    while (true) {
        try {
            // Connect to distributed database using environment variables
            dbConn conn = dbConnect();

            // Update clinic status in the database
            conn.updateClinicStatus(clinicId, status);

            // Log success and break out of the loop
            std::cout << "Updated clinic status successfully." << std::endl;
            return 0;
        } catch (const std::exception& e) {
            // Handle error, increment attempt counter, and update last error time
            attempts++;
            lastErrorTime = millis();

            if (attempts >= MAX_ATTEMPTS || millis() - lastErrorTime > RETRY_DELAY * (1 << (MAX_ATTEMPTS - 1))) {
                // Log the error and throw an exception
                std::cerr << "Failed to update clinic status: " << e.what() << std::endl;
                throw;
            }

            // Wait for retry delay before attempting again
            std::this_thread::sleep_for(std::chrono::milliseconds(RETRY_DELAY));
        }
    }
}

int main(int argc, char* argv[]) {
    if (argc != 3) {
        std::cerr << "Usage: updateClinicStatus <clinicId> <status>" << std::endl;
        return 1;
    }

    std::string clinicId = argv[1];
    std::string status = argv[2];

    int result = updateClinicStatus(clinicId, status);

    if (result != 0) {
        std::cerr << "Error updating clinic status." << std::endl;
    }

    return 0;
}

