    def hash_file(self, file_path: str) -> Generator[Dict[str, str], None, None]:
        with open(file_path, 'rb') as f:
            chunk_size = 1024 * 1024
            for i in range(0, int(f.size()), chunk_size):
                chunk = BytesIO(f.read(chunk_size))
                self.md5_hash.update(chunk.getvalue())
                self.sha256_hash.update(chunk.getvalue())

                yield {
                    'chunk_number': i,
                    'md5_partial_hash': self.md5_hash.hexdigest(),
                    'sha256_partial_hash': self.sha256_hash.hexdigest()
                }
        self.md5_hash = hashlib.md5()
        self.sha256_hash = hashlib.sha256()

    def get_final_hashes(self) -> Dict[str, str]:
        self.md5_hash.update(b'')
        self.sha256_hash.update(b'')
        return {
            'md5_hash': self.md5_hash.hexdigest(),
            'sha256_hash': self.sha256_hash.hexdigest()
        }

class LoggingHandler:
    def __init__(self):
        import logging
        from flask.logging import default_handler

        self.logger = logging.getLogger('file_hasher')
        self.logger.setLevel(logging.INFO)
        self.handler = default_handler(self.logger)

    def log_event(self, event: str) -> None:
        self.handler.emit(logging.LogRecord(logging.INFO, 0, 'file_hasher', 1, f"{event}"))

class FileAPI:
    def __init__(self):
        self.file_hasher = FileHasher()
        self.logging_handler = LoggingHandler()

    @staticmethod
    def get_config():
        return {
            'chunk_size': 1024 * 1024,
            'logging_level': logging.INFO,
            'logging_format': '%(asctime)s - %(name)s - %(levelname)s - %(message)s'
        }

    def put_resource(self, resource_id: str, data: bytes) -> None:
        # optimistic concurrency control
