bool resolve_and_process_hostname(const char* hostname, int timeout_ms, std::vector<unsigned char>* ip_addresses, std::string* error_message, bool is_async, int max_results) {
    // Initialize the third-party DNS resolver
    dns_resolver* resolver = dns_resolver_init();
    if (!resolver) {
        *error_message = "Failed to initialize DNS resolver";
        return false;
    }

    // Set up the request parameters
    dns_request request;
    request.hostname = hostname;
    request.timeout_ms = timeout_ms;

    // Send the DNS query and receive the response
    std::vector<dns_record*> records = dns_resolver_query(resolver, &request);
    if (!records) {
        *error_message = "DNS resolution failed";
        return false;
    }

    // Process the resolved IP addresses
    for (const auto& record : records) {
        if (record->type == dns_type_A) { // IPv4 address
            std::vector<unsigned char> ip_address(record->data, record->data + 4);
            ip_addresses->push_back(ip_address[0]);
            ip_addresses->push_back(ip_address[1]);
            ip_addresses->push_back(ip_address[2]);
            ip_addresses->push_back(ip_address[3]);
        } else if (record->type == dns_type_AAAA) { // IPv6 address
            std::vector<unsigned char> ip_address(record->data, record->data + 16);
            ip_addresses->insert(ip_addresses->end(), ip_address.begin(), ip_address.end());
        }
    }

    // Release the DNS records and resolver
    for (const auto& record : records) {
        dns_record_free(record);
    }
    dns_resolver_free(resolver);

    return true;
}
