['Here is the code block for the distributed task scheduling framework:

```python
import asyncio
import logging
from typing import Dict, List

class Task:
    def __init__(self, id: int, name: str, resource_requirements: Dict[str, int], 
                 execution_pattern: str, external_dependencies: List[str]):
        self.id = id
        self.name = name
        self.resource_requirements = resource_requirements
        self.execution_pattern = execution_pattern
        self.external_dependencies = external_dependencies

class TaskQueue:
    def __init__(self):
        self.tasks = []
        self.assigned_resources = {}
        self.scheduling_policy = "FIFO"

    async def submit_task(self, task: Task):
        # Assign resources based on scheduling policy
        if self.scheduling_policy == "FIFO":
            assigned_resources = await self.assign_fifo_resources(task)
        elif self.scheduling_policy == "Priority":
            assigned_resources = await self.assign_priority_resources(task)
        else:
            raise ValueError("Invalid scheduling policy")

        # Update task status and dependencies
        task.status = "Running"
        for dependency in task.external_dependencies:
            if not self.has_task(dependency):
                raise ValueError(f"Task {dependency} not found")
            task.status = f"Waiting on {dependency}"

    async def assign_fifo_resources(self, task: Task):
        # Assign resources based on FIFO policy
        available_resources = self.assigned_resources.copy()
        for resource, amount in task.resource_requirements.items():
            if amount > 0:
                if resource not in available_resources or available_resources[resource] >= amount:
                    available_resources[resource] += amount
                else:
                    raise ValueError(f"Insufficient resources for {task.name}")
        return available_resources

    async def assign_priority_resources(self, task: Task):
        # Assign resources based on priority policy
        available_resources = self.assigned_resources.copy()
        priority_queue = [(amount, resource) for resource, amount in task.resource_requirements.items() if amount > 0]
        while priority_queue:
            amount, resource = heapq.heappop(priority_queue)
            if amount <= self.assigned_resources.get(resource, 0):
                self.assigned_resources[resource] -= amount
            else:
                raise ValueError(f"Insufficient resources for {task.name}")
        return self.assigned_resources

    def has_task(self, task_id: int) -> bool:
        return any(t.id == task_id for t in self.tasks)

class SchedulingPolicy:
    @abstractmethod
    async def assign_resources(self, task: Task):
        pass

class FIFOPolicy(SchedulingPolicy):
    async def assign_resources(self, task: Task):
        # Assign resources based on FIFO policy
        available_resources = {}
        for resource, amount in task.resource_requirements.items():
            if amount > 0:
                if resource not in available_resources or available_resources[resource] >= amount:
                    available_resources[resource] += amount
                else:
                    raise ValueError(f"Insufficient resources for {task.name}")
        return available_resources

class PriorityPolicy(SchedulingPolicy):
    async def assign_resources(self, task: Task):
        # Assign resources based on priority policy
        available_resources = {}
        priority_queue = [(amount, resource) for resource, amount in task.resource_requirements.items() if amount > 0]
        while priority_queue:
            amount, resource = heapq.heappop(priority_queue)
            if amount <= self.assigned_resources.get(resource, 0):
                self.assigned_resources[resource] -= amount
            else:
                raise ValueError(f"Insufficient resources for {task.name}")
        return available_resources

class TaskScheduler:
    def __init__(self):
        self.task_queue = TaskQueue()
        self.scheduling_policy = FIFOPolicy()

    async def schedule_task(self, task: Task):
        # Assign resources and update task status
        await self.task_queue.submit_task(task)
        await self.scheduling_policy.assign_resources(task)

    async def run_scheduler(self):
        while True:
            tasks = await self.task_queue.get_pending_tasks()
            for task in tasks:
                await self.schedule_task(task)

# Example usage:

async def main():
    scheduler = TaskScheduler()

    task1 = Task(1, "CPU-bound", {"cpu": 2}, "Heavy", ["Task2"])
    task2 = Task(2, "I/O-bound", {"io": 1}, "Light", [])
    task3 = Task(3, "Network-bound", {"network": 0.5}, "Medium", ["Task1"])

    await scheduler.task_queue.submit_task(task1)
    await scheduler.task_queue.submit_task(task2)
    await scheduler.task_queue.submit_task(task3)

    await scheduler.run_scheduler()

asyncio.run(main())
