import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import io.swagger.annotations.ApiOperation;
import io.swagger.annotations.ApiParam;

import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.*;

// Define a Service class that encapsulates the PokemonWeaknessService logic
public class PokemonWeaknessService {

    private static final String CACHE_NAME = "pokemon_weakness_cache";
    private static final long REFRESH_INTERVAL = 48 * 60 * 1000; // 48 hours

    private Map<String, PokemonWeakness> pokemonWeaknessCache;
    private ExecutorService executorService;

    public PokemonWeaknessService() {
        this.pokemonWeaknessCache = new ConcurrentHashMap<>();
        this.executorService = Executors.newFixedThreadPool(5);
    }

    // Method to retrieve a Pokémon's weaknesses
    @ApiOperation(value = "Get Pokémon Weaknesses", notes = "Retrieve a Pokémon's primary and secondary weaknesses")
    public PokemonWeakness getPokemonWeakness(@ApiParam("Pokémon name or ID") String pokemonName) throws IOException, ExecutionException {

        // Check cache first
        PokemonWeakness cachedPokemonWeakness = pokemonWeaknessCache.get(pokemonName);
        if (cachedPokemonWeakness != null) {
            return cachedPokemonWeakness;
        }

        // Get weaknesses from external API
        List<Future<PokemonWeakness>> futures = new ArrayList<>();
        for (int i = 0; i < 3; i++) { // Try multiple APIs up to 3 times
            Future<PokemonWeakness> future = executorService.submit(() -> getFromExternalAPI(pokemonName));
            futures.add(future);
        }

        PokemonWeakness pokemonWeakness = null;
        for (Future<PokemonWeakness> future : futures) {
            try {
                PokemonWeakness result = future.get(); // Get the first successful response
                if (result != null && pokemonWeakness == null) {
                    pokemonWeakness = result;
                }
            } catch (CancellationException e) {
                // Ignore cancelled tasks
            } catch (ExecutionException e) {
                // Log and retry if API request failed
                logError("Failed to retrieve Pokémon weaknesses from " + future.toString());
                try {
                    Thread.sleep(5000); // Sleep for 5 seconds before retrying
                } catch (InterruptedException ie) {
                    Thread.currentThread().interrupt();
                }
            }
        }

        // Update cache and refresh interval
        if (pokemonWeakness != null) {
            pokemonWeaknessCache.put(pokemonName, pokemonWeakness);
            scheduleRefresh(pokemonName);
        }

        return pokemonWeakness;
    }

    private PokemonWeakness getFromExternalAPI(String pokemonName) throws IOException {

        // Call the external API using a REST client
        RestTemplate restTemplate = new RestTemplate();
        String url = "https://api.pokemon.com/pokemon/" + pokemonName + "/weaknesses";
        ResponseEntity<String> response = restTemplate.getForEntity(url, String.class);

        if (response.getStatusCode() == HttpStatus.OK) {
            PokemonWeakness pokemonWeakness = parseResponse(response.getBody());
            return pokemonWeakness;
        } else {
            return null; // API request failed
        }
    }

    private void scheduleRefresh(String pokemonName) {
        ScheduledExecutorService scheduledExecutorService = Executors.newSingleThreadScheduledExecutor();
        scheduledExecutorService.schedule(() -> refreshPokemonWeakness(pokemonName), REFRESH_INTERVAL, TimeUnit.MILLISECONDS);
    }

    private PokemonWeakness refreshPokemonWeakness(String pokemonName) {
        // Refresh the Pokémon's weaknesses using the external API
        PokemonWeakness updatedPokemonWeakness = getFromExternalAPI(pokemonName);

        if (updatedPokemonWeakness != null) {
            // Update the cache and schedule a new refresh
            pokemonWeaknessCache.put(pokemonName, updatedPokemonWeakness);
            scheduleRefresh(pokemonName);
        }

        return updatedPokemonWeakness;
    }

    private PokemonWeakness parseResponse(String response) throws IOException {

        // Parse the JSON response using Jackson
        ObjectMapper mapper = new ObjectMapper();
        JsonNode jsonNode = mapper.readTree(response);

        PokemonWeakness pokemonWeakness = new PokemonWeakness();
        // Extract primary and secondary weaknesses from the JSON node
        List<String> primaryWeaknesses = extractWeaknesses(jsonNode, "primary");
        List<String> secondaryWeaknesses = extractWeaknesses(jsonNode, "secondary");

        pokemonWeakness.setPrimaryWeaknesses(primaryWeaknesses);
        pokemonWeakness.setSecondaryWeaknesses(secondaryWeaknesses);

        return pokemonWeakness;
    }

    private List<String> extractWeaknesses(JsonNode jsonNode, String type) {
        List<String> weaknesses = new ArrayList<>();
        for (JsonNode weaknessNode : jsonNode.get(type)) {
            weaknesses.add(weaknessNode.asText());
        }
        return weaknesses;
    }
}

class PokemonWeakness {

    private List<String> primaryWeaknesses;
    private List<String> secondaryWeaknesses;

    public PokemonWeakness() {}

    public List<String> getPrimaryWeaknesses() {
        return primaryWeaknesses;
    }

    public void setPrimaryWeaknesses(List<String> primaryWeaknesses) {
        this.primaryWeaknesses = primaryWeaknesses;
    }

    public List<String> getSecondaryWeaknesses() {
        return secondaryWeaknesses;
    }

    public void setSecondaryWeaknesses(List<String> secondaryWeaknesses) {
        this.secondaryWeaknesses = secondaryWeaknesses;
    }
}

