```c
#include <pthread.h>
#include <stdlib.h>
#include <stdio.h>

// Struct for semaphore with dynamic resizing via environment variables or centralized configuration service.
typedef struct {
    int value;
    pthread_mutex_t lock;
    pthread_cond_t cond;
} semaphore_t;

semaphore_t* create_semaphore(int init_value) {
    semaphore_t* sem = (semaphore_t*)malloc(sizeof(semaphore_t));
    sem->value = init_value;
    pthread_mutex_init(&sem->lock, NULL);
    pthread_cond_init(&sem->cond, NULL);
    return sem;
}

void destroy_semaphore(semaphore_t* sem) {
    pthread_mutex_destroy(&sem->lock);
    pthread_cond_destroy(&sem->cond);
    free(sem);
}

int wait_semaphore(semaphore_t* sem) {
    pthread_mutex_lock(&sem->lock);
    while (sem->value == 0) {
        pthread_cond_wait(&sem->cond, &sem->lock);
    }
    --sem->value;
    pthread_mutex_unlock(&sem->lock);
    return 1;
}

int signal_semaphore(semaphore_t* sem) {
    pthread_mutex_lock(&sem->lock);
    ++sem->value;
    if (sem->value > 0) {
        pthread_cond_signal(&sem->cond);
    }
    pthread_mutex_unlock(&sem->lock);
    return 1;
}

// Dynamic resizing via environment variables or centralized configuration service.
int get_semaphore_value() {
    // Read semaphore value from environment variable or central config service.
    return atoi(getenv("SEM_VALUE"));
}

void set_semaphore_value(int new_value) {
    // Update semaphore value in environment variable or central config service.
    setenv("SEM_VALUE", getenv("SEM_VALUE") + (new_value - 1), 1);
}

// Main function to demonstrate the usage of the semaphore.
int main() {
    int sem_value = get_semaphore_value();
    semaphore_t* sem = create_semaphore(sem_value);

    // Thread A: Accessing shared resource with semaphore.
    pthread_t thread_a;
    pthread_create(&thread_a, NULL, access_shared_resource, (void*)sem);
    pthread_join(thread_a, NULL);

    // Thread B: Accessing shared resource with semaphore.
    pthread_t thread_b;
    pthread_create(&thread_b, NULL, access_shared_resource, (void*)sem);
    pthread_join(thread_b, NULL);

    destroy_semaphore(sem);

    return 0;
}
