using System;
using System.Threading.Tasks;
using System.Net.Http;
using System.Web.Http;
using System.Data.SqlClient;
using StackExchange.Redis;

namespace MyApi
{
    public class UpdatePageSectionController : ApiController
    {
        private readonly IRedisConnectionMultiplexer _redis;
        private readonly SqlConnection _sqlConn;

        public UpdatePageSectionController(IRedisConnectionMultiplexer redis, SqlConnection sqlConn)
        {
            _redis = redis;
            _sqlConn = sqlConn;
        }

        [HttpPost]
        public async Task<HttpResponseMessage> UpdatePageSection([FromBody]UpdatePageSectionModel model)
        {
            // Validate and fetch HTML content from external data source.
            string htmlContent = await FetchHtmlContent(model.PageSectionId, model.ElementId);

            // Lock the page section for concurrent updates.
            using (var redisLock = _redis.GetDatabase().StringSetEx("pageSectionLock", 0, TimeSpan.FromHours(1)))
            {
                if (!redisLock)
                {
                    // Handle lock timeout or failure.
                    return Request.CreateErrorResponse(HttpStatusCode.InternalServerError, "Failed to acquire lock.");
                }

                try
                {
                    // Update the page section with the new HTML content.
                    using (var db = _sqlConn.GetDatabase())
                    {
                        await db.ExecuteAsync("UPDATE page_sections SET html_content = @htmlContent WHERE id = @pageSectionId", model.PageSectionId, htmlContent);
                    }

                    return Request.CreateResponse(HttpStatusCode.OK);
                }
                catch (Exception ex)
                {
                    // Log and handle any exceptions.
                    return Request.CreateErrorResponse(HttpStatusCode.InternalServerError, ex.Message);
                }
                finally
                {
                    redisLock.Dispose();
                }
            }
        }
    }

    public class UpdatePageSectionModel
    {
        public int PageSectionId { get; set; }
        public int ElementId { get; set; }
        public string HtmlContent { get; set; }
    }
}
