#define UE_CONN_STATUS_MAX_SIZE 1024
#define TTL_DEFAULT 300 // seconds

typedef struct {
    int status;
    time_t last_update;
} UEConnectionStatus;

typedef struct {
    UEConnectionStatus* connections;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} UEConnectionStatusManager;

UEConnectionStatusManager* ue_conn_status_manager_init(size_t initial_capacity) {
    UEConnectionStatusManager* manager = (UEConnectionStatusManager*)malloc(sizeof(UEConnectionStatusManager));
    manager->connections = (UEConnectionStatus*)calloc(initial_capacity, sizeof(UEConnectionStatus));
    manager->capacity = initial_capacity;
    manager->size = 0;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void ue_conn_status_manager_free(UEConnectionStatusManager* manager) {
    free(manager->connections);
    free(manager);
}

int ue_conn_status_manager_add_connection(UEConnectionStatusManager* manager, UEConnectionStatus* connection) {
    pthread_mutex_lock(&manager->lock);
    if (manager->size >= manager->capacity) {
        // Reallocates the connections array with a new capacity that is twice the current size
        manager->connections = (UEConnectionStatus*)realloc(manager->connections, 2 * manager->capacity * sizeof(UEConnectionStatus));
        manager->capacity *= 2;
    }
    manager->connections[manager->size] = *connection;
    manager->size++;
    pthread_mutex_unlock(&manager->lock);
    return 0;
}

int ue_conn_status_manager_remove_connection(UEConnectionStatusManager* manager, time_t cutoff) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->size; i++) {
        if (manager->connections[i].last_update <= cutoff) {
            // Shift elements down after the removed connection
            size_t j;
            for (j = i; j < manager->size - 1; j++) {
                manager->connections[j] = manager->connections[j + 1];
            }
            // Reduce array size and reallocate if necessary
            manager->size--;
            if (manager->size * sizeof(UEConnectionStatus) <= manager->capacity * sizeof(UEConnectionStatus)) {
                manager->connections = (UEConnectionStatus*)realloc(manager->connections, manager->size * sizeof(UEConnectionStatus));
                manager->capacity = manager->size;
            }
            break;
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return 0;
}

int ue_conn_status_manager_iterate_connections(UEConnectionStatusManager* manager, void (*callback)(UEConnectionStatus*)) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->size; i++) {
        callback(&manager->connections[i]);
    }
    pthread_mutex_unlock(&manager->lock);
    return 0;
}

int main() {
    UEConnectionStatusManager* manager = ue_conn_status_manager_init(16);

    // Simulate adding connections
    for (size_t i = 0; i < 8; i++) {
        UEConnectionStatus connection;
        connection.status = rand() % 2;
        connection.last_update = time(NULL);
        ue_conn_status_manager_add_connection(manager, &connection);
    }

    // Simulate removing outdated connections
    for (int i = TTL_DEFAULT; i >= 0; i--) {
        ue_conn_status_manager_remove_connection(manager, time(NULL) - i);
    }

    // Simulate iterating over connections
