    void (*callback)(UEConnectionStatus*) = &my_callback;
    ue_conn_status_manager_iterate_connections(manager, callback);

    return 0;
}

void my_callback(UEConnectionStatus* connection) {
    printf("Connection status: %d\n", connection->status);
}
