#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the structure to represent UEConnectionStatus
typedef struct {
    int id;
    char status[20];
    time_t timestamp;
} UEConnectionStatus;

// Define the library's data structure to manage connection statuses
typedef struct {
    UEConnectionStatus* connections;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} ConnectionManager;

// Function to create a new connection manager
ConnectionManager* create_connection_manager(size_t initial_capacity) {
    ConnectionManager* cm = malloc(sizeof(ConnectionManager));
    cm->connections = calloc(initial_capacity, sizeof(UEConnectionStatus));
    cm->capacity = initial_capacity;
    cm->size = 0;
    pthread_mutex_init(&cm->lock, NULL);
    return cm;
}

// Function to add a new connection status
void add_connection_status(ConnectionManager* cm, UEConnectionStatus* status) {
    pthread_mutex_lock(&cm->lock);
    if (cm->size == cm->capacity) {
        // Resize the array when it's full
        cm->capacity *= 2;
        cm->connections = realloc(cm->connections, sizeof(UEConnectionStatus) * cm->capacity);
    }
    cm->connections[cm->size] = *status;
    cm->size++;
    pthread_mutex_unlock(&cm->lock);
}

// Function to remove outdated connections
void evict_outdated_connections(ConnectionManager* cm, time_t ttl) {
    pthread_mutex_lock(&cm->lock);
    for (int i = 0; i < cm->size; i++) {
        if ((time(NULL) - cm->connections[i].timestamp) > ttl) {
            // Evict outdated connections
            memmove(&cm->connections[i], &cm->connections[i+1], sizeof(UEConnectionStatus) * (cm->size-i-1));
            cm->size--;
            i--;  // Decrement i to re-check the same index again
        }
    }
    pthread_mutex_unlock(&cm->lock);
}

// Function to update connection status from API
void update_connection_status(ConnectionManager* cm, UEConnectionStatus* new_status) {
    pthread_mutex_lock(&cm->lock);
    for (int i = 0; i < cm->size; i++) {
        if (cm->connections[i].id == new_status->id) {
            // Update existing connection status
            strcpy(cm->connections[i].status, new_status->status);
            cm->connections[i].timestamp = time(NULL);
            break;
        }
    }
    pthread_mutex_unlock(&cm->lock);
}

// Function to print connection statuses
void print_connection_statuses(ConnectionManager* cm) {
    pthread_mutex_lock(&cm->lock);
    for (int i = 0; i < cm->size; i++) {
        printf("ID: %d, Status: %s, Timestamp: %ld\n", cm->connections[i].id, cm->connections[i].status, (long int)cm->connections[i].timestamp);
    }
    pthread_mutex_unlock(&cm->lock);
}

int main() {
    // Create a connection manager
    ConnectionManager* cm = create_connection_manager(10);

    // Add some initial connection statuses
    UEConnectionStatus status1 = {"1234", "connected", time(NULL)};
    UEConnectionStatus status2 = {"5678", "disconnected", time(NULL)};
    add_connection_status(cm, &status1);
    add_connection_status(cm, &status2);

    // Update a connection status from API
    UEConnectionStatus new_status = {"1234", "terminated", time(NULL)};
    update_connection_status(cm, &new_status);

    // Evict outdated connections
    evict_outdated_connections(cm, 300);  // TTL is 5 minutes

    // Print the remaining connection statuses
    print_connection_statuses(cm);

    return 0;
}

