// Define a struct to represent UE connection status
typedef struct {
    int id;
    char* ip;
    time_t timestamp;
} UEConnectionStatus;

// Define a linked list node for dynamic collection of UEConnectionStatus
typedef struct Node {
    UEConnectionStatus* data;
    struct Node* next;
} Node;

// Function to create a new node with given UE connection status
Node* create_node(UEConnectionStatus* ue_status) {
    Node* node = (Node*) malloc(sizeof(Node));
    node->data = ue_status;
    node->next = NULL;
    return node;
}

// Function to add an element to the end of the linked list
void add_to_end(Node** head, UEConnectionStatus* new_data) {
    if (*head == NULL) {
        *head = create_node(new_data);
    } else {
        Node* current = *head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = create_node(new_data);
    }
}

// Function to remove the first element of the linked list
void remove_first(Node** head) {
    if (*head == NULL) {
        return;
    } else {
        Node* temp = *head;
        *head = (*head)->next;
        free(temp);
    }
}

// Function to update the Time-To-Live (TTL) for UE connection status
void update_ttl(Node** head, time_t current_time) {
    Node* current = *head;
    while (current != NULL) {
        if (difftime(current->data->timestamp, current_time) > 0) {
            remove_first(&current);
        } else {
            current = current->next;
        }
    }
}

