#include <pthread.h>

typedef struct UEConnectionStatus {
    int id;
    bool connected;
} UEConnectionStatus;

struct DynamicCollection {
    UEConnectionStatus **elements;
    int size;
    pthread_mutex_t lock;
};

DynamicCollection* dynamic_collection_create(int initial_size) {
    DynamicCollection *collection = malloc(sizeof(DynamicCollection));
    collection->size = initial_size;
    collection->elements = malloc(collection->size * sizeof(UEConnectionStatus *));
    pthread_mutex_init(&collection->lock, NULL);
    return collection;
}

void dynamic_collection_insert(DynamicCollection *collection, UEConnectionStatus *element) {
    pthread_mutex_lock(&collection->lock);
    if (collection->size == 0) {
        collection->elements = realloc(collection->elements, sizeof(UEConnectionStatus *) * 2);
        collection->size *= 2;
    }
    collection->elements[collection->size] = element;
    collection->size++;
    pthread_mutex_unlock(&collection->lock);
}

void dynamic_collection_evict(DynamicCollection *collection) {
    pthread_mutex_lock(&collection->lock);
    if (collection->size > 0) {
        free(collection->elements[--collection->size]);
    }
    pthread_mutex_unlock(&collection->lock);
}

int dynamic_collection_size(const DynamicCollection *collection) {
    return collection->size;
}
