#include <chrono>

class L2CacheAccessRecord {
public:
    uint64_t accessTimestamp;
    uint64_t memoryAddress;
    bool cacheHitStatus;

    // Constructor
    L2CacheAccessRecord(uint64_t timestamp, uint64_t address, bool hit) 
        : accessTimestamp(timestamp), memoryAddress(address), cacheHitStatus(hit) {}

    // Destructor
    ~L2CacheAccessRecord() {}
};

class L2CacheManager {
private:
    std::vector<L2CacheAccessRecord> records;
    mutable std::mutex recordMutex;
    std::condition_variable cv;

public:
    void addRecord(L2CacheAccessRecord* record) {
        std::unique_lock<std::mutex> lock(recordMutex);
        records.push_back(*record);
        cv.notify_all();
    }

    L2CacheAccessRecord* getRecord(size_t index) {
        std::lock_guard<std::mutex> lock(recordMutex);
        if (index >= records.size()) {
            return nullptr;
        }
        return &records[index];
    }

    void filterRecords(uint64_t timestamp, bool hitStatus) {
        std::unique_lock<std::mutex> lock(recordMutex);
        records.erase(std::remove_if(records.begin(), records.end(),
            [&](const L2CacheAccessRecord& record) {
                return record.accessTimestamp < timestamp || record.cacheHitStatus != hitStatus;
            }), records.end());
    }

    void sortRecords() {
        std::lock_guard<std::mutex> lock(recordMutex);
        std::sort(records.begin(), records.end(),
            [](const L2CacheAccessRecord& a, const L2CacheAccessRecord& b) {
                return a.accessTimestamp < b.accessTimestamp;
            });
    }

    // Constructor
    L2CacheManager() {}

    // Destructor
    ~L2CacheManager() {}
};

// Example usage:
int main() {
    L2CacheAccessRecord record1(100, 0x12345678, true);
    L2CacheAccessRecord record2(200, 0x98765432, false);

    L2CacheManager cache;
    std::thread t1([&cache]() {
        while (true) {
            cache.addRecord(&record1);
            std::this_thread::sleep_for(std::chrono::milliseconds(100));
        }
    });

    std::thread t2([&cache]() {
        while (true) {
            L2CacheAccessRecord* record = cache.getRecord(0);
            if (record != nullptr) {
                // Process the record
                printf("Received record: %x, %d\n", record->memoryAddress, record->cacheHitStatus);
            }
            std::this_thread::sleep_for(std::chrono::milliseconds(50));
        }
    });

    t1.join();
    t2.join();

    return 0;
}

