}

// Function to count disjoint pairs in an integer array using Union-Find
int countDisjointPairs(const std::vector<int>& arr) {
    int disjointPairCount = 0;

    // Initialize the parent array for Union-Find
    std::vector<int> parent(arr.size());

    for (int i = 0; i < arr.size(); ++i) {
        parent[i] = i;
    }

    // Iterate through the array to count disjoint pairs
    for (int i = 0; i < arr.size(); ++i) {
        for (int j = i + 1; j < arr.size(); ++j) {
            if (find(parent, i) != find(parent, j)) {
                // Update parent arrays and increment the disjoint pair count
                unionSets(parent, i, j);
                disjointPairCount++;
            }
        }
    }

    return disjointPairCount;
}

// Helper function to find a set in Union-Find
int find(std::vector<int>& parent, int x) {
    if (parent[x] != x) {
        parent[x] = find(parent, parent[x]);
    }
    return parent[x];
}

// Helper function to union sets in Union-Find
void unionSets(std::vector<int>& parent, int x, int y) {
    int rootX = find(parent, x);
    int rootY = find(parent, y);

    if (rootX != rootY) {
        parent[rootY] = rootX;
    }
}

