#include "redis_client.h"
#include "postgres_client.h"
#include "kafka_client.h"

// Define the NFAPI_CRC_INDICATION_PDU_T structure
typedef struct {
    uint8_t rx_ue_info_tag;
    uint16_t rnti;
    uint8_t crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the function prototype
void generateAndPersistNFAPDUs(int N, int *pdu_list);

// Function implementation
void generateAnd PersistNFAPDUs(int N, int *pdu_list) {
    // Initialize Redis client
    redis_client_t *redis = redis_client_init();
    if (!redis) {
        fprintf(stderr, "Error initializing Redis client\n");
        return;
    }

    // Initialize PostgreSQL client
    postgres_client_t *postgres = postgres_client_init();
    if (!postgres) {
        fprintf(stderr, "Error initializing PostgreSQL client\n");
        redis_client_free(redis);
        return;
    }

    // Initialize Kafka client
    kafka_client_t *kafka = kafka_client_init();
    if (!kafka) {
        fprintf(stderr, "Error initializing Kafka client\n");
        postgres_client_free(postgres);
        redis_client_free(redis);
        return;
    }

    // Validate input parameters
    if (N < 1 || N > 10000) {
        fprintf(stderr, "Invalid value for N: %d. Must be between 1 and 10,000.\n", N);
        kafka_client_free(kafka);
        postgres_client_free(postgres);
        redis_client_free(redis);
        return;
    }

    // Generate the specified number of structures
    NFAPI_CRC_INDICATION_PDU_T *pdu_list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    for (int i = 0; i < N; i++) {
        pdu_list[i].rx_ue_info_tag = rand() % 256;
        pdu_list[i].rnti = rand() % 65536;
        pdu_list[i].crc_indication_rel8_tag = rand() % 256;
    }

    // Persist the structures in Redis
    for (int i = 0; i < N; i++) {
        redis_client_set(redis, "pdu_list", pdu_list[i]);
    }

    // Commit changes to PostgreSQL database
    postgres_client_commit(postgres);

    // Produce the structures to Kafka topic
    kafka_client_produce(kafka, "pdu_topic", pdu_list);

    // Clean up resources
    free(pdu_list);
    kafka_client_free(kafka);
    postgres_client_free(postgres);
    redis_client_free(redis);
}

// Function prototypes for Redis, PostgreSQL, and Kafka clients
void redis_client_init();
void postgres_client_init();
void kafka_client_init();
void redis_client_set(redis_client_t *redis, const char *key, NFAPI_CRC_INDICATION_PDU_T pdu);
void postgres_client_commit(postgres_client_t *postgres);
void kafka_client_produce(kafka_client_t *kafka, const char *topic, NFAPI_CRC_INDICATION_PDU_T pdu);

int main() {
    int N = 1000; // Change this value to specify the number of structures
    int *pdu_list;
    generateAndPersistNFAPDUs(N, &pdu_list);
    return 0;
}
