#include <stdlib.h>
#include <pthread.h>

#define UE_CONNECTION_STATUS_CACHE_SIZE 16
#define UE_CONNECTION_STATUS_LOCK_TIMEOUT 1000

typedef struct {
    int connection_id;
    char* status_text;
} UEConnectionStatus;

// Structure to represent a cache entry
typedef struct {
    UEConnectionStatus* status;
    pthread_mutex_t lock;
} UEConnectionStatusCacheEntry;

// Structure to manage the dynamic collection of UEConnectionStatus structures
typedef struct {
    UEConnectionStatus** statuses;
    size_t capacity;
    pthread_rwlock_t lock;
    pthread_mutex_t resize_lock;
    int cache_count;
    UEConnectionStatusCacheEntry* cache;
} UEConnectionStatusManager;

// Function to create a new UEConnectionStatusManager instance
UEConnectionStatusManager* ue_connection_status_manager_create(size_t initial_capacity) {
    UEConnectionStatusManager* manager = malloc(sizeof(UEConnectionStatusManager));
    manager->statuses = calloc(initial_capacity, sizeof(UEConnectionStatus*));
    manager->capacity = initial_capacity;
    pthread_rwlock_init(&manager->lock, NULL);
    pthread_mutex_init(&manager->resize_lock, NULL);
    manager->cache_count = 0;
    manager->cache = NULL;
    return manager;
}

// Function to add a new UEConnectionStatus structure to the collection
void ue_connection_status_manager_add(UEConnectionStatusManager* manager, UEConnectionStatus* status) {
    pthread_rwlock_wrlock(&manager->lock);
    if (manager->capacity == 0 || manager->cache_count >= manager->capacity) {
        // Resize the array and update the cache count
        size_t new_capacity = manager->capacity * 2 + 1;
        UEConnectionStatus** new_statuses = realloc(manager->statuses, new_capacity * sizeof(UEConnectionStatus*));
        manager->statuses = new_statuses;
        manager->capacity = new_capacity;
    }
    // Add the new status to the array
    for (size_t i = 0; i < manager->cache_count; i++) {
        if (!manager->statuses[i]) {
            manager->statuses[i] = status;
            break;
        }
    }
    pthread_rwlock_unlock(&manager->lock);
}

// Function to retrieve a UEConnectionStatus structure from the collection
UEConnectionStatus* ue_connection_status_manager_get(UEConnectionStatusManager* manager, int connection_id) {
    pthread_rwlock_rdlock(&manager->lock);
    for (size_t i = 0; i < manager->cache_count; i++) {
        if (manager->statuses[i]->connection_id == connection_id) {
            // Return the requested status
            return manager->statuses[i]->status;
        }
    }
    pthread_rwlock_unlock(&manager->lock);
    return NULL;
}

// Function to remove a UEConnectionStatus structure from the collection
void ue_connection_status_manager_remove(UEConnectionStatusManager* manager, int connection_id) {
    pthread_rwlock_wrlock(&manager->lock);
    for (size_t i = 0; i < manager->cache_count; i++) {
        if (manager->statuses[i]->connection_id == connection_id) {
            // Remove the status from the array
            memmove(&manager->statuses[i], &manager->statuses[i + 1], (manager->cache_count - i - 1) * sizeof(UEConnectionStatus*));
            manager->cache_count--;
            break;
        }
    }
    pthread_rwlock_unlock(&manager->lock);
}

// Function to release memory and destroy the UEConnectionStatusManager instance
void ue_connection_status_manager_destroy(UEConnectionStatusManager* manager) {
    for (size_t i = 0; i < manager->cache_count; i++) {
        free(manager->statuses[i]->status_text);
        free(manager->statuses[i]);
    }
    free(manager->statuses);
    pthread_rwlock_destroy(&manager->lock);
    pthread_mutex_destroy(&manager->resize_lock);
    free(manager);
}

// Function to create a new UEConnectionStatusCacheEntry instance
UEConnectionStatusCacheEntry* ue_connection_status_cache_entry_create(UEConnectionStatus* status) {
    UEConnectionStatusCacheEntry* entry = malloc(sizeof(UEConnectionStatusCacheEntry));
    entry->status = status;
    pthread_mutex_init(&entry->lock, NULL);
    return entry;
}

// Function to add a cache entry to the cache
void ue_connection_status_manager_add_cache_entry(UEConnectionStatusManager* manager, UEConnectionStatus* status) {
    // Check if the cache is full or has reached its maximum size
    if (manager->cache_count >= UE_CONNECTION_STATUS_CACHE_SIZE) {
        // Evict an entry from the cache based on its connection_id
        for (size_t i = 0; i < manager->cache_count; i++) {
            if (manager->statuses[i]->connection_id <= status->connection_id) {
                // Remove the evicted entry from the array and update the cache count
                memmove(&manager->statuses[i], &manager->statuses[i + 1], (manager->cache_count - i - 1) * sizeof(UEConnectionStatus*));
                manager->cache_count--;
                break;
            }
        }
    }
    // Add the new status to the cache
    UEConnectionStatusCacheEntry* entry = ue_connection_status_cache_entry_create(status);
    pthread_mutex_lock(&entry->lock);
    manager->statuses[manager->cache_count++] = status;
    pthread_mutex_unlock(&entry->lock);
}

// Function to get a connection status from the cache
UEConnectionStatus* ue_connection_status_manager_get_cache(UEConnectionStatusManager* manager, int connection_id) {
    for (size_t i = 0; i < manager->cache_count; i++) {
        if (manager->statuses[i]->connection_id == connection_id) {
            // Return the requested status from the cache
            return manager->statuses[i]->status;
        }
    }
    return NULL;
}

// Function to remove a connection status from the cache
void ue_connection_status_manager_remove_cache(UEConnectionStatusManager* manager, int connection_id) {
    for (size_t i = 0; i < manager->cache_count; i++) {
