typedef struct {
    UEConnectionStatus* connections; // Array of connection statuses
    int num_connections; // Number of current connections
    pthread_mutex_t lock; // Mutex for thread-safe operations
} UEConnectionManager;

// Function to initialize the connection manager
void ue_connection_manager_init(UEConnectionManager* manager) {
    manager->num_connections = 0;
    pthread_mutex_init(&manager->lock, NULL);
}

// Function to add a new connection status to the collection
void ue_add_connection_status(UEConnectionManager* manager, UEConnectionStatus* conn) {
    pthread_mutex_lock(&manager->lock);

    // Allocate memory for a new array element if necessary
    if (manager->num_connections >= sizeof(manager->connections) / sizeof(manager->connections[0])) {
        manager->connections = realloc(manager->connections, (manager->num_connections + 1) * sizeof(UEConnectionStatus));
    }

    // Copy the new connection status into the array
    manager->connections[manager->num_connections++] = *conn;

    pthread_mutex_unlock(&manager->lock);
}

// Function to remove a connection status from the collection
void ue_remove_connection_status(UEConnectionManager* manager, int id) {
    pthread_mutex_lock(&manager->lock);

    // Iterate through the connections array to find and remove the specified connection
    for (int i = 0; i < manager->num_connections; i++) {
        if (manager->connections[i].id == id) {
            // Shift all subsequent connections up one position
            memmove(&manager->connections[i], &manager->connections[i + 1], sizeof(UEConnectionStatus) * (manager->num_connections - i - 1));
            manager->num_connections--;
            break;
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

