typedef struct {
    UEConnectionStatus **connections;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} ConnectionManager;

// Initialize the ConnectionManager
ConnectionManager *connection_manager_init(size_t initial_capacity) {
    ConnectionManager *manager = (ConnectionManager *)malloc(sizeof(ConnectionManager));
    manager->capacity = initial_capacity;
    manager->size = 0;
    manager->connections = (UEConnectionStatus **)calloc(initial_capacity, sizeof(UEConnectionStatus *));
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

// Add a new UEConnectionStatus to the collection
void connection_manager_add(ConnectionManager *manager, UEConnectionStatus *connection) {
    if (manager->size >= manager->capacity) {
        // Resize the array if it's full
        size_t new_capacity = manager->capacity * 2;
        UEConnectionStatus **new_connections = (UEConnectionStatus **)calloc(new_capacity, sizeof(UEConnectionStatus *));
        for (int i = 0; i < manager->size; i++) {
            new_connections[i] = manager->connections[i];
        }
        free(manager->connections);
        manager->connections = new_connections;
        manager->capacity = new_capacity;
    }
    manager->connections[manager->size++] = connection;
}

// Remove a UEConnectionStatus from the collection
void connection_manager_remove(ConnectionManager *manager, int connection_id) {
    for (int i = 0; i < manager->size; i++) {
        if (manager->connections[i]->connection_id == connection_id) {
            memmove(&manager->connections[i], &manager->connections[i + 1], (manager->size - i - 1) * sizeof(UEConnectionStatus *));
            manager->size--;
            return;
        }
    }
}

// Get a UEConnectionStatus from the collection
