    void eventLoop() {
        std::unique_lock<std::mutex> lock(mtx_);
        cv_.wait(lock, [this] { return !events_.empty(); });

        while (!events_.empty()) {
            auto& event = events_.front();
            processEvent(event);
            events_.pop_front();
        }
    }

