// Add a UEConnectionStatus to the collection
void connection_manager_add(ConnectionManager* manager, UEConnectionStatus* connection) {
    pthread_mutex_lock(&manager->lock);
    manager->connections = (UEConnectionStatus**)realloc(manager->connections, (manager->size + 1) * sizeof(UEConnectionStatus*));
    manager->connections[manager->size] = connection;
    manager->size++;
    pthread_mutex_unlock(&manager->lock);
}

// Remove a UEConnectionStatus from the collection
void connection_manager_remove(ConnectionManager* manager, int index) {
    pthread_mutex_lock(&manager->lock);
    if (index >= 0 && index < manager->size) {
        memmove(&manager->connections[index], &manager->connections[index + 1], (manager->size - index - 1) * sizeof(UEConnectionStatus*));
        free(manager->connections[manager->size - 1]);
        manager->size--;
    }
    pthread_mutex_unlock(&manager->lock);
}

// Get a UEConnectionStatus from the collection
