// SensorReading class
class SensorReading {
public:
    std::string sensorId;
    double value;
    time_t timestamp;

    SensorReading(std::string id, double val, time_t ts) : 
        sensorId(id), value(val), timestamp(ts) {}
};

// SensorManager class (framework)
class SensorManager {
private:
    std::mutex mtx;
    std::condition_variable cv;
    bool running = true;

public:
    std::vector<SensorReading> readings;
    int64_t readingCount = 0;

    void addReading(SensorReading reading) {
        std::unique_lock<std::mutex> lock(mtx);
        readings.push_back(reading);
        ++readingCount;
        cv.notify_one();
    }

    bool isRunning() { return running; }

    // cloud service upload interface
    virtual void uploadReadings() = 0;

    // filter and aggregate sensor readings
    std::vector<SensorReading> filterAndAggregate(int threshold, int window) {
        std::vector<SensorReading> filteredReadings;
        for (auto& reading : readings) {
            if (reading.value > threshold && timeDiff(reading.timestamp) < window) {
                filteredReadings.push_back(reading);
            }
        }
        return filteredReadings;
    }

private:
    int64_t timeDiff(time_t timestamp) {
        time_t now = time(nullptr);
        return now - timestamp;
    }
};

