    UEConnectionManager* manager = (UEConnectionManager*)malloc(sizeof(UEConnectionManager));
    manager->connections = NULL;
    manager->numConnections = 0;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

// Add a new connection to the dynamic collection
void uecm_add_connection(UEConnectionManager* manager, UEConnectionStatus* connection) {
    pthread_mutex_lock(&manager->lock);
    manager->connections = (UEConnectionStatus**)realloc(manager->connections, (manager->numConnections + 1) * sizeof(UEConnectionStatus*));
    manager->connections[manager->numConnections++] = connection;
    pthread_mutex_unlock(&manager->lock);
}

// Remove a connection from the dynamic collection
void uecm_remove_connection(UEConnectionManager* manager, UEConnectionStatus* connection) {
    pthread_mutex_lock(&manager->lock);
    int i;
    for (i = 0; i < manager->numConnections; i++) {
        if (manager->connections[i] == connection) {
            // Shift elements after the removed connection
            for (; i < manager->numConnections - 1; i++)
                manager->connections[i] = manager->connections[i + 1];
            break;
        }
    }
    free(connection);
    pthread_mutex_unlock(&manager->lock);
}

