void nfa_api_crc_indication_pdu_t_array_insert(NfaApiCrcIndicationPduTArray* arr, int index, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (index > arr->size || index < 0) {
        LOG_ERROR("Invalid index for insertion.");
        return;
    }
    if (arr->capacity <= arr->size) {
        arr->capacity *= 2;
        arr->data = realloc(arr->data, sizeof(NFAPI_CRC_INDICATION_PDU_T) * arr->capacity);
    }
    memmove(&arr->data[index + 1], &arr->data[index], sizeof(NFAPI_CRC_INDICATION_PDU_T) * (arr->size - index));
    arr->data[index] = pdu;
    arr->size++;
}

void nfa_api_crc_indication_pdu_t_array_delete(NfaApiCrcIndicationPduTArray* arr, int index) {
    if (index >= arr->size || index < 0) {
        LOG_ERROR("Invalid index for deletion.");
        return;
    }
    memmove(&arr->data[index], &arr->data[index + 1], sizeof(NFAPI_CRC_INDICATION_PDU_T) * (arr->size - index - 1));
