// Define the NFAPI CRC indication PDU structure
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define a linked list node for storing PDUs
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    struct Node* next;
} Node;

// Function to process a continuous stream of NFAPIS PDU from an external source
void processNfapiPduStream(Node** head, pthread_mutex_t* mutex) {
    // Allocate memory for a new node
    Node* newNode = (Node*)malloc(sizeof(Node));

    if (!newNode) {
        printf("Memory allocation failed.\n");
        return;
    }

    // Initialize the PDU structure
    int pduInfoTag = rand();
    int rnti = rand() % 65535 + 1;
    int crcIndRel8Tag = rand();
    int crcFlag = rand() % 2;

    newNode->pdu.RX_UE_INFORMATION_TAG = pduInfoTag;
    newNode->pdu.RNTI = rnti;
    newNode->pdu.CRC_INDICATION_REL8_TAG = crcIndRel8Tag;
    newNode->pdu.CRCFLAG = crcFlag;

    // Add the new node to the linked list
    pthread_mutex_lock(mutex);
    Node* current = *head;
    if (!current) {
        *head = newNode;
    } else {
        while (current->next) {
            current = current->next;
        }
        current->next = newNode;
    }
    pthread_mutex_unlock(mutex);
}

// Function to print the linked list
void printLinkedList(Node* head) {
    Node* current = head;
    while (current) {
        printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRC_INDICATION_REL8_TAG: %d, CRCFLAG: %d\n",
               current->pdu.RX_UE_INFORMATION_TAG, current->pdu.RNTI,
               current->pdu.CRC_INDICATION_REL8_TAG, current->pdu.CRCFLAG);
        current = current->next;
    }
}

int main() {
    Node* head = NULL;
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    for (int i = 0; i < 100000; i++) {
        processNfapiPduStream(&head, &mutex);
    }

    printLinkedList(head);

    return 0;
}
