#include <functional>

class SessionCache {
public:
    SessionCache(int capacity) : cache_(capacity), lock_(), cond_(cache_.empty()), max_size_(capacity) {}

    void put(const std::string& key, const std::string& value) {
        std::unique_lock<std::mutex> lk(lock_);
        if (cond_.wait_for(lk, std::chrono::milliseconds(100)) == std::cv_status::timeout) {
            // cache is empty
            cache_[key] = value;
            cond_.notify_one();
            return;
        }
        auto it = cache_.find(key);
        if (it != cache_.end()) {
            lk.unlock();
            return; // key already exists
        }
        if (cache_.size() >= max_size_) {
            // evict LRU item
            std::string lru_key;
            auto lru_it = (--cache_.rbegin())->first;
            lk.unlock();
            cache_.erase(lru_it);
            lk.lock();
        }
        cache_[key] = value;
    }

    void get(const std::string& key, std::string& result) {
        std::unique_lock<std::mutex> lk(lock_);
        if (cond_.wait_for(lk, std::chrono::milliseconds(100)) == std::cv_status::timeout) {
            // cache is empty
            return; // not found
        }
        auto it = cache_.find(key);
        if (it != cache_.end()) {
            result = it->second;
            lk.unlock();
            return; // found
        }
    }

private:
    std::map<std::string, std::string> cache_;
    std::mutex lock_;
    std::condition_variable cond_;
    int max_size_;
};

int main() {
    SessionCache cache(1000000); // 1 million capacity

    // ... use the cache ...

    return 0;
}

