import os
import hashlib
from cryptography.hazmat.primitives import hashes
from cryptography.hazmat.primitives.kdf.pbkdf2 import PBKDF2HMAC

def encrypt_file(file_path, password):
    # Compute MD5 and SHA-256 hashes in parallel for large files
    md5_hash = hashlib.md5(open(file_path, 'rb').read()).hexdigest()
    sha256_hash = hashlib.sha256(open(file_path, 'rb').read()).hexdigest()

    # Derive an AES-256-CBC encryption key from file hashes and password
    salt = os.urandom(16)
    kdf = PBKDF2HMAC(
        algorithm=hashes.SHA256(),
        length=32,
        salt=salt,
        iterations=100000,
    )
    key = kdf.derive(password.encode())

    # Encrypt file using AES-256-CBC
    with open(file_path, 'rb') as f:
        file_data = f.read()

    encrypted_file_data = aes_encrypt(file_data, key)

    # Store encrypted file data and derived key
    with open('encrypted_' + file_path, 'wb') as f:
        f.write(encrypted_file_data)

def verify_integrity(file_path):
    # Verify integrity of encrypted file using HMAC-SHA256
    with open(file_path, 'rb') as f:
        encrypted_file_data = f.read()

    hmac_hash = hashlib.sha256(encrypted_file_data).hexdigest()
    return hmac_hash
