#include <unordered_map>
#include <mutex>
#include <thread>
#include <chrono>
#include <atomic>

struct UEConnectionStatus {
    int id;
    std::string status;
    time_t lastUpdated;
};

class UEConnectionManager {
public:
    UEConnectionManager() : _ttl(600), _evictionInterval(1000) {}

    void addConnection(const UEConnectionStatus& connection) {
        std::lock_guard<std::mutex> lock(_mutex);
        _connections[connection.id] = connection;
        _lastUpdatedTimepoints[connection.id] = time(NULL);
    }

    bool updateConnection(int id, const UEConnectionStatus& newStatus) {
        std::lock_guard<std::mutex> lock(_mutex);
        if (_connections.find(id) == _connections.end()) return false;

        _connections[id] = newStatus;
        _lastUpdatedTimepoints[id] = time(NULL);

        // Check TTL
        if (time(NULL) - _lastUpdatedTimepoints[id] > _ttl) {
            removeConnection(id);
            return true;  // Connection removed due to TTL expiration
        }

        return false;  // Connection updated successfully
    }

    void removeConnection(int id) {
        std::lock_guard<std::mutex> lock(_mutex);
        _connections.erase(id);
        _lastUpdatedTimepoints.erase(id);
    }

    UEConnectionStatus getConnections() const {
        std::lock_guard<std::mutex> lock(_mutex);
        return _connections;
    }

private:
    std::unordered_map<int, UEConnectionStatus> _connections;
    std::unordered_map<int, time_t> _lastUpdatedTimepoints;
    mutable std::mutex _mutex;
    atomic_int _ttl;
    atomic_int _evictionInterval;
};

