```cpp
#include <iostream>
#include <mutex>
#include <condition_variable>
#include <map>
#include <thread>
#include <chrono>

class UserSessionMetrics {
public:
    UserSessionMetrics() : lock_(std::make_unique<std::mutex>()),
                            cond_(std::make_unique<std::condition_variable>()) {}

    void addMetric(const std::string& userId, const std::string& metricName,
                   int value) {
        std::unique_lock<std::mutex> lock(*lock_);
        metrics_[userId][metricName] = value;
        cond_.notify_one();
    }

    bool getMetrics(const std::string& userId, std::map<std::string, int>& metrics) {
        std::unique_lock<std::mutex> lock(*lock_);
        while (metrics_.find(userId) == metrics_.end()) {
            cond_.wait(lock);
        }
        metrics = metrics_[userId];
        return true;
    }

private:
    struct MetricMap {
        std::map<std::string, int> metrics;
    };

    std::unique_ptr<std::mutex> lock_;
    std::unique_ptr<std::condition_variable> cond_;
    std::map<std::string, MetricMap> metrics_;
};

int main() {
    UserSessionMetrics metrics;

    // Add some metrics
    std::thread t1([&metrics]() {
        for (int i = 0; i < 10; ++i) {
            metrics.addMetric("user1", "clicks", i);
            std::this_thread::sleep_for(std::chrono::seconds(1));
        }
    });

    // Get some metrics
    std::map<std::string, int> userMetrics;
    t1.join();
    while (!metrics.getMetrics("user1", userMetrics)) {
        std::this_thread::yield();
    }

    for (const auto& metric : userMetrics) {
        std::cout << "Metric: " << metric.first << ", Value: " << metric.second << std::endl;
    }

    return 0;
}
