#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define UE_CONNECTION_STATUS_MAX 1024
#define UE_CONNECTION_STATUS_TTL 300 // seconds
#define UE_CONNECTION_STATUS_LOCKING_STRATEGY_FINE_GRAINED

typedef struct {
    int connection_id;
    char ip_address[16];
    int status;
} UEConnectionStatus;

typedef struct {
    pthread_mutex_t lock;
    UEConnectionStatus *connections;
    size_t capacity;
    size_t used;
} UEConnectionStatusManager;

UEConnectionStatusManager ue_conn_mgr = {0};

void ue_conn_mgr_init() {
    ue_conn_mgr.capacity = 16;
    ue_conn_mgr.used = 0;
    pthread_mutex_init(&ue_conn_mgr.lock, NULL);
}

int ue_conn_mgr_resize(int new_capacity) {
    UEConnectionStatus *new_connections = (UEConnectionStatus *)malloc(new_capacity * sizeof(UEConnectionStatus));
    if (!new_connections)
        return -1;

    pthread_mutex_lock(&ue_conn_mgr.lock);
    memmove(new_connections, ue_conn_mgr.connections, ue_conn_mgr.used * sizeof(UEConnectionStatus));
    free(ue_conn_mgr.connections);
    ue_conn_mgr.connections = new_connections;
    ue_conn_mgr.capacity = new_capacity;
    pthread_mutex_unlock(&ue_conn_mgr.lock);

    return 0;
}

void ue_conn_add(UEConnectionStatus *conn) {
    if (ue_conn_mgr.used >= ue_conn_mgr.capacity) {
        int new_capacity = ue_conn_mgr.capacity * 2;
        if (ue_conn_mgr_resize(new_capacity)) {
            printf("Error resizing connection manager: %d\n", new_capacity);
            return;
        }
    }

    pthread_mutex_lock(&ue_conn_mgr.lock);
    UEConnectionStatus *new_connections = (UEConnectionStatus *)malloc((ue_conn_mgr.used + 1) * sizeof(UEConnectionStatus));
    if (!new_connections)
        return;

    memmove(new_connections, ue_conn_mgr.connections, ue_conn_mgr.used * sizeof(UEConnectionStatus));
    free(ue_conn_mgr.connections);
    ue_conn_mgr.connections = new_connections;
    pthread_mutex_unlock(&ue_conn_mgr.lock);

    // Add the connection
    conn->status = 1; // Set status to "connected"
    ue_conn_mgr.connections[ue_conn_mgr.used] = *conn;
    ue_conn_mgr.used++;
}

int main() {
    ue_conn_mgr_init();
    UEConnectionStatus conn1 = {123, "192.168.1.100", 1};
    UEConnectionStatus conn2 = {456, "192.168.1.200", 0};

    ue_conn_add(&conn1);
    ue_conn_add(&conn2);

    return 0;
}

