            "Isaiah", "Jeremiah", "Lamentations", "Ezekiel", "Daniel", "Hosea", "Joel", "Amos", "Obadiah",
            "Jonah", "Micah", "Nahum", "Habakkuk", "Zephaniah", "Haggai", "Zechariah", "Malachi"};

    static {
        for (int i = 0; i < 39; i++) {
            String[] patternComponents = BOOK_NAMES[i].split(" ");
            StringBuilder patternBuilder = new StringBuilder();
            for (String component : patternComponents) {
                if (!component.equalsIgnoreCase("Of")) {
                    patternBuilder.append("(?i:").append(component).append(")");
                    patternBuilder.append("|");
                }
            }
            PATTERNS[i] = Pattern.compile(patternBuilder.toString().substring(0, patternBuilder.length() - 1));
        }
    }

    public static Object extractMentions(String text) {
        Object bookFrequencyMap = new java.util.HashMap<>();
        for (Pattern pattern : PATTERNS) {
            Matcher matcher = pattern.matcher(text);
            while (matcher.find()) {
                String bookName = matcher.group();
                if (!bookFrequencyMap.containsKey(bookName)) {
                    ((HashMap) bookFrequencyMap).put(bookName, 1);
                } else {
                    int frequency = (int) ((HashMap) bookFrequencyMap).get(bookName) + 1;
                    ((HashMap) bookFrequencyMap).put(bookName, frequency);
                }
            }
        }
        return bookFrequencyMap;
    }
}
