int* fetch_data(const char* api_url) {
    // Simulate API call
    int* data = (int*)malloc(MAX_CACHE_SIZE * sizeof(int));
    for (int i = 0; i < MAX_CACHE_SIZE; i++) {
        if (rand() % 2 == 0) { // 50% chance of valid integer
            data[i] = rand() % (MAX_INT + 1);
        } else {
            data[i] = -1; // invalid integer
        }
    }
    return data;
}

// Function to validate integers against predefined range and store in cache
void validate_data(int* data, int size) {
    for (int i = 0; i < size; i++) {
        if (data[i] >= 1 && data[i] <= MAX_INT) {
            pthread_mutex_lock(&cache.mutex);
            // Dynamically expand array if necessary
            if (cache.data == NULL || cache.data[cache.data ? cache.data[0] : 0] + 1 > i) {
                int* new_data = (int*)realloc(cache.data, (i + 1) * sizeof(int));
                if (!new_data) {
                    pthread_mutex_unlock(&cache.mutex);
                    return;
                }
                cache.data = new_data;
            }
            for (int j = 0; j < i; j++) {
                if (data[j] >= 1 && data[j] <= MAX_INT) {
                    cache.data[cache.data ? cache.data[0] : 0]++;
                } else {
                    break;
                }
            }
            pthread_mutex_unlock(&cache.mutex);
        }
    }
}

// Function to print the largest integer and frequency distribution
void analyze_data() {
    pthread_mutex_lock(&cache.mutex);
    if (cache.data) {
        int max_val = cache.data[0];
        for (int i = 1; i <= MAX_INT; i++) {
            while (i > max_val && i - 1 < cache.data ? cache.data[0] : 0) {
                i--;
            }
            if (cache.data[i]) {
                printf("Largest integer: %d\n", i);
                for (int j = 1; j <= MAX_INT; j++) {
                    printf("Frequency of %d: %d\n", j, cache.data[j]);
                }
                break;
            }
        }
    }
    pthread_mutex_unlock(&cache.mutex);
}

// Function to prioritize and process data streams based on urgency
void* process_data(void* api_url) {
    int* data = fetch_data((const char*)api_url);
    validate_data(data, sizeof(data) / sizeof(data[0]));
    free(data);
    return NULL;
}

int main() {
