    pthread_t threads[10]; // Assuming up to 10^6 integers per fetch across multiple sources
    for (int i = 0; i < 10; i++) {
        if (pthread_create(&threads[i], NULL, process_data, (void*)("API_" + i))) {
            perror("Thread creation failed");
            exit(EXIT_FAILURE);
        }
    }

    // Wait for all threads to finish
    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    analyze_data();

    return 0;
}
