// Initialize the connection manager
UEConnectionManager* ue_connection_manager_init(size_t initial_capacity) {
    UEConnectionManager* manager = (UEConnectionManager*)malloc(sizeof(UEConnectionManager));
    manager->connections = (UEConnectionStatus**)malloc(initial_capacity * sizeof(UEConnectionStatus*));
    manager->capacity = initial_capacity;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

// Add a new connection status to the manager
void ue_connection_manager_add(UEConnectionManager* manager, UEConnectionStatus* connection) {
    pthread_mutex_lock(&manager->lock);
    // Resize if necessary
    if (manager->capacity <= manager->connections[0]) {
        size_t new_capacity = manager->capacity * 2;
        manager->connections = (UEConnectionStatus**)realloc(manager->connections, new_capacity * sizeof(UEConnectionStatus*));
        manager->capacity = new_capacity;
    }
    // Add the connection
    manager->connections[manager->connections[0]] = connection;
    manager->connections[0]++;
    pthread_mutex_unlock(&manager->lock);
}

// Remove a connection status from the manager
void ue_connection_manager_remove(UEConnectionManager* manager, UEConnectionStatus* connection) {
    pthread_mutex_lock(&manager->lock);
    // Find and remove the connection
    for (size_t i = 0; i < manager->connections[0]; i++) {
        if (manager->connections[i] == connection) {
            for (size_t j = i + 1; j < manager->connections[0]; j++) {
                manager->connections[j - 1] = manager->connections[j];
            }
            free(connection);
            manager->connections[0]--;
            break;
        }
    }
    pthread_mutex_unlock(&manager->lock);
}

// Check if a connection exists in the manager
int ue_connection_manager_contains(UEConnectionManager* manager, UEConnectionStatus* connection) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->connections[0]; i++) {
        if (manager->connections[i] == connection) {
            pthread_mutex_unlock(&manager->lock);
            return 1;
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return 0;
}

// Free the connection manager
void ue_connection_manager_free(UEConnectionManager* manager) {
    for (size_t i = 0; i < manager->connections[0]; i++) {
        free(manager->connections[i]);
    }
    free(manager->connections);
    free(manager);
}
