        while (running_) {
            // Dequeue the next batch of processed data
            std::vector<ProcessedData> batch;
            while (!dataQueue_.empty()) {
                batch.push_back(dataQueue_.front());
                dataQueue_.pop();
            }

            if (!batch.empty()) {
