int load_resource_bundle(const char* file_path, void** bundle_ptr) {
    FILE *fp = fopen(file_path, "rb");
    if (!fp) {
        printf("Error: File not found!\n");
        return -1;
    }

    fseek(fp, 0, SEEK_END);
    int size = ftell(fp);

    if (size < 0) {
        fclose(fp);
        printf("Error: Incorrect file format!\n");
        return -2;
    }

    *bundle_ptr = malloc(size + 1);
    fread(*bundle_ptr, 1, size, fp);
    fclose(fp);

    ((char*)*bundle_ptr)[size] = '\0';

    return 0;
}

int main() {
    int n = 10;
    NFAPI_CRC_INDICATION_PDU_T* pdu_list = populate_nfapi_crc_indication_pdu(n, stdin);
