    // Check for required fields
    if (!tokenData.contains("access_token") || 
        !tokenData.contains("expires_in") || 
        !tokenData.contains("token_type")) {
        throw std::runtime_error("Invalid OAuth2 token: missing required field(s)");
    }

    // Verify that the token type is 'Bearer'
    if (tokenData["token_type"].asString() != "Bearer") {
        throw std::runtime_error("Invalid OAuth2 token: invalid token type");
    }

    // Check that expires_in is a positive integer
    if (!tokenData["expires_in"].isInteger() || tokenData["expires_in"].getInt64() <= 0) {
        throw std::runtime_error("Invalid OAuth2 token: invalid expires_in value");
    }

    // Optional: verify refresh_token (if present)
    if (tokenData.contains("refresh_token")) {
        // Check that the refresh_token is a valid string
        if (!tokenData["refresh_token"].is_string()) {
            throw std::runtime_error("Invalid OAuth2 token: invalid refresh_token value");
        }
    }
}
