#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>
#include <mysql/mysql.h>

#define MAX_N 1000
#define MAX_THREADS 10
#define BATCH_SIZE 50

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8;
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
MYSQL *mysql_conn;

void* worker(void* arg) {
    int tid = *(int*)arg;
    for(int i=0; i<BATCH_SIZE; i++) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        // populate the pdu structure
        pthread_mutex_lock(&mutex);
        // store the pdu in database
        if(mysql_query(mysql_conn, "INSERT INTO crc_indications (rx_ue_info, rnti, crc_indication_rel8) VALUES (?, ?, ?)", 
                       &pdu.rx_ue_info, &pdu.rnti, &pdu.crc_indication_rel8)) {
            // handle database error
        }
        pthread_mutex_unlock(&mutex);
    }
    return NULL;
}

int create_crc_indications(int num_puds) {
    int i;
    pthread_t threads[MAX_THREADS];
    int* thread_ids = (int*)malloc(MAX_THREADS * sizeof(int));

    for(i=0; i<num_puds; i++) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        // populate the pdu structure
        if(i % BATCH_SIZE == 0) {
            pthread_create(&threads[i/BATCH_SIZE], NULL, worker, &thread_ids[i/BATCH_SIZE]);
        }
    }

    for(i=0; i<num_puds; i++) {
        if(i % BATCH_SIZE == 0) {
            pthread_join(threads[i/BATCH_SIZE], NULL);
        }
    }

    free(thread_ids);

    return 0;
}

int main() {
    // initialize mysql connection
    mysql_conn = mysql_init(NULL);
    mysql_real_connect(mysql_conn, "localhost", "username", "password", "", MYSQL_TCP);

    int num_puds = MAX_N; // number of CRC indication PDU structures to create
    create_crc_indications(num_puds);

    return 0;
}

