#define UE_CONNECTION_STATUS_SIZE sizeof(struct UEConnectionStatus)
#define TTL_DEFAULT 300 // seconds
#define MAX_THREADS 10
#define LOCK_TYPE pthread_rwlock_t

struct UEConnectionStatus {
    char imei[16];
    int status;
};

typedef struct {
    int count;
    struct UEConnectionStatus* connections;
} ConnectionList;

ConnectionList connection_list = {0, NULL};

LOCK_TYPE lock = PTHREAD_RWLOCK_INITIALIZER;

void init_connection_list() {
    pthread_rwlock_init(&lock, NULL);
}

int add_ue_connection(char* imei, int status) {
    pthread_rwlock_wrlock(&lock);

    struct UEConnectionStatus* new_connection = (struct UEConnectionStatus*) malloc(UE_CONNECTION_STATUS_SIZE);
    strcpy(new_connection->imei, imei);
    new_connection->status = status;

    if (!connection_list.connections) {
        connection_list.count = 1;
        connection_list.connections = &new_connection;
    } else {
        connection_list.count++;
        connection_list.connections = (struct UEConnectionStatus*) realloc(connection_list.connections,
                connection_list.count * UE_CONNECTION_STATUS_SIZE);
        connection_list.connections[connection_list.count - 1] = new_connection;
    }

    pthread_rwlock_unlock(&lock);

    return 0;
}

int remove_ue_connection(char* imei) {
    pthread_rwlock_wrlock(&lock);

    for (int i = 0; i < connection_list.count; i++) {
        if (!strcmp(connection_list.connections[i]->imei, imei)) {
            free(connection_list.connections[i]);
            for (int j = i + 1; j < connection_list.count; j++) {
                connection_list.connections[j - 1] = connection_list.connections[j];
            }
            connection_list.count--;
            break;
        }
    }

    pthread_rwlock_unlock(&lock);

    return 0;
}

void update_ue_connection(char* imei, int status) {
    pthread_rwlock_wrlock(&lock);

    for (int i = 0; i < connection_list.count; i++) {
        if (!strcmp(connection_list.connections[i]->imei, imei)) {
            connection_list.connections[i]->status = status;
            break;
        }
    }

    pthread_rwlock_unlock(&lock);
}

void evict_old_connections() {
    pthread_rwlock_wrlock(&lock);

    for (int i = 0; i < connection_list.count; i++) {
        if ((time(NULL) - connection_list.connections[i]->timestamp) > TTL_DEFAULT) {
            free(connection_list.connections[i]);
            for (int j = i + 1; j < connection_list.count; j++) {
                connection_list.connections[j - 1] = connection_list.connections[j];
            }
            connection_list.count--;
        }
    }

    pthread_rwlock_unlock(&lock);
}

void* periodic_update_thread(void*) {
    while (1) {
        // API update logic
        sleep(5); // adjust this value based on your use case
