#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Structure to represent UE connection status
typedef struct {
    int ue_id;
    char imei[16];
    int signal_strength;
} UEConnectionStatus;

// Hash table structure for storing UE connection statuses
typedef struct {
    size_t capacity;
    UEConnectionStatus **entries;
    pthread_mutex_t lock;
} UEHashTable;

// Function to create a new hash table
UEHashTable* ue_hash_table_create(size_t initial_capacity) {
    UEHashTable *hash_table = malloc(sizeof(UEHashTable));
    hash_table->capacity = initial_capacity;
    hash_table->entries = calloc(initial_capacity, sizeof(UEConnectionStatus *));
    pthread_mutex_init(&hash_table->lock, NULL);
    return hash_table;
}

// Function to add a new UE connection status to the hash table
void ue_hash_table_add(UEHashTable *hash_table, int ue_id, char imei[], int signal_strength) {
    pthread_mutex_lock(&hash_table->lock);

    // Find an empty slot in the hash table
    size_t i;
    for (i = 0; i < hash_table->capacity; i++) {
        if (!hash_table->entries[i]) {
            break;
        }
    }

    // If no slots are available, resize the hash table
    if (i == hash_table->capacity) {
        UEHashTable *new_hash_table = ue_hash_table_create(hash_table->capacity * 2);
        for (size_t j = 0; j < hash_table->capacity; j++) {
            new_hash_table->entries[j] = hash_table->entries[j];
        }
        free(hash_table->entries);
        hash_table = new_hash_table;
    }

    // Insert the new UE connection status into the hash table
    UEConnectionStatus *entry = malloc(sizeof(UEConnectionStatus));
    entry->ue_id = ue_id;
    strcpy(entry->imei, imei);
    entry->signal_strength = signal_strength;
    hash_table->entries[i] = entry;

    pthread_mutex_unlock(&hash_table->lock);
}

// Function to remove a UE connection status from the hash table
void ue_hash_table_remove(UEHashTable *hash_table, int ue_id) {
    pthread_mutex_lock(&hash_table->lock);

    // Find the slot containing the UE connection status with the given ID
    size_t i;
    for (i = 0; i < hash_table->capacity; i++) {
        if (hash_table->entries[i] && hash_table->entries[i]->ue_id == ue_id) {
            break;
        }
    }

    // If found, remove the entry and resize the hash table if necessary
    if (i < hash_table->capacity) {
        free(hash_table->entries[i]);
        hash_table->entries[i] = NULL;

        size_t new_capacity = hash_table->capacity / 2;
        UEHashTable *new_hash_table = ue_hash_table_create(new_capacity);
        for (size_t j = 0; j < hash_table->capacity; j++) {
            if (hash_table->entries[j]) {
                ue_hash_table_add(new_hash_table, hash_table->entries[j]->ue_id, hash_table->entries[j]->imei, hash_table->entries[j]->signal_strength);
            }
        }
        free(hash_table->entries);
        hash_table = new_hash_table;
    }

    pthread_mutex_unlock(&hash_table->lock);
}

// Function to get the UE connection status with the given ID from the hash table
UEConnectionStatus* ue_hash_table_get(UEHashTable *hash_table, int ue_id) {
    pthread_mutex_lock(&hash_table->lock);

    // Find the slot containing the UE connection status with the given ID
    size_t i;
    for (i = 0; i < hash_table->capacity; i++) {
        if (hash_table->entries[i] && hash_table->entries[i]->ue_id == ue_id) {
            break;
        }
    }

    // Return the UE connection status if found, or NULL otherwise
    pthread_mutex_unlock(&hash_table->lock);
    return hash_table->entries[i];
}

