import hashlib
import os
import threading

def compute_hashes(filename):
    # Compute MD5 and SHA-256 hashes in parallel for large files
    md5_hash = hashlib.md5()
    sha256_hash = hashlib.sha256()

    with open(filename, 'rb') as file:
        while True:
            chunk = file.read(4096)
            if not chunk:
                break
            md5_hash.update(chunk)
            sha256_hash.update(chunk)

    return {
        'md5': md5_hash.hexdigest(),
        'sha256': sha256_hash.hexdigest()
    }

def derive_encryption_key(password):
    # Derive an AES-256-CBC encryption key using PBKDF2-SHA256
    import pbkdf2
    salt = os.urandom(16)
    key = pbkdf2.pbkdf2_hmac(hash_name='sha256', password=password.encode(), salt=salt, iterations=100000, keylen=32)
    return key

