// Function to create a new connection status list
ConnectionStatusList* new_connection_status_list(size_t initial_capacity) {
    ConnectionStatusList* list = (ConnectionStatusList*)malloc(sizeof(ConnectionStatusList));
    list->connections = (UEConnectionStatus*)calloc(initial_capacity, sizeof(UEConnectionStatus));
    list->capacity = initial_capacity;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

// Function to add a new connection status to the list
void add_connection_status(ConnectionStatusList* list, UEConnectionStatus new_status) {
    if (list->size >= list->capacity / 2) { // Check if list needs resizing
        size_t new_capacity = list->capacity * 2;
        UEConnectionStatus* new_connections = (UEConnectionStatus*)realloc(list->connections, new_capacity * sizeof(UEConnectionStatus));
        list->connections = new_connections;
        list->capacity = new_capacity;
    }
    pthread_mutex_lock(&list->lock);
    list->connections[list->size++] = new_status;
    pthread_mutex_unlock(&list->lock);
}

// Function to remove a connection status from the list
void remove_connection_status(ConnectionStatusList* list, int id) {
    for (int i = 0; i < list->size; i++) {
        if (list->connections[i].id == id) {
            memmove(&list->connections[i], &list->connections[i + 1], (list->size - i - 1) * sizeof(UEConnectionStatus));
            list->size--;
            break;
        }
    }
}

