using MongoDB.Driver;

[ApiController]
[Route("api/[controller]")]
public class UpdateController : ControllerBase
{
    private readonly IMongoDatabase _database;
    private readonly IContentSanitizerService _contentSanitizerService;
    private readonly IDistributedMessageQueue _messageQueue;

    public UpdateController(IMongoDatabase database, IContentSanitizerService contentSanitizerService, IDistributedMessageQueue messageQueue)
    {
        _database = database;
        _contentSanitizerService = contentSanitizerService;
        _messageQueue = messageQueue;
    }

    [HttpPost]
    [Authorize(AuthenticationSchemes = "OAuth2")]
    public async Task<IActionResult> Update([FromBody]UpdateRequest request)
    {
        // Sanitize HTML content
        string sanitizedContent = await _contentSanitizerService.Sanitize(request.Content);

        // Update database and message queue
        await _database.GetCollection<BsonDocument>("pages").UpdateOneAsync(
            Builders<BsonDocument>.Filter.Eq("sectionId", request.SectionId),
            Builders<BsonDocument>.Update.Set("elements." + request.ElementId, sanitizedContent)
        );

        // Enqueue update for asynchronous processing
        await _messageQueue.Enqueue(request);

        return Ok();
    }
}

public class UpdateRequest
{
    public string SectionId { get; set; }
    public string ElementId { get; set; }
    public string Content { get; set; }
}
