    private static final Pattern OLD_TESTAMENT_BOOK_PATTERN = Pattern.compile("[A-Za-z]+ (Genesis|Exodus|Leviticus|Numbers|Deuteronomy|Joshua|Judges|Ruth|1 Samuel|2 Samuel|1 Kings|2 Kings|1 Chronicles|2 Chronicles|Ezra|Nehemiah|Esther|Job|Psalms|Proverbs|Ecclesiastes|Song of Solomon|Isaiah|Jeremiah|Lamentations|Ezekiel|Daniel|Hosea|Joel|Amos|Obadiah|Jonah|Micah|Zephaniah|Haggai|Zechariah|Malachi)");

    public Map<String, Integer> extractBookMentions(String text) {
        Matcher matcher = BIBLE_BOOK_PATTERN.matcher(text);
        while (matcher.find()) {
            String bookName = matcher.group(1).trim();
            BOOK_MENTIONS.put(bookName, BOOK_MENTIONS.getOrDefault(bookName, 0) + 1);
        }
        return BOOK_MENTIONS;
    }

    public Map<String, Integer> extractOldTestamentBookMentions(String text) {
        Matcher matcher = OLD_TESTAMENT_BOOK_PATTERN.matcher(text);
        while (matcher.find()) {
            String bookName = matcher.group(1).trim();
            BOOK_MENTIONS.put(bookName, BOOK_MENTIONS.getOrDefault(bookName, 0) + 1);
        }
        return BOOK_MENTIONS;
    }
}
