// Securely process large files with MD5 and SHA-256 hashes
void secureFileProcessing(const char* filePath) {
    FILE* file = fopen(filePath, "rb");
    if (file != NULL) {
        unsigned char buffer[1024];
        size_t bytesRead;
        while ((bytesRead = fread(buffer, 1, 1024, file)) > 0) {
            // Compute MD5 hash
            unsigned char md5Hash[16];
            MD5_CTX ctx;
            MD5_Init(&ctx);
            MD5_Update(&ctx, buffer, bytesRead);
            MD5_Final(md5Hash, &ctx);

            // Compute SHA-256 hash
            unsigned char sha256Hash[32];
            SHA256_CTX ctxSha256;
            SHA256_Init(&ctxSha256);
            SHA256_Update(&ctxSha256, buffer, bytesRead);
            SHA256_Final(sha256Hash, &ctxSha256);
        }
        fclose(file);
    }
}

