import hashlib
import os

# Define a function to securely compute MD5 and SHA-256 hashes in parallel for large files
def secure_file_processing(file_path):
    # Open the file in binary mode
    with open(file_path, 'rb') as file:
        # Read the file in chunks of 1024 bytes
        buffer = bytearray(1024)
        while True:
            read_bytes = os.read(file.fileno(), buffer)
            if not read_bytes:
                break

            # Compute MD5 hash
            md5_hash = hashlib.md5(buffer[:read_bytes]).digest()

            # Compute SHA-256 hash
            sha256_hash = hashlib.sha256(buffer[:read_bytes]).digest()

    return md5_hash, sha256_hash

# Example usage
md5_hash, sha256_hash = secure_file_processing('large_file.bin')
print(f"MD5 Hash: {md5_hash.hex()}")
print(f"SHA-256 Hash: {sha256_hash.hex()}")

