// Function to create a new UE connection manager
UEConnectionManager* ue_connection_manager_create(size_t initial_capacity) {
    UEConnectionManager* manager = (UEConnectionManager*)malloc(sizeof(UEConnectionManager));
    manager->connections = (UEConnectionStatus*)calloc(initial_capacity, sizeof(UEConnectionStatus));
    manager->capacity = initial_capacity;
    manager->size = 0;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

// Function to add a new UE connection status
int ue_connection_manager_insert(UEConnectionManager* manager, UEConnectionStatus* connection) {
    pthread_mutex_lock(&manager->lock);
    // Check if the size exceeds the capacity and reallocate memory if necessary
    if (manager->size == manager->capacity) {
        manager->capacity *= 2;
        manager->connections = (UEConnectionStatus*)realloc(manager->connections, sizeof(UEConnectionStatus) * manager->capacity);
    }
    manager->connections[manager->size++] = *connection;
    pthread_mutex_unlock(&manager->lock);
    return 0;
}

// Function to evict outdated entries based on TTL
void ue_connection_manager_evict_old_entries(UEConnectionManager* manager) {
    time_t current_time = time(NULL);
    for (size_t i = 0; i < manager->size; ++i) {
        if (current_time - manager->connections[i].timestamp > manager->ttl) {
            // Remove the outdated entry
            memmove(&manager->connections[i], &manager->connections[i + 1], sizeof(UEConnectionStatus) * (manager->size - i - 1));
            manager->size--;
        }
    }
}

