class ResourceUsageMetric {
public:
    std::string instanceId;
    int cpuUsage;
    double memoryUsage;

    ResourceUsageMetric(std::string instanceId, int cpuUsage, double memoryUsage)
        : instanceId(instanceId), cpuUsage(cpuUsage), memoryUsage(memoryUsage) {}
};

class DynamicCollection {
public:
    using LockType = std::unique_lock<std::mutex>;
    using ConditionType = std::condition_variable;

    DynamicCollection() : lock_(lock_), condition_(condition_) {}

    void addMetric(ResourceUsageMetric&& metric) {
        LockType lock(lock_);
        metrics_.push_back(std::move(metric));
    }

    bool removeMetric(const std::string& instanceId) {
        LockType lock(lock_);
        auto it = std::find_if(metrics_.begin(), metrics_.end(),
            [instanceId](const ResourceUsageMetric& metric) {
                return metric.instanceId == instanceId;
            });
        if (it != metrics_.end()) {
            metrics_.erase(it);
            return true;
        }
        return false;
    }

    size_t size() const {
        LockType lock(lock_);
        return metrics_.size();
    }

private:
    std::mutex lock_;
    ConditionType condition_;
    std::vector<ResourceUsageMetric> metrics_;
};

int main() {
    // Create a dynamic collection
    DynamicCollection collection;

    // Add some metrics
    collection.addMetric(ResourceUsageMetric("Instance 1", 10, 0.5));
    collection.addMetric(ResourceUsageMetric("Instance 2", 20, 1.0));
    collection.addMetric(ResourceUsageMetric("Instance 3", 30, 1.5));

    // Check the size
    std::cout << "Collection size: " << collection.size() << std::endl;

    // Remove a metric
    if (collection.removeMetric("Instance 2")) {
        std::cout << "Removed instance 2" << std::endl;
    }

    return 0;
}
