// Define a linked list node structure
typedef struct Node {
    UEConnectionStatus* data;
    struct Node* next;
} Node;

// Define the library's main data structure: a dynamic collection of connection statuses
typedef struct ConnectionCollection {
    Node* head;
    pthread_mutex_t lock; // Fine-grained locking mechanism
    int numConnections; // Number of active connections
} ConnectionCollection;

// Function to create a new connection status node
Node* createConnectionStatusNode(UEConnectionStatus* data) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->data = data;
    newNode->next = NULL;
    return newNode;
}

// Function to add a new connection status to the collection
void addConnectionStatus(ConnectionCollection* collection, UEConnectionStatus* data) {
    Node* newNode = createConnectionStatusNode(data);
    pthread_mutex_lock(&collection->lock); // Acquire fine-grained lock for thread safety
    if (collection->head == NULL) {
        collection->head = newNode;
    } else {
        Node* current = collection->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = newNode;
    }
    collection->numConnections++;
    pthread_mutex_unlock(&collection->lock);
}

// Function to remove a connection status from the collection
void removeConnectionStatus(ConnectionCollection* collection, int id) {
    Node* current = collection->head;
    Node* previous = NULL;
    while (current != NULL && current->data->id != id) {
        previous = current;
        current = current->next;
    }
    if (current == NULL) return; // Connection not found

    pthread_mutex_lock(&collection->lock); // Acquire fine-grained lock for thread safety
    if (previous == NULL) {
        collection->head = current->next;
    } else {
        previous->next = current->next;
    }
    free(current);
    collection->numConnections--;
    pthread_mutex_unlock(&collection->lock);
}

// Function to get the number of active connections
