#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the structure to represent a UEConnectionStatus
typedef struct {
    int id;
    char* status;
    time_t timestamp;
} UEConnectionStatus;

// Define the library's internal data structure
typedef struct {
    UEConnectionStatus** connections;
    size_t capacity;
    pthread_mutex_t lock;
    time_t ttl;
} ConnectionManager;

// Initialize the connection manager with a given TTL value
ConnectionManager* init_connection_manager(size_t initial_capacity, time_t ttl) {
    ConnectionManager* cm = (ConnectionManager*)malloc(sizeof(ConnectionManager));
    cm->connections = (UEConnectionStatus**)calloc(initial_capacity, sizeof(UEConnectionStatus*));
    cm->capacity = initial_capacity;
    pthread_mutex_init(&cm->lock, NULL);
    cm->ttl = ttl;
    return cm;
}

// Insert a new UE connection status into the manager
void insert_connection(ConnectionManager* cm, int id, const char* status) {
    pthread_mutex_lock(&cm->lock);

    // Check if the ID already exists in the manager
    for (size_t i = 0; i < cm->capacity; ++i) {
        UEConnectionStatus* connection = cm->connections[i];
        if (connection && connection->id == id) {
            // Update the existing connection's status and timestamp
            free(connection->status);
            connection->status = strdup(status);
            connection->timestamp = time(NULL);
            break;
        }
    }

    // If the ID does not exist, create a new entry
    if (cm->capacity <= 0) {
        cm->connections = (UEConnectionStatus**)realloc(cm->connections, (cm->capacity + 1) * sizeof(UEConnectionStatus*));
        cm->connections[cm->capacity++] = (UEConnectionStatus*)malloc(sizeof(UEConnectionStatus));
        cm->connections[cm->capacity - 1]->id = id;
        cm->connections[cm->capacity - 1]->status = strdup(status);
        cm->connections[cm->capacity - 1]->timestamp = time(NULL);
    }

    pthread_mutex_unlock(&cm->lock);
}

// Evict outdated connections based on the TTL value
void evict_outdated_connections(ConnectionManager* cm) {
    pthread_mutex_lock(&cm->lock);

    // Iterate over the connections and remove those that are older than the TTL
    for (size_t i = 0; i < cm->capacity; ++i) {
        UEConnectionStatus* connection = cm->connections[i];
        if (connection && time(NULL) - connection->timestamp > cm->ttl) {
            // Remove the outdated connection and shift the remaining ones forward
            free(connection->status);
            free(connection);
            memmove(&cm->connections[i], &cm->connections[i + 1], (cm->capacity - i - 1) * sizeof(UEConnectionStatus*));
            cm->capacity--;
        }
    }

    pthread_mutex_unlock(&cm->lock);
}

// Get the current connection status of a UE
int get_connection_status(ConnectionManager* cm, int id) {
    pthread_mutex_lock(&cm->lock);

    // Find the connection with the given ID and return its status
    for (size_t i = 0; i < cm->capacity; ++i) {
        UEConnectionStatus* connection = cm->connections[i];
        if (connection && connection->id == id) {
            pthread_mutex_unlock(&cm->lock);
            return strcmp(connection->status, "active") ? -1 : 0;
        }
    }

    // If the ID does not exist, return an error code
    pthread_mutex_unlock(&cm->lock);
    return -2;
}

// Free the memory allocated for the connection manager
void free_connection_manager(ConnectionManager* cm) {
    pthread_mutex_lock(&cm->lock);

    // Iterate over the connections and free their memory
    for (size_t i = 0; i < cm->capacity; ++i) {
        UEConnectionStatus* connection = cm->connections[i];
        if (connection) {
            free(connection->status);
            free(connection);
        }
    }

    pthread_mutex_unlock(&cm->lock);

    // Free the manager's memory
    free(cm->connections);
    free(cm);
}

int main() {
    // Initialize the connection manager with an initial capacity of 10 and a TTL value of 300 seconds (5 minutes)
    ConnectionManager* cm = init_connection_manager(10, 300);

    // Insert some connections into the manager
    insert_connection(cm, 1, "active");
    insert_connection(cm, 2, "inactive");
    insert_connection(cm, 3, "active");

    // Evict outdated connections
    evict_outdated_connections(cm);

    // Get the connection status of UE with ID 1
    int status = get_connection_status(cm, 1);
    printf("Connection status for UE with ID 1: %d\n", status);

    // Free the memory allocated by the connection manager
    free_connection_manager(cm);

    return 0;
}
