#include <iostream>
#include <vector>
#include <thread>
#include <mutex>
#include <atomic>
#include <unordered_map>

class ConfigurationService {
public:
    ConfigurationService() {
        config = std::unordered_map<std::string, std::string>();
        lock = std::mutex();
        atomicFlag = std::atomic<bool>(false);
    }

    void updateConfig(const std::string& key, const std::string& value) {
        if (!atomicFlag.exchange(true)) {
            // LRU eviction policy implementation
            for (auto it = config.begin(); it != config.end();) {
                if (it->second.empty()) {
                    it = config.erase(it);
                } else {
                    ++it;
                }
            }

            std::lock_guard<std::mutex> lockGuard(lock);

            config[key] = value;

            atomicFlag.store(false);
        }
    }

    std::string getConfig(const std::string& key) {
        if (!atomicFlag.exchange(true)) {
            // LRU eviction policy implementation
            for (auto it = config.begin(); it != config.end();) {
                if (it->second.empty()) {
                    it = config.erase(it);
                } else {
                    ++it;
                }
            }

            std::lock_guard<std::mutex> lockGuard(lock);

            atomicFlag.store(false);
        }

        return config.at(key);
    }

private:
    std::unordered_map<std::string, std::string> config;
    std::mutex lock;
    std::atomic<bool> atomicFlag;
};

int main() {
    ConfigurationService service;

    // Update configuration
    service.updateConfig("key1", "value1");
    service.updateConfig("key2", "value2");

    // Retrieve configuration
    std::cout << service.getConfig("key1") << std::endl;
    std::cout << service.getConfig("key2") << std::endl;

    return 0;
}

