    pthread_mutex_lock(&collection->lock);
    if (collection->data) {
        collection->data = realloc(collection->data, (collection->size + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!collection->data) {
            pthread_mutex_unlock(&collection->lock);
            return -2; // Memory allocation failed
