public:
    CommandLineTool() = default;

    void processFiles(const std::vector<std::string>& files) {
        // Initialize a thread pool
        int numThreads = 4; // adjust this value based on system resources
        std::vector<std::thread> threads;
        for (int i = 0; i < numThreads; ++i) {
            threads.emplace_back([this, &files]() {
                for (const auto& file : files) {
                    processFile(file);
                }
            });
        }

        // Wait for all threads to finish
        for (auto& thread : threads) {
            thread.join();
        }
    }

private:
    void processFile(const std::string& file) {
        // Read the file contents
        std::ifstream ifs(file);
        std::string content((std::istreambuf_iterator<char>(ifs)), std::streambuf_iterator<char>());

        // Process the file using a plugin
        for (const auto& plugin : plugins) {
            plugin.processFunction(std::vector<std::string>{content});
