// Define a structure to store UE connection status information
typedef struct {
    int ue_id;
    int connection_status;
} UEConnectionStatus;

// Define a linked list node structure for dynamic collection management
typedef struct Node {
    UEConnectionStatus data;
    struct Node* next;
} Node;

// Create a new linked list node with given UE connection status information
Node* create_node(int ue_id, int connection_status) {
    Node* new_node = (Node*) malloc(sizeof(Node));
    new_node->data.ue_id = ue_id;
    new_node->data.connection_status = connection_status;
    new_node->next = NULL;
    return new_node;
}

// Add a new node to the end of the linked list
void add_node(Node** head, Node* new_node) {
    if (*head == NULL || (*head)->next == NULL) {
        *head = new_node;
    } else {
        Node* current = *head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }
}

// Remove a node from the linked list based on UE ID
void remove_node(Node** head, int ue_id) {
    if (*head == NULL)
        return;

    Node* prev = *head;
    Node* current = *head->next;

    while (current != NULL) {
        if (current->data.ue_id == ue_id) {
            if (prev == NULL)
                *head = current->next;
            else
                prev->next = current->next;
            free(current);
            return;
        }
        prev = current;
        current = current->next;
    }
}

// Function to check the connection status of a UE with given ID
int get_connection_status(Node* head, int ue_id) {
    Node* current = head;
    while (current != NULL) {
        if (current->data.ue_id == ue_id)
            return current->data.connection_status;
        current = current->next;
    }
    return -1; // UE not found
}

// Function to update the connection status of a UE with given ID
void update_connection_status(Node** head, int ue_id, int new_status) {
    Node* current = *head;
    while (current != NULL) {
        if (current->data.ue_id == ue_id) {
            current->data.connection_status = new_status;
            return;
        }
        current = current->next;
    }
}

// Function to list all UEs with their connection status
void list_ue_connection_status(Node* head) {
    Node* current = head;
    while (current != NULL) {
        printf("UE ID: %d, Connection Status: %d\n", current->data.ue_id, current->data.connection_status);
        current = current->next;
    }
}

// Function to free the linked list memory
void free_list(Node* head) {
    Node* current = head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
}
