// Define a structure to represent mobile network user equipment sessions.
typedef struct {
    int session_id;
    char *imei;
    char *msisdn;
} UEConnectionStatus;

// Define the library's data structure to manage a dynamic collection of UEConnectionStatus structures.
typedef struct {
    size_t capacity;
    size_t size;
    UEConnectionStatus **connections;
    pthread_mutex_t lock;
} UEConnectionManager;

// Function to create and initialize an instance of UEConnectionManager.
UEConnectionManager *ue_connection_manager_init(size_t initial_capacity) {
    UEConnectionManager *manager = (UEConnectionManager *)malloc(sizeof(UEConnectionManager));
    manager->capacity = initial_capacity;
    manager->size = 0;
    manager->connections = (UEConnectionStatus **)calloc(initial_capacity, sizeof(UEConnectionStatus *));
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

// Function to add a new UEConnectionStatus structure to the manager.
int ue_connection_manager_add_ue_connection(UEConnectionManager *manager, UEConnectionStatus *connection) {
    if (pthread_mutex_lock(&manager->lock)) {
        return -1;  // Error
    }
    if (manager->size >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        UEConnectionStatus **new_connections = (UEConnectionStatus **)realloc(manager->connections, sizeof(UEConnectionStatus *) * new_capacity);
        if (!new_connections) {
            pthread_mutex_unlock(&manager->lock);
            return -1;  // Error
        }
        manager->connections = new_connections;
        manager->capacity = new_capacity;
    }
    manager->connections[manager->size] = connection;
    manager->size++;
    pthread_mutex_unlock(&manager->lock);
    return 0;  // Success
}

// Function to remove a UEConnectionStatus structure from the manager.
int ue_connection_manager_remove_ue_connection(UEConnectionManager *manager, int session_id) {
    for (int i = 0; i < manager->size; i++) {
        if (manager->connections[i]->session_id == session_id) {
            pthread_mutex_lock(&manager->lock);
            memmove(&manager->connections[i], &manager->connections[i + 1], sizeof(UEConnectionStatus *) * (manager->size - i - 1));
            manager->size--;
            pthread_mutex_unlock(&manager->lock);
            return 0;  // Success
        }
    }
    return -1;  // Error
}

// Function to get the UEConnectionStatus structure by session ID.
UEConnectionStatus *ue_connection_manager_get_ue_connection(UEConnectionManager *manager, int session_id) {
    for (int i = 0; i < manager->size; i++) {
        if (manager->connections[i]->session_id == session_id) {
            return manager->connections[i];
        }
    }
    return NULL;
}

// Function to free the resources allocated by UEConnectionManager.
void ue_connection_manager_free(UEConnectionManager *manager) {
    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < manager->size; i++) {
        free(manager->connections[i]->imei);
        free(manager->connections[i]->msisdn);
    }
    free(manager->connections);
    pthread_mutex_unlock(&manager->lock);
    free(manager);
}

// Example usage of the library.
int main() {
    UEConnectionManager *manager = ue_connection_manager_init(16);

    UEConnectionStatus *connection1 = (UEConnectionStatus *)malloc(sizeof(UEConnectionStatus));
    connection1->session_id = 123;
    connection1->imei = "IMEI-123";
    connection1->msisdn = "MSISDN-123";

    UEConnectionStatus *connection2 = (UEConnectionStatus *)malloc(sizeof(UEConnectionStatus));
    connection2->session_id = 456;
    connection2->imei = "IMEI-456";
    connection2->msisdn = "MSISDN-456";

    ue_connection_manager_add_ue_connection(manager, connection1);
    ue_connection_manager_add_ue_connection(manager, connection2);

    UEConnectionStatus *connection = ue_connection_manager_get_ue_connection(manager, 123);
    printf("Session ID: %d, IMEI: %s, MSISDN: %s\n", connection->session_id, connection->imei, connection->msisdn);

    ue_connection_manager_remove_ue_connection(manager, 456);

    UEConnectionStatus *connection3 = ue_connection_manager_get_ue_connection(manager, 123);
