    collection->capacity = initial_capacity;
    collection->count = 0;
    collection->entries = (UEConnectionStatus**)malloc(initial_capacity * sizeof(UEConnectionStatus*));
}

// Add UEConnectionStatus to the collection
void ueconn_add(UEConnecionStatusCollection* collection, UEConnectionStatus* status) {
    pthread_mutex_lock(&collection->lock);
    if (collection->count >= collection->capacity) {
        // Evict oldest entry when capacity is reached
        size_t i = 0;
        while (i < collection->count && collection->entries[i]->timestamp <= status->timestamp - 3600) { // TTL-based eviction
            free(collection->entries[i]);
            i++;
        }
        if (i == collection->count) {
            // Shrink capacity when no evictions are necessary
            collection->capacity /= 2;
            collection->entries = (UEConnectionStatus**)realloc(collection->entries, collection->capacity * sizeof(UEConnectionStatus*));
        }
    }
    collection->entries[collection->count] = status;
    collection->count++;
    pthread_mutex_unlock(&collection->lock);
}

