    UEConnectionStatus **connections;
    size_t capacity;
    size_t count;
    time_t ttl; // Time-To-Live value for eviction
} ConnectionStatusManager;

// Initialize connection status manager
void init_connection_status_manager(ConnectionStatusManager *manager, size_t initial_capacity) {
    pthread_mutex_init(&manager->lock, NULL);
    manager->connections = (UEConnectionStatus **)calloc(initial_capacity, sizeof(UEConnectionStatus *));
    manager->capacity = initial_capacity;
    manager->count = 0;
}

// Evict outdated connections
void evict_outdated_connections(ConnectionStatusManager *manager) {
    for (size_t i = 0; i < manager->count; i++) {
        if (time(NULL) - manager->connections[i]->ttl > manager->ttl) {
            free(manager->connections[i]);
            memmove(&manager->connections[i], &manager->connections[i + 1], (manager->capacity - i - 1) * sizeof(UEConnectionStatus *));
            manager->count--;
        }
    }
}

// Add connection status
void add_connection_status(ConnectionStatusManager *manager, UEConnectionStatus *connection) {
    pthread_mutex_lock(&manager->lock);
    if (manager->count >= manager->capacity) {
        // Adaptive resizing strategy: double capacity when full
        manager->connections = (UEConnectionStatus **)realloc(manager->connections, 2 * manager->capacity * sizeof(UEConnectionStatus *));
        manager->capacity *= 2;
    }
    manager->connections[manager->count] = connection;
    manager->count++;
    pthread_mutex_unlock(&manager->lock);
}

// Remove connection status
void remove_connection_status(ConnectionStatusManager *manager, UEConnectionStatus *connection) {
