class UserSession {
public:
    string userId;
    bool isActive = true;
    int64_t lastActiveTime;
};

class SessionManager {
public:
    unordered_map<string, UserSession> sessions;
    mutex sessionMutex;
    condition_variable sessionCond;
    queue<pair<int64_t, pair<string, bool>>> idleSessions;

    void addSession(string userId) {
        lock_guard<mutex> lock(sessionMutex);
        sessions[userId] = { userId, true };
    }

    void removeSession(string userId) {
        lock_guard<mutex> lock(sessionMutex);
        if (sessions.find(userId) != sessions.end()) {
            sessions.erase(userId);
        }
    }

    void updateSessionStatus(string userId, bool isActive) {
        lock_guard<mutex> lock(sessionMutex);
        if (sessions.find(userId) != sessions.end()) {
            sessions[userId].isActive = isActive;
            if (!isActive) {
                sessions[userId].lastActiveTime = chrono::system_clock::now().time_since_epoch().count();
            }
        }
    }

    void evictIdleSessions(int64_t idleThreshold, int64_t maxIdleTime) {
        lock_guard<mutex> lock(sessionMutex);
        while (idleSessions.size() > 0 && idleSessions.front().first <= idleThreshold) {
            pair<string, bool> session = idleSessions.front().second;
            sessions.erase(session.first);
            idleSessions.pop();
        }
    }

    void checkIdleSessions(int64_t maxIdleTime) {
        lock_guard<mutex> lock(sessionMutex);
        for (auto& session : sessions) {
            if (!session.second.isActive && chrono::system_clock::now().time_since_epoch().count() - session.second.lastActiveTime >= maxIdleTime) {
                idleSessions.push({ session.second.lastActiveTime, session });
            }
        }
    }

    void run() {
        while (true) {
            lock_guard<mutex> lock(sessionMutex);
            checkIdleSessions();
            this_thread::sleep_for(chrono::seconds(10));
        }
    }
};

