    // Constructor
    ConnectionManager(size_t maxConnections) : connections_(maxConnections), lock_(std::make_unique<std::mutex>()),
                                                 cond_(std::make_unique<std::condition_variable>()) {}

    // Add a new UE connection status
    void addConnection(const UEConnectionStatus& ueStatus) {
        std::unique_lock<std::mutex> lk(*lock_);
        connections_.emplace_back(ueStatus);
        lk.unlock();
        cond_->notify_all();
    }

    // Remove an existing UE connection status
    void removeConnection(const std::string& ueId) {
        std::unique_lock<std::mutex> lk(*lock_);
        auto it = connections_.begin();
        while (it != connections_.end()) {
            if (it->ueId == ueId) {
                connections_.erase(it);
                break;
            }
            it++;
        }
    }

    // Get all UE connection status
    std::vector<UEConnectionStatus> getAllConnections() {
        std::unique_lock<std::mutex> lk(*lock_);
        std::vector<UEConnectionStatus> result = connections_;
        return result;
    }

