// Initialize a new connection status list
ConnectionStatusList* init_connection_status_list() {
    ConnectionStatusList* list = (ConnectionStatusList*)malloc(sizeof(ConnectionStatusList));
    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

// Add a new connection status to the list
void add_connection_status(ConnectionStatusList* list, UEConnectionStatus status) {
    Node* node = (Node*)malloc(sizeof(Node));
    node->status = status;
    node->next = NULL;

    pthread_mutex_lock(&list->lock);
    if (list->head == NULL) {
        list->head = node;
        list->tail = node;
    } else {
        list->tail->next = node;
        list->tail = node;
    }
    pthread_mutex_unlock(&list->lock);
}

// Remove a connection status from the list
void remove_connection_status(ConnectionStatusList* list, int connection_id) {
    Node* current = list->head;
    Node* previous = NULL;

    pthread_mutex_lock(&list->lock);
    while (current != NULL) {
        if (current->status.connection_id == connection_id) {
            if (previous == NULL) {
                list->head = current->next;
            } else {
                previous->next = current->next;
            }
            if (current == list->tail) {
                list->tail = previous;
            }
            free(current);
            break;
        }
        previous = current;
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

