// Function to add a new connection status
void add_connection_status(int id, const char *status) {
    if (connections_count >= connections_capacity) {
        connections_capacity *= 2; // Double the capacity for growth
        connections = realloc(connections, sizeof(UEConnectionStatus *) * connections_capacity);
    }
    connections[connections_count] = malloc(sizeof(UEConnectionStatus));
    connections[connections_count]->id = id;
    strcpy(connections[connections_count]->status, status);
    connections_count++;
}

// Function to print all connection statuses
void print_connection_statuses() {
    for (int i = 0; i < connections_count; i++) {
        printf("ID: %d, Status: %s\n", connections[i]->id, connections[i]->status);
    }
}

// Thread-safe function to remove a connection status by ID
void remove_connection_status(int id) {
    for (int i = 0; i < connections_count; i++) {
        if (connections[i]->id == id) {
            free(connections[i]);
            memmove(&connections[i], &connections[i + 1], sizeof(UEConnectionStatus *) * (connections_count - i - 1));
            connections_count--;
            break;
        }
    }
}

// Initialize the dynamic array
void init_connections() {
    connections = malloc(sizeof(UEConnectionStatus *) * connections_capacity);
    connections_count = 0;
}

// Clean up memory
void clean_up() {
