    uint32_t ttl; // Time-To-Live value
} UEConnectionManager;

// Initialize the library
UEConnectionManager* ue_connection_manager_init(uint32_t initial_entry_capacity) {
    UEConnectionManager* manager = (UEConnectionManager*)malloc(sizeof(UEConnectionManager));
    manager->entries = (UEConnectionStatus**)calloc(initial_entry_capacity, sizeof(UEConnectionStatus*));
    manager->entry_count = 0;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

// Add a new UE connection status entry
void ue_connection_manager_insert(UEConnectionManager* manager, UEConnectionStatus* entry) {
    pthread_mutex_lock(&manager->lock);
    if (manager->entry_count >= manager->ttl) {
        // Evict the oldest entry to make room for the new one
        manager->entries[0] = manager->entries[1];
        manager->entry_count--;
    }
    manager->entries[manager->entry_count++] = entry;
    pthread_mutex_unlock(&manager->lock);
}

// Remove a UE connection status entry by ID
void ue_connection_manager_remove_by_id(UEConnectionManager* manager, uint32_t ue_id) {
    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < manager->entry_count; i++) {
        if (manager->entries[i]->ue_id == ue_id) {
            free(manager->entries[i]);
            memmove(&manager->entries[i], &manager->entries[i + 1], sizeof(UEConnectionStatus*) * (manager->entry_count - i));
            manager->entry_count--;
