#include <queue>
#include <mutex>
#include <condition_variable>
#include <memory>
#include <thread>
#include <atomic>

class MediaStreamProcessor {
public:
    MediaStreamProcessor();
    ~MediaStreamProcessor();

    void configure(const std::string& bitrate, const int samplingRate, const int resolution, const float frameRate);
    void setCodec(std::shared_ptr<Codec> codec);
    void startStreaming();
    void stopStreaming();

private:
    class Packet {
    public:
        uint8_t* data;
        size_t length;

        Packet(uint8_t* data, size_t length) : data(data), length(length) {}
    };

    std::queue<Packet*> packetQueue;
    std::mutex queueMutex;
    std::condition_variable queueConditionVariable;
    bool isStreaming = false;
    int maxBitrate = 0;
    int audioSamplingRate = 0;
    int videoResolution = 0;
    float frameRate = 0.0f;

    std::atomic<bool> isConfigured = false;

    void processPacket(Packet* packet);
};

MediaStreamProcessor::MediaStreamProcessor() {}

MediaStreamProcessor::~MediaStreamProcessor() {
    stopStreaming();
}

void MediaStreamProcessor::configure(const std::string& bitrate, const int samplingRate, const int resolution, const float frameRate) {
    maxBitrate = std::stoi(bitrate);
    audioSamplingRate = samplingRate;
    videoResolution = resolution;
    this->frameRate = frameRate;

    isConfigured = true;
}

void MediaStreamProcessor::setCodec(std::shared_ptr<Codec> codec) {}

void MediaStreamProcessor::startStreaming() {
    if (isConfigured && !isStreaming) {
        isStreaming = true;

        std::thread([this]() {
            while (isStreaming) {
                // Process packets from queue
                Packet* packet = nullptr;
                {
                    std::unique_lock<std::mutex> lock(queueMutex);
                    if (!packetQueue.empty()) {
                        packet = packetQueue.front();
                        packetQueue.pop();
                    }
                }

                if (packet != nullptr) {
                    processPacket(packet);
                } else {
                    // Wait for new packets or until streaming stops
                    std::unique_lock<std::mutex> lock(queueMutex);
                    queueConditionVariable.wait(lock, [this]() { return !isStreaming; });
                }
            }
        }).detach();
    }
}

void MediaStreamProcessor::stopStreaming() {
    if (isStreaming) {
        isStreaming = false;
        // Notify threads waiting for packets
        std::unique_lock<std::mutex> lock(queueMutex);
        queueConditionVariable.notify_all();
    }
}

void MediaStreamProcessor::processPacket(Packet* packet) {
