        perror("bind failed");
        return -1;
    }

    // Listen for incoming client connections
    listen(server_fd, MAX_CLIENTS);

    while (1) {
        // Accept a new client connection
        if ((client_sock = accept(server_fd, (struct sockaddr*)&client_addr, &client_len)) < 0) {
