class WeatherAPI(Resource):
    def get(self, location):
        try:
            primary_response = requests.get(f'https://api.weather.com/{location}')
            if primary_response.status_code == 200:
                return jsonify(primary_response.json())
            else:
                # Try secondary API
                secondary_response = requests.get(f'https://api.secondaryweather.com/{location}')
                if secondary_response.status_code == 200:
                    return jsonify(secondary_response.json())
        except Exception as e:
            print(f'Error: {e}')

class WeatherForecast(Resource):
    def get(self, location, start_date, end_date):
        cache_key = f'{location}-{start_date}-{end_date}'
        cached_data = cache.get(cache_key)
        if cached_data is None:
            # Fetch data from primary API
            primary_response = requests.get(f'https://api.weather.com/{location}/{start_date}/{end_date}')
            if primary_response.status_code == 200:
                data = primary_response.json()
                # Cache the data for 1 hour
                cache.set(cache_key, data, timeout=3600)
                return jsonify(data)
        else:
            return jsonify(cached_data)

class WeatherHistorical(Resource):
    def get(self, location, start_date, end_date):
        try:
            response = requests.get(f'https://api.historicalweather.com/{location}/{start_date}/{end_date}')
            if response.status_code == 200:
                return jsonify(response.json())
        except Exception as e:
            print(f'Error: {e}')

