    {
        if (!System.IO.File.Exists(filePath)) throw new FileNotFoundException($"File not found: {filePath}");
        var fileFormat = System.IO.Path.GetExtension(filePath);
        switch (fileFormat)
        {
            case ".csv":
                // CSV validation
                break;
            case ".json":
                // JSON validation
                break;
            default:
                throw new ArgumentException("Unsupported file format");
        }
    }

    if (config == null) throw new ArgumentNullException(nameof(config));
    if (strategy == null) throw new ArgumentNullException(nameof(strategy));

    foreach (var filePath in filePaths)
    {
        try
        {
            var apiResponse = ValidateFileContent(filePath, config);
            if (!apiResponse.IsValid) throw new Exception(apiResponse.Message);

            var fileMetadata = FetchCloudStorageMetadata(filePath);
            if (fileMetadata == null) throw new Exception("Failed to fetch metadata");

            strategy.Process(filePaths, apiResponse, fileMetadata, callback);
        }
        catch (Exception ex)
        {
            LogError(ex);
            if (ex.IsTransientFailure) await RetryOperation(ex.Message);
            else callback?.Invoke(new Result { Success = false, Message = ex.Message });
        }
    }
}

