namespace UEConnectionStatusWebAPI
{
    [ApiController]
    [Route("api/[controller]")]
    public class ConnectionStatusController : ControllerBase
    {
        private readonly ILogger<ConnectionStatusController> _logger;
        private readonly IRedisService _redisService;
        private readonly IElasticSearchService _elasticSearchService;

        public ConnectionStatusController(ILogger<ConnectionStatusController> logger, IRedisService redisService, IElasticSearchService elasticSearchService)
        {
            _logger = logger;
            _redisService = redisService;
            _elasticSearchService = elasticSearchService;
        }

        [HttpPost("update")]
        public async Task<IActionResult> UpdateConnectionStatus([FromBody]UpdateConnectionStatusRequest request)
        {
            if (!request.IsValid())
            {
                return BadRequest("Invalid request");
            }

            string cachedHTMLContent = await _redisService.GetCachedHtmlContent(request.PageSectionId, request.ElementId);
            if (string.IsNullOrEmpty(cachedHTMLContent))
            {
                cachedHTMLContent = await _elasticSearchService.GetHtmlContent(request.PageSectionId, request.ElementId);
                await _redisService.SetCachedHtmlContent(request.PageSectionId, request.ElementId, cachedHTMLContent);
            }

            return Ok("Connection status updated successfully");
        }
    }

