#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <unistd.h>
#include <fcntl.h>
#include <pthread.h>

#define MAX_FILES 10000
#define RECORD_SIZE sizeof(struct record)
#define ARRAY_SIZE (MAX_FILES / RECORD_SIZE)

struct record {
    int id;
};

int main(int argc, char *argv[]) {
    pthread_t threads[MAX_FILES];
    FILE *files[MAX_FILES];
    struct record records[ARRAY_SIZE];
    int file_count = 0;
    int i;

    // Initialize memory pool
    void *memory_pool = malloc(RECORD_SIZE * ARRAY_SIZE);
    if (!memory_pool) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }

    for (i = 0; i < MAX_FILES; i++) {
        char file_name[255];
        // Create a file and read its contents
        sprintf(file_name, "input_file_%d.txt", i);
        files[i] = fopen(file_name, "r");
        if (!files[i]) {
            perror("File opening failed");
            exit(EXIT_FAILURE);
        }
        // Read the contents of the file into the records array
        fread(&records[file_count], RECORD_SIZE, 1, files[i]);
        fclose(files[i]);
        file_count++;
    }

    for (i = 0; i < file_count; i++) {
        pthread_create(&threads[i], NULL, process_file, &files[i]);
    }

    for (i = 0; i < file_count; i++) {
        pthread_join(threads[i], NULL);
    }

    free(memory_pool);

    return 0;
}

void *process_file(void *file_pointer) {
    FILE *file = (FILE *)file_pointer;
    // Read the contents of the file
    struct record record;
    fread(&record, RECORD_SIZE, 1, file);
    fclose(file);
    // Process the record
    printf("Record ID: %d\n", record.id);

    return NULL;
}
