class LTE_RRC_UE_CONTEXT {
public:
    std::shared_ptr<LTE_RRC_MSG> rrc_msg;
    std::shared_ptr<LTE_PHY_CELL_INFO> phy_cell_info;

    LTE_RRC_UE_CONTEXT(std::shared_ptr<LTE_RRC_MSG> msg, std::shared_ptr<LTE_PHY_CELL_INFO> cell) :
        rrc_msg(msg), phy_cell_info(cell) {}
};

class LTE_RRC_MSG {
public:
    // ...
};

class LTE_PHY_CELL_INFO {
public:
    // ...
};

class MemoryManager {
private:
    std::mutex mtx;
    std::condition_variable cv;
    std::map<void*, LTE_RRC_UE_CONTEXT> cache;
    std::queue<std::pair<void*, LTE_RRC_UE_CONTEXT>> allocation_queue;

public:
    void* allocate(size_t size) {
        std::unique_lock<std::mutex> lock(mtx);
        while (!allocation_queue.empty()) {
            auto it = allocation_queue.front();
            allocation_queue.pop();
            if (it.second.rrc_msg->get_size() == size && it.second.phy_cell_info->get_size() == size) {
                return it.first;
            }
        }
        void* ptr = ::operator new(size);
        cache[ptr] = LTE_RRC_UE_CONTEXT(std::make_shared<LTE_RRC_MSG>(), std::make_shared<LTE_PHY_CELL_INFO>());
        lock.unlock();
        cv.notify_one();
        return ptr;
    }

    void deallocate(void* ptr) {
        std::unique_lock<std::mutex> lock(mtx);
        if (cache.find(ptr) != cache.end()) {
            cache.erase(ptr);
            ::operator delete(ptr);
        }
    }

    void enqueue_for_deallocation(void* ptr) {
        std::unique_lock<std::mutex> lock(mtx);
        allocation_queue.push({ptr, cache[ptr]});
        cv.notify_one();
    }

    void* get_from_cache(size_t size) {
        std::unique_lock<std::mutex> lock(mtx);
        for (auto it = cache.begin(); it != cache.end(); ++it) {
            if (it->second.rrc_msg->get_size() == size && it->second.phy_cell_info->get_size() == size) {
                return it->first;
            }
        }
        cv.wait(lock, [this] { return !allocation_queue.empty(); });
        auto ptr = allocation_queue.front().first;
        allocation_queue.pop();
        return ptr;
    }

    bool is_cached(void* ptr) {
        std::unique_lock<std::mutex> lock(mtx);
        return cache.find(ptr) != cache.end();
    }
};

int main() {
    MemoryManager memory_manager;
    // ...
}
