// Define the structure to hold NPM report data
typedef struct {
    int latency;
    double throughput;
    int packet_loss;
} npm_report_t;

// Define the structure to manage a dynamic list of NPM reports
typedef struct {
    pthread_mutex_t lock; // Lock for concurrent access
    size_t capacity; // Initial capacity of the list
    size_t size; // Current number of reports in the list
    npm_report_t** reports; // Pointer to an array of report pointers
} npm_manager_t;

// Function to initialize and allocate memory for NPM manager
npm_manager_t* npm_manager_init(size_t initial_capacity) {
    npm_manager_t* manager = (npm_manager_t*)malloc(sizeof(npm_manager_t));
    manager->capacity = initial_capacity;
    manager->size = 0;
    manager->reports = (npm_report_t**)calloc(initial_capacity, sizeof(npm_report_t*));
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

// Function to add a new NPM report to the manager
int npm_manager_add_report(npm_manager_t* manager, int latency, double throughput, int packet_loss) {
    if (manager->size >= manager->capacity) {
        // Resize the array when it's full
        size_t new_capacity = manager->capacity * 2;
        npm_report_t** new_reports = (npm_report_t**)realloc(manager->reports, new_capacity * sizeof(npm_report_t*));
        pthread_mutex_lock(&manager->lock);
        memcpy(new_reports, manager->reports, manager->size * sizeof(npm_report_t*));
        pthread_mutex_unlock(&manager->lock);
        free(manager->reports);
        manager->capacity = new_capacity;
        manager->reports = new_reports;
    }
    npm_report_t* report = (npm_report_t*)malloc(sizeof(npm_report_t));
    report->latency = latency;
    report->throughput = throughput;
    report->packet_loss = packet_loss;
    pthread_mutex_lock(&manager->lock);
    manager->reports[manager->size] = report;
    manager->size++;
    pthread_mutex_unlock(&manager->lock);
    return 0;
}

