#include <unistd.h>
#include <pthread.h>

// Structure to represent a linked list node
typedef struct Node {
    int value;
    struct Node* next;
} Node;

// Function to create a new linked list node with given value
Node* newNode(int value) {
    Node* newNode = (Node*) malloc(sizeof(Node));
    if (!newNode) {
        printf("Memory allocation failed\n");
        return NULL;
    }
    newNode->value = value;
    newNode->next = NULL;
    return newNode;
}

// Function to add a new node at the end of the linked list
void append(Node** headRef, int value) {
    Node* newEnd = newNode(value);
    if (*headRef == NULL) {
        *headRef = newEnd;
        return;
    }

    Node* lastNode = *headRef;
    while (lastNode->next) {
        lastNode = lastNode->next;
    }
    lastNode->next = newEnd;
}

// Function to validate an integer against the configurable range
int isValid(int value, int min, int max) {
    return (value >= min && value <= max);
}

// Function to handle TCP socket connection and process real-time integer streams
void* handleConnection(void* sock) {
    int conn = *(int*) sock;
    struct sockaddr_in clientAddress;
    socklen_t clientLen = sizeof(clientAddress);

    // Accept incoming connections from multiple clients
    while (1) {
        int newConn = accept(conn, (struct sockaddr*)&clientAddress, &clientLen);
        if (newConn < 0) {
            printf("Error accepting connection\n");
            continue;
        }

        char buffer[1024];
        int bytesRead;

        // Process real-time integer streams from multiple TCP socket connections
        while (1) {
            bytesRead = read(newConn, buffer, 1024);
            if (bytesRead < 0) {
                printf("Error reading from connection\n");
                break;
            }
            else if (bytesRead == 0) {
                // Handle client disconnection
                close(newConn);
                break;
            }

            int value = atoi(buffer);

            // Validate input integer against the configurable range
            if (!isValid(value, 1, 1000)) {
                printf("Invalid input: %d\n", value);
            }
            else {
                append(&head, value); // Add valid integers to the linked list

                // Asynchronous database persistence mechanism using a third-party REST API
                int retries = 3;
                for (int i = 0; i < retries; i++) {
                    if (persistDataToDatabase(value)) {
                        break;
                    }
                    else {
                        printf("Transient network failure detected. Retrying...\n");
                    }
                }

                // Handle partial data losses due to API unavailability
                if (!isDataAvailableInDatabase()) {
                    printf("Partial data loss detected. Resynchronizing with database...\n");
                    resynchronizeWithDatabase();
                }
            }
        }
    }
}

int main() {
    int servSock = socket(AF_INET, SOCK_STREAM, 0);
    struct sockaddr_in serverAddress;

    // Set up TCP socket for listening
    serverAddress.sin_family = AF_INET;
    serverAddress.sin_port = htons(8080);
    inet_pton(AF_INET, "127.0.0.1", &serverAddress.sin_addr);

    bind(servSock, (struct sockaddr*)&serverAddress, sizeof(serverAddress));
    listen(servSock, 3);

    // Handle multiple TCP socket connections asynchronously
    pthread_t threads[3];
    for (int i = 0; i < 3; i++) {
        int* sock = &servSock;
        pthread_create(&threads[i], NULL, handleConnection, sock);
    }

    for (int i = 0; i < 3; i++) {
        pthread_join(threads[i], NULL);
    }

    close(servSock);

    return 0;
}
