        if (connections[i].connectionId == -1) {
            connections[i].connectionId = connectionId;
            connections[i].ipaddress = ipaddress;
            connections[i].port = port;
            return;
        }
    }
}

// Remove a connection from the dynamic array
void remove_connection(int connectionId) {
    for (int i = 0; i < MAX_CONNECTIONS; i++) {
        if (connections[i].connectionId == connectionId) {
            connections[i].connectionId = -1;
            connections[i].ipaddress = NULL;
            connections[i].port = -1;
            return;
        }
    }
}

