            chrono::high_resolution_clock clock;
            int maxCacheSize = 10000;
            int minCacheSize = 5000;
            float evictionThreshold = 0.7f;

        public:
            void put(const string& key, const string& value) {
                // implement custom eviction policy
                // consider time-based TTL and access frequency
                if (cache.size() >= maxCacheSize * evictionThreshold) {
                    evict();
                }
                cache[key] = make_shared<Node>(key, value);
            }

            shared_ptr<Node> get(const string& key) {
