                int64_t oldestTime = clock.now().count();
                for (auto it = cache.begin(); it != end(cache); ) {
                    auto node = it->second;
                    int64_t age = clock.now().count() - oldestTime;
                    if (age > minCacheSize && !node->dirty) {
                        it = cache.erase(it);
                    } else {
                        ++it;
                    }
                }
            }
