    time_t lastHeartbeat;
    int currentLoad;
    map<string, string> configSettings;
};

// Thread-safe lock mechanism
class Lockable {
public:
    mutex mtx_;
    condition_variable cv_;

    void lock() {
        unique_lock<mutex> lk(mtx_);
    }

    template <typename Rep, typename Period>
    bool wait_for(const chrono::duration<Rep, Period>& d) {
        return cv_.wait_for(d);
    }

    void notify_one() {
        cv_.notify_one();
    }
};

// Adaptive locking mechanism
class AdaptiveLock {
public:
    Lockable lock_;
    int contentionCount_;

    AdaptiveLock(int initialContestionThreshold) : contentionCount_(0) {}

    void lock() {
        if (contentionCount_ >= 10) {
            this_thread::sleep_for(chrono::microseconds(100));
        }
        lock_.lock();
    }

    template <typename Rep, typename Period>
    bool wait_for(const chrono::duration<Rep, Period>& d) {
        return lock_.wait_for(d);
    }

    void notify_one() {
        lock_.notify_one();
    }
};

