            res.body() = "Success";
        } else {
            res.body() = "Error";
        }

        // Cache response for future requests.
        it_->cache_response(req.body(), res.body());

        // Send response back to the client.
        beast::http::async_write(*io_, res, [this](beast::error_code ec) {
            if (!ec)
                std::cout << "Response sent successfully.\n";
            else
                std::cerr << "Error sending response: " << ec.message() << "\n";
        });
    }

