    private final LoggingService loggingService;

    public MoSTStateService(CloudStorage cloudStorage, ConfigManager configManager, DistributedEventStreamService eventStream, LoggingService loggingService) {
        this.cloudStorage = cloudStorage;
        this.configManager = configManager;
        this.eventStream = eventStream;
        this.loggingService = loggingService;
        init();
    }

    public void update(MoSTState stateUpdate) {
        MoSTState currentState = this.state.get();
        MoSTState nextState = applyUpdates(currentState, stateUpdate);
        if (!this.state.compareAndSet(currentState, nextState)) {
            // conflict detected, resolve
            handleConflict(nextState);
        }
    }

    private MoSTState applyUpdates(MoSTState currentState, MoSTState stateUpdate) {
        // implement partial update logic here
    }

    private void handleConflict(MoSTState nextState) {
