using Microsoft.AspNetCore.Authentication;
using Microsoft.AspNetCore.Authentication.OpenIdConnect;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Caching.StackExchangeRedis;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using System.Collections.Generic;
using System.Threading.Tasks;

namespace MyApp
{
    public class AuthenticationController : ControllerBase
    {
        private readonly UserManager<ApplicationUser> _userManager;
        private readonly SignInManager<ApplicationUser> _signInManager;
        private readonly IAuthenticationService _authenticationService;
        private readonly RedisCache _redisCache;

        public AuthenticationController(UserManager<ApplicationUser> userManager, 
            SignInManager<ApplicationUser> signInManager, IAuthenticationService authenticationService, 
            RedisCache redisCache)
        {
            _userManager = userManager;
            _signInManager = signInManager;
            _authenticationService = authenticationService;
            _redisCache = redisCache;
        }

        [HttpPost("login")]
        public async Task<IActionResult> Login(LoginModel model)
        {
            if (!await _signInManager.UserIsInRoleAsync(model.Role))
                return BadRequest("Invalid role");

            var result = await _signInManager.PasswordSignInAsync(model.Username, 
                model.Password, isPersistent: false);
            if (result.Succeeded)
                return RedirectToAction(nameof(HomeController.Index));
            else
                return BadRequest("Invalid username or password");
        }

        [HttpPost("register")]
        public async Task<IActionResult> Register(RegisterModel model)
        {
            var user = new ApplicationUser { UserName = model.Username, Email = model.Email };
            await _userManager.CreateAsync(user);
            await _signInManager.SignInAsync(user, isPersistent: false);
            return RedirectToAction(nameof(HomeController.Index));
        }

        [HttpGet("logout")]
        public async Task<IActionResult> Logout()
        {
            await _signInManager.SignOutAsync();
            return RedirectToAction(nameof(HomeController.Index));
        }
    }
}
