["Here is the code block for the `runTests` function in JavaScript:

```javascript
import { blueslip } from 'blueslip';
import { setTimeout, clearTimeout } from 'timers';
import { retry } from 'retry';

const runTests = async (testSuite) => {
  const testResults = [];
  let blueslipInstance;

  if (!process.env.SKIP_TESTS || process.env.SKIP_TESTS.toLowerCase() === 'false') {
    for await (const test of testSuite) {
      try {
        const testName = test.testName;
        const testFunction = test.testFunction;
        const timeout = test.timeout ?? 30000;
        const retryCount = test.retryCount ?? 3;
        let currentAttempt = 0;

        blueslipInstance = new blueslip({
          level: 'info',
          serialize: true,
        });

        while (currentAttempt <= retryCount) {
          try {
            await testFunction(blueslipInstance);
            testResults.push({ testName, result: 'pass' });
            break;
          } catch (error) {
            currentAttempt++;

            if (currentAttempt < retryCount) {
              // exponential backoff
              setTimeout(() => {
                runTests([test]);
              }, Math.min(1000 * Math.pow(2, currentAttempt - 1), timeout));
            } else {
              testResults.push({ testName, result: 'fail' });
            }
          }
        }
      } catch (error) {
        console.error(`Test ${testName} failed`, error);
      }
    }

    // log and display results
    if (!process.env.SKIP_TESTS || process.env.SKIP_TESTS.toLowerCase() === 'false') {
      console.log('Test Results:');
      for (const result of testResults) {
        console.log(`${result.testName}: ${result.result}`);
      }
    }
  } else {
    console.log('Tests skipped');
  }
};

export default runTests;
