function generateHeaderComponent(configurations) {
  const headerHTML = [];

  configurations.forEach((config) => {
    const { text, url, label, target } = config;

    // Fetch fallback accessibility label if not provided
    let accessibilityLabel = label;
    fetch('https://api.accessibility-labels.com/labels')
      .then(response => response.json())
      .then((data) => (accessibilityLabel = data.find(({ text }) => text === label)?.text))
      .catch((error) => console.error(`Error fetching fallback label: ${error}`));

    headerHTML.push(`
      <a
        href="${url}"
        target="${target || '_self'}"
        aria-label="${accessibilityLabel}"
        >${text}</a>
    `);
  });

  return headerHTML.join('');
}
