// Job definition structure
interface Job {
  id: number;
  type: string;
  priority: number;
  duration: number;
}

// Adaptive scheduling algorithm
function scheduleJobs(jobs) {
  const availableServers = servers.filter((server) => server.availability);
  jobs.forEach((job) => {
    let bestServer = null;
    let minDuration = Infinity;
    for (const server of availableServers) {
      if (server.availability && server.cpusAvailable >= job.duration) {
        if (server.lastJobFinishTime + job.duration <= Date.now()) {
          if (server.cpusAvailable > 0.5 * minDuration) {
            bestServer = server;
            minDuration = server.cpusAvailable;
          }
        }
      }
    }
    if (bestServer) {
      bestServer.assignJob(job);
      availableServers.splice(availableServers.indexOf(bestServer), 1);
    } else {
      console.log(`No suitable server found for job ${job.id}`);
    }
  });
}

