using Amazon.S3;
using Amazon.SSM;
using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Threading.Tasks;

namespace ConfigStore
{
    public class ConfigManager
    {
        private readonly AmazonS3Client _s3Client;
        private readonly AmazonSSMClient _ssmClient;
        private readonly Dictionary<string, string> _configCache = new Dictionary<string, string>();

        public ConfigManager(AmazonS3Client s3Client, AmazonSSMClient ssmClient)
        {
            _s3Client = s3Client;
            _ssmClient = ssmClient;
        }

        public async Task<string> GetConfigValueAsync(string configName)
        {
            if (_configCache.ContainsKey(configName))
                return _configCache[configName];

            try
            {
                var paramResponse = await _ssmClient.GetParameterAsync(new GetParameterRequest { Name = configName, WithDecryption = true });
                if (paramResponse.Parameter.Value == null)
                    throw new Exception($"Config value not found for {configName}");

                _configCache[configName] = paramResponse.Parameter.Value;
                return paramResponse.Parameter.Value;
            }
            catch (Exception ex)
            {
                // Handle transient failures or partial service unavailability
                await Task.Delay(500);
                try
                {
                    var bucketResponse = await _s3Client.GetObjectAsync(new GetObjectRequest { BucketName = "config-store", Key = configName });
                    if (bucketResponse.HttpStatusCode == 404)
                        throw new Exception($"Config value not found for {configName}");
                    var responseBody = new StreamReader(bucketResponse.ResponseStream).ReadToEnd();
                    _configCache[configName] = responseBody;
                    return responseBody;
                }
                catch (Exception ex2)
                {
                    // Handle permanent failures or service unavailability
                    throw new Exception("Failed to retrieve config value", ex);
                }
            }
        }

        public async Task SetConfigValueAsync(string configName, string configValue)
        {
            try
            {
                await _ssmClient.PutParameterAsync(new PutParameterRequest { Name = configName, Value = configValue, Type = "String" });
            }
            catch (Exception ex)
            {
                // Handle transient failures or partial service unavailability
                await Task.Delay(500);
                try
                {
                    await _s3Client.PutObjectAsync(new PutObjectRequest { BucketName = "config-store", Key = configName, StringBody = configValue });
                }
                catch (Exception ex2)
                {
                    // Handle permanent failures or service unavailability
                    throw new Exception("Failed to set config value", ex);
                }
            }
        }

        public async Task DeleteConfigValueAsync(string configName)
        {
            try
            {
                await _ssmClient.DeleteParameterAsync(new DeleteParameterRequest { Name = configName });
            }
            catch (Exception ex)
            {
                // Handle transient failures or partial service unavailability
                await Task.Delay(500);
                try
                {
                    await _s3Client.DeleteObjectAsync(new DeleteObjectRequest { BucketName = "config-store", Key = configName });
                }
                catch (Exception ex2)
                {
                    // Handle permanent failures or service unavailability
                    throw new Exception("Failed to delete config value", ex);
                }
            }
        }
    }

    public class ConfigCacheStrategy : IConfigCacheStrategy
    {
        private readonly int _cacheExpirationMinutes;

        public ConfigCacheStrategy(int cacheExpirationMinutes)
