        UnionFind uf = new UnionFind();

        try {
            consumer.subscribe(Collections.singleton(TOPIC_NAME));

            while (true) {
                ConsumerRecord<String, Long> record = consumer.poll(100);
                if (record == null || record.value() == null) {
                    continue;
                }

                int size = 0;
                long[] values = new long[1024];
                for (int i = 0; i < record.value().length; i++) {
                    values[i] = record.value()[i];
                    size++;
                }

                // Process the batch of disjoint pairs
                processBatch(uf, values);

                // Acknowledge the consumed message
                consumer.commitSync();
            }
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            if (consumer != null) {
                consumer.close();
            }
        }
    }

    private static void processBatch(UnionFind uf, long[] values) {
        // Implement your logic here to calculate disjoint pairs
    }
}

class UnionFind {
    int[] parent;
    int[] rank;

    public UnionFind() {
        this.parent = new int[1024];
        this.rank = new int[1024];

        for (int i = 0; i < 1024; i++) {
            makeSet(i);
        }
    }

    private void makeSet(int x) {
        parent[x] = x;
        rank[x] = 0;
    }

    public int find(int x) {
        if (parent[x] != x) {
            parent[x] = find(parent[x]);
        }
        return parent[x];
    }

    public void union(int x, int y) {
        int rootX = find(x);
        int rootY = find(y);

        if (rootX == rootY)
            return;

        if (rank[rootX] > rank[rootY]) {
            parent[rootY] = rootX;
        } else {
            parent[rootX] = rootY;
            if (rank[rootX] == rank[rootY])
                rank[rootY]++;
        }
    }
}

```

Note that this code only sets up the Kafka consumer and initializes a `UnionFind` data structure. The actual logic for processing the batch of disjoint pairs is left blank (`processBatch(uf, values);`) as it depends on your specific requirements.']

