["```
CREATE PROCEDURE sp_GetEmployeeDetails
    @SupervisorID INT,
    @DepartmentID INT = NULL,
    @HireDateRange DATE = NULL,
    @SalaryRange DECIMAL(10, 2) = NULL,
    @ExternalAPIFilter VARCHAR(MAX) = NULL,
    @PageNumber INT = 1,
    @PageSize INT = 25
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @CachedQueryResults TABLE (EmployeeID INT, Name VARCHAR(50), City VARCHAR(50), Address VARCHAR(100));

    IF EXISTS (SELECT 1 FROM syscache WHERE keyname = 'sp_GetEmployeeDetails_Cached')
    BEGIN
        SELECT * INTO #CachedResults FROM syscache WHERE keyname = 'sp_GetEmployeeDetails_Cached';
    END;

    DECLARE @QueryText NVARCHAR(MAX) = '
        SELECT e.EmployeeID, e.Name, c.City, a.Address
        FROM Employee e
        JOIN City c ON e.CityID = c.CityID
        JOIN Address a ON e.AddressID = a.AddressID
        WHERE e.SupervisorID = @SupervisorID';

    IF @DepartmentID IS NOT NULL
    BEGIN
        SET @QueryText += ' AND e.DepartmentID = @DepartmentID';
    END;

    IF @HireDateRange IS NOT NULL
    BEGIN
        SET @QueryText += ' AND e.HireDate BETWEEN @HireStartDate AND @HireEndDate';
    END;

    IF @SalaryRange IS NOT NULL
    BEGIN
        SET @QueryText += ' AND e.Salary BETWEEN @MinSalary AND @MaxSalary';
    END;

    IF @ExternalAPIFilter IS NOT NULL
    BEGIN
        SET @QueryText += '
            AND EXISTS (
                SELECT 1
                FROM ExternalHRAPI xh
                WHERE xh.EmployeeID = e.EmployeeID
                AND xh.FilterCriteria LIKE ''%'' + @ExternalAPIFilter + ''%''
            )';
    END;

    EXEC sp_ExecuteSQL @QueryText, N'@SupervisorID INT, @DepartmentID INT, @HireStartDate DATE, @HireEndDate DATE, @MinSalary DECIMAL(10, 2), @MaxSalary DECIMAL(10, 2), @ExternalAPIFilter VARCHAR(MAX)', 
        @SupervisorID, @DepartmentID, @HireDateRange, @SalaryRange, @ExternalAPIFilter;

    INSERT INTO @CachedQueryResults
    SELECT e.EmployeeID, e.Name, c.City, a.Address
    FROM #CachedResults;

    DROP TABLE #CachedResults;

    IF NOT EXISTS (SELECT 1 FROM syscache WHERE keyname = 'sp_GetEmployeeDetails_Cached')
    BEGIN
        INSERT INTO syscache VALUES ('sp_GetEmployeeDetails_Cached', @CachedQueryResults);
    END;

    SELECT * FROM @CachedQueryResults ORDER BY EmployeeID OFFSET (@PageNumber - 1) * @PageSize ROWS FETCH NEXT @PageSize ROWS ONLY;
END;
```"]

