    State* s = (State*)malloc(sizeof(State));
    if (!s) return NULL;
    s->id = id;
    strcpy(s->name, name);
    return s;
}

// Function to add a new state to the list
int addState(StateList* list, State* state) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->data = *state;
    newNode->next = list->head;
    list->head = newNode;
    list->size++;
    return 0;
}

