    State* state2 = createState(2, "State 2");
    State* state3 = createState(3, "State 3");

    // Add the states to the list
    addState(&list, state1);
    addState(&list, state2);
    addState(&list, state3);

    // Serialize and deserialize the state list
    char buffer[1024];
    serializeStateList(&list, &buffer);
    StateList* deserializedList = (StateList*)malloc(sizeof(StateList));
    pthread_mutex_init(&deserializedList->lock, NULL);
    deserializeStateList(buffer, &deserializedList);

    // Print the serialized state list
    printStateList(&deserializedList);

    return 0;
}
