```java
import java.io.IOException;
import java.util.concurrent.*;
import java.util.logging.*;

public class FlexibleLogger {
    private static final Logger rootLogger = Logger.getLogger(Logger.GLOBAL_LOGGER_NAME);
    private static final Map<String, LogSink> sinks = new ConcurrentHashMap<>();
    private static final ExecutorService executorService = Executors.newCachedThreadPool();

    public enum LogLevel { DEBUG, INFO, WARNING, ERROR }

    public interface LogSink {
        void write(LogRecord record) throws IOException;
    }

    public static Logger getRootLogger() {
        return rootLogger;
    }

    public static void addSink(String name, LogSink sink) {
        sinks.put(name, sink);
    }

    public static void log(LogLevel level, String message) {
        LogRecord record = new LogRecord(level.equals(LogLevel.DEBUG), level.equals(LogLevel.INFO), level.equals(LogLevel.WARNING), level.equals(LogLevel.ERROR), null, System.currentTimeMillis(), message);
        executorService.submit(() -> rootLogger.log(record));
    }
}
```']

