int extract_metadata(const char *filename, ImageMetadata *metadata) {
    if (strcmp(filename + strlen(filename) - 3, "tiff") == 0) {
        return parse_tiff(filename, metadata);
    } else if (strcmp(filename + strlen(filename) - 4, "jpeg") == 0 ||
               strcmp(filename + strlen(filename) - 4, "jpg") == 0) {
        return parse_jpeg(filename, metadata);
    } else if (strcmp(filename + strlen(filename) - 3, "png") == 0) {
        return parse_png(filename, metadata);
    } else if (strcmp(filename + strlen(filename) - 3, "raw") == 0) {
        return parse_raw(filename, metadata);
    }
    return -1; // unsupported format
}

