import java.util.concurrent.*;

public class DataProcessingPipeline {
    private static final int MAX_CONCURRENCY = Runtime.getRuntime().availableProcessors();
    private static final int MIN_CONCURRENCY = 2;
    private static final int RETRY_ATTEMPTS = 3;
    private static final int RETRY_BACKOFF_DELAY = 1000;

    public void processLargeDataset() throws InterruptedException, ExecutionException {
        ExecutorService executor = new ThreadPoolExecutor(
            MAX_CONCURRENCY,
            MAX_CONCURRENCY,
            0L,
            TimeUnit.MILLISECONDS,
            new LinkedBlockingQueue<Runnable>()
        );

        // Resource management
        int availableCPUCores = Runtime.getRuntime().availableProcessors();
        int concurrency = adjustConcurrency(availableCPUCores);
        executor.setMaximumPoolSize(concurrency);

        // External script execution
        try {
            executeScript(executor, "path/to/external/script.sh");
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            throw new ExecutionException("External script execution failed", e);
        }

        // Integration and dependency management
        // ...

        // Performance monitoring and logging
        // ...

        // Resource cleanup
        executor.shutdown();

        if (!executor.awaitTermination(10, TimeUnit.SECONDS)) {
            executor.shutdownNow();
        }
    }

    private int adjustConcurrency(int availableCPUCores) {
        // Implement adaptive scaling strategy based on real-time system resource usage metrics
        return Math.min(MAX_CONCURRENCY, availableCPUCores);
    }

    private void executeScript(ExecutorService executor, String scriptPath) throws InterruptedException, ExecutionException {
        // Dynamically invoke the external script to process data in parallel
        Callable<Object> scriptCallable = () -> {
            try {
                // Execute the external script
                Runtime.getRuntime().exec(scriptPath);
                return null;
            } catch (IOException e) {
                // Manage transient errors through retry mechanisms with exponential backoff
                for (int attempt = 0; attempt < RETRY_ATTEMPTS; attempt++) {
                    if (attempt > 0) {
                        try {
                            Thread.sleep(RETRY_BACKOFF_DELAY * (1 << attempt));
                        } catch (InterruptedException ex) {
                            Thread.currentThread().interrupt();
                            throw new ExecutionException("Script execution failed", e);
                        }
                    }
                    try {
                        // Re-execute the script
                        Runtime.getRuntime().exec(scriptPath);
                        return null;
                    } catch (IOException e2) {
                        if (attempt >= RETRY_ATTEMPTS - 1) {
                            throw new ExecutionException("Script execution failed after retries", e2);
                        }
                    }
                }
            }
        };

        // Submit the script task to the executor
        Future<Object> scriptFuture = executor.submit(scriptCallable);

        try {
            // Wait for the script completion or failure
            Object result = scriptFuture.get();
            if (result != null) {
                // Log relevant information for further investigation
                System.out.println("Script execution successful");
            } else {
                System.out.println("Script execution failed");
            }
        } catch (ExecutionException e) {
            throw new ExecutionException("Script execution failed", e);
        }
    }
}
