    int timeout;
    bool debug_mode;
};

class ConfigurationManager {
public:
    ConfigurationManager();

    void init();
    void loadConfig(const std::string& config_file);
    void updateConfigFromEnvVars();
    void updateConfigFromRemoteService();
    void getSetting(const std::string& key);

private:
    Config config_;
    std::mutex mtx_;
    std::condition_variable cv_;

    // Load configuration from environment variables
    void loadConfigFromEnvVars();

    // Load configuration from remote service
    void loadConfigFromRemoteService();

    // Update configuration with new values from environment variables
    void updateConfigFromEnvVarsImpl();

    // Update configuration with new values from remote service
    void updateConfigFromRemoteServiceImpl();
};

int main() {
    ConfigurationManager config_manager;
    config_manager.init();
    config_manager.loadConfig("config.ini");
    std::cout << "API Key: " << config_manager.getSetting("api_key") << std::endl;
    return 0;
}

// Implementation of the ConfigurationManager class
ConfigurationManager::ConfigurationManager() : 
    config_({"", 0, false}) {}

void ConfigurationManager::init() {
    // Initialize configuration with default values
    config_.api_key = "";
    config_.timeout = 0;
    config_.debug_mode = false;

    // Load configuration from environment variables
    loadConfigFromEnvVars();

    // Load configuration from remote service
    loadConfigFromRemoteService();
}

void ConfigurationManager::loadConfig(const std::string& config_file) {
    // Load configuration from file
    std::ifstream file(config_file);
    if (!file.is_open()) {
        std::cerr << "Error: Unable to open configuration file." << std::endl;
        return;
    }
    std::stringstream ss;
    ss << file.rdbuf();
    file.close();

    // Parse configuration file contents
    std::map<std::string, std::string> config_map;
    std::string line;
    while (std::getline(ss, line)) {
        size_t pos = line.find('=');
        if (pos != std::string::npos) {
            std::string key = line.substr(0, pos);
            std::string value = line.substr(pos + 1);
            config_map[key] = value;
        }
    }

    // Update configuration with values from file
    for (const auto& pair : config_map) {
        if (pair.first == "api_key") {
            config_.api_key = pair.second;
        } else if (pair.first == "timeout") {
            config_.timeout = std::stoi(pair.second);
        } else if (pair.first == "debug_mode") {
            config_.debug_mode = (pair.second == "true");
        }
    }
}

void ConfigurationManager::updateConfigFromEnvVars() {
    // Update configuration with values from environment variables
    updateConfigFromEnvVarsImpl();
}

void ConfigurationManager::getSetting(const std::string& key) {
    // Return setting value for given key
    if (config_.find(key) != config_.end()) {
        return config_[key];
    }
    return "";
}
