public:
    OAuthTokenFetcher(string apiEndpoint, string apiKey, int retryAttempts) 
        : apiEndpoint(apiEndpoint), apiKey(apiKey), retryAttempts(retryAttempts), tokenQueue(new queue<string>()), lock(new mutex), conditionVariable(new condition_variable) {}

    void fetchTokens() {
        while (true) {
            fetchAndValidateToken();
            this_thread::sleep_for(chrono::seconds(60)); // Fetch tokens every minute
        }
    }

private:
    string apiEndpoint;
    string apiKey;
    int retryAttempts;
    queue<string>* tokenQueue;
    mutex* lock;
    condition_variable* conditionVariable;

    void fetchAndValidateToken() {
        try {
            // Make API request to fetch new token
            string response = makeRequest(apiEndpoint);

            // Validate the fetched token
            if (!validateToken(response)) {
                // Token is invalid, retry fetching
                for (int i = 0; i < retryAttempts; i++) {
                    this_thread::sleep_for(chrono::seconds(pow(2, i))); // Exponential backoff
                    response = makeRequest(apiEndpoint);
                    if (validateToken(response)) break;
                }

                // If all retries fail, log error and exit
                if (!validateToken(response)) {
                    lock->lock();
                    ofstream file("error.log");
                    if (file) {
                        file << "Failed to fetch valid token after " << retryAttempts << " attempts." << endl;
                        file.close();
                    }
                    lock->unlock();
                    return;
                }
            }

            // Token is valid, add it to the queue
            lock->lock();
            tokenQueue->push(response);
            conditionVariable->notify_all();
            lock->unlock();

        } catch (exception& e) {
            // Log error and retry fetching
            logError(e.what());
