using System;
using System.Security.Cryptography;
using System.Threading.Tasks;

public class SecureHasher
{
    public enum Algorithm { MD5, SHA256 }

    private readonly Algorithm _algorithm;
    private readonly HashAlgorithm _hashAlg;
    private readonly ILogger _logger;

    public SecureHasher(string algorithm = "SHA256", ILogger logger = null)
    {
        _algorithm = Enum.Parse<Algorithm>(algorithm);
        _logger = logger ?? new Logger();
        switch (_algorithm)
        {
            case Algorithm.MD5:
                _hashAlg = MD5.Create();
                break;
            case Algorithm.SHA256:
            default:
                _hashAlg = SHA256.Create();
                break;
        }
    }

    public string Hash(string input, int userId = 0)
    {
        byte[] hashBytes;
        using (var stream = new MemoryStream())
        {
            using (var writer = new StreamWriter(stream))
            {
                writer.WriteLine(userId);
                writer.WriteLine(input);
            }
            stream.Position = 0;
            using (var cryptStream = _hashAlg.CreateEncryptor())
            {
                var hashBytesBuffer = new byte[stream.Length];
                stream.Read(hashBytesBuffer, 0, hashBytesBuffer.Length);
                cryptStream.TransformFinalBlock(hashBytesBuffer, 0, hashBytesBuffer.Length);
                return Convert.ToBase64String(hashBytesBuffer);
            }
        }
    }

    public async Task<string> HashAsync(string input, int userId = 0)
    {
        byte[] hashBytes;
        using (var stream = new MemoryStream())
        {
            using (var writer = new StreamWriter(stream))
            {
                await writer.WriteLineAsync(userId);
                await writer.WriteLineAsync(input);
            }
            stream.Position = 0;
            using (var cryptStream = _hashAlg.CreateEncryptor())
            {
                var hashBytesBuffer = new byte[stream.Length];
                await stream.ReadAsync(hashBytesBuffer, 0, hashBytesBuffer.Length);
                await cryptStream.TransformFinalBlockAsync(hashBytesBuffer, 0, hashBytesBuffer.Length);
                return Convert.ToBase64String(hashBytesBuffer);
            }
        }
    }

    public void Log(string input, int userId = 0)
    {
        _logger.Log($"Hashed at {DateTime.Now}: {input} (User ID: {userId}, Algorithm: {_algorithm})");
    }
}
