namespace ResilientBinaryFileProcessor
{
    public class BinaryFileProcessor
    {
        private readonly ILogger _logger;
        private readonly HttpClient _httpClient;
        private readonly ICacheService _cacheService;
        private readonly IPipelineValidator _validator;

        public BinaryFileProcessor(ILogger logger, HttpClient httpClient, ICacheService cacheService, IPipelineValidator validator)
        {
            _logger = logger;
            _httpClient = httpClient;
            _cacheService = cacheService;
            _validator = validator;
        }

        public async Task ProcessBinaryFileAsync(string filePath)
        {
            using (var fileStream = File.OpenRead(filePath))
            {
                var binaryData = fileStream.ReadAllBytes();
                await ProcessBinaryDataAsync(binaryData);
            }
        }

        private async Task ProcessBinaryDataAsync(byte[] binaryData)
        {
            try
            {
                // Deserialize and validate the binary data
                var deserializedObjects = _cacheService.GetDeserializedObjects(binaryData);

                foreach (var obj in deserializedObjects)
                {
                    await ValidateObjectAsync(obj);
                }
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error processing binary file");
            }
        }

        private async Task ValidateObjectAsync(object obj)
        {
            try
            {
                // Validate the object against the external API schema
                var validationResult = await _validator.ValidateObjectAsync(obj);

