use std::path::{Path, PathBuf};
use std::fs::create_dir_all;
use std::io::Write;
use std::env;
use std::collections::HashMap;

struct DirectoryManager {
    dir_map: HashMap<String, String>,
}

impl DirectoryManager {
    fn new() -> Self {
        DirectoryManager { dir_map: HashMap::new() }
    }

    fn create_dir(&mut self, path: &str) -> Result<(), std::io::Error> {
        let mut path = PathBuf::from(path);
        if !path.is_absolute() {
            return Err(std::io::Error::new(
                std::io::ErrorKind::InvalidInput,
                "Path must be absolute",
            ));
        }
        if let Some(dir) = self.dir_map.get(&path.to_string_lossy().to_string()) {
            create_dir_all(&dir, true)?;
        } else {
            if path.exists() && !path.is_dir() {
                return Err(std::io::Error::new(
                    std::io::ErrorKind::InvalidInput,
                    "Path exists but is not a directory",
                ));
            }
            if let Err(e) = create_dir_all(&path, true) {
                return Err(e);
            }
        }
        self.dir_map.insert(path.to_string_lossy().to_string(), path.display().to_string());
        Ok(())
    }

    fn set_env_var(&mut self, name: &str, value: &str) -> Result<(), std::io::Error> {
        env::set_var(name, value);
        Ok(())
    }
}

fn main() {
    let mut dir_manager = DirectoryManager::new();
    if let Err(e) = dir_manager.create_dir("/path/to/directory") {
        eprintln!("Error creating directory: {}", e);
    } else {
        println!("Directory created successfully");
    }

    if let Err(e) = dir_manager.set_env_var("VARIABLE_NAME", "variable_value") {
        eprintln!("Error setting environment variable: {}", e);
