// Define a structure to manage dynamic collection of UEConnectionStatus structures
typedef struct {
    UEConnectionStatus* connections;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} UEConnectionManager;

// Initialize the UEConnectionManager with initial capacity and size 0
UEConnectionManager* ue_manager_init(size_t capacity) {
    UEConnectionManager* manager = (UEConnectionManager*) malloc(sizeof(UEConnectionManager));
    manager->connections = (UEConnectionStatus*) calloc(capacity, sizeof(UEConnectionStatus));
    manager->capacity = capacity;
    manager->size = 0;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

// Resize the UEConnectionManager to maintain optimal memory usage and performance
void ue_manager_resize(UEConnectionManager* manager) {
    size_t new_capacity = (manager->size * 2 < manager->capacity) ? manager->size * 2 : manager->capacity + 16;
    UEConnectionStatus** new_connections = (UEConnectionStatus**) realloc(manager->connections, new_capacity * sizeof(UEConnectionStatus));
    manager->connections = new_connections;
    manager->capacity = new_capacity;
}

// Insert a new UEConnectionStatus into the UEConnectionManager
void ue_manager_insert(UEConnectionManager* manager, int session_id, const char* status) {
    pthread_mutex_lock(&manager->lock);
    if (manager->size >= manager->capacity) {
        ue_manager_resize(manager);
    }
    UEConnectionStatus* new_connection = &manager->connections[manager->size++];
    new_connection->session_id = session_id;
    strcpy(new_connection->status, status);
    pthread_mutex_unlock(&manager->lock);
}

// Evict a UEConnectionStatus from the UEConnectionManager
void ue_manager_evict(UEConnectionManager* manager) {
    if (manager->size > 0) {
        pthread_mutex_lock(&manager->lock);
