// Define the structure for UE Connection Status
typedef struct {
    int sessionId;
    char imei[17];
    char_tacacs_username[64];
    time_t timestamp;
} UEConnectionStatus;

// Define the dynamic collection of UE Connection Status structures
typedef struct {
    UEConnectionStatus* connections;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} UEConnectionCollection;

// Function to initialize the UE connection collection
UEConnectionCollection* ue_connections_init(size_t initial_capacity) {
    UEConnectionCollection* collection = (UEConnectionCollection*)malloc(sizeof(UEConnectionCollection));
    if (!collection) return NULL;

    collection->connections = (UEConnectionStatus*)calloc(initial_capacity, sizeof(UEConnectionStatus));
    if (!collection->connections) {
        free(collection);
        return NULL;
    }

    collection->capacity = initial_capacity;
    collection->count = 0;
    pthread_mutex_init(&collection->lock, NULL);

    return collection;
}

// Function to add a new UE connection status
int ue_connections_add(UEConnectionCollection* collection, UEConnectionStatus* new_connection) {
    if (collection->count == collection->capacity) {
        // Reallocate memory with increased capacity
        size_t new_capacity = collection->capacity * 2;
        UEConnectionStatus** temp_connections = (UEConnectionStatus**)realloc(collection->connections, new_capacity * sizeof(UEConnectionStatus));
        if (!temp_connections) return -1;

        collection->connections = temp_connections;
        collection->capacity = new_capacity;
    }

    // Add the new connection to the collection
    memcpy(&collection->connections[collection->count], new_connection, sizeof(UEConnectionStatus));
    collection->count++;

    return 0;
}

// Function to get a UE connection status by session ID
int ue_connections_get_by_session_id(UEConnectionCollection* collection, int session_id, UEConnectionStatus* target_connection) {
    for (size_t i = 0; i < collection->count; i++) {
        if (collection->connections[i].sessionId == session_id) {
            memcpy(target_connection, &collection->connections[i], sizeof(UEConnectionStatus));
            return 0;
        }
    }

    return -1;
}

// Function to free the UE connection collection
void ue_connections_free(UEConnectionCollection* collection) {
    free(collection->connections);
    pthread_mutex_destroy(&collection->lock);
    free(collection);
}
