function copyBytes(chunks, byteCount) {
  const targetBuffer = Buffer.alloc(byteCount);
  let writtenBytes = 0;
  let bytesRead = 0;

  for (const chunk of chunks) {
    bytesRead += chunk.length;
    if (byteCount <= bytesRead) break;
    const remainingBytes = Math.min(chunk.length, byteCount - bytesRead);
    targetBuffer.copy(chunk, 0, bytesRead, bytesRead + remainingBytes);
    writtenBytes += remainingBytes;
  }

  return writtenBytes < byteCount ? Buffer.alloc(0) : targetBuffer;
}

