class DeviceLogEntry {
public:
    int id;
    std::string message;

    DeviceLogEntry(int id, const std::string& message) : id(id), message(message) {}
};

class UEConnectionStatus {
public:
    int id;
    bool connected;

    UEConnectionStatus(int id, bool connected) : id(id), connected(connected) {}
};

class LogManager {
private:
    std::mutex mtx;
    std::condition_variable cv;
    std::queue<DeviceLogEntry> logEntries;
    std::vector<UEConnectionStatus> connectionStatuses;

public:
    void addLogEntry(const DeviceLogEntry& entry) {
        std::unique_lock<std::mutex> lock(mtx);
        logEntries.push(entry);
        lock.unlock();
        cv.notify_one();
    }

    void addConnectionStatus(const UEConnectionStatus& status) {
        std::unique_lock<std::mutex> lock(mtx);
        connectionStatuses.push_back(status);
        lock.unlock();
        cv.notify_one();
    }

    void processLogs() {
        while (true) {
            std::unique_lock<std::mutex> lock(mtx);
            cv.wait(lock, [this] { return !logEntries.empty(); });
            DeviceLogEntry entry = logEntries.front();
            logEntries.pop();
            // Process the log entry
            std::cout << "Received log entry: " << entry.message << std::endl;
        }
    }

    void processConnectionStatus() {
        while (true) {
            std::unique_lock<std::mutex> lock(mtx);
            cv.wait(lock, [this] { return !connectionStatuses.empty(); });
            UEConnectionStatus status = connectionStatuses.back();
            connectionStatuses.pop_back();
            // Process the connection status
            std::cout << "Received connection status: " << (status.connected ? "connected" : "disconnected") << std::endl;
        }
    }

    void startProcessingLogs() {
        thread t1(&LogManager::processLogs, this);
        thread t2(&LogManager::processConnectionStatus, this);
        t1.join();
        t2.join();
    }
};
