#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pthread.h>

// Config structure to store commands and their respective APIs
typedef struct {
    char* command;
    char* api;
} Config;

// Function to load config from file
Config* load_config(char* filename) {
    // Load the config from a file
    // For simplicity, let's assume it's just reading lines from a text file
    FILE* f = fopen(filename, "r");
    if (f == NULL) {
        return NULL;
    }

    Config* config = malloc(sizeof(Config));
    char line[1024];
    while (fgets(line, sizeof(line), f)) {
        // Split the line into command and api
        char* token = strtok(line, "=");
        config->command = strdup(token);
        token = strtok(NULL, ";");
        config->api = strdup(token);
    }

    fclose(f);
    return config;
}

// Function to execute a command using an API
int execute_command(Config* config) {
    // Check if the config is valid
    if (config == NULL || strlen(config->command) == 0 || strlen(config->api) == 0) {
        return 0;  // Return 0 for error
    }

    // Create a socket to connect to the API
    int sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        return 0;
    }

    // Connect to the API
    struct sockaddr_in api_addr;
    api_addr.sin_family = AF_INET;
    api_addr.sin_port = htons(8080);  // Replace with the actual port number of the API
    inet_pton(AF_INET, "127.0.0.1", &api_addr.sin_addr);
    if (connect(sockfd, (struct sockaddr*)&api_addr, sizeof(api_addr)) < 0) {
        close(sockfd);
        return 0;
    }

    // Send the command to the API
    send(sockfd, config->command, strlen(config->command), 0);

    // Receive the response from the API
    char buffer[1024];
    recv(sockfd, buffer, sizeof(buffer), 0);

    // Close the socket and return the result
    close(sockfd);
    if (strncmp(buffer, "OK", 2) == 0) {
        return 1;  // Return 1 for success
    } else {
        return 0;  // Return 0 for error
    }
}

// Function to execute a command asynchronously using an API
void* async_execute_command(void* arg) {
    Config* config = (Config*)arg;

    // Create a socket to connect to the API
    int sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        return NULL;  // Return NULL for error
    }

    // Connect to the API
    struct sockaddr_in api_addr;
    api_addr.sin_family = AF_INET;
    api_addr.sin_port = htons(8080);  // Replace with the actual port number of the API
    inet_pton(AF_INET, "127.0.0.1", &api_addr.sin_addr);
    if (connect(sockfd, (struct sockaddr*)&api_addr, sizeof(api_addr)) < 0) {
        close(sockfd);
        return NULL;
    }

    // Send the command to the API
    send(sockfd, config->command, strlen(config->command), 0);

    // Receive the response from the API
    char buffer[1024];
    recv(sockfd, buffer, sizeof(buffer), 0);

    // Close the socket and return the result
    close(sockfd);
    if (strncmp(buffer, "OK", 2) == 0) {
        pthread_exit(NULL);  // Exit the thread
    } else {
        pthread_exit((void*)config->command);  // Return the error command for debugging
    }
}

// Function to execute a command synchronously using an API
int sync_execute_command(Config* config) {
    int status = -1;  // Initialize with error

    // Create a socket to connect to the API
    int sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        return 0;  // Return 0 for error
    }

    // Connect to the API
    struct sockaddr_in api_addr;
    api_addr.sin_family = AF_INET;
    api_addr.sin_port = htons(8080);  // Replace with the actual port number of the API
    inet_pton(AF_INET, "127.0.0.1", &api_addr.sin_addr);
    if (connect(sockfd, (struct sockaddr*)&api_addr, sizeof(api_addr)) < 0) {
        close(sockfd);
        return 0;
    }

    // Send the command to the API
    send(sockfd, config->command, strlen(config->command), 0);

    // Receive the response from the API
    char buffer[1024];
    recv(sockfd, buffer, sizeof(buffer), 0);

    // Close the socket and return the result
    close(sockfd);
    if (strncmp(buffer, "OK", 2) == 0) {
        status = 1;  // Return 1 for success
    }

    return status;
}

int main() {
    Config* config = load_config("config.txt");
    if (config == NULL) {
        return -1;  // Return error code
    }

    int result = execute_command(config);
    printf("Result: %d\n", result);  // Print the result

    pthread_t thread;
    pthread_create(&thread, NULL, async_execute_command, config);
    pthread_join(thread, NULL);  // Wait for the thread to finish

    return 0;  // Return success code
}
