// Define a function to identify and extract names of books from the Old Testament mentioned in input text
#include <json-c/json.h>

#define OLD_TESTAMENT_BOOKS "Genesis, Exodus, Leviticus, Numbers, Deuteronomy, Joshua, Judges, Ruth, 1Samuel, 2Samuel, 1Kings, 2Kings, 1Chronicles, 2Chronicles, Ezra, Nehemiah, Esther"

void extract_old_testament_books(const char* input_text) {
    json_object *json_obj = json_object_new_object();
    for (char** book : split_string(input_text, ", ")) {
        if (strstr(OLD_TESTAMENT_BOOKS, book[0])) {
            json_object_set_new(json_obj, book[0], json_object_new_string("1"));
        }
    }
}

// Function to split a string into an array of substrings
char** split_string(const char* str, const char* delimiter) {
    int count = 0;
    for (char c : str) {
        if (c == ',') {
            count++;
        }
    }
    char** arr = (char**)malloc((count + 1) * sizeof(char*));
    char* token = strtok(str, delimiter);
    int i = 0;
    while (token) {
        arr[i] = token;
        token = strtok(NULL, delimiter);
        i++;
    }
    arr[count] = NULL;
    return arr;
}

// Define a function to compute MD5 and SHA-256 hashes in parallel
#include <openssl/evp.h>
#include <openssl/hmac.h>

void compute_hashes(const char* input_file) {
    EVP_MD_CTX *mdctx;
    unsigned char md_value[64];
    const EVP_MD *md;
    int md_len;

    // Initialize MD5 and SHA-256 contexts
    md = EVP_sha256();
    mdctx = EVP_MD_CTX_new();
    EVP_DigestInit_ex(mdctx, md, NULL);

    // Compute hashes in parallel using PBKDF2-SHA256
    HMAC_CTX ctx;
    HMAC_Init(&ctx, "your_secret_key", 12, EVP_sha256());
    HMAC_Update(&ctx, input_file, strlen(input_file));
    unsigned char* hash = HMAC_Final(&ctx, NULL);

    // Print the hashes
    printf("MD5: %s\n", MD5(input_file));
    printf("SHA-256: %s\n", hex_encode(hash, 32));

    // Free resources
    EVP_DigestFree(mdctx);
    HMAC_Final(&ctx, hash);
}

