['Here is the C++ code for the OAuth2 access token response validation function:

```cpp
#include <iostream>
#include <json/json.h> // using jsoncpp library for parsing JSON strings

// Function to validate and deserialize an OAuth2 access token response
bool validateOAuthTokenResponse(const std::string& jsonStr) {
    Json::Value root;
    try {
        root = Json::parse(jsonStr); // attempt to parse the JSON string
    } catch (Json::Exception &e) {
        std::cerr << "Error parsing JSON: " << e.what() << std::endl;
        return false; // invalid JSON format
    }

    if (!root.isObject()) { // token response must be an object
        std::cerr << "Invalid token response format" << std::endl;
        return false;
    }

    const Json::Value& accessToken = root["access_token"];
    const Json::Value& expiresIn = root["expires_in"];
    const Json::Value& tokenType = root["token_type"];

    if (!accessToken.isString() || !expiresIn.isInt() || !tokenType.isString()) {
        std::cerr << "Invalid field types" << std::endl;
        return false; // expected types not found
    }

    if (accessToken.asString().empty() || expiresIn.asInt() <= 0) {
        std::cerr << "Invalid access token or expires_in value" << std::endl;
        return false; // invalid values
    }

    if (tokenType.asString() != "Bearer") {
        std::cerr << "Invalid token type" << std::endl;
        return false; // expected 'Bearer' token type not found
    }

    return true; // validation successful
}
```']

