#define UE_CONNECTION_STATUS_MAX 1000 // max number of connection status entries

typedef struct {
    int id;
    char status[50];
} UEConnectionStatus;

// dynamic array to store UE connection statuses
UEConnectionStatus* ue_connections = NULL;
int ue_connection_count = 0;
int ue_connection_max = UE_CONNECTION_STATUS_MAX;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// adaptive resizing strategy for the dynamic array
void resize_ue_connections(int new_max) {
    if (new_max > ue_connection_max) {
        ue_connections = realloc(ue_connections, new_max * sizeof(UEConnectionStatus));
        ue_connection_max = new_max;
    }
}

// function to add a new UE connection status
void add_ue_connection_status(int id, char* status) {
    pthread_mutex_lock(&lock);
    resize_ue_connections(ue_connection_count + 1);
    ue_connections[ue_connection_count].id = id;
    strcpy(ue_connections[ue_connection_count].status, status);
    ue_connection_count++;
    pthread_mutex_unlock(&lock);
}

// function to remove a UE connection status
void remove_ue_connection_status(int id) {
    int i;
    pthread_mutex_lock(&lock);
    for (i = 0; i < ue_connection_count; i++) {
        if (ue_connections[i].id == id) {
            break;
        }
    }
    if (i < ue_connection_count) {
        memmove(ue_connections + i, ue_connections + i + 1, (ue_connection_count - i - 1) * sizeof(UEConnectionStatus));
        ue_connection_count--;
        free(ue_connections[i]);
    }
    pthread_mutex_unlock(&lock);
}

// function to get a UE connection status
UEConnectionStatus* get_ue_connection_status(int id) {
    int i;
    pthread_mutex_lock(&lock);
    for (i = 0; i < ue_connection_count; i++) {
        if (ue_connections[i].id == id) {
            break;
        }
    }
    if (i < ue_connection_count) {
        UEConnectionStatus* status = &ue_connections[i];
        pthread_mutex_unlock(&lock);
        return status;
    } else {
        pthread_mutex_unlock(&lock);
        return NULL;
    }
}

// function to update a UE connection status
void update_ue_connection_status(int id, char* status) {
    int i;
    pthread_mutex_lock(&lock);
    for (i = 0; i < ue_connection_count; i++) {
        if (ue_connections[i].id == id) {
            strcpy(ue_connections[i].status, status);
            break;
        }
    }
    if (i >= ue_connection_count) {
        printf("UE connection not found: %d\n", id);
    }
    pthread_mutex_unlock(&lock);
}

// function to handle API updates
void update_ue_connections_from_api(char* api_response) {
    // parse the API response and add/update/remove UE connection statuses as needed
    // ...
}

int main() {
    // initialize the dynamic array with initial capacity
    ue_connections = malloc(UE_CONNECTION_STATUS_MAX * sizeof(UEConnectionStatus));
    ue_connection_max = UE_CONNECTION_STATUS_MAX;

    // start updating UE connections from the API periodically
    pthread_t thread;
    pthread_create(&thread, NULL, (void*)update_ue_connections_from_api, NULL);

    return 0;
}
