} UEConnectionStatus;

void ue_connection_status_manager_init();
void ue_connection_status_manager_shutdown();

int ue_connection_status_manager_add(UEConnectionStatus* status);
int ue_connection_status_manager_remove(uint64_t connection_id);
UEConnectionStatus* ue_connection_status_manager_get(uint64_t connection_id);

// thread-safe wrapper for atomic operations
uint32_t atomic_load(uint32_t* addr);
void atomic_store(uint32_t* addr, uint32_t val);

#endif  // UE_CONNECTION_STATUS_MANAGER_H

// ue_connection_status_manager.c
#include "ue_connection_status_manager.h"
#include <stdatomic_ops.h>
#include <pthread.h>

static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static atomic_uint64_t connection_ids[UINT_MAX];
static atomic_UEConnectionStatus* connection_statuses[UINT_MAX];

void ue_connection_status_manager_init() {
    // initialize thread-local storage
}

void ue_connection_status_manager_shutdown() {
    // release resources and shut down threads
}

int ue_connection_status_manager_add(UEConnectionStatus* status) {
    uint64_t connection_id = atomic_load(&connection_ids);
    if (connection_id >= UINT_MAX) return -1;
    atomic_store(&connection_ids, connection_id + 1);

    connection_statuses[connection_id].store(status, memory_order_relaxed);

    return 0;
}

int ue_connection_status_manager_remove(uint64_t connection_id) {
    if (connection_id >= UINT_MAX || connection_id < 0) return -1;

    // remove from cache and update internal state
    atomic_store(&connection_ids, connection_id);
    connection_statuses[connection_id].store(NULL, memory_order_relaxed);

    return 0;
}

UEConnectionStatus* ue_connection_status_manager_get(uint64_t connection_id) {
    if (connection_id >= UINT_MAX || connection_id < 0) return NULL;

    // read from cache and update internal state
    UEConnectionStatus* status = atomic_load(&connection_statuses[connection_id]);
    return status;
}

