    std::condition_variable cv;
    std::queue<DeviceLogEntry> deviceLogEntries;

public:
    void addDeviceLogEntry(DeviceLogEntry entry) {
        std::unique_lock<std::mutex> lock(mtx);
        deviceLogEntries.push(entry);
        cv.notify_all();
    }

    DeviceLogEntry getDeviceLogEntry() {
        std::unique_lock<std::mutex> lock(mtx);
        while (deviceLogEntries.empty()) {
            cv.wait(lock);
        }
        return deviceLogEntries.front();
    }
};

class AdaptiveCachingStrategy {
private:
    size_t cacheSize;
    double hitRate;

public:
    AdaptiveCachingStrategy(size_t initialCacheSize) : 
        cacheSize(initialCacheSize), hitRate(0.0) {}

    void updateHitRate(double newHitRate) {
        hitRate = newHitRate;
    }

    bool shouldCache() {
        return (hitRate > 0.5 && cacheSize < 100000);
    }
};

class EventStreamingPlatformInterface {
public:
    virtual void sendLogEntry(DeviceLogEntry entry) = 0;

    virtual ~EventStreamingPlatformInterface() {}
};

class DeviceLogEntriesProcessor : public std::enable_shared_from_this<DeviceLogEntriesProcessor> {
private:
    EventStreamingPlatformInterface* eventStreamingPlatform;
    AdaptiveCachingStrategy adaptiveCachingStrategy;
    DeviceLogEntriesManager deviceLogEntriesManager;

public:
