        : eventStreamingPlatform(eventStreamingPlatform) {}

    void processDeviceLogEntry(DeviceLogEntry entry) {
        if (adaptiveCachingStrategy.shouldCache()) {
            // cache the log entry
        } else {
            // send the log entry to the event streaming platform
            eventStreamingPlatform->sendLogEntry(entry);
        }
    }

    void startProcessing() {
        std::thread thread([this]() {
            while (true) {
                DeviceLogEntry entry = deviceLogEntriesManager.getDeviceLogEntry();
                processDeviceLogEntry(entry);
            }
        }).detach();
    }
};

