    class DynamicCollection {
        private:
            std::map<int, DeviceLogEntry> device_log_entries;
            std::vector<UEConnectionStatus> ue_connection_statuses;
            std::mutex lock;
            std::condition_variable cv;

        public:
            void add_device_log_entry(DeviceLogEntry entry) {
                // thread-safe operation
                std::unique_lock<std::mutex> ulock(lock);
                device_log_entries.insert({entry.id, entry});
                ulock.unlock();
                cv.notify_one(); // notify waiting threads
            }

            void add_ue_connection_status(UEConnectionStatus status) {
                // thread-safe operation
                std::unique_lock<std::mutex> ulock(lock);
                ue_connection_statuses.push_back(status);
                ulock.unlock();
                cv.notify_one(); // notify waiting threads
            }

            DeviceLogEntry get_device_log_entry(int id) {
                // thread-safe operation
                std::unique_lock<std::mutex> ulock(lock);
                if (device_log_entries.find(id) != device_log_entries.end()) {
                    return device_log_entries.at(id);
                } else {
                    throw std::runtime_error("Device log entry not found");
                }
            }

            UEConnectionStatus get_ue_connection_status(int id) {
                // thread-safe operation
                std::unique_lock<std::mutex> ulock(lock);
                for (auto& status : ue_connection_statuses) {
                    if (status.id == id) {
                        return status;
                    }
                }
                throw std::runtime_error("UE connection status not found");
            }

            void remove_device_log_entry(int id) {
                // thread-safe operation
                std::unique_lock<std::mutex> ulock(lock);
                device_log_entries.erase(id);
                ulock.unlock();
                cv.notify_one(); // notify waiting threads
            }

            void remove_ue_connection_status(int id) {
                // thread-safe operation
                std::unique_lock<std::mutex> ulock(lock);
                for (auto it = ue_connection_statuses.begin(); it != ue_connection_statuses.end();) {
                    if (it->id == id) {
                        it = ue_connection_statuses.erase(it);
                    } else {
                        ++it;
                    }
                }
                ulock.unlock();
                cv.notify_one(); // notify waiting threads
            }

            void clear() {
                // thread-safe operation
                std::unique_lock<std::mutex> ulock(lock);
                device_log_entries.clear();
                ue_connection_statuses.clear();
                ulock.unlock();
                cv.notify_one(); // notify waiting threads
            }
