#include <openssl/aes.h>
#include <openssl/err.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Function to initialize AES-256-CBC cipher with a given password
AES_Cipher *aes_cipher_init(const char *password, int *cipher_context) {
    // Set the IV length and key length to fixed values
    unsigned char iv[AES_BLOCK_SIZE], salt[SALT_SIZE];
    RAND_bytes(iv, AES_BLOCK_SIZE);
    RAND_bytes(salt, SALT_SIZE);

    // Derive the encryption key from the password using PBKDF2
    char *derived_key = NULL;
    int derived_key_len = 0;
    PBKDF2(password, strlen(password), salt, SALT_SIZE, &derived_key, &derived_key_len, 10000);

    // Initialize AES-256-CBC cipher context
    AES_Cipher *cipher = (AES_Cipher *)malloc(sizeof(AES_Cipher));
    cipher->key = derived_key;
    cipher->key_len = derived_key_len;
    cipher->iv = iv;
    cipher->iv_len = AES_BLOCK_SIZE;

    // Enable the cipher and return a pointer to the cipher context
    if (AES_set_encrypt_key(cipher->key, cipher->key_len, cipher)) {
        ERR_error_fp(stderr);
        free(derived_key);
        free(cipher);
        return NULL;
    }

    *cipher_context = cipher;
    return cipher;
}

// Function to clean up and disable the cipher when it is no longer needed
void aes_cipher_free(AES_Cipher *cipher) {
    if (cipher) {
        ERR_remove_sect163r2();
        free(cipher->key);
        free(cipher);
    }
}
