typedef struct UEConnectionStatus {
    int connection_id;
    char status[20];
} UEConnectionStatus;

typedef struct {
    UEConnectionStatus* entries;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} UEConnectionStatusCollection;

void ue_connection_status_collection_init(UEConnectionStatusCollection* collection, size_t initial_capacity) {
    collection->entries = (UEConnectionStatus*)malloc(initial_capacity * sizeof(UEConnectionStatus));
    collection->capacity = initial_capacity;
    collection->size = 0;
    pthread_mutex_init(&collection->lock, NULL);
}

void ue_connection_status_collection_insert(UEConnectionStatusCollection* collection, UEConnectionStatus* entry) {
    pthread_mutex_lock(&collection->lock);
    if (collection->size == collection->capacity) {
        // Adaptive resizing strategy
        size_t new_capacity = collection->capacity * 2;
        UEConnectionStatus* new_entries = (UEConnectionStatus*)realloc(collection->entries, new_capacity * sizeof(UEConnectionStatus));
        collection->entries = new_entries;
        collection->capacity = new_capacity;
    }
    memcpy(&collection->entries[collection->size], entry, sizeof(UEConnectionStatus));
    collection->size++;
    pthread_mutex_unlock(&collection->lock);
}

int ue_connection_status_collection_evict(UEConnectionStatusCollection* collection) {
    pthread_mutex_lock(&collection->lock);
    if (collection->size > 0) {
        UEConnectionStatus* evicted_entry = &collection->entries[--collection->size];
        free(evicted_entry);
        return 1;
    }
    pthread_mutex_unlock(&collection->lock);
    return 0;
}

void ue_connection_status_collection_free(UEConnectionStatusCollection* collection) {
    for (size_t i = 0; i < collection->size; i++) {
        free(&collection->entries[i]);
    }
    free(collection->entries);
    pthread_mutex_destroy(&collection->lock);
}
