        file_data = file.read()

    hashes = []
    for i in range(num_threads):
        start = i * len(file_data) // num_threads
        end = (i + 1) * len(file_data) // num_threads if i < num_threads - 1 else len(file_data)
        hash_data = file_data[start:end]

        md5_hash = hashlib.md5(hash_data).hexdigest()
        sha256_hash = hashlib.sha256(hash_data).hexdigest()

        hashes.append((md5_hash, sha256_hash))

