// ApplicationMetrics class represents real-time performance indicators
class ApplicationMetrics {
public:
    int id;
    std::string name;
    double latency;
    int requests;

    // Constructor
    ApplicationMetrics(int id, const std::string& name) : id(id), name(name), latency(0.0), requests(0) {}
};

// Thread-safe queue for storing ApplicationMetrics objects
class MetricsQueue {
private:
    std::mutex mtx;
    std::condition_variable cv;
    std::queue<ApplicationMetrics*> metricsQueue;

public:
    void enqueue(ApplicationMetrics* metric) {
        std::unique_lock<std::mutex> lock(mtx);
        metricsQueue.push(metric);
        cv.notify_one();
    }

    ApplicationMetrics* dequeue() {
        std::unique_lock<std::mutex> lock(mtx);
        while (metricsQueue.empty()) {
            cv.wait(lock);
        }
        ApplicationMetrics* metric = metricsQueue.front();
        metricsQueue.pop();
        return metric;
    }
};

// External API client to fetch metrics data
class MetricsApiClient {
public:
    std::vector<ApplicationMetrics*> fetchData() {
        // Simulate external API request and response
        std::this_thread::sleep_for(std::chrono::seconds(1));
        ApplicationMetrics* metric = new ApplicationMetrics(1, "Service A");
        metric->latency = 50.0;
        metric->requests = 100;
        return {metric};
    }
};

// Main application logic to manage metrics queue and API client
int main() {
    MetricsQueue metricsQueue;
    MetricsApiClient apiClient;

    // Start a thread to fetch metrics data from the external API
    std::thread apiThread([&apiClient, &metricsQueue]() {
        while (true) {
            std::vector<ApplicationMetrics*> metrics = apiClient.fetchData();
            for (ApplicationMetrics* metric : metrics) {
                metricsQueue.enqueue(metric);
            }
            std::this_thread::sleep_for(std::chrono::seconds(5));
        }
    });

    // Start a thread to process and analyze the metrics data
    std::thread analysisThread([&metricsQueue]() {
        while (true) {
            ApplicationMetrics* metric = metricsQueue.dequeue();
            if (metric != nullptr) {
                // Process and analyze the metric data here
                std::cout << "Received metric: " << metric->name << ", latency: " << metric->latency << ", requests: " << metric->requests << std::endl;
                delete metric;
            }
        }
    });

    apiThread.join();
    analysisThread.join();

    return 0;
}
