// Structure representing UE connection status
typedef struct {
    int ue_id;
    char imei[16];
    int rrc_connected;
} UEConnectionStatus;

// Dynamic collection of UE connections
typedef struct {
    UEConnectionStatus* connections;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} UECollections;

// Initialize UE connection collection
UECollections* ue_collections_init(size_t initial_capacity) {
    UECollections* collections = (UECollections*)malloc(sizeof(UECollections));
    if (!collections) return NULL;

    collections->connections = (UEConnectionStatus*)calloc(initial_capacity, sizeof(UEConnectionStatus));
    if (!collections->connections) {
        free(collections);
        return NULL;
    }

    collections->capacity = initial_capacity;
    collections->size = 0;
    pthread_mutex_init(&collections->mutex, NULL);

    return collections;
}

// Add UE connection to the collection
int ue_collections_add(UECollections* collections, int ue_id, const char* imei) {
    pthread_mutex_lock(&collections->mutex);
    if (collections->size >= collections->capacity) {
        // Resize the array when full
        size_t new_capacity = collections->capacity * 2;
        UEConnectionStatus* new_connections = (UEConnectionStatus*)realloc(collections->connections, new_capacity * sizeof(UEConnectionStatus));
        if (!new_connections) {
            pthread_mutex_unlock(&collections->mutex);
            return -1;
        }
        collections->connections = new_connections;
        collections->capacity = new_capacity;
    }

    UEConnectionStatus* connection = &collections->connections[collections->size];
    connection->ue_id = ue_id;
    strcpy(connection->imei, imei);
    connection->rrc_connected = 0; // Default to not connected

    collections->size++;
    pthread_mutex_unlock(&collections->mutex);

    return 0;
}

// Remove UE connection from the collection
int ue_collections_remove(UECollections* collections, int ue_id) {
    pthread_mutex_lock(&collections->mutex);
    for (size_t i = 0; i < collections->size; i++) {
        if (collections->connections[i].ue_id == ue_id) {
            // Shift elements down to fill the gap
            memmove(&collections->connections[i], &collections->connections[i + 1], (collections->size - i - 1) * sizeof(UEConnectionStatus));
            collections->size--;
            break;
        }
    }
    pthread_mutex_unlock(&collections->mutex);

    return 0;
}

// Evict outdated UE connections based on TTL
void ue_collections_evict(UECollections* collections, int ttl_seconds) {
    pthread_mutex_lock(&collections->mutex);
    for (size_t i = 0; i < collections->size; i++) {
        if (time(NULL) - collections->connections[i].last_update > ttl_seconds) {
            // Evict outdated connection
            memmove(&collections->connections[i], &collections->connections[i + 1], (collections->size - i - 1) * sizeof(UEConnectionStatus));
            collections->size--;
        }
    }
    pthread_mutex_unlock(&collections->mutex);
}

