#include <iostream>
#include <fstream>
#include <string>
#include <vector>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <chrono>
#include <map>
#include <unordered_map>
#include <queue>

// Utility classes and functions
class ThreadPool {
public:
    ThreadPool(size_t numThreads) : stop(false), threads(numThreads) {
        for (auto& thread in threads) {
            thread = std::thread([this] {
                while (!stop) {
                    std::function<void()> task;
                    {
                        std::unique_lock<std::mutex> lock(queue_mutex);
                        // Wait until a task is available
                        queue_wait.lock();
                        while (queue.empty()) {
                            queue_wait.wait(lock, [this] { return !this->stop || !this->queue.empty(); });
                        }
                        // Get the next task from the queue
                        task = std::move(queue.front());
                        queue.pop();
                    }
                    // Process the task
                    task();
                }
            });
        }
    }

    ~ThreadPool() {
        {
            std::unique_lock<std::mutex> lock(queue_mutex);
            stop = true;
        }
        // Wait for all threads to finish
        for (auto& thread in threads) {
            thread.join();
        }
    }

    template <class F>
    void enqueue(F&& f) {
        {
            std::lock_guard<std::mutex> lock(queue_mutex);
            queue.emplace(std::forward<F>(f));
        }
        // Wake up one of the threads
        queue_wait.notify_one();
    }

private:
    bool stop;
    std::vector<std::thread> threads;
    std::queue<std::function<void()>> queue;
    mutable std::mutex queue_mutex;
    mutable std::condition_variable queue_wait;
};

