// Define UEConnectionStatus structure
typedef struct {
    int connection_id;
    char* status;
} UEConnectionStatus;

// Define dynamic collection of UEConnectionStatus structures
typedef struct {
    UEConnectionStatus** connections;
    size_t capacity;
    pthread_mutex_t mutex;
    size_t count;
} UEConnections;

// Initialize UEConnections with given initial capacity
UEConnections* ue_connections_init(size_t initial_capacity) {
    UEConnections* connections = (UEConnections*)malloc(sizeof(UEConnections));
    connections->connections = (UEConnectionStatus**)malloc(initial_capacity * sizeof(UEConnectionStatus*));
    connections->capacity = initial_capacity;
    pthread_mutex_init(&connections->mutex, NULL);
    connections->count = 0;
    return connections;
}

// Add UEConnectionStatus to the dynamic collection
void ue_connections_add(UEConnections* connections, UEConnectionStatus* connection) {
    if (connections->count >= connections->capacity) {
        // Resize the array when it reaches capacity
        size_t new_capacity = connections->capacity * 2 + 1;
        UEConnectionStatus** new_connections = (UEConnectionStatus**)realloc(connections->connections, new_capacity * sizeof(UEConnectionStatus*));
        connections->connections = new_connections;
        connections->capacity = new_capacity;
    }
    connections->connections[connections->count] = connection;
    connections->count++;
}

// Get UEConnectionStatus from the dynamic collection by ID
UEConnectionStatus* ue_connections_get_by_id(UEConnections* connections, int connection_id) {
    pthread_mutex_lock(&connections->mutex);
    for (size_t i = 0; i < connections->count; i++) {
        if (connections->connections[i]->connection_id == connection_id) {
            UEConnectionStatus* connection = connections->connections[i];
            pthread_mutex_unlock(&connections->mutex);
            return connection;
        }
    }
    pthread_mutex_unlock(&connections->mutex);
    return NULL;
}

