typedef struct {
    int id;
    char* state;
} UEConnectionStatus;

// Define a struct to manage the dynamic collection of UEConnectionStatus structures
typedef struct {
    UEConnectionStatus** connections;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} UEConnectionManager;

// Function to read integers from standard input and store them in the dynamic array
void read_integers(UEConnectionManager* manager) {
    int id, num;
    while (scanf("%d", &id) == 1 && scanf("%d", &num) == 1) {
        // Allocate memory for a new UEConnectionStatus struct
        UEConnectionStatus* connection = malloc(sizeof(UEConnectionStatus));
        connection->id = id;
        connection->state = strdup("available");

        // Realloc the dynamic array if necessary
        if (manager->size >= manager->capacity) {
            manager->capacity *= 2;
            manager->connections = realloc(manager->connections, sizeof(void*) * manager->capacity);
        }

        // Store the new connection status in the dynamic array
        manager->connections[manager->size++] = connection;
    }
}

// Function to find and print the largest integer in the dynamic array
void find_largest_integer(UEConnectionManager* manager) {
    UEConnectionStatus* max_connection = NULL;
    int max_id = 0;

    pthread_mutex_lock(&manager->mutex);

    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->connections[i]->id > max_id) {
            max_id = manager->connections[i]->id;
            max_connection = manager->connections[i];
        }
    }

    pthread_mutex_unlock(&manager->mutex);

    printf("Largest integer: %d\n", max_id);
}

// Initialize the UEConnectionManager struct
void ue_connection_manager_init(UEConnectionManager* manager) {
    manager->connections = NULL;
    manager->capacity = 2;
    manager->size = 0;
    pthread_mutex_init(&manager->mutex, NULL);
}
