    char indication;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the library data structure to manage dynamic collections
typedef struct {
    UEConnectionStatus* connections;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
} DynamicCollection;

// Function prototypes
DynamicCollection* create_collection(size_t initial_capacity);
void add_connection(DynamicCollection*, UEConnectionStatus*);
UEConnectionStatus* get_connection_by_rnti(DynamicCollection*, int);
void remove_connection(DynamicCollection*, int);
void resize_collection(DynamicCollection*, size_t);
size_t get_collection_size(DynamicCollection*);

// Library functions
DynamicCollection* create_collection(size_t initial_capacity) {
    DynamicCollection* collection = (DynamicCollection*)malloc(sizeof(DynamicCollection));
    collection->connections = (UEConnectionStatus*)malloc(initial_capacity * sizeof(UEConnectionStatus));
    collection->capacity = initial_capacity;
    collection->size = 0;
    pthread_mutex_init(&collection->mutex, NULL);
    pthread_cond_init(&collection->cond, NULL);
    return collection;
}

void add_connection(DynamicCollection* collection, UEConnectionStatus* connection) {
    pthread_mutex_lock(&collection->mutex);
    if (collection->size >= collection->capacity) {
        resize_collection(collection, collection->capacity * 2);
    }
    collection->connections[collection->size] = *connection;
    collection->size++;
    pthread_cond_signal(&collection->cond);
    pthread_mutex_unlock(&collection->mutex);
}

UEConnectionStatus* get_connection_by_rnti(DynamicCollection* collection, int rnti) {
    UEConnectionStatus* connection;
    pthread_mutex_lock(&collection->mutex);
    for (int i = 0; i < collection->size; i++) {
        if (collection->connections[i].rnti == rnti) {
            connection = &collection->connections[i];
            break;
        }
    }
    pthread_mutex_unlock(&collection->mutex);
    return connection;
}

void remove_connection(DynamicCollection* collection, int rnti) {
    UEConnectionStatus* connection;
    pthread_mutex_lock(&collection->mutex);
    for (int i = 0; i < collection->size; i++) {
        if (collection->connections[i].rnti == rnti) {
            connection = &collection->connections[i];
            memmove(&collection->connections[i], &collection->connections[i+1], (collection->size - i - 1) * sizeof(UEConnectionStatus));
            collection->size--;
            break;
        }
    }
    pthread_mutex_unlock(&collection->mutex);
}

void resize_collection(DynamicCollection* collection, size_t new_capacity) {
    UEConnectionStatus* new_connections = (UEConnectionStatus*)malloc(new_capacity * sizeof(UEConnectionStatus));
    memcpy(new_connections, collection->connections, collection->size * sizeof(UEConnectionStatus));
    free(collection->connections);
    collection->connections = new_connections;
    collection->capacity = new_capacity;
}

size_t get_collection_size(DynamicCollection* collection) {
    return collection->size;
}
