};

class SensorDataManager {
private:
    std::mutex mtx;
    std::vector<SensorData> data;
    std::unordered_map<int, int> sensorIdToIndexMap;
    bool isUpdating = false;

public:
    void addSensorData(SensorData& data) {
        std::lock_guard<std::mutex> lock(mtx);
        this->data.push_back(data);
        sensorIdToIndexMap[data.id] = this->data.size() - 1;
    }

    SensorData getSensorData(int id) {
        std::lock_guard<std::mutex> lock(mtx);
        if (sensorIdToIndexMap.find(id) != sensorIdToIndexMap.end()) {
            return data[sensorIdToIndexMap.at(id)];
        } else {
            throw std::runtime_error("Sensor data not found");
        }
    }

    void updateSensorData(int id, float value) {
        std::lock_guard<std::mutex> lock(mtx);
        if (sensorIdToIndexMap.find(id) != sensorIdToIndexMap.end()) {
            data[sensorIdToIndexMap.at(id)].value = value;
        } else {
            throw std::runtime_error("Sensor data not found");
        }
    }

    void calculateAverage(float& average, bool weighted) {
        float sum = 0.0f;
        int count = 0;

        std::lock_guard<std::mutex> lock(mtx);
        for (const auto& sensorData : data) {
            if (!sensorData.isValid) continue;
            sum += sensorData.value;
            count++;
        }

        average = weighted ? (sum / count) : (sum / static_cast<float>(data.size()));
    }
};

