// Define structure for UE connection status
typedef struct {
    int id;
    int status;
    time_t timestamp;
} UEConnectionStatus;

// Define dynamic array to manage connections
typedef struct {
    UEConnectionStatus* data;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} ConnectionManager;

// Function to create a new connection manager with initial capacity
ConnectionManager* connection_manager_create(size_t initial_capacity) {
    ConnectionManager* cm = (ConnectionManager*)malloc(sizeof(ConnectionManager));
    cm->data = (UEConnectionStatus*)calloc(initial_capacity, sizeof(UEConnectionStatus));
    cm->capacity = initial_capacity;
    cm->size = 0;
    pthread_mutex_init(&cm->lock, NULL);
    return cm;
}

// Function to add a new connection status
void connection_manager_add(ConnectionManager* cm, UEConnectionStatus* status) {
    pthread_mutex_lock(&cm->lock);
    if (cm->size == cm->capacity) {
        // Realloc array with doubled capacity
        size_t new_capacity = cm->capacity * 2;
        UEConnectionStatus* newData = (UEConnectionStatus*)realloc(cm->data, new_capacity * sizeof(UEConnectionStatus));
        cm->data = newData;
        cm->capacity = new_capacity;
    }
    // Add new status to the end of the array
    cm->data[cm->size] = *status;
    cm->size++;
    pthread_mutex_unlock(&cm->lock);
}

// Function to remove outdated connections based on TTL
void connection_manager_evict(ConnectionManager* cm, time_t current_time) {
    pthread_mutex_lock(&cm->lock);
    for (int i = 0; i < cm->size; i++) {
        if (current_time - cm->data[i].timestamp > 300) { // Check every 5 minutes
            memmove(&cm->data[i], &cm->data[i + 1], (cm->size - i - 1) * sizeof(UEConnectionStatus));
            cm->size--;
            i--;
        }
    }
    pthread_mutex_unlock(&cm->lock);
}

// Function to get the number of connections
int connection_manager_size(ConnectionManager* cm) {
    int size;
    pthread_mutex_lock(&cm->lock);
    size = cm->size;
    pthread_mutex_unlock(&cm->lock);
    return size;
}
