class BatchProcessor {
public:
    BatchProcessor(int batchSize, int maxParallelStreams, std::chrono::milliseconds timeout)
        : batchSize_(batchSize), maxParallelStreams_(maxParallelStreams), timeout_(timeout) {}

    void process(std::function<void()> batchProc);

private:
    int batchSize_;
    int maxParallelStreams_;
    std::chrono::milliseconds timeout_;

    std::queue<std::function<void()>> taskQueue_;
    std::mutex taskMutex_;
    std::condition_variable taskCondition_;
    std::vector<std::thread> workerThreads_;

    void startWorkerThread();
    void stopWorkerThread();

    template<typename... Args>
    void executeBatchProc(Args&&... args);
};

void BatchProcessor::startWorkerThread() {
    for (int i = 0; i < maxParallelStreams_; ++i) {
        workerThreads_.emplace_back([this]() {
            while (true) {
                std::unique_lock<std::mutex> lock(taskMutex_);
                taskCondition_.wait_for(std::chrono::milliseconds(timeout_), [this]() {
                    return !taskQueue_.empty();
                });
                auto task = std::move(taskQueue_.front());
                taskQueue_.pop();
                lock.unlock();
                executeBatchProc(task);
            }
        });
    }
}

void BatchProcessor::stopWorkerThread() {
    for (auto& thread : workerThreads_) {
        thread.join();
    }
}

template<typename... Args>
