class LogAggregator {
public:
    virtual ~LogAggregator() {}
    virtual void aggregate(const std::vector<std::string>& logs) = 0;
};

// Implement a basic log aggregator that counts the number of logs by level (INFO, ERROR, etc.)
class BasicLogAggregator : public LogAggregator {
public:
    void aggregate(const std::vector<std::string>& logs) override {
        // Count the number of logs by level
        std::map<std::string, int> logCounts;
        for (const auto& log : logs) {
            const size_t pos = log.find(" ");
            const std::string logLevel = log.substr(0, pos);
            if (++logCounts[logLevel] == 1) {
                // Handle the first occurrence of each level
                processFirstOccurrence(logLevel);
            }
        }
    }

