    Location *Location `json:"location"`
}

// API main handler
func main() {
    r := gin.New()

    // Handle CRUD operations
    r.POST("/users", createUser)
    r.GET("/users/:id", getUser)
    r.PUT("/users/:id", updateUser)
    r.DELETE("/users/:id", deleteUser)

    // Handle concurrency control
    r.Use(concurrencyControl())

    // Handle authentication and authorization
    r.Use(authenticate())
    r.Use(authorize())

    // Start the API server
    r.Run(":8080")
}

// Concurrency control middleware
func concurrencyControl() gin.HandlerFunc {
    return func(c *gin.Context) {
        c.Next()
    }
}

// Authentication middleware
func authenticate() gin.HandlerFunc {
    return func(c *gin.Context) {
        // Authenticate the user
        if !c.Request.Header.Get("Authorization") == "Bearer YOUR_API_KEY" {
            c.JSON(401, gin.H{"message": "Unauthorized"})
            c.Abort()
            return
        }
        c.Next()
    }
}

// Authorization middleware
func authorize() gin.HandlerFunc {
    return func(c *gin.Context) {
        // Check if the user has permission to access the resource
        if !hasPermission(c.Request.URL.Path) {
            c.JSON(403, gin.H{"message": "Forbidden"})
            c.Abort()
            return
        }
        c.Next()
    }
}

// Create a new user
func createUser(c *gin.Context) {
    // Validate the request body
    var user User
    if err := c.BindJSON(&user); err != nil {
        c.JSON(400, gin.H{"message": "Invalid request body"})
        return
    }

    // Insert the user into the database
    db.InsertUser(user)

    c.JSON(201, user)
}

// Get a user by ID
func getUser(c *gin.Context) {
    // Retrieve the user from the database
    user, err := db.GetUser(c.Param("id"))
    if err != nil {
        c.JSON(404, gin.H{"message": "User not found"})
        return
    }

    c.JSON(200, user)
}

// Update a user
func updateUser(c *gin.Context) {
    // Retrieve the user from the database
    user, err := db.GetUser(c.Param("id"))
    if err != nil {
        c.JSON(404, gin.H{"message": "User not found"})
        return
    }

    // Validate the request body
    var updatedUser User
    if err := c.BindJSON(&updatedUser); err != nil {
        c.JSON(400, gin.H{"message": "Invalid request body"})
        return
    }

    // Update the user in the database
    db.UpdateUser(user.ID, updatedUser)

    c.JSON(200, updatedUser)
}

// Delete a user
func deleteUser(c *gin.Context) {
    // Retrieve the user from the database
    user, err := db.GetUser(c.Param("id"))
    if err != nil {
        c.JSON(404, gin.H{"message": "User not found"})
        return
    }

    // Delete the user from the database
    db.DeleteUser(user.ID)

    c.JSON(204, nil)
}

// Concurrency control for optimistic concurrency control
func concurrencyControl() gin.HandlerFunc {
    return func(c *gin.Context) {
        // Check if the request is a PUT or DELETE operation
        if c.Request.Method == "PUT" || c.Request.Method == "DELETE" {
            // Get the current version of the user
            var user User
            db.GetUser(c.Param("id"), &user)

            // Check if the client-provided version matches the server-side version
            if user.Version != c.GetQuery("version") {
                c.JSON(409, gin.H{"message": "Conflict"})
                return
            }
        }

        c.Next()
    }
}
