#include <string.h>

// Thread-safe, dynamically expanding array to store integers
typedef struct {
    int* data;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} IntegerArray;

IntegerArray* integer_array_create(size_t initial_capacity) {
    IntegerArray* array = malloc(sizeof(IntegerArray));
    array->data = malloc(initial_capacity * sizeof(int));
    array->capacity = initial_capacity;
    array->size = 0;
    pthread_mutex_init(&array->mutex, NULL);
    return array;
}

void integer_array_insert(IntegerArray* array, int value) {
    pthread_mutex_lock(&array->mutex);
    if (array->size == array->capacity) {
        array->data = realloc(array->data, (array->capacity * 2) * sizeof(int));
        array->capacity *= 2;
    }
    array->data[array->size++] = value;
    pthread_mutex_unlock(&array->mutex);
}

int integer_array_max(IntegerArray* array) {
    int max = INT_MIN;
    for (size_t i = 0; i < array->size; i++) {
        if (array->data[i] > max)
            max = array->data[i];
    }
    return max;
}
