    UEConnectionSet* set = (UEConnectionSet*)malloc(sizeof(UEConnectionSet));
    set->entries = (UEConnectionStatus**)malloc(initialCapacity * sizeof(UEConnectionStatus*));
    set->capacity = initialCapacity;
    pthread_mutexattr_t attr;
    pthread_mutexattr_init(&attr);
    pthread_mutexattr_settype(&attr, PTHREAD_MUTEX_ADAPTIVE_NP);
    pthread_mutex_init(&set->lock, &attr);
    return set;
}

// Add a new UE connection status to the collection
void ueConnectionSet_add(UEConnectionSet* set, UEConnectionStatus* entry) {
    pthread_mutex_lock(&set->lock);
    if (set->capacity <= set->entries) {
        size_t newCapacity = set->capacity * 2;
        set->entries = (UEConnectionStatus**)realloc(set->entries, newCapacity * sizeof(UEConnectionStatus*));
        set->capacity = newCapacity;
    }
    set->entries[set->capacity - 1] = entry;
    pthread_mutex_unlock(&set->lock);
}

