#include <unistd.h>

// Define the structure to store connection status
typedef struct {
    int status;
    char* description;
} UEConnectionStatus;

// Define a dynamically resizable array to store connection status
typedef struct {
    UEConnectionStatus** statuses;
    size_t capacity;
    size_t size;
} ConnectionStatusArray;

// Initialize a new connection status array with the given initial capacity
ConnectionStatusArray* init_connection_status_array(size_t initial_capacity) {
    ConnectionStatusArray* array = (ConnectionStatusArray*)malloc(sizeof(ConnectionStatusArray));
    array->statuses = (UEConnectionStatus**)malloc(initial_capacity * sizeof(UEConnectionStatus*));
    array->capacity = initial_capacity;
    array->size = 0;
    return array;
}

// Add a new connection status to the array
void add_connection_status_array(ConnectionStatusArray* array, UEConnectionStatus* status) {
    if (array->size >= array->capacity) {
        // Resize the array if it's full
        array->statuses = (UEConnectionStatus**)realloc(array->statuses, 2 * array->capacity * sizeof(UEConnectionStatus*));
        array->capacity *= 2;
    }
    array->statuses[array->size] = status;
    array->size++;
}

// Free the connection status array and its contents
void free_connection_status_array(ConnectionStatusArray* array) {
    for (int i = 0; i < array->size; i++) {
        free(array->statuses[i]->description);
        free(array->statuses[i]);
    }
    free(array->statuses);
    free(array);
}

// Define a semaphore to control access to the connection status array
sem_t* init_semaphore() {
    sem_t* semaphore = (sem_t*)malloc(sizeof(sem_t));
    sem_init(semaphore, 0, 1);
    return semaphore;
}

// Acquire the semaphore before accessing the connection status array
void acquire_semaphore(sem_t* semaphore) {
    sem_wait(semaphore);
}

// Release the semaphore after accessing the connection status array
void release_semaphore(sem_t* semaphore) {
    sem_post(semaphore);
}

// Define a function to retrieve the current status of all connections
UEConnectionStatus** get_connection_statuses(ConnectionStatusArray* array) {
    UEConnectionStatus** statuses = (UEConnectionStatus**)malloc(array->size * sizeof(UEConnectionStatus*));
    for (int i = 0; i < array->size; i++) {
        statuses[i] = array->statuses[i];
    }
    return statuses;
}

// Define a function to update the status of a connection
void update_connection_status(ConnectionStatusArray* array, UEConnectionStatus* new_status) {
    acquire_semaphore(array->semaphore);
    for (int i = 0; i < array->size; i++) {
        if (array->statuses[i]->status == new_status->status) {
            // Update the existing status
            array->statuses[i] = new_status;
            break;
        }
    }
    release_semaphore(array->semaphore);
}

// Define a function to remove a connection from the array
void remove_connection(ConnectionStatusArray* array, UEConnectionStatus* status) {
    acquire_semaphore(array->semaphore);
    for (int i = 0; i < array->size; i++) {
        if (array->statuses[i] == status) {
            // Remove the connection
            memmove(&array->statuses[i], &array->statuses[i+1], (array->size - i - 1) * sizeof(UEConnectionStatus*));
            array->size--;
            break;
        }
    }
    release_semaphore(array->semaphore);
}

// Define a function to free the connection status array and its contents
void free_connection_status_array_and_contents(ConnectionStatusArray* array) {
