    std::string line;
    while (std::getline(std::cin, line)) {
        FileMetaData metaData;
        metaData.filePath = line;
        metaData.fileSize = 0; // assuming we'll calculate this later
        metaData.lastModified = std::time(nullptr); // default to current time
        metaData.checksum = ""; // default checksum

        fileMetadata.push_back(metaData);
    }
}

bool checkFileCondition(const FileMetaData& metaData) {
    auto now = std::chrono::system_clock::now().time_since_epoch();
    auto sevenDaysAgo = now - std::chrono::hours(168); // 7 days in hours

    if (metaData.lastModified < sevenDaysAgo)
        return false; // file not modified in last 7 days

    // Add your checksum validation logic here
