typedef struct {
    char *name;
    int ttl; // Time-To-Live value
} UEConnectionStatus;

// Define a structure to represent a connection status
struct ConnectionStatus {
    UEConnectionStatus *ue_status;
    pthread_mutex_t lock;
};

// Function to initialize the connection status structure
void init_connection_status(struct ConnectionStatus *connection) {
    connection->ue_status = NULL;
    pthread_mutex_init(&connection->lock, NULL);
}

// Function to add a new UE connection status to the dynamic collection
void add_ue_status(struct ConnectionStatus *connection, char *name, int ttl) {
    UEConnectionStatus *new_ue_status = (UEConnectionStatus *)malloc(sizeof(UEConnectionStatus));
    new_ue_status->name = strdup(name);
    new_ue_status->ttl = ttl;

    // Add the new UE connection status to the dynamic collection
    if (connection->ue_status == NULL) {
        connection->ue_status = new_ue_status;
    } else {
        UEConnectionStatus *temp = connection->ue_status;
        while (temp->next != NULL) temp = temp->next;
        temp->next = new_ue_status;
    }
}

// Function to remove a UE connection status from the dynamic collection
void remove_ue_status(struct ConnectionStatus *connection, char *name) {
    // Find the UE connection status with the given name in the dynamic collection
    UEConnectionStatus *current = connection->ue_status;
    UEConnectionStatus *previous = NULL;

    while (current != NULL && strcmp(current->name, name) != 0) {
        previous = current;
        current = current->next;
    }

    if (current == NULL) return; // UE connection status not found

    // Remove the UE connection status from the dynamic collection
    if (previous == NULL) {
        connection->ue_status = current->next;
    } else {
        previous->next = current->next;
    }

    free(current->name);
    free(current);
}

// Function to check if a UE connection status is still valid based on its TTL value
int is_ue_status_valid(struct ConnectionStatus *connection, char *name) {
    // Find the UE connection status with the given name in the dynamic collection
    UEConnectionStatus *current = connection->ue_status;

    while (current != NULL && strcmp(current->name, name) != 0) current = current->next;

    if (current == NULL || current->ttl <= 0) return 0; // UE connection status is invalid

    // Update the TTL value of the UE connection status
    current->ttl--;

    return 1; // UE connection status is still valid
}

