function copyBytes(buffer, bytesToCopy) {
  const maxBytes = buffer.length;
  let copiedBytes;

  if (bytesToCopy > maxBytes) {
    copiedBytes = maxBytes;
  } else {
    copiedBytes = bytesToCopy;
  }

  const compressedBuffer = zlib.compress(buffer.slice(0, copiedBytes));
  const compressedData = new Uint8Array(compressedBuffer);

  return { buffer: buffer.subarray(copiedBytes), compressedData };
}

