#include <iostream>
#include <string>
#include <vector>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <semaphore>

class ResourceMonitor {
public:
    std::string name;
    bool monitoringEnabled;

    ResourceMonitor(const std::string& name) : name(name), monitoringEnabled(true) {}
};

class ResourceManager {
private:
    std::vector<ResourceMonitor*> monitors;
    std::mutex mutex;
    std::condition_variable conditionVariable;
    int availableSemaphoreValue = 0;

public:
    ResourceManager() {}

    void addMonitor(ResourceMonitor* monitor) {
        std::unique_lock<std::mutex> lock(mutex);
        monitors.push_back(monitor);
    }

    bool removeMonitor(const std::string& name) {
        std::unique_lock<std::mutex> lock(mutex);
        for (auto it = monitors.begin(); it != monitors.end(); ++it) {
            if ((*it)->name == name) {
                monitors.erase(it);
                return true;
            }
        }
        return false;
    }

    void updateMonitor(const std::string& name, bool enabled) {
        std::unique_lock<std::mutex> lock(mutex);
        for (auto it = monitors.begin(); it != monitors.end(); ++it) {
            if ((*it)->name == name) {
                (*it)->monitoringEnabled = enabled;
            }
        }
    }

    void monitorResources() {
        std::unique_lock<std::mutex> lock(mutex);

        // Check if there are any monitors
        if (monitors.empty()) {
            return;
        }

        // Acquire the semaphore
        int acquiredValue = acquireSemaphore();
        if (acquiredValue > 0) {
            try {
                // Start monitoring resources
                for (auto monitor : monitors) {
                    if (monitor->monitoringEnabled) {
                        std::cout << "Monitoring " << monitor->name << "...\n";
                    }
                }
            } catch (...) {
                // Handle any exceptions that occur during monitoring
            }

            // Release the semaphore
            releaseSemaphore(acquiredValue);
        }
    }

private:
    int acquireSemaphore() {
        std::unique_lock<std::mutex> lock(mutex);
        if (availableSemaphoreValue > 0) {
            --availableSemaphoreValue;
            return availableSemaphoreValue + 1;
        } else {
            conditionVariable.wait(lock);
            return acquireSemaphore();
        }
    }

    void releaseSemaphore(int value) {
        std::unique_lock<std::mutex> lock(mutex);
        if (value == 0) {
            // The semaphore is now available
            availableSemaphoreValue = monitors.size();
        } else {
            conditionVariable.notify_all();
        }
    }
};

int main() {
    ResourceManager manager;

    ResourceMonitor monitor1("Monitor 1");
    ResourceMonitor monitor2("Monitor 2");

    manager.addMonitor(&monitor1);
    manager.addMonitor(&monitor2);

    manager.updateMonitor("Monitor 1", false);

    std::thread thread([&manager]() {
        while (true) {
            manager.monitorResources();
            // Simulate some delay
            std::this_thread::sleep_for(std::chrono::seconds(5));
        }
    });

    thread.join();

    return 0;
}
```

This code provides a basic implementation of the `ResourceMonitor` and `ResourceManager` classes. The `ResourceMonitor` class represents a monitoring tool or service, and the `ResourceManager` class manages a collection of these monitors.

The `addMonitor` function adds a new monitor to the manager, while the `removeMonitor` function removes a monitor by its name. The `updateMonitor` function updates the enabled state of a specific monitor.

The `monitorResources` function is responsible for monitoring all available resources that are currently being monitored. It uses a semaphore to control access to shared monitoring metrics and to ensure thread-safe scheduling and execution.

In the main function, we create two `ResourceMonitor` objects and add them to the manager. We then update one of the monitors to be disabled. Finally, we start a separate thread that calls the `monitorResources` function repeatedly with a 5-second delay between each call.

This code provides a basic foundation for implementing a dynamic collection of `ResourceMonitor` objects, managing semaphore access, and ensuring thread-safe scheduling and execution.']

