#include <iostream>
#include <vector>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <semaphore.h>

class ResourceMonitor {
public:
    virtual void monitor() = 0;
};

class Semaphore {
private:
    sem_t sem;

public:
    Semaphore(int value) : sem(value) {}

    ~Semaphore() {
        sem_destroy(&sem);
    }

    int wait() {
        return sem_wait(&sem);
    }

    int post(int numPosts) {
        return sem_post(&sem, numPosts);
    }
};

class MonitorManager {
private:
    std::vector<ResourceMonitor*> monitors;
    Semaphore semaphore(1);

public:
    void addMonitor(ResourceMonitor* monitor) {
        monitors.push_back(monitor);
    }

    void startMonitoring() {
        std::thread threads[monitors.size()];
        for (int i = 0; i < monitors.size(); i++) {
            threads[i] = std::thread([this, i]() {
                sem_wait(&semaphore);
                try {
                    monitors[i]->monitor();
                } catch (...) {
                    // Handle exceptions
                }
                sem_post(1);
            });
        }
        for (int i = 0; i < monitors.size(); i++) {
            threads[i].join();
        }
    }

    void stopMonitoring() {
        // Stop and join all threads
    }
};

int main() {
    MonitorManager manager;
    ResourceMonitor* monitor1 = new ResourceMonitor();
    ResourceMonitor* monitor2 = new ResourceMonitor();
    manager.addMonitor(monitor1);
    manager.addMonitor(monitor2);
    manager.startMonitoring();
    return 0;
}
