// Function to initialize dynamic collection
void initDynamicCollection(DynamicCollection *collection, size_t initialCapacity) {
    collection->capacity = initialCapacity;
    collection->size = 0;
    collection->ueConnStats = (UEConnectionStatus **)malloc(collection->capacity * sizeof(UEConnectionStatus *));
    collection->crcIndications = (NFAPI_CRC_INDICATION_PDU_T **)malloc(collection->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T *));
    pthread_mutex_init(&collection->mutex, NULL);
}

// Function to add UE Connection Status to dynamic collection
void addUEConnStat(DynamicCollection *collection, UEConnectionStatus *ueConnStat) {
    pthread_mutex_lock(&collection->mutex);

    if (collection->size == collection->capacity) {
        // Resize the collection if necessary
        collection->capacity *= 2;
        collection->ueConnStats = (UEConnectionStatus **)realloc(collection->ueConnStats, collection->capacity * sizeof(UEConnectionStatus *));
        collection->crcIndications = (NFAPI_CRC_INDICATION_PDU_T **)realloc(collection->crcIndications, collection->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T *));
    }

    collection->ueConnStats[collection->size] = ueConnStat;
    collection->size++;
    pthread_mutex_unlock(&collection->mutex);
}

// Function to add NFAPI CRC INDICATION PDU T to dynamic collection
void addCRCIndication(DynamicCollection *collection, NFAPI_CRC_INDICATION_PDU_T *crcIndication) {
    pthread_mutex_lock(&collection->mutex);

    if (collection->size == collection->capacity) {
        // Resize the collection if necessary
        collection->capacity *= 2;
        collection->ueConnStats = (UEConnectionStatus **)realloc(collection->ueConnStats, collection->capacity * sizeof(UEConnectionStatus *));
        collection->crcIndications = (NFAPI_CRC_INDICATION_PDU_T **)realloc(collection->crcIndications, collection->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T *));
    }

    collection->crcIndications[collection->size] = crcIndication;
    collection->size++;
    pthread_mutex_unlock(&collection->mutex);
}

// Function to get UE Connection Status from dynamic collection
UEConnectionStatus *getUEConnStat(DynamicCollection *collection, size_t index) {
    pthread_mutex_lock(&collection->mutex);

    if (index >= collection->size) {
        // Handle out-of-range error
        pthread_mutex_unlock(&collection->mutex);
        return NULL;
    }

    UEConnectionStatus *ueConnStat = collection->ueConnStats[index];
    pthread_mutex_unlock(&collection->mutex);

    return ueConnStat;
}

// Function to get NFAPI CRC INDICATION PDU T from dynamic collection
NFAPI_CRC_INDICATION_PDU_T *getCRCIndication(DynamicCollection *collection, size_t index) {
    pthread_mutex_lock(&collection->mutex);

    if (index >= collection->size) {
        // Handle out-of-range error
        pthread_mutex_unlock(&collection->mutex);
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *crcIndication = collection->crcIndications[index];
    pthread_mutex_unlock(&collection->mutex);

    return crcIndication;
}

// Function to free dynamic collection
void freeDynamicCollection(DynamicCollection *collection) {
    for (size_t i = 0; i < collection->size; i++) {
