// Session data structure
struct Session {
    int userId;
    std::string productId;
    bool paymentStatus;
};

// Session manager class
class SessionManager {
public:
    SessionManager() : sessionCount(0), maxSessions(10000000) {}

    // Add a new session
    void addSession(const Session& session) {
        std::unique_lock<std::mutex> lock(sessionMutex);
        if (sessionCount >= maxSessions) {
            // Handle exceeded maximum sessions
            throw std::runtime_error("Maximum number of sessions reached");
        }
        sessionData[session.userId] = session;
        ++sessionCount;
    }

    // Remove a session
    void removeSession(int userId) {
        std::unique_lock<std::mutex> lock(sessionMutex);
        if (sessionData.find(userId) == sessionData.end()) {
            // Handle unknown user ID
            throw std::runtime_error("Unknown user ID");
        }
        sessionData.erase(userId);
        --sessionCount;
    }

    // Get a session by user ID
    Session getSession(int userId) {
        std::unique_lock<std::mutex> lock(sessionMutex);
        if (sessionData.find(userId) == sessionData.end()) {
            // Handle unknown user ID
            throw std::runtime_error("Unknown user ID");
        }
        return sessionData[userId];
    }

private:
    int sessionCount;
    const int maxSessions;
    std::unordered_map<int, Session> sessionData;
    std::mutex sessionMutex;

};

int main() {
    // Initialize the session manager
    SessionManager sessionMgr;

    // Simulate adding and removing sessions
    for (int i = 0; i < 10; ++i) {
        try {
            Session session{i, "Product " + std::to_string(i), false};
            sessionMgr.addSession(session);
            std::this_thread::sleep_for(std::chrono::seconds(1));
            sessionMgr.removeSession(i);
        } catch (const std::exception& e) {
            std::cerr << "Error: " << e.what() << std::endl;
        }
    }

    return 0;
}
