// Add event to dynamic list
void add_event(DynamicList *list, int type, time_t timestamp, const char* src_ip, const char* data) {
    if (list->length >= list->capacity) {
        // Increase capacity by doubling the current value
        size_t new_capacity = list->capacity * 2;
        Event *new_events = (Event*)realloc(list->events, new_capacity * sizeof(Event));
        if (!new_events) {
            printf("Error: Memory allocation failed.\n");
            return;
        }
        list->events = new_events;
        list->capacity = new_capacity;
    }

    Event event = {type, timestamp, src_ip, data};
    list->events[list->length++] = event;
}

// Remove events from dynamic list based on criteria
void remove_events(DynamicList *list, int type, time_t start_timestamp, time_t end_timestamp, const char* src_ip) {
    for (size_t i = 0; i < list->length; i++) {
        Event &event = list->events[i];
        if ((event.type != type || event.timestamp < start_timestamp || event.timestamp > end_timestamp) &&
            strcmp(event.src_ip, src_ip)) {
            // Shift remaining events to the left
            memmove(&list->events[i], &list->events[i+1], (list->length - i - 1) * sizeof(Event));
            list->length--;
            i--; // Decrement i to re-check the current index
        }
    }
}

// Retrieve events from dynamic list based on criteria
void retrieve_events(DynamicList *list, int type, time_t start_timestamp, time_t end_timestamp, const char* src_ip) {
    for (size_t i = 0; i < list->length; i++) {
        Event &event = list->events[i];
        if ((event.type == type && event.timestamp >= start_timestamp && event.timestamp <= end_timestamp) &&
            !strcmp(event.src_ip, src_ip)) {
            printf("Event type: %d, Timestamp: %lu, Source IP: %s, Data: %s\n",
                   event.type, (unsigned long)event.timestamp, event.src_ip, event.data);
        }
    }
}

int main() {
    // Initialize dynamic list with initial capacity of 10
    DynamicList *list = init_dynamic_list(10);

    // Add events to the list
    add_event(list, 1, time(NULL), "192.168.0.1", "Event data");
    add_event(list, 2, time(NULL) + 5, "192.168.0.2", "Another event");
    add_event(list, 1, time(NULL) + 10, "192.168.0.3", "Yet another");

    // Remove events based on criteria
    remove_events(list, 2, (time_t)time(NULL), (time_t)(time(NULL) + 10), "192.168.0.2");

    // Retrieve events based on criteria
    retrieve_events(list, 1, (time_t)time(NULL), (time_t)(time(NULL) + 15), "192.168.0.1");

    return 0;
}
