#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <pthread.h>

// Define a struct to hold semaphore data
typedef struct {
    int value;
    pthread_mutex_t mutex;
} semaphore_t;

// Function to create a new semaphore
semaphore_t* semaphore_create(int initial_value) {
    semaphore_t* sem = (semaphore_t*)malloc(sizeof(semaphore_t));
    sem->value = initial_value;
    pthread_mutex_init(&sem->mutex, NULL);
    return sem;
}

// Function to acquire the semaphore
int semaphore_acquire(semaphore_t* sem) {
    pthread_mutex_lock(&sem->mutex);
    while (sem->value <= 0) {
        // Check for signal and exit if true
        if (pthread_cond_signal(&sem) == 0) {
            break;
        }
    }
    sem->value--;
    pthread_mutex_unlock(&sem->mutex);
    return 1;
}

// Function to release the semaphore
void semaphore_release(semaphore_t* sem) {
    pthread_mutex_lock(&sem->mutex);
    sem->value++;
    pthread_mutex_unlock(&sem->mutex);
}

// Main function for semaphore operations
int main() {
    // Create a new semaphore with initial value 5
    semaphore_t* my_sem = semaphore_create(5);

    // Acquire the semaphore and wait
    int acquired = semaphore_acquire(my_sem);
    if (acquired) {
        printf("Semaphore acquired\n");
    } else {
        printf("Semaphore not acquired\n");
    }

    // Release the semaphore
    semaphore_release(my_sem);

    return 0;
}

