class SensorData {
public:
    std::string sensorId;
    std::string data;

    // Constructor
    SensorData(std::string id, std::string d) : sensorId(id), data(d) {}
};

class SensorDataManager {
private:
    std::vector<SensorData> sensorDataCollection;
    mutable std::mutex collectionMutex;
    mutable std::condition_variable collectionCondVar;
public:
    void addSensorData(SensorData& data) {
        {
            std::unique_lock<std::mutex> lock(collectionMutex);
            sensorDataCollection.push_back(data);
        }
        std::notify_one(collectionCondVar);
    }

    bool getSensorData(std::vector<SensorData>& retrievedData) {
        {
            std::unique_lock<std::mutex> lock(collectionMutex);
            if (sensorDataCollection.empty()) {
                return false;
            }
            retrievedData = sensorDataCollection;
            sensorDataCollection.clear();
        }
        return true;
    }

    void processSensorData() {
        std::vector<SensorData> processedData;
        while (true) {
            if (getSensorData(processedData)) {
                // Process the data here
                for (const auto& data : processedData) {
                    std::cout << "Processing sensor data: " << data.sensorId << std::endl;
                }
                std::this_thread::sleep_for(std::chrono::milliseconds(1000));
            } else {
                std::cout << "No more data available." << std::endl;
                break;
            }
        }
    }
};

int main() {
    SensorDataManager sensorDataMgr;

    // Simulate adding sensor data
    for (int i = 1; i <= 10; ++i) {
        SensorData sensorData("Sensor" + std::to_string(i), "Some data");
        sensorDataMgr.addSensorData(sensorData);
    }

    // Start processing the sensor data in a separate thread
    std::thread processThread([&sensorDataMgr]() {
        sensorDataMgr.processSensorData();
    });
    processThread.join();

    return 0;
}
