// Define a struct to manage dynamic collections of UEConnectionStatuses
typedef struct {
    UEConnectionStatus* connections;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
    pthread_cond_t cond;
} ConnectionManager;

// Function to initialize the ConnectionManager
void connection_manager_init(ConnectionManager* cm, size_t initial_capacity) {
    cm->connections = (UEConnectionStatus*)calloc(initial_capacity, sizeof(UEConnectionStatus));
    cm->capacity = initial_capacity;
    cm->size = 0;
    pthread_mutex_init(&cm->lock, NULL);
    pthread_cond_init(&cm->cond, NULL);
}

// Function to add a UEConnectionStatus to the ConnectionManager
void connection_manager_insert(ConnectionManager* cm, UEConnectionStatus* status) {
    pthread_mutex_lock(&cm->lock);

    // Check if the current capacity is exceeded and resize if necessary
    if (cm->size == cm->capacity) {
        size_t new_capacity = cm->capacity * 2;
        UEConnectionStatus* new_connections = (UEConnectionStatus*)calloc(new_capacity, sizeof(UEConnectionStatus));
        memcpy(new_connections, cm->connections, cm->capacity * sizeof(UEConnectionStatus));
        free(cm->connections);
        cm->connections = new_connections;
        cm->capacity = new_capacity;
    }

    // Add the status to the connection manager
    cm->connections[cm->size] = *status;
    cm->size++;

    pthread_mutex_unlock(&cm->lock);
}

// Function to remove a UEConnectionStatus from the ConnectionManager
void connection_manager_remove(ConnectionManager* cm, uint32_t connection_id) {
    pthread_mutex_lock(&cm->lock);

    // Find and remove the status with the given connection id
    for (size_t i = 0; i < cm->size; i++) {
        if (cm->connections[i].connection_id == connection_id) {
            memmove(&cm->connections[i], &cm->connections[i + 1], (cm->size - i - 1) * sizeof(UEConnectionStatus));
