#include <iostream>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <functional>
#include <queue>
#include <map>
#include <string>

class ThreadPool {
public:
    ThreadPool(size_t numThreads) : stop(false) {
        for (size_t i = 0; i < numThreads; ++i)
            threads.emplace_back([this] {
                while (true) {
                    std::function<void()> task;
                    {
                        std::unique_lock<std::mutex> lock(queue_mutex);
                        // Wait until a task is available
                        queue.wait(lock, [this]{ return stop || !tasks.empty(); });
                        if (stop && tasks.empty())
                            return; // Exit the thread
                        task = std::move(tasks.front());
                        tasks.pop();
                    }
                    // Execute the task
                    task();
                }
            });
    }

    ~ThreadPool() {
        {
            std::unique_lock<std::mutex> lock(queue_mutex);
            stop = true;
        }
        queue.notify_all();
        for (std::thread & th : threads)
            th.join();
    }

    template<typename FunctionType>
    void enqueue(FunctionType f) {
        {
            std::unique_lock<std::mutex> lock(queue_mutex);
            tasks.emplace([f] { return f(); });
        }
        queue.notify_one();
    }

private:
    std::vector<std::thread> threads;
    std::queue<std::function<void()> > tasks;
    mutable std::mutex queue_mutex;
    std::condition_variable queue;

    bool stop;
};

class DataProcessor {
public:
    void processFiles(const std::vector<std::string>& files) {
        ThreadPool pool(4); // Create a thread pool with 4 threads

        for (const auto& file : files) {
            pool.enqueue([file] {
                // Simulate processing time
                std::this_thread::sleep_for(std::chrono::seconds(2));
                std::cout << "Processed file: " << file << std::endl;
            });
        }
    }
};

int main() {
    DataProcessor processor;
    const std::vector<std::string> files = {"file1.txt", "file2.txt", "file3.txt"};
    processor.processFiles(files);
    return 0;
}
