public class MarketDataAggregator {
    public static void fetchMarketData(String provider, String symbol) throws InterruptedException, ExecutionException {
        List<Future<String>> futures = new ArrayList<>();

        for (int i = 0; i < 3; i++) { // Try multiple providers
            int attempts = 0;
            while (attempts < 5) { // Retry up to 5 times in case of errors
                try {
                    Future<String> future = Executors.newSingleThreadExecutor().submit(() -> {
                        // Simulate data fetching from the provider
                        Thread.sleep(1000); // Simulate latency
                        return "Data fetched successfully from " + provider + " for symbol " + symbol;
                    });
                    futures.add(future);
                    break; // Successful attempt, stop trying other providers
                } catch (Exception e) {
                    attempts++; // Error occurred, try another provider
                }
            }
        }

        // Process the results of the data fetching
        List<String> results = new ArrayList<>();
        for (Future<String> future : futures) {
            try {
                results.add(future.get()); // Get the result and add it to the list
            } catch (Exception e) {
                System.out.println("Error occurred while processing data from " + provider);
            }
        }

        // Print the results
        for (String result : results) {
            System.out.println(result);
        }
    }
}
