        [HttpPost]
        public async Task<IActionResult> UpdateDocument([FromUri]int documentId, [FromUri]int sectionId, string updatedContent)
        {
            // Optimistic locking and conflict resolution
            var version = await _documentRepository.GetVersion(documentId, sectionId);
            if (version != 0 && version != await _documentRepository.GetLatestVersion())
            {
                return Conflict("Document has been modified by another user");
            }

            // Validate updated content
            if (!await ValidateContent(updatedContent))
            {
                return BadRequest("Invalid content format");
            }

            // Update document section
            await _documentRepository.UpdateSection(documentId, sectionId, updatedContent);

            // Trigger analytics and caching updates
            await _analyticsService.TrackUpdate();
            await _cacheService.InvalidateDocumentCache();

            return Ok();
        }

        [HttpGet]
        public async Task<IActionResult> GetDocument([FromUri]int documentId)
        {
            // Load document from cache or database
            var document = await _cacheService.GetCachedDocument(documentId);

            if (document == null)
            {
                document = await _documentRepository.GetDocument(documentId);
                await _cacheService.CacheDocument(documentId, document);
            }

            return Ok(document);
        }

