#define MAX_INTEGERS 1000
#define LOG_SERVICE_PORT 8080

int validate_integer(int integer) {
    return (integer >= -1000 && integer <= 1000);
}

void *malloc_or_die(size_t size) {
    void *ptr = malloc(size);
    if (!ptr) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void free_and_null(void **ptr) {
    free(*ptr);
    *ptr = NULL;
}

int main() {
    int server_fd, new_socket;
    struct sockaddr_in address;
    int addrlen = sizeof(address);
    char buffer[1024] = {0};
    int valread;
    int *valid_integers = malloc_or_die(MAX_INTEGERS * sizeof(int));
    int valid_integer_count = 0;

    // Establish socket connection
    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        perror("socket");
        exit(EXIT_FAILURE);
    }

    address.sin_family = AF_INET;
    address.sin_port = htons(LOG_SERVICE_PORT);
    inet_pton(AF_INET, "127.0.0.1", &address.sin_addr);

    bind(server_fd, (struct sockaddr *)&address, sizeof(address));
    listen(server_fd, 3);

    while (1) {
        new_socket = accept(server_fd, NULL, NULL);
        if (new_socket < 0) {
            perror("accept");
            exit(EXIT_FAILURE);
        }

        valread = read(new_socket, buffer, 1024);
        int integer;
        char *token = strtok(buffer, " ");
        while (token && strcmp(token, "") != 0) {
            integer = atoi(token);
            if (validate_integer(integer)) {
                valid_integers[valid_integer_count++] = integer;
            }
            token = strtok(NULL, " ");
        }

        // Log the number of valid integers
        send(new_socket, &valid_integer_count, sizeof(int), 0);

        close(new_socket);

        free_and_null(&valid_integers);
    }

    return 0;
}
