```cpp
#include <iostream>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <map>

// Forward declarations
class DataProcessor;
class ExternalSink;

class DataPipeline {
public:
    DataPipeline(size_t numProcessors, size_t maxQueueSize);

    void submit(const std::string& data);
    bool process();
    void shutdown();

private:
    std::mutex mtx_;
    std::condition_variable cv_;
    std::queue<std::pair<DataProcessor*, std::string>> queue_;
    std::map<DataProcessor*, ExternalSink*> sinks_;
};

class DataProcessor {
public:
    virtual ~DataProcessor() {}

    virtual bool process(const std::string& data) = 0;
};

class ExternalSink {
public:
    virtual ~ExternalSink() {}

    virtual void deliver(const std::string& data) = 0;
};

// Implementation
#include <iostream>
#include <queue>
#include <mutex>

DataPipeline::DataPipeline(size_t numProcessors, size_t maxQueueSize)
: queue_(maxQueueSize), sinks_() {
    for (size_t i = 0; i < numProcessors; ++i) {
        DataProcessor* processor = new DataProcessor(); // create a new DataProcessor
        ExternalSink* sink = new ExternalSink(); // create a new ExternalSink

        // associate the processor with the sink
        sinks_.insert(std::make_pair(processor, sink));

        std::thread t([processor]() {
            while (true) {
                // acquire lock and process data
                std::unique_lock<std::mutex> lock(mtx_);
                cv_.wait(lock, [this] { return !queue_.empty(); });
                std::string data = queue_.front().second;
                queue_.pop();

                if (!processor->process(data)) {
                    // processor failed to process the data
                    delete processor; // clean up
                    processor = nullptr;
                    break;
                }

                lock.unlock();
            }
        });
        t.detach();
    }
}

void DataPipeline::submit(const std::string& data) {
    {
        std::unique_lock<std::mutex> lock(mtx_);
        queue_.push(std::make_pair(nullptr, data));
    }
    cv_.notify_one();
}

bool DataPipeline::process() {
    // check if there are any processors available
    if (sinks_.empty()) return false;

    // select a processor at random and deliver the data to it
    auto it = sinks_.begin();
    ExternalSink* sink = it->second;
    std::string data = queue_.front().second;
    queue_.pop();

    // acquire lock on the sink's mutex
    std::unique_lock<std::mutex> lock(sink->mtx_);
    cv_.wait(lock, [this] { return !queue_.empty(); });
    sink->deliver(data);

    return true;
}

void DataPipeline::shutdown() {
    for (auto& processorSink : sinks_) {
        delete processorSink.first; // clean up processors
        delete processorSink.second; // clean up sinks
    }
    sinks_.clear();
}
```"]

