// Function to create a new UE connection status collection with initial capacity
UEConnectionStatusCollection* ue_connection_status_collection_create(size_t initial_capacity) {
    UEConnectionStatusCollection* collection = (UEConnectionStatusCollection*)malloc(sizeof(UEConnectionStatusCollection));
    collection->capacity = initial_capacity;
    collection->size = 0;
    collection->statuses = (UEConnectionStatus**)malloc(collection->capacity * sizeof(UEConnectionStatus*));
    return collection;
