// Function to add a new UE connection status to the collection
void ue_connection_status_collection_add(UEConnectionStatusCollection* collection, UEConnectionStatus* status) {
    pthread_mutex_lock(&collection->mutex);
    if (collection->size == collection->capacity) {
        // Reallocate memory with doubled capacity
        size_t new_capacity = collection->capacity * 2;
        UEConnectionStatus** new_statuses = (UEConnectionStatus**)malloc(new_capacity * sizeof(UEConnectionStatus*));
        memcpy(new_statuses, collection->statuses, collection->capacity * sizeof(UEConnectionStatus*));
        free(collection->statuses);
        collection->statuses = new_statuses;
        collection->capacity = new_capacity;
