    UEConnectionStatus* data;
    size_t capacity, size;
    pthread_mutex_t lock;
} ConnectionStatusArray;

// Create a new connection status array with initial capacity
ConnectionStatusArray* create_array(size_t initial_capacity) {
    ConnectionStatusArray* arr = (ConnectionStatusArray*)malloc(sizeof(ConnectionStatusArray));
    arr->data = (UEConnectionStatus*)calloc(initial_capacity, sizeof(UEConnectionStatus));
    arr->capacity = initial_capacity;
    arr->size = 0;
    pthread_mutex_init(&arr->lock, NULL);
    return arr;
}

// Add a new connection status to the array
void add_status(ConnectionStatusArray* arr, UEConnectionStatus* status) {
    if (arr->size >= arr->capacity * 3/4) { // resize when 75% full
        size_t new_capacity = arr->capacity * 2;
        UEConnectionStatus* new_data = (UEConnectionStatus*)realloc(arr->data, new_capacity * sizeof(UEConnectionStatus));
        arr->data = new_data;
        arr->capacity = new_capacity;
    }
    status->timestamp = time(NULL);
    arr->data[arr->size++] = *status;
}

// Eviction policy based on configurable TTL values
void evict_old(ConnectionStatusArray* arr, time_t current_time) {
    size_t i;
    for (i = 0; i < arr->size; ++i) {
        if ((arr->data[i].timestamp + 60 * 30) <= current_time) { // 30 minutes TTL
            memmove(&arr->data[i], &arr->data[i+1], sizeof(UEConnectionStatus) * (arr->size - i - 1));
            arr->size--;
        }
    }
}

// Concurrent access handling with adaptive locking mechanism
void* thread_func(void* arg) {
    ConnectionStatusArray* arr = (ConnectionStatusArray*)arg;
    while (1) {
        // acquire lock
        pthread_mutex_lock(&arr->lock);

        // add new status, evict old ones, and release lock
        UEConnectionStatus* new_status = (UEConnectionStatus*)malloc(sizeof(UEConnectionStatus));
        add_status(arr, new_status);
        evict_old(arr, time(NULL));
        free(new_status);
        pthread_mutex_unlock(&arr->lock);

        // sleep for a random amount of time to avoid contention
        usleep(rand() % 1000000);
    }
}

int main() {
    ConnectionStatusArray* arr = create_array(16); // initial capacity of 16

    pthread_t threads[4];
    int i;
    for (i = 0; i < 4; ++i) {
        pthread_create(&threads[i], NULL, thread_func, arr);
    }

