        // periodically update connection statuses
        UEConnectionStatus* status = (UEConnectionStatus*)malloc(sizeof(UEConnectionStatus));
        add_status(arr, status); // update and evict old ones
        free(status);

        // sleep for a short period to allow other threads to run
        usleep(10000);
    }

    return 0;
}
