    int priorityLevel;
    int estimatedExecutionTime;
    int resultVersion;

    JobMetadata(int id, time_t timestamp, std::string status, int priority, int time, int version)
        : jobId(id), submissionTimestamp(timestamp), status(status), priorityLevel(priority),
          estimatedExecutionTime(time), resultVersion(version) {}
};

class JobManager {
public:
    static const int THIRTY_MINUTES = 30 * 60; // in seconds
    static const int MIN_ESTIMATED_EXECUTION_TIME = 300; // in seconds

    void processJobs() {
        std::vector<JobMetadata> jobQueue;
        bool isOnline;

        // Load initial configuration and connect to the API
        // ...

        std::cout << "Enter a list of job IDs (or 'q' to quit):" << std::endl;
        std::string jobIdStr;
        while (true) {
            std::cin >> jobIdStr;
            if (jobIdStr == "q") break;

            int jobId = stoi(jobIdStr);
            // Add job ID to the job queue
            jobQueue.push_back(JobMetadata(jobId, time(NULL), "PENDING", 0, 0, 0));
        }

        while (!jobQueue.empty()) {
            JobMetadata& currentJob = jobQueue.front();
            jobQueue.pop_front();

            if (isJobPending(currentJob) && isEstimatedExecutionTimeExceeded(currentJob)) {
                std::cout << "Found a pending job with high estimated execution time: " << currentJob.status << std::endl;
                break; // exit loop
            }
        }

        // Release any held locks and clean up resources
        // ...
    }

private:
    bool isJobPending(const JobMetadata& job) {
        return job.status == "PENDING" && (time(NULL) - job.submissionTimestamp > THIRTY_MINUTES);
    }

    bool isEstimatedExecutionTimeExceeded(const JobMetadata& job) {
        return job.estimatedExecutionTime > MIN_ESTIMATED_EXECUTION_TIME;
    }
};

int main() {
    JobManager().processJobs();
    return 0;
}
