    pthread_mutex_lock(&connection_status_lock);
    // Allocate space for the new status and copy it
    UEConnectionStatus** new_array = (UEConnectionStatus**)realloc(ue_connections, sizeof(UEConnectionStatus*) * ++num_ue_connections);
    new_array[num_ue_connections - 1] = new_status;
    ue_connections = new_array;
    pthread_mutex_unlock(&connection_status_lock);
}

// Function to update a UE connection status
void update_ue_connection(int id, char* new_status) {
    pthread_mutex_lock(&connection_status_lock);
    // Find the index of the UE connection with matching ID
    for (int i = 0; i < num_ue_connections; i++) {
        if (ue_connections[i]->id == id) {
            strcpy(ue_connections[i]->status, new_status);
            break;
        }
    }
    pthread_mutex_unlock(&connection_status_lock);
}

// Function to retrieve a UE connection status
UEConnectionStatus* get_ue_connection(int id) {
    pthread_mutex_lock(&connection_status_lock);
    // Find the index of the UE connection with matching ID
    for (int i = 0; i < num_ue_connections; i++) {
        if (ue_connections[i]->id == id) {
            UEConnectionStatus* status = ue_connections[i];
            pthread_mutex_unlock(&connection_status_lock);
            return status;
        }
    }
    pthread_mutex_unlock(&connection_status_lock);
    // If not found, return NULL
    return NULL;
}

