package com.financial.dataanalyzer;

import java.util.concurrent.*;
import java.time.*;

public class DataAnalyzerManager {
    private final ExecutorService executor;
    private final Semaphore semaphore;
    private final Map<String, DataAnalyzer> analyzers;
    private final ConcurrentHashMap<String, CompletableFuture<Void>> futures;

    public DataAnalyzerManager(int numThreads) {
        this.executor = Executors.newFixedThreadPool(numThreads);
        this.semaphore = new Semaphore(numThreads);
        this.analyzers = new HashMap<>();
        this.futures = new ConcurrentHashMap<>();
    }

    public void submitAnalysis(String providerId, AnalysisConfiguration config) {
        if (!semaphore.tryAcquire()) {
            throw new RuntimeException("No available threads for analysis");
        }

        try {
            CompletableFuture<Void> future = new CompletableFuture<>();
            analyzers.computeIfAbsent(providerId, k -> new DataAnalyzer(k)).analyze(config).whenComplete((r, e) -> {
                if (e != null) {
                    System.out.println("Error analyzing data for " + providerId);
                } else {
                    System.out.println("Analysis completed for " + providerId);
