typedef struct {
    UEConnectionStatus **entries;
    size_t capacity;
    size_t used;
    pthread_mutex_t lock;
    pthread_cond_t cond;
} UEConnectionCache;

// Function to initialize the cache
UEConnectionCache *ue_connection_cache_init(size_t initial_capacity) {
    UEConnectionCache *cache = (UEConnectionCache *)malloc(sizeof(UEConnectionCache));
    cache->entries = (UEConnectionStatus **)calloc(initial_capacity, sizeof(UEConnectionStatus *));
    cache->capacity = initial_capacity;
    cache->used = 0;
    pthread_mutex_init(&cache->lock, NULL);
    pthread_cond_init(&cache->cond, NULL);
    return cache;
}

// Function to add a new UE connection to the cache
void ue_connection_cache_add(UEConnectionCache *cache, UEConnectionStatus *status) {
    pthread_mutex_lock(&cache->lock);
    if (cache->used >= cache->capacity) {
        // Rebalance the cache when full
        size_t new_capacity = cache->capacity * 2;
        UEConnectionStatus **new_entries = (UEConnectionStatus **)realloc(cache->entries, new_capacity * sizeof(UEConnectionStatus *));
        for (size_t i = 0; i < cache->used; i++) {
            new_entries[i] = cache->entries[i];
        }
        free(cache->entries);
        cache->entries = new_entries;
        cache->capacity = new_capacity;
    }
    // Add the new entry
    cache->entries[cache->used++] = status;
    pthread_mutex_unlock(&cache->lock);
}

// Function to remove an outdated UE connection from the cache
void ue_connection_cache_evict(UEConnectionCache *cache, int ttl) {
    pthread_mutex_lock(&cache->lock);
    for (size_t i = 0; i < cache->used; i++) {
        if (time(NULL) - status->timestamp > ttl) {
            // Evict the outdated entry
            free(status);
            memmove(cache->entries + i, cache->entries + i + 1, (cache->used - i - 1) * sizeof(UEConnectionStatus *));
            cache->used--;
        }
    }
    pthread_mutex_unlock(&cache->lock);
}

