// Initialize the dynamic array with initial capacity and allocate memory
DynamicArray* dynamic_array_init(size_t initial_capacity) {
    DynamicArray* da = (DynamicArray*)malloc(sizeof(DynamicArray));
    da->capacity = initial_capacity;
    da->size = 0;
    da->data = (UEConnectionStatus**)calloc(initial_capacity, sizeof(UEConnectionStatus*));
    return da;
}

// Resize the dynamic array if necessary and allocate memory
void dynamic_array_resize(DynamicArray* da, size_t new_size) {
    if (new_size > da->capacity) {
        size_t new_capacity = da->capacity * 2;
        DynamicArray* temp_da = dynamic_array_init(new_capacity);
        for (size_t i = 0; i < da->size; i++) {
            temp_da->data[i] = da->data[i];
        }
        free(da);
        da = temp_da;
    }
}

// Append an element to the dynamic array and resize if necessary
void dynamic_array_append(DynamicArray* da, UEConnectionStatus* elem) {
    if (da->size >= da->capacity) {
        dynamic_array_resize(da, da->size * 2 + 1);
    }
    da->data[da->size++] = elem;
}

// Read integers from standard input and store them in a thread-safe dynamic array
void read_integers() {
    DynamicArray* da = dynamic_array_init(10);
    while (1) {
        int num;
        scanf("%d", &num);
        UEConnectionStatus* elem = (UEConnectionStatus*)malloc(sizeof(UEConnectionStatus));
        elem->status = num;
        elem->message = NULL;
        dynamic_array_append(da, elem);
    }
}

// Identify the largest integer in a thread-safe, dynamically expanding array
int find_largest_int(DynamicArray* da) {
    int max = da->data[0]->status;
    for (size_t i = 1; i < da->size; i++) {
        if (da->data[i]->status > max) {
            max = da->data[i]->status;
        }
    }
    return max;
}

int main() {
