# Define the SHA-256 hashing function with retry mechanism
def hash_file(file_path: str, max_retries: int) -> str:
    def inner():
        while True:
            try:
                with open(file_path, 'rb') as f:
                    file_hash = hashlib.sha256(f.read()).hexdigest()
                    return file_hash
            except (IOError, OSError) as e:
                if max_retries > 0 and isinstance(e, IOError):
                    logger.error(f"Error hashing file {file_path}: {e}")
                    time.sleep(1)  # retry after 1 second
                    max_retries -= 1
                else:
                    raise

    return inner()

# Define the concurrent file processing function with lock-free design
def process_file_list(file_paths: List[str], num_workers: int, max_retries: int) -> Dict[str, str]:
    def worker(file_path):
        logger.info(f"Processing file {file_path}...")
        try:
            file_hash = hash_file(file_path, max_retries)
            return {file_path: file_hash}
        except Exception as e:
            logger.error(f"Error processing file {file_path}: {e}")
            return {}

    with ThreadPoolExecutor(max_workers=num_workers) as executor:
        results = list(executor.map(worker, file_paths))
    combined_results = {}
    for result in results:
