// Define the structure to hold measurement result
typedef struct {
    int64_t timestamp;
    char measurement_type[16];
    double value;
} LTEPHYMeasurementResult;

// Define a node in the linked list for measurements
typedef struct Node {
    LTEPHYMeasurementResult measurement;
    struct Node* next;
} Node;

// Create and return a new measurement result structure
LTEPHYMeasurementResult* create_measurement_result(int64_t timestamp, const char* measurement_type, double value) {
    LTEPHYMeasurementResult* result = (LTEPHYMeasurementResult*)malloc(sizeof(LTEPHYMeasurementResult));
    strcpy(result->measurement_type, measurement_type);
    result->timestamp = timestamp;
    result->value = value;
    return result;
}

// Create a new node in the linked list and add it to the head
void add_measurement_result(Node** head_ref, LTEPHYMeasurementResult* measurement) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    new_node->measurement = *measurement;
    new_node->next = *head_ref;
    *head_ref = &new_node;
}

// Update existing measurements by type
void update_measurement_type(Node** head_ref, const char* measurement_type, double value) {
    Node* current = *head_ref;
    while (current != NULL) {
        if (strcmp(current->measurement.measurement_type, measurement_type) == 0) {
            current->measurement.value = value;
        }
        current = current->next;
    }
}

// Retrieve all measurements older than a specified timestamp
void get_measurements_older_than(Node* head, int64_t timestamp, LTEPHYMeasurementResult** result_array, int* array_size) {
    *array_size = 0;
    Node* current = head;
    while (current != NULL) {
        if (current->measurement.timestamp < timestamp) {
            (*result_array)++;
            memcpy(*result_array, &current->measurement, sizeof(LTEPHYMeasurementResult));
            (*array_size)++;
        }
        current = current->next;
    }
}

// Clear the entire measurement collection
void clear_measurement_collection(Node** head_ref) {
    Node* current = *head_ref;
    while (current != NULL) {
        free(current);
        current = current->next;
    }
    *head_ref = NULL;
}
