// Add a new measurement result to the collection (efficient insertion)
void measurement_collection_add(MeasurementCollection* collection, LTEPHYMeasurementResult* measurement) {
    // Check if there is space in the existing array
    if (collection->capacity == collection->count) {
        // If not, double the capacity and reallocate the memory
        collection->measurements = realloc(collection->measurements, (collection->capacity * 2 + 1) * sizeof(LTEPHYMeasurementResult));
        collection->capacity *= 2;
    }
    collection->measurements[collection->count++] = *measurement;
}

// Update all measurements of a specific type in the collection
void measurement_collection_update_by_type(MeasurementCollection* collection, enum { SNR, SINR, RSRP } measurement_type, double new_value) {
    for (size_t i = 0; i < collection->count; ++i) {
        if (collection->measurements[i].measurement_type == measurement_type) {
            collection->measurements[i].value = new_value;
        }
    }
}

// Retrieve all measurements older than a specified time
