    LTEPHYMeasurementResult* result = malloc(sizeof(LTEPHYMeasurementResult) * (collection->count - 1));
    size_t j = 0;
    for (size_t i = 0; i < collection->count; ++i) {
        if (collection->measurements[i].timestamp < cutoff_time) {
            result[j++] = collection->measurements[i];
        }
    }
    return result;
}

// Clear the entire measurement collection
