    time_t timestamp;
    int type; // SNR, SINR, RSRP
    float value;
} LTEPHYMeasurementResult;

// Define the collection of LTE PHY measurement results
typedef struct {
    LTEPHYMeasurementResult* measurements;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} LTEPHYMeasurementCollection;

// Initialize an empty measurement collection
LTEPHYMeasurementCollection* ltephy_measurement_collection_init(size_t capacity) {
    LTEPHYMeasurementCollection* collection = (LTEPHYMeasurementCollection*)malloc(sizeof(LTEPHYMeasurementCollection));
    collection->measurements = (LTEPHYMeasurementResult*)calloc(capacity, sizeof(LTEPHYMeasurementResult));
    collection->capacity = capacity;
    collection->size = 0;
    pthread_mutex_init(&collection->lock, NULL);
    return collection;
}

// Add a new measurement result to the collection
void ltephy_measurement_collection_add(LTEPHYMeasurementCollection* collection, LTEPHYMeasurementResult* measurement) {
    pthread_mutex_lock(&collection->lock);
    if (collection->size >= collection->capacity) {
        // Reallocate memory for more measurements
        size_t new_capacity = collection->capacity * 2;
        LTEPHYMeasurementResult* new_measurements = (LTEPHYMeasurementResult*)realloc(collection->measurements, new_capacity * sizeof(LTEPHYMeasurementResult));
        collection->measurements = new_measurements;
        collection->capacity = new_capacity;
    }
    memcpy(&collection->measurements[collection->size], measurement, sizeof(LTEPHYMeasurementResult));
    collection->size++;
    pthread_mutex_unlock(&collection->lock);
}

// Retrieve a measurement result from the collection
LTEPHYMeasurementResult* ltephy_measurement_collection_get(LTEPHYMeasurementCollection* collection, size_t index) {
    pthread_mutex_lock(&collection->lock);
    if (index >= collection->size) {
        // Return NULL for out-of-bounds requests
        return NULL;
    }
    LTEPHYMeasurementResult* measurement = &collection->measurements[index];
    pthread_mutex_unlock(&collection->lock);
    return measurement;
}

// Free a measurement collection
void ltephy_measurement_collection_free(LTEPHYMeasurementCollection* collection) {
    free(collection->measurements);
    pthread_mutex_destroy(&collection->lock);
    free(collection);
}
