class DynamicThreadPool {
public:
    // Create a new thread pool with 10 threads
    DynamicThreadPool(int numThreads) : stopped(false), queue(), condition_var() {
        for (int i = 0; i < numThreads; ++i) {
            threads.emplace_back([this] {
                while (!stopped) {
                    std::function<void()> task;
                    {
                        std::unique_lock<std::mutex> lock(this->mutex);
                        this->condition_var.wait(lock, [this] { return !queue.empty() || stopped; });
                        if (stopped || queue.empty()) {
                            return;
                        }
                        task = std::move(queue.front());
                        queue.pop();
                    }
                    task();
                }
            });
        }
    }

    // Add a new task to the thread pool
    void enqueue(std::function<void()> task) {
        {
            std::unique_lock<std::mutex> lock(mutex);
            while (queue.size() >= threads.size()) {
                condition_var.wait(lock, [this] { return queue.size() < threads.size(); });
            }
            queue.push(std::move(task));
        }
        condition_var.notify_one();
    }

    // Stop the thread pool
    void stop() {
        stopped = true;
        condition_var.notify_all();
    }

private:
    bool stopped;
    std::queue<std::function<void()>> queue;
    std::vector<std::thread> threads;
    std::mutex mutex;
    std::condition_variable condition_var;
};

class CachingMechanism {
public:
    // Add a new key-value pair to the cache
    void add(const std::string& key, const std::string& value) {
        if (evictionPolicy == "LRU") {
            cache[key] = value;
        } else if (evictionPolicy == "FIFO") {
            cache.insert({key, value});
        }
    }

    // Get the cached value for a given key
    std::string get(const std::string& key) {
        if (evictionPolicy == "LRU") {
            return cache.find(key)->second;
        } else if (evictionPolicy == "FIFO") {
            return cache[key];
        }
    }

private:
    std::map<std::string, std::string> cache;
    std::string evictionPolicy;
};

class ForwardListManipulator {
public:
    // Modify the forward list by inserting a specified string after the first occurrence of another string
    void insertAfter(const std::forward_list<std::string>& original, const std::string& target, const std::string& newString) {
        auto it = original.begin();
        while (it != original.end()) {
            if (*it == target) {
                original.insert_after(it, newString);
                return;
            }
            ++it;
        }
        original.append(newString);
    }
};
