    if (manager->used >= manager->capacity) {
        // resize the array
        size_t new_capacity = manager->capacity * 2;
        UEConnectionStatus** new_connections = realloc(manager->connections, sizeof(UEConnectionStatus*) * new_capacity);
        manager->connections = new_connections;
        manager->capacity = new_capacity;
    }
    manager->connections[manager->used] = connection;
    manager->used++;
    pthread_mutex_unlock(&manager->mutex);
    return 0;
}

