#include <openssl/evp.h>
size_t md5_hash(const char* input, size_t length, unsigned char* output) {
    EVP_MD_CTX ctx;
    const EVP_MD* md = EVP_md_md5();
    if (!EVP_MD_CTX_init(&ctx)) return 0;
    if (!EVP_DigestInit_ex(&ctx, md, NULL)) return 0;
    if (!EVP_DigestUpdate(&ctx, input, length)) return 0;
    size_t out_len = EVP_MAX_DIGEST_SIZE;
    unsigned char* out = output;
    if (!EVP_DigestFinal_ex(&ctx, out, &out_len)) return 0;
    EVP_MD_CTX_cleanup(&ctx);
    return out_len;
}

