import java.util.ArrayList;
import java.util.List;

public class InventoryManagementSystem {

    private List<Product> products = new ArrayList<>();
    private List<Store> stores = new ArrayList<>();

    public void addProduct(Product product) {
        products.add(product);
    }

    public void addStore(Store store) {
        stores.add(store);
    }

    public void processInventory() {
        for (Product product : products) {
            for (Store store : stores) {
                if (store.hasProductInStock(product)) {
                    System.out.println("Product " + product.getName() + " is in stock at " + store.getName());
                } else {
                    System.out.println("Product " + product.getName() + " is out of stock at " + store.getName());
                }
            }
        }
    }

    public class Product {
        private String name;
        private int quantity;

        public Product(String name, int quantity) {
            this.name = name;
            this.quantity = quantity;
        }

        public String getName() {
            return name;
        }

        public int getQuantity() {
            return quantity;
        }
    }

    public class Store {
        private String name;
        private List<Product> productsInStock = new ArrayList<>();

        public Store(String name) {
            this.name = name;
        }

        public boolean hasProductInStock(Product product) {
            for (Product p : productsInStock) {
                if (p.getName().equals(product.getName())) {
                    return true;
                }
            }
            return false;
        }

        public void addProductToInventory(Product product, int quantity) {
            productsInStock.add(new Product(product.getName(), quantity));
        }
    }
}
