#include <iostream>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <shared_mutex>
#include <semaphore>

class DynamicResourceManager {
public:
    DynamicResourceManager(size_t numThreads) : _numThreads(numThreads), _resourceMonitors() {}

    void addResourceMonitor(const ResourceMonitor& monitor) {
        std::unique_lock<std::mutex> lock(_mutex);
        _resourceMonitors.push_back(monitor);
    }

    void startMonitoring() {
        for (size_t i = 0; i < _numThreads; ++i) {
            auto threadFunc = [this, i]() {
                while (true) {
                    std::unique_lock<std::mutex> lock(_mutex);
                    if (_resourceMonitors.empty()) break;
                    ResourceMonitor monitor = _resourceMonitors.front();
                    _resourceMonitors.pop_front();
                    monitor.startMonitoring();
                }
            };
            std::thread thread(threadFunc);
            threads.push_back(std::move(thread));
        }
    }

    void stopMonitoring() {
        for (auto& thread : threads) {
            thread.join();
        }
    }

private:
    size_t _numThreads;
    std::vector<ResourceMonitor> _resourceMonitors;
    std::mutex _mutex;
    std::condition_variable _condVar;
    std::vector<std::thread> threads;
};

class ResourceMonitor {
public:
    virtual void startMonitoring() = 0;
};

semaphore_t semaphore;

int executeCommand(char* cmd) {
    pid_t pid = fork();
    if (pid == -1) return 0; // fork failed
    if (pid == 0) { // child process
        execl(cmd, NULL);
        std::cerr << "Error executing command: " << cmd << "\n";
        _exit(1); // terminate with error code
    } else { // parent process
        wait(NULL);
        return 1; // successful execution
    }
}
