// Define the library data structure to manage dynamic collection of UEConnectionStatus structures
typedef struct UEConnectionStatusCollection {
    UEConnectionStatus *entries;
    size_t capacity;
    pthread_mutex_t lock;
    time_t ttl;
} UEConnectionStatusCollection;

// Function to create a new UEConnectionStatusCollection instance
UEConnectionStatusCollection *ue_connection_status_collection_create(size_t initial_capacity, time_t ttl) {
    UEConnectionStatusCollection *collection = malloc(sizeof(UEConnectionStatusCollection));
    collection->entries = malloc(initial_capacity * sizeof(UEConnectionStatus));
    collection->capacity = initial_capacity;
    pthread_mutex_init(&collection->lock, NULL);
    collection->ttl = ttl;
    return collection;
}

// Function to add a new UE connection status entry
void ue_connection_status_collection_add_entry(UEConnectionStatusCollection *collection, int ue_id) {
    pthread_mutex_lock(&collection->lock);
    // Check if the collection needs resizing based on TTL expiration and capacity utilization
    if (collection->ttl <= 0 || collection->entries == NULL || collection->capacity <= 1) {
        // Rebalance the collection by reallocating memory and updating capacity
        size_t new_capacity = collection->capacity * 2;
        UEConnectionStatus **new_entries = realloc(collection->entries, new_capacity * sizeof(UEConnectionStatus *));
        for (size_t i = 0; i < collection->capacity; i++) {
            new_entries[i] = &collection->entries[i];
        }
        free(collection->entries);
        collection->entries = new_entries;
        collection->capacity = new_capacity;
    }
    // Add the new entry
    UEConnectionStatus *entry = &collection->entries[collection->capacity - 1];
    entry->ue_id = ue_id;
    entry->timestamp = time(NULL);
    pthread_mutex_unlock(&collection->lock);
}

// Function to remove outdated entries based on TTL
void ue_connection_status_collection_evict_entries(UEConnectionStatusCollection *collection) {
    pthread_mutex_lock(&collection->lock);
    for (size_t i = 0; i < collection->capacity; i++) {
        UEConnectionStatus *entry = &collection->entries[i];
        if (time(NULL) - entry->timestamp > collection->ttl) {
            // Evict outdated entries
            free(entry);
            memmove(&collection->entries[i], &collection->entries[i + 1], (collection->capacity - i - 1) * sizeof(UEConnectionStatus *));
            collection->capacity--;
        }
    }
    pthread_mutex_unlock(&collection->lock);
}

