    if (!pdu) {
        return NULL;
    }
    pdu->crc_indication_rel8_tag_count = 0;
    pdu->crc_indications = (CRC_INDICATION_REL8_TAG**) calloc(NFAPI_MAX_UES, sizeof(CRC_INDICATION_REL8_TAG*));
    if (!pdu->crc_indications) {
        free(pdu);
        return NULL;
    }
    return pdu;
}

void nfapi_message_pdu_free(NFAPI_MESSAGE_PDU_T* pdu) {
    for (size_t i = 0; i < pdu->crc_indication_rel8_tag_count; i++) {
        if (pdu->crc_indications[i]) {
            free(pdu->crc_indications[i]);
        }
    }
    free(pdu->crc_indications);
    free(pdu);
}

void nfapi_message_pdu_add_crc_indication(NFAPI_MESSAGE_PDU_T* pdu, CRC_INDICATION_REL8_TAG* crc_indication) {
    pthread_mutex_lock(&pdu->mutex);
    pdu->crc_indications[pdu->crc_indication_rel8_tag_count] = crc_indication;
    pdu->crc_indication_rel8_tag_count++;
    pthread_mutex_unlock(&pdu->mutex);
}

void nfapi_message_pdu_remove_crc_indication(NFAPI_MESSAGE_PDU_T* pdu, size_t index) {
    if (index >= pdu->crc_indication_rel8_tag_count) {
        return;
    }
    pthread_mutex_lock(&pdu->mutex);
    free(pdu->crc_indications[index]);
    memmove(&pdu->crc_indications[index], &pdu->crc_indications[index + 1],
            (pdu->crc_indication_rel8_tag_count - index - 1) * sizeof(CRC_INDICATION_REL8_TAG*));
    pdu->crc_indication_rel8_tag_count--;
    pthread_mutex_unlock(&pdu->mutex);
}

void nfapi_message_pdu_update_crcflag(NFAPI_MESSAGE_PDU_T* pdu, size_t index, uint32_t crcflag) {
    if (index >= pdu->crc_indication_rel8_tag_count) {
        return;
    }
    pthread_mutex_lock(&pdu->mutex);
    pdu->crc_indications[index]->crcflag = crcflag;
    pthread_mutex_unlock(&pdu->mutex);
