    CRC_INDICATION_REL8_TAG *crc_tags; // Array of CRC_INDICATION_REL8_TAG structures
} NFV_Message;

// Structure to represent a dynamic list of NFV message units
typedef struct {
    pthread_mutex_t lock;
    unsigned int size; // Current number of NFV message units in the list
    NFV_Message **message_list; // Dynamic array of NFV message unit pointers
} NFV_Message_List;

// Function to create a new NFV message unit
NFV_Message *nfv_message_create(RX_UE_INFORMATION_TAG rx_ue_info, RNTI rnti) {
    NFV_Message *message = (NFV_Message *)malloc(sizeof(NFV_Message));
    message->rx_ue_info = rx_ue_info;
    message->rnti = rnti;
    message->num_crc_tags = 0; // Initialize the number of CRC tags to 0
    return message;
}

// Function to add a new NFV message unit to the list
void nfv_message_list_add(NFV_Message_List *list, NFV_Message *message) {
    pthread_mutex_lock(&list->lock);

    // Reallocate memory if necessary
    if (list->size == 0 || list->size % 16 == 0) {
        unsigned int new_size = list->size + 16;
        NFV_Message **new_list = (NFV_Message **)realloc(list->message_list, sizeof(NFV_Message *) * new_size);
        for (unsigned int i = list->size; i < new_size; i++) {
            new_list[i] = NULL;
        }
        list->message_list = new_list;
    }

    // Add the message to the end of the list
    list->message_list[list->size++] = message;
    pthread_mutex_unlock(&list->lock);
}

// Function to remove a NFV message unit from the list
void nfv_message_list_remove(NFV_Message_List *list, NFV_Message *message) {
    pthread_mutex_lock(&list->lock);

    // Find the message in the list and set it to NULL
    for (unsigned int i = 0; i < list->size; i++) {
        if (list->message_list[i] == message) {
            list->message_list[i] = NULL;
            break;
        }
    }

    // Reallocate memory if necessary
    unsigned int new_size = list->size - 1;
    NFV_Message **new_list = (NFV_Message **)realloc(list->message_list, sizeof(NFV_Message *) * new_size);
    for (unsigned int i = 0; i < new_size; i++) {
        list->message_list[i] = NULL;
    }
    list->size = new_size;
    pthread_mutex_unlock(&list->lock);
}

