        array->nfa_pi_crc_indication_pdu = realloc(array->nfa_pi_crc_indication_pdu, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        array->capacity = new_capacity;
    }
}

// Add a new UEConnectionStatus and NFAPI_CRC_INDICATION_PDU_T to the DynamicArray
void dynamic_array_add(DynamicArray *array, UEConnectionStatus ue_connection_status, NFAPI_CRC_INDICATION_PDU_T nfa_pi_crc_indication_pdu) {
    if (array->size >= array->capacity) {
        dynamic_array_resize(array, array->capacity * 2);
    }
