// Concurrently access the DynamicArray from multiple threads
pthread_mutex_t dynamic_array_lock = PTHREAD_MUTEX_INITIALIZER;

void *thread_function(void *arg) {
    int thread_id = *(int *)arg;
    for (int i = 0; i < 10; i++) {
        pthread_mutex_lock(&dynamic_array_lock);
        UEConnectionStatus ue_connection_status = dynamic_array_get(array, thread_id);
        NFAPI_CRC_INDICATION_PDU_T nfa_pi_crc_indication_pdu = dynamic_array_get(array, thread_id);
        pthread_mutex_unlock(&dynamic_array_lock);
    }
    free(arg);
    return NULL;
}

int main() {
    DynamicArray *array = dynamic_array_init(10);

    int num_threads = 4;
    pthread_t threads[num_threads];
    for (int i = 0; i < num_threads; i++) {
        int thread_id = i;
        int *arg = malloc(sizeof(int));
        *(int *)arg = thread_id;
        pthread_create(&threads[i], NULL, thread_function, arg);
    }

    for (int i = 0; i < num_threads; i++) {
        pthread_join(threads[i], NULL);
    }

    free(array);

    return 0;
}
