#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the structure for UE connection status
typedef struct {
    int id;
    char status[20];
} UEConnectionStatus;

// Define the dynamic collection of UE connection statuses
typedef struct {
    UEConnectionStatus* connections;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
    pthread_cond_t cond;
} UEConnectionCollection;

// Function to initialize the UE connection collection
UEConnectionCollection* ue_connection_collection_init(size_t initial_capacity) {
    UEConnectionCollection* collection = (UEConnectionCollection*)malloc(sizeof(UEConnectionCollection));
    collection->connections = (UEConnectionStatus*)calloc(initial_capacity, sizeof(UEConnectionStatus));
    collection->capacity = initial_capacity;
    collection->size = 0;
    pthread_mutex_init(&collection->lock, NULL);
    pthread_cond_init(&collection->cond, NULL);
    return collection;
}

// Function to add a UE connection status to the collection
void ue_connection_collection_add(UEConnectionCollection* collection, UEConnectionStatus new_status) {
    pthread_mutex_lock(&collection->lock);
    if (collection->size >= collection->capacity) {
        // Resize the array if it's full
        size_t new_capacity = collection->capacity * 2;
        UEConnectionStatus* new_connections = (UEConnectionStatus*)calloc(new_capacity, sizeof(UEConnectionStatus));
        memcpy(new_connections, collection->connections, sizeof(UEConnectionStatus) * collection->size);
        free(collection->connections);
        collection->connections = new_connections;
        collection->capacity = new_capacity;
    }
    // Add the new status to the end of the array
    collection->connections[collection->size] = new_status;
    collection->size++;
    pthread_mutex_unlock(&collection->lock);
}

// Function to remove a UE connection status from the collection
void ue_connection_collection_remove(UEConnectionCollection* collection, int id) {
    pthread_mutex_lock(&collection->lock);
    for (int i = 0; i < collection->size; i++) {
        if (collection->connections[i].id == id) {
            // Shift all remaining statuses down to fill the gap
            memmove(&collection->connections[i], &collection->connections[i + 1], sizeof(UEConnectionStatus) * (collection->size - i - 1));
            collection->size--;
            break;
        }
    }
    pthread_mutex_unlock(&collection->lock);
}

// Function to update a UE connection status in the collection
void ue_connection_collection_update(UEConnectionCollection* collection, int id, char new_status[20]) {
    pthread_mutex_lock(&collection->lock);
    for (int i = 0; i < collection->size; i++) {
        if (collection->connections[i].id == id) {
            // Update the status and move on
            memcpy(collection->connections[i].status, new_status, sizeof(char) * 20);
            pthread_mutex_unlock(&collection->lock);
            return;
        }
    }
    pthread_mutex_unlock(&collection->lock);
}

// Function to get a UE connection status from the collection
UEConnectionStatus* ue_connection_collection_get(UEConnectionCollection* collection, int id) {
    pthread_mutex_lock(&collection->lock);
    for (int i = 0; i < collection->size; i++) {
        if (collection->connections[i].id == id) {
            // Return the matching status
            UEConnectionStatus* result = &collection->connections[i];
            pthread_mutex_unlock(&collection->lock);
            return result;
        }
    }
    pthread_mutex_unlock(&collection->lock);
    return NULL;
}

// Function to free the UE connection collection
void ue_connection_collection_free(UEConnectionCollection* collection) {
    free(collection->connections);
    pthread_mutex_destroy(&collection->lock);
    pthread_cond_destroy(&collection->cond);
    free(collection);
}

int main() {
    // Initialize the UE connection collection with an initial capacity of 10
    UEConnectionCollection* collection = ue_connection_collection_init(10);

    // Add some UE connection statuses to the collection
    UEConnectionStatus new_status1 = {"1234", "connected"};
    UEConnectionStatus new_status2 = {"5678", "disconnected"};
    ue_connection_collection_add(collection, new_status1);
    ue_connection_collection_add(collection, new_status2);

    // Update a UE connection status in the collection
    char new_status[20] = "reconnecting";
    ue_connection_collection_update(collection, 1234, new_status);

    // Get a UE connection status from the collection
    UEConnectionStatus* result = ue_connection_collection_get(collection, 5678);
    if (result != NULL) {
        printf("Status: %s\n", result->status);
    }

    // Remove a UE connection status from the collection
    ue_connection_collection_remove(collection, 1234);

    // Free the UE connection collection
    ue_connection_collection_free(collection);

    return 0;
}
