class ConnectionManager {
public:
    void addConnection(const UEConnectionStatus& status) {
        lock_guard<mutex> lock(mutex_);
        connections_[status.connectionId] = status;
    }

    void removeConnection(const string& connectionId) {
        lock_guard<mutex> lock(mutex_);
        connections_.erase(connectionId);
    }

    void checkConnections() {
        lock_guard<mutex> lock(mutex_);
        for (auto it = connections_.begin(); it != connections_.end();) {
            if (!it->second.isConnected) {
                removeConnection(it->first);
                it = connections_.erase(it);
            } else {
                ++it;
            }
        }
    }

private:
    mutex mutex_;
    map<string, UEConnectionStatus> connections_;
};

class MessageHandler {
public:
    void handleMessage(const string& message) {
        lock_guard<mutex> lock(mutex_);
        messages_.push(message);
    }

    string popMessage() {
        lock_guard<mutex> lock(mutex_);
        if (messages_.empty()) {
            return "";
        }
        string msg = messages_.front();
        messages_.pop();
        return msg;
    }

private:
    mutex mutex_;
    queue<string> messages_;
};

class Pipeline {
public:
    void start() {
        thread_ = thread([this] { run(); });
    }

    void stop() {
        if (thread_) {
            thread_->join();
            thread_.reset();
        }
    }

    void processMessage(const string& message) {
        lock_guard<mutex> lock(mutex_);
        messages_.push(message);
    }

private:
    mutex mutex_;
    queue<string> messages_;
    unique_ptr[thread>] thread_;
};

