// Function to read integers from standard input and store them in a dynamic array
void read_integers(int** data, int* size) {
    *size = 0;
    while (1) {
        int num;
        scanf("%d", &num);
        if (num == -1) break; // Read -1 to stop reading integers

        (*data) = realloc((*data), ((*size) + 2) * sizeof(int));
        ((int*)((*data)))[(*size)] = num;
        ((int*)((*data)))[(*size)+1] = -1; // Add sentinel value
        (*size)++;
    }
}

// Function to find the largest integer in the array
int largest_integer(int* data, int size) {
    if (size == 0) return -1;

    int max = data[0];
    for (int i = 0; i < size; i++) {
        if (data[i] > max) max = data[i];
    }
    return max;
}

// Main function
int main() {
    int* integers;
    int size = 0;

    read_integers(&integers, &size);

    printf("The largest integer is: %d\n", largest_integer(integers, size));

    // Free dynamically allocated memory
    for (int i = 0; i < size; i++) {
        free((void*)(&(integers[i])));
    }
    free((void*)integers);

    return 0;
}
