// Define a struct to represent UE connection status
typedef struct {
    char* imei;
    int signalStrength;
    int rxBytesReceived;
} UEConnectionStatus;

// Define a struct to manage the dynamic collection of UE connection statuses
typedef struct {
    UEConnectionStatus** connections;
    int size;
    pthread_mutex_t lock;
    int ttl;
} UEConnectionsManager;

// Function to initialize the UE connections manager
UEConnectionsManager* ue_connections_manager_init(int initial_size, int ttl) {
    UEConnectionsManager* manager = (UEConnectionsManager*)malloc(sizeof(UEConnectionsManager));
    manager->connections = (UEConnectionStatus**)calloc(initial_size, sizeof(UEConnectionStatus*));
    manager->size = initial_size;
    pthread_mutex_init(&manager->lock, NULL);
    manager->ttl = ttl;
    return manager;
}

// Function to add a new UE connection status
void ue_connections_manager_add_connection(UEConnectionsManager* manager, char* imei, int signalStrength, int rxBytesReceived) {
    pthread_mutex_lock(&manager->lock);

    // Check if the connections array needs resizing
    if (manager->size <= 0) {
        int new_size = manager->size * 2;
        UEConnectionStatus** new_connections = (UEConnectionStatus**)realloc(manager->connections, new_size * sizeof(UEConnectionStatus*));
        manager->connections = new_connections;
        manager->size = new_size;
    }

    // Add the new connection status
    UEConnectionStatus* new_connection = (UEConnectionStatus*)malloc(sizeof(UEConnectionStatus));
    new_connection->imei = imei;
    new_connection->signalStrength = signalStrength;
    new_connection->rxBytesReceived = rxBytesReceived;
    manager->connections[manager->size] = new_connection;
    manager->size++;

    pthread_mutex_unlock(&manager->lock);
}

// Function to remove an outdated UE connection status
void ue_connections_manager_remove_outdated_connections(UEConnectionsManager* manager) {
    pthread_mutex_lock(&manager->lock);

    // Iterate over the connections array and remove outdated connections
    for (int i = 0; i < manager->size; i++) {
        UEConnectionStatus* connection = manager->connections[i];
        if (connection->ttl <= 0) {
            free(connection);
            for (int j = i; j < manager->size - 1; j++) {
                manager->connections[j] = manager->connections[j + 1];
            }
            manager->size--;
            i--;
        } else {
            connection->ttl--;
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

// Function to get the number of active UE connections
int ue_connections_manager_get_active_connections(UEConnectionsManager* manager) {
