#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

#define MAX_ENTRIES 1000

typedef struct {
    int status;
    time_t last_update;
} UEConnectionStatus;

typedef struct {
    UEConnectionStatus* entries;
    size_t capacity;
    pthread_mutex_t mutex;
    time_t ttl;
} ConnectionManager;

void connection_manager_init(ConnectionManager* manager, size_t initial_capacity) {
    manager->capacity = initial_capacity;
    manager->entries = (UEConnectionStatus*)malloc(initial_capacity * sizeof(UEConnectionStatus));
    pthread_mutex_init(&manager->mutex, NULL);
}

size_t connection_manager_size(ConnectionManager* manager) {
    return manager->capacity;
}

void connection_manager_add_entry(ConnectionManager* manager, UEConnectionStatus entry) {
    pthread_mutex_lock(&manager->mutex);

    for (size_t i = 0; i < manager->capacity; ++i) {
        if (!manager->entries[i].last_update || time(NULL) - manager->entries[i].last_update > manager->ttl) {
            // Evict outdated entry
            memcpy(&manager->entries[i], &entry, sizeof(UEConnectionStatus));
            break;
        }
    }

    pthread_mutex_unlock(&manager->mutex);
}

void connection_manager_update_entry(ConnectionManager* manager, UEConnectionStatus entry) {
    pthread_mutex_lock(&manager->mutex);

    for (size_t i = 0; i < manager->capacity; ++i) {
        if (!manager->entries[i].last_update || time(NULL) - manager->entries[i].last_update > manager->ttl) {
            // Evict outdated entry
            memcpy(&manager->entries[i], &entry, sizeof(UEConnectionStatus));
            break;
        }
    }

    pthread_mutex_unlock(&manager->mutex);
}

int connection_manager_get_status(ConnectionManager* manager, size_t index) {
    pthread_mutex_lock(&manager->mutex);

    if (index < manager->capacity) {
        UEConnectionStatus entry = manager->entries[index];
        if (entry.last_update || time(NULL) - entry.last_update <= manager->ttl) {
            return entry.status;
        }
    }

    pthread_mutex_unlock(&manager->mutex);
    return -1; // Entry not found or outdated
}

void connection_manager_resize(ConnectionManager* manager, size_t new_capacity) {
    if (new_capacity > manager->capacity) {
        UEConnectionStatus* new_entries = (UEConnectionStatus*)malloc(new_capacity * sizeof(UEConnectionStatus));
        memcpy(new_entries, manager->entries, manager->capacity * sizeof(UEConnectionStatus));
        free(manager->entries);
        manager->entries = new_entries;
    } else if (new_capacity < manager->capacity) {
        UEConnectionStatus* new_entries = (UEConnectionStatus*)malloc(new_capacity * sizeof(UEConnectionStatus));
        memcpy(new_entries, manager->entries, new_capacity * sizeof(UEConnectionStatus));
        free(manager->entries);
        manager->entries = new_entries;
    }
}

void connection_manager_free(ConnectionManager* manager) {
    free(manager->entries);
    pthread_mutex_destroy(&manager->mutex);
}
