        {
            _logger = logger;
            _httpClient = httpClient;
            _dnsResolver = dnsResolver;
        }

        public void LoadConfig(string configurationUrl)
        {
            int maxRetries = 3; // configurable backoff strategy
            int retryInterval = 500; // milliseconds

            for (int i = 0; i < maxRetries; i++)
            {
                try
                {
                    string configJson = _httpClient.GetStringAsync(configurationUrl).Result;
                    ConfigData config = JsonConvert.DeserializeObject<ConfigData>(configJson);

                    // Initialize game world parameters using config data
                    TileSize = config.TileSize;
                    WorldDimensions = config.WorldDimensions;
                    CameraMovementSpeed = config.CameraMovementSpeed;

                    return; // success
                }
                catch (HttpRequestException ex)
                {
                    _logger.LogError("Failed to load configuration: " + ex.Message);
                    if (i < maxRetries - 1)
                    {
                        Thread.Sleep(retryInterval); // backoff strategy
                    }
                }
            }

            throw new Exception("Failed to load configuration after maximum retries");
        }
    }

