// Define the dynamic collection of UEConnectionStatus structures
typedef struct {
    UEConnectionStatus* data;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} UEConnectionStatusCollection;

// Function to create a new UEConnectionStatusCollection instance
UEConnectionStatusCollection* ue_connection_status_collection_create(size_t initial_capacity) {
    UEConnectionStatusCollection* collection = malloc(sizeof(UEConnectionStatusCollection));
    if (!collection) return NULL;

    collection->data = malloc(initial_capacity * sizeof(UEConnectionStatus));
    if (!collection->data) {
        free(collection);
        return NULL;
    }

    collection->capacity = initial_capacity;
    collection->size = 0;
    pthread_mutex_init(&collection->mutex, NULL);

    return collection;
}

// Function to add a new UEConnectionStatus structure to the collection
int ue_connection_status_collection_add(UEConnectionStatusCollection* collection, UEConnectionStatus* status) {
    if (!collection || !status) return -1;

    pthread_mutex_lock(&collection->mutex);

    // If the collection is full, double its capacity
    if (collection->size == collection->capacity) {
        collection->data = realloc(collection->data, (collection->capacity * 2) * sizeof(UEConnectionStatus));
        if (!collection->data) {
            pthread_mutex_unlock(&collection->mutex);
            return -1;
        }

        collection->capacity *= 2;
    }

    // Add the new status to the end of the collection
    memcpy(collection->data + collection->size, status, sizeof(UEConnectionStatus));
    collection->size++;

    pthread_mutex_unlock(&collection->mutex);

    return 0;
}

