// Dynamic array structure
typedef struct {
    UEConnectionStatus **elements;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} DynamicArray;

// Function to read integers from standard input and store them in a dynamic array
void read_integers_and_store(DynamicArray *array) {
    int32_t integer;
    while (scanf("%d", &integer) == 1) {
        // Check if the array needs resizing
        if (array->size >= array->capacity - 1) {
            array->capacity *= 2;
            array->elements = realloc(array->elements, array->capacity * sizeof(UEConnectionStatus *));
        }
        // Store the integer in the array
        array->elements[array->size++] = malloc(sizeof(UEConnectionStatus));
        (*array->elements[array->size - 1])->status_code = integer;
    }
}

// Function to find the largest integer in the dynamic array
int32_t find_largest_integer(DynamicArray *array) {
    int32_t largest = INT_MIN;
    for (int i = 0; i < array->size; i++) {
        if ((*array->elements[i])->status_code > largest) {
            largest = (*array->elements[i])->status_code;
        }
    }
    return largest;
}

// Function to initialize a dynamic array
void init_dynamic_array(DynamicArray *array, size_t capacity) {
    array->capacity = capacity;
    array->size = 0;
    array->elements = malloc(capacity * sizeof(UEConnectionStatus *));
    pthread_mutex_init(&array->mutex, NULL);
}

// Function to free a dynamic array
void free_dynamic_array(DynamicArray *array) {
    for (int i = 0; i < array->size; i++) {
        free(array->elements[i]);
    }
    free(array->elements);
    pthread_mutex_destroy(&array->mutex);
}
