    char* state;
} UEConnectionStatus;

// Define a struct to manage a dynamic collection of UE connections
typedef struct {
    UEConnectionStatus** connections;
    int capacity;
    int size;
    pthread_mutex_t lock;
} UEConnectionManager;

// Function to initialize the UE connection manager
UEConnectionManager* ue_connection_manager_init(int initial_capacity) {
    UEConnectionManager* manager = (UEConnectionManager*)malloc(sizeof(UEConnectionManager));
    manager->connections = (UEConnectionStatus**)calloc(initial_capacity, sizeof(UEConnectionStatus*));
    manager->capacity = initial_capacity;
    manager->size = 0;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

// Function to add a new UE connection status
void ue_connection_manager_add(UEConnectionManager* manager, UEConnectionStatus* status) {
    pthread_mutex_lock(&manager->lock);
    if (manager->size >= manager->capacity) {
        // Resize the array when it's full
        manager->connections = (UEConnectionStatus**)realloc(manager->connections, (manager->capacity *= 2) * sizeof(UEConnectionStatus*));
    }
    manager->connections[manager->size++] = status;
    pthread_mutex_unlock(&manager->lock);
}

// Function to remove a UE connection status
void ue_connection_manager_remove(UEConnectionManager* manager, int id) {
    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < manager->size; i++) {
        if (manager->connections[i]->id == id) {
            // Shift the array down to fill the gap
            memmove(&manager->connections[i], &manager->connections[i + 1], (manager->size - i - 1) * sizeof(UEConnectionStatus*));
            manager->size--;
            break;
        }
    }
    pthread_mutex_unlock(&manager->lock);
}

// Function to update the UE connection status
void ue_connection_manager_update(UEConnectionManager* manager, int id, char* new_state) {
    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < manager->size; i++) {
        if (manager->connections[i]->id == id) {
            // Update the state
            free(manager->connections[i]->state);
            manager->connections[i]->state = strdup(new_state);
            break;
        }
    }
    pthread_mutex_unlock(&manager->lock);
}

// Function to get a UE connection status
UEConnectionStatus* ue_connection_manager_get(UEConnectionManager* manager, int id) {
    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < manager->size; i++) {
        if (manager->connections[i]->id == id) {
            // Return a copy of the UE connection status
            UEConnectionStatus* copy = (UEConnectionStatus*)malloc(sizeof(UEConnectionStatus));
            copy->id = manager->connections[i]->id;
            copy->state = strdup(manager->connections[i]->state);
            return copy;
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return NULL;
}

// Function to release resources and clean up
void ue_connection_manager_free(UEConnectionManager* manager) {
    for (int i = 0; i < manager->size; i++) {
        free(manager->connections[i]->state);
        free(manager->connections[i]);
    }
    free(manager->connections);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}
