using json = nlohmann::json;

bool validateToken(const std::string& tokenJson) {
    try {
        json token = json::parse(tokenJson);

        if (!token.is_object()) {
            return false;
        }

        bool hasAllFields = true;
        for (const auto& field : {"access_token", "expires_in", "token_type"}) {
            if (!token.contains(field) || token[field].type() != json::value::string_t) {
                hasAllFields = false;
                break;
            }
        }

        if (!hasAllFields) {
            return false;
        }

        auto accessToken = token["access_token"];
        auto expiresIn = token["expires_in"].get<int>();
        auto tokenType = token["token_type"];

        if (accessToken.type() != json::value::string_t || expiresIn <= 0 || tokenType != "Bearer") {
            return false;
        }

        return true;

    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
        return false;
    }
}

int main() {
    // Example usage
    std::string tokenJson = R"({"access_token": "abc123", "expires_in": 3600, "token_type": "Bearer"})";
    if (validateToken(tokenJson)) {
        std::cout << "Token is valid." << std::endl;
    } else {
        std::cout << "Token is invalid." << std::endl;
    }

    return 0;
}
