// Create a new dynamic collection
DynamicCollection* createDynamicCollection() {
    DynamicCollection* collection = (DynamicCollection*)malloc(sizeof(DynamicCollection));
    collection->items = NULL;
    collection->size = 0;
    pthread_mutex_init(&collection->lock, NULL);
    return collection;
}

// Add an item to the dynamic collection
void addItem(DynamicCollection* collection, UEConnectionStatus* item) {
    pthread_mutex_lock(&collection->lock);

    // Allocate memory for the new item
    UEConnectionStatus** newItems = (UEConnectionStatus**)realloc(collection->items, (collection->size + 1) * sizeof(UEConnectionStatus*));
    if (!newItems) {
        printf("Memory allocation failed.\n");
        pthread_mutex_unlock(&collection->lock);
        return;
    }

    // Copy the item to the new array
    newItems[collection->size] = item;
    collection->items = newItems;
    collection->size++;

    pthread_mutex_unlock(&collection->lock);
}

// Get an item from the dynamic collection
UEConnectionStatus* getItem(DynamicCollection* collection, int index) {
    pthread_mutex_lock(&collection->lock);

    // Check if the index is within bounds
    if (index >= collection->size || index < 0) {
        printf("Index out of bounds.\n");
        pthread_mutex_unlock(&collection->lock);
        return NULL;
    }

    // Return the item at the specified index
    UEConnectionStatus* item = collection->items[index];
    pthread_mutex_unlock(&collection->lock);
    return item;
}

// Free the dynamic collection and its items
void freeDynamicCollection(DynamicCollection* collection) {
    pthread_mutex_lock(&collection->lock);

    // Free each item in the collection
    for (int i = 0; i < collection->size; i++) {
        UEConnectionStatus* item = collection->items[i];
        if (item) {
            free(item->statusText);
            free(item);
        }
    }

    // Free the items array and the dynamic collection structure
    free(collection->items);
    free(collection);

    pthread_mutex_unlock(&collection->lock);
}

