// Define a class to represent sensor data
class SensorData {
public:
    std::string sensor_id;
    double value;

    SensorData(std::string id, double val) : sensor_id(id), value(val) {}
};

// Define a class to manage the dynamic collection of SensorData objects
class SensorDataManager {
private:
    std::deque<SensorData> data_queue;
    mutable std::mutex mutex;
    std::condition_variable cv;

public:
    void add_data(const SensorData& data) {
        std::unique_lock<std::mutex> lock(mutex);
        data_queue.push_back(data);
        cv.notify_one();
    }

    bool get_data(std::deque<SensorData>& queue) {
        std::unique_lock<std::mutex> lock(mutex);
        cv.wait(lock, [this] { return !data_queue.empty(); });
        if (!data_queue.empty()) {
            queue = data_queue;
            data_queue.clear();
            return true;
        }
        return false;
    }

    void resample_data(int interval) {
        std::deque<SensorData> temp_queue;
        for (auto it = data_queue.begin(); it != data_queue.end();) {
            if (it->value < 0.5f) { // Simple aggregation rule
                ++it;
                continue;
            }
            temp_queue.push_back(*it);
            while (it != data_queue.end() && it->value >= 0.5f) {
                ++it;
            }
        }
        data_queue = temp_queue;
    }

