DynamicList* createDynamicList(int initialCapacity) {
    DynamicList* list = (DynamicList*)malloc(sizeof(DynamicList));
    list->entries = (NFAPI_CRC_INDICATION_PDU_T*)malloc(initialCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->size = 0;
    list->capacity = initialCapacity;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

