#include <iostream>
#include <string>
#include <vector>
#include <unordered_map>
#include <thread>
#include <mutex>
#include <atomic>
#include <chrono>

struct HTTP_RESPONSE_PDU {
    std::atomic<std::uint64_t> request_id;
    int status_code;
    std::string response_body;
};

class CacheManager {
public:
    CacheManager(size_t initial_capacity) : cache_(initial_capacity), capacity_(initial_capacity) {}

    void put(const HTTP_RESPONSE_PDU& pdu) {
        auto it = cache_.emplace(pdu.request_id, pdu);
        if (!it.second) { // Eviction
            auto oldest = lru_.begin();
            lru_.erase(oldest);
            cache_[pdu.request_id] = pdu;
        }
    }

    HTTP_RESPONSE_PDU* get(std::uint64_t request_id) {
        auto it = cache_.find(request_id);
        if (it != cache_.end()) {
            return &it->second;
        }
        return nullptr;
    }

private:
    std::unordered_map<std::uint64_t, HTTP_RESPONSE_PDU> cache_;
    std::vector<HTTP_RESPONSE_PDU> lru_;
    size_t capacity_;
};

class ServiceClient {
public:
    void request(std::string url) {
        // Simulate API call
        auto response = get_response(url);
        CacheManager& cache = *cache_.load();
        if (response) {
            cache.put({std::chrono::time_point<std::chrono::system_clock>(std::chrono::duration_cast<std::chrono::microseconds>(std::chrono::high_resolution_clock::now().time_since_epoch())), response->status_code, response->body});
        }
    }

private:
    std::atomic<std::shared_ptr<HTTP_RESPONSE_PDU>> cache_;
};

int main() {
    CacheManager cache(1024);
