  const authResult = authProviders[req.headers['x-auth-provider']](req, res);
  if (!authResult) return res.status(401).send('Unauthorized');
  req.authData = authResult;
  next();
});

// Cache authentication tokens
app.use((req, res, next) => {
  const token = jwt.sign(req.authData, 'secret', { expiresIn: '1h' });
  cache.set(token, req.authData, 3600);
  next();
});

// Backup authentication method ( caching )
