#include <stdlib.h>
#include <string.h>
#include <stdio.h>

// Node structure for the linked list
typedef struct {
    int state_id;
    void* data;  // pointer to additional data (e.g., metadata)
} StateNode;

// Linked List Structure
typedef struct {
    StateNode* head;
    size_t size;
    pthread_mutex_t lock;
} StateList;

// Function to create a new node with given state ID and data
StateNode* createStateNode(int state_id, void* data) {
    StateNode* node = (StateNode*)malloc(sizeof(StateNode));
    if (!node) {
        return NULL;  // Out of memory
    }
    node->state_id = state_id;
    node->data = data;
    return node;
}

// Function to create a new linked list
StateList* createStateList() {
    StateList* list = (StateList*)malloc(sizeof(StateList));
    if (!list) {
        return NULL;  // Out of memory
    }
    pthread_mutex_init(&list->lock, NULL);
    list->head = NULL;
    list->size = 0;
    return list;
}

// Function to add a new state node to the linked list
int addState(StateList* list, int state_id, void* data) {
    StateNode* newNode = createStateNode(state_id, data);

    // Add to end of list
    if (!list->head) {
        list->head = newNode;
    } else {
        StateNode* current = list->head;
        while (current->next) {
            current = current->next;
        }
        current->next = newNode;
    }

    list->size++;

    pthread_mutex_unlock(&list->lock);
}

// Function to remove a state node from the linked list
int removeState(StateList* list, int state_id) {
    StateNode** current = &list->head;

    // Find and remove node with given state ID
    while (*current && (*current)->state_id != state_id) {
        current = &((*current)->next);
    }

    if (!*current) {
        return 1;  // Node not found
    }

    StateNode* temp = *current;
    *current = (*current)->next;
    free(temp);

    list->size--;

    pthread_mutex_unlock(&list->lock);
}

// Function to serialize the state list to disk
int serializeStateList(StateList* list, FILE* file) {
    // Write state ID and data to file
    fwrite(&list->head, sizeof(StateNode), 1, file);

    // Close file
    fclose(file);

    return 0;  // Success
}

// Function to deserialize the state list from disk
int deserializeStateList(StateList* list, FILE* file) {
    // Read state ID and data from file
    fread(&list->head, sizeof(StateNode), 1, file);

    return 0;  // Success
}

// Main function for testing the library
int main() {
    StateList* list = createStateList();

    addState(list, 1, "Initial");
    addState(list, 2, "Second");
    addState(list, 3, "Third");

    // Serialize and deserialize test
    FILE* file = fopen("states.bin", "wb+");
    serializeStateList(list, file);
    fclose(file);

    file = fopen("states.bin", "rb+");
    deserializeStateList(list, file);
    fclose(file);

    removeState(list, 2);']

