public:
    void addConnectionStatus(UEConnectionStatus status) {
        std::unique_lock<std::mutex> lock(mtx);
        queue.push(status);
        lock.unlock();
        cv.notify_all();
    }

    void startConsuming() {
        for (int i = 0; i < 4; i++) { // Start 4 threads
            threads.emplace_back([this] {
                while (true) {
                    std::unique_lock<std::mutex> lock(mtx);
                    cv.wait(lock, [this] { return !queue.empty(); });
                    UEConnectionStatus status = queue.front();
                    queue.pop();
                    std::cout << "Thread " << std::this_thread::get_id() << ": Received connection status " << status.status << " with message " << status.message << std::endl;
                    lock.unlock();
                }
            });
        }
    }

    void stopConsuming() {
        for (auto& thread : threads) {
            thread.join();
        }
    }
};

int main() {
    UEConnectionManager manager;

    // Add some connection statuses
    manager.addConnectionStatus(UEConnectionStatus(1, "Connected to server"));
    manager.addConnectionStatus(UEConnectionStatus(2, "Disconnected from server"));

    // Start consuming threads
    manager.startConsuming();

    // Wait for 5 seconds before stopping consumption
    std::this_thread::sleep_for(std::chrono::seconds(5));

    // Stop consuming threads
    manager.stopConsuming();

    return 0;
}
```

Note that this is a simplified implementation of the required features and may not cover all edge cases or performance optimization.']

