    list->capacity = initial_capacity;
    list->size = 0;
    return list;
}

// Initialize a UE connection status list
UEConnectionList* create_ue_connection_list(size_t initial_capacity) {
    UEConnectionList* list = malloc(sizeof(UEConnectionList));
