// Add a cell measurement record to the list
void add_cell_measurement(CellMeasurementList* list, CellMeasurementRecord record) {
    if (list->size >= list->capacity) {
        // Resize the array
        list->records = realloc(list->records, (list->capacity * 2) * sizeof(CellMeasurementRecord));
        list->capacity *= 2;
    }
    list->records[list->size++] = record;
}

// Add a UE connection status to the list
void add_ue_connection_status(UEConnectionList* list, UEConnectionStatus status) {
    if (list->size >= list->capacity) {
        // Resize the array
        list->statuses = realloc(list->statuses, (list->capacity * 2) * sizeof(UEConnectionStatus));
        list->capacity *= 2;
    }
    list->statuses[list->size++] = status;
}

