    float value;

    SensorData(const std::string& id, float val) : sensorId(id), value(val) {}
};

// Library to manage a dynamic collection of SensorData objects
class SensorDataManager {
private:
    std::mutex mtx;
    std::condition_variable cv;
    std::vector<SensorData> sensorData;

public:
    // Add a new sensor reading
    void addSensorData(const SensorData& data) {
        std::unique_lock<std::mutex> lock(mtx);
        sensorData.push_back(data);
        cv.notify_all();
    }

    // Get the average value of all sensor readings
    float getAverage() {
        std::unique_lock<std::mutex> lock(mtx);
        return std::accumulate(sensorData.begin(), sensorData.end(), 0.0f) / static_cast<float>(sensorData.size());
    }
};

// Adaptive resampling strategy
class Resampler {
public:
    // Configure the aggregation interval and granularity
    void configure(int interval, int granularity) {
        this->interval = interval;
        this->granularity = granularity;
    }

    // Aggregate and reduce the dataset based on the configuration
    std::vector<SensorData> aggregate(const std::vector<SensorData>& data) {
        std::vector<SensorData> aggregatedData;
        for (int i = 0; i < data.size(); i += granularity) {
            SensorData aggregatedReading;
            float sum = 0.0f;
            for (int j = i; j < std::min(i + granularity, data.size()); j++) {
                sum += data[j].value;
            }
            aggregatedReading.value = sum / static_cast<float>(granularity);
            aggregatedReading.sensorId = data[i].sensorId;
            aggregatedData.push_back(aggregatedReading);
        }
        return aggregatedData;
    }

private:
    int interval;
    int granularity;
};

