typedef struct {
    int id;
} UEConnectionStatus;

// Dynamic array to store UEConnectionStatus
typedef struct {
    UEConnectionStatus* arr;
    int size;
    int capacity;
    pthread_mutex_t mutex;
} DynamicArray;

void initDynamicArray(DynamicArray* da, int initialCapacity) {
    da->arr = (UEConnectionStatus*)calloc(initialCapacity, sizeof(UEConnectionStatus));
    da->size = 0;
    da->capacity = initialCapacity;
    pthread_mutex_init(&da->mutex, NULL);
}

int dynamicArrayPush(DynamicArray* da, UEConnectionStatus status) {
    if (da->size >= da->capacity) {
        int newCapacity = da->capacity * 2;
        UEConnectionStatus* newArr = (UEConnectionStatus*)realloc(da->arr, newCapacity * sizeof(UEConnectionStatus));
        da->arr = newArr;
        da->capacity = newCapacity;
    }
    pthread_mutex_lock(&da->mutex);
    da->arr[da->size] = status;
    da->size++;
    pthread_mutex_unlock(&da->mutex);
    return da->size - 1;
}

UEConnectionStatus dynamicArrayPop(DynamicArray* da) {
    if (da->size > 0) {
        UEConnectionStatus status = da->arr[da->size - 1];
        da->size--;
        pthread_mutex_lock(&da->mutex);
        if (da->size < da->capacity / 2) {
            int newCapacity = da->capacity / 2;
            UEConnectionStatus* newArr = (UEConnectionStatus*)realloc(da->arr, newCapacity * sizeof(UEConnectionStatus));
            da->arr = newArr;
            da->capacity = newCapacity;
        }
        pthread_mutex_unlock(&da->mutex);
        return status;
    } else {
        printf("Array is empty\n");
        return NULL;
    }
}

int main() {
    DynamicArray da;
    initDynamicArray(&da, 10);

    int i;
    for (i = 0; i < 5; i++) {
        UEConnectionStatus status = {i};
        dynamicArrayPush(&da, status);
    }

    for (i = 0; i < 5; i++) {
        UEConnectionStatus status = dynamicArrayPop(&da);
        printf("Popped: %d\n", status.id);
    }

    return 0;
}
