#define CONNECTION_POOL_SIZE 1024
#define TIMEOUT_CHECK_INTERVAL 1000 // milliseconds

typedef enum {
    ESTABLISHED,
    CONNECTING,
    DISCONNECTED
} ConnectionState;

typedef struct {
    uuid_t connectionID;
    char clientIP[16];
    uint16_t clientPort;
    char serverIP[16];
    uint16_t serverPort;
    ConnectionState status;
    int timeout;
    int latency;
    time_t lastActivity;
} ConnectionInfo;

typedef struct {
    ConnectionInfo* connections;
    pthread_mutex_t mutex;
    size_t connectionCount;
    pthread_cond_t cond;
} ConnectionPool;

ConnectionPool connectionPool = {
    .connections = (ConnectionInfo*)malloc(CONNECTION_POOL_SIZE * sizeof(ConnectionInfo)),
    .mutex = PTHREAD_MUTEX_INITIALIZER,
    .connectionCount = 0,
    .cond = PTHREAD_COND_INITIALIZER
};

// External monitoring service API
int monitorServiceUpdateConnectionState(uuid_t connectionID, ConnectionState status) {
    // TO DO: implement the actual API call
    printf("Updated connection state for ID %s to %d\n", uuidUnparse(connectionID), status);
    return 0;
}

void* timeoutThread(void* arg) {
    while (1) {
        pthread_mutex_lock(&connectionPool.mutex);
        size_t i;
        for (i = 0; i < connectionPool.connectionCount; i++) {
            ConnectionInfo* conn = &connectionPool.connections[i];
            if (conn->status == DISCONNECTED && conn->timeout <= 0) {
                // Close and remove expired connection
                printf("Closed expired connection %s\n", uuidUnparse(conn->connectionID));
                memmove(&connectionPool.connections[i], &connectionPool.connections[i + 1], sizeof(ConnectionInfo) * (connectionPool.connectionCount - i - 1));
                connectionPool.connectionCount--;
            }
        }
        pthread_mutex_unlock(&connectionPool.mutex);
        usleep(TIMEOUT_CHECK_INTERVAL * 1000); // convert milliseconds to microseconds
    }
}

int addConnection(uuid_t connectionID, char clientIP[], uint16_t clientPort, char serverIP[], uint16_t serverPort, ConnectionState status) {
    ConnectionInfo* conn = &connectionPool.connections[connectionPool.connectionCount++];
    strcpy(conn->clientIP, clientIP);
    conn->clientPort = clientPort;
    strcpy(conn->serverIP, serverIP);
    conn->serverPort = serverPort;
    conn->status = status;
    conn->timeout = 0; // initialize timeout
    conn->latency = 0;
    conn->lastActivity = time(NULL);
    uuid_copy(&conn->connectionID, connectionID);
    return 0;
}

int updateConnection(uuid_t connectionID, ConnectionState status) {
    pthread_mutex_lock(&connectionPool.mutex);
    size_t i;
    for (i = 0; i < connectionPool.connectionCount; i++) {
        if (uuid_compare(connectionID, &connectionPool.connections[i].connectionID) == 0) {
            connectionPool.connections[i].status = status;
            monitorServiceUpdateConnectionState(connectionID, status);
            pthread_mutex_unlock(&connectionPool.mutex);
            return 0;
        }
    }
    pthread_mutex_unlock(&connectionPool.mutex);
    return -1; // connection not found
}

int removeConnection(uuid_t connectionID) {
    pthread_mutex_lock(&connectionPool.mutex);
    size_t i;
    for (i = 0; i < connectionPool.connectionCount; i++) {
        if (uuid_compare(connectionID, &connectionPool.connections[i].connectionID) == 0) {
            memmove(&connectionPool.connections[i], &connectionPool.connections[i + 1], sizeof(ConnectionInfo) * (connectionPool.connectionCount - i - 1));
            connectionPool.connectionCount--;
            pthread_mutex_unlock(&connectionPool.mutex);
            return 0;
        }
    }
    pthread_mutex_unlock(&connectionPool.mutex);
    return -1; // connection not found
}

void queryConnections() {
    pthread_mutex_lock(&connectionPool.mutex);
    size_t i;
    for (i = 0; i < connectionPool.connectionCount; i++) {
        printf("Connection %s: status=%d, timeout=%d, latency=%d, lastActivity=%ld\n",
            uuidUnparse(&connectionPool.connections[i].connectionID),
            connectionPool.connections[i].status,
            connectionPool.connections[i].timeout,
            connectionPool.connections[i].latency,
            connectionPool.connections[i].lastActivity);
    }
    pthread_mutex_unlock(&connectionPool.mutex);
}

int main() {
    // Start the timeout thread
    pthread_t timeoutThreadHandle;
    pthread_create(&timeoutThreadHandle, NULL, timeoutThread, NULL);

    // Add some connections
    addConnection(uuidCreate(NULL), "192.168.1.100", 5000, "8.8.8.8", 443, ESTABLISHED);
    addConnection(uuidCreate(NULL), "192.168.2.200", 8080, "4.4.4.4", 22, CONNECTING);

    // Update a connection status
    updateConnection(uuidCreate(NULL), DISCONNECTED);

    // Remove a connection
    removeConnection(uuidCreate(NULL));

    // Query all connections
    queryConnections();

    return 0;
}

