        rxIndications[i]->RNTI = rand() % 5000;
        rxIndications[i]->CRC_INDICATION_REL8_TAG = rand() % 20000;
        rxIndications[i]->CRCFLAG = rand() % 2;

        // check for errors
        if (rxIndications[i] == NULL) {
            printf("Error allocating memory!\n");
            return;
        }
    }

    // no need to free the array, as each structure has been freed
}

