    int N = 10; // adjust this value based on your requirements

    NFAPI_CRC_INDICATION_PDU_T *rxIndications = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * N);

    if (rxIndications == NULL) {
        printf("Memory allocation failed!\n");
        return -1;
    }

    populateRxIndications(&rxIndications, N);

    // free dynamically allocated memory
    for (int i = 0; i < N; i++) {
        free(rxIndications[i]);
    }
