} ConnectionInfo;

typedef struct {
    pthread_mutex_t lock;
    ConnectionInfo* connections;
    size_t connectionCount;
} ConnectionPool;

ConnectionPool* connectionPoolInit() {
    ConnectionPool* pool = malloc(sizeof(ConnectionPool));
    pthread_mutex_init(&pool->lock, NULL);
    pool->connections = NULL;
    pool->connectionCount = 0;
    return pool;
}

void connectionPoolAdd(ConnectionPool* pool, ConnectionInfo* connection) {
    pthread_mutex_lock(&pool->lock);
    pool->connections = realloc(pool->connections, (pool->connectionCount + 1) * sizeof(ConnectionInfo));
    pool->connections[pool->connectionCount++] = *connection;
    pthread_mutex_unlock(&pool->lock);
}

void connectionPoolRemove(ConnectionPool* pool, uuid_t connectionID) {
    pthread_mutex_lock(&pool->lock);
    for (size_t i = 0; i < pool->connectionCount; ++i) {
        if (uuid_compare(&connections[i].connectionID, &connectionID) == 0) {
            memmove(&connections[i], &connections[i+1], (pool->connectionCount - i - 1) * sizeof(ConnectionInfo));
            pool->connectionCount--;
            break;
        }
    }
    pthread_mutex_unlock(&pool->lock);
}

void connectionPoolUpdateTimeouts(ConnectionPool* pool, time_t currentTime) {
    pthread_mutex_lock(&pool->lock);
    for (size_t i = 0; i < pool->connectionCount; ++i) {
        if (connections[i].lastActivityTimestamp + connections[i].timeout <= currentTime) {
            // connection timed out
            connectionPoolRemove(pool, connections[i].connectionID);
        }
    }
    pthread_mutex_unlock(&pool->lock);
}

