#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the UEConnectionStatus structure
typedef struct {
    int connection_id;
    int status_code;
} UEConnectionStatus;

// Create a list to store UEConnectionStatus structures
typedef struct {
    UEConnectionStatus* connections;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} UEConnectionList;

// Function to initialize the UEConnectionList
UEConnectionList* ue_connection_list_init(size_t initial_capacity) {
    UEConnectionList* list = (UEConnectionList*)malloc(sizeof(UEConnectionList));
    list->connections = (UEConnectionStatus*)calloc(initial_capacity, sizeof(UEConnectionStatus));
    list->capacity = initial_capacity;
    list->size = 0;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

// Function to add a UEConnectionStatus structure to the list
void ue_connection_list_add(UEConnectionList* list, UEConnectionStatus* connection) {
    pthread_mutex_lock(&list->mutex);
    if (list->size == list->capacity) {
        // Reallocate memory if the list is full
        list->connections = (UEConnectionStatus*)realloc(list->connections, 2 * list->capacity * sizeof(UEConnectionStatus));
        list->capacity *= 2;
    }
    memcpy(&list->connections[list->size], connection, sizeof(UEConnectionStatus));
    list->size++;
    pthread_mutex_unlock(&list->mutex);
}

// Function to get the UEConnectionStatus structure at a specific index
UEConnectionStatus* ue_connection_list_get(UEConnectionList* list, size_t index) {
    if (index >= list->size) return NULL;
    pthread_mutex_lock(&list->mutex);
    UEConnectionStatus* connection = &list->connections[index];
    pthread_mutex_unlock(&list->mutex);
    return connection;
}

// Function to free the UEConnectionList
void ue_connection_list_free(UEConnectionList* list) {
    if (list == NULL) return;
    free(list->connections);
    pthread_mutex_destroy(&list->mutex);
    free(list);
}
