#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the UEConnectionStatus structure
typedef struct {
    int id;
    int importanceLevel;
    char status[20];
} UEConnectionStatus;

// Define a dynamic array of UEConnectionStatus structures
typedef struct {
    UEConnectionStatus* connections;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} ConnectionArray;

// Function to create and initialize the connection array
ConnectionArray* connection_array_create(size_t initial_capacity) {
    ConnectionArray* arr = (ConnectionArray*)malloc(sizeof(ConnectionArray));
    arr->connections = (UEConnectionStatus*)malloc(initial_capacity * sizeof(UEConnectionStatus));
    arr->capacity = initial_capacity;
    arr->size = 0;
    pthread_mutex_init(&arr->mutex, NULL);
    return arr;
}

// Function to add a new connection to the array
void connection_array_add(ConnectionArray* arr, UEConnectionStatus new_conn) {
    pthread_mutex_lock(&arr->mutex);

    if (arr->size == arr->capacity) {
        // Resize the array when it reaches capacity
        size_t new_capacity = arr->capacity * 2;
        arr->connections = (UEConnectionStatus*)realloc(arr->connections, new_capacity * sizeof(UEConnectionStatus));
        arr->capacity = new_capacity;
    }

    arr->connections[arr->size] = new_conn;
    arr->size++;

    pthread_mutex_unlock(&arr->mutex);
}

// Function to get a connection by ID from the array
UEConnectionStatus* connection_array_get(ConnectionArray* arr, int id) {
    for (int i = 0; i < arr->size; i++) {
        if (arr->connections[i].id == id) {
            return &arr->connections[i];
        }
    }
    return NULL;
}

// Function to prioritize connections based on importance levels
void connection_array_prioritize(ConnectionArray* arr) {
    UEConnectionStatus temp_conn;
    for (int i = 0; i < arr->size - 1; i++) {
        for (int j = i + 1; j < arr->size; j++) {
            if (arr->connections[i].importanceLevel > arr->connections[j].importanceLevel) {
                temp_conn = arr->connections[i];
                arr->connections[i] = arr->connections[j];
                arr->connections[j] = temp_conn;
            }
        }
    }
}

// Function to update connection status from an external data source
void connection_array_update(ConnectionArray* arr, UEConnectionStatus updated_conn) {
    pthread_mutex_lock(&arr->mutex);

    for (int i = 0; i < arr->size; i++) {
        if (arr->connections[i].id == updated_conn.id) {
            // Update the existing connection status
            memcpy(&arr->connections[i], &updated_conn, sizeof(UEConnectionStatus));
            break;
        }
    }

    pthread_mutex_unlock(&arr->mutex);
}

// Function to log critical operations
void connection_array_log(ConnectionArray* arr) {
    printf("Critical operation logged for connection ID %d.\n", arr->connections[0].id);
}

int main() {
    // Create the connection array with an initial capacity of 10
    ConnectionArray* arr = connection_array_create(10);

    UEConnectionStatus new_conn1 = {"UE1234", 3, "ESTABLISHED"};
    UEConnectionStatus new_conn2 = {"UE5678", 2, "DISCONNECTED"};

    // Add connections to the array
    connection_array_add(arr, new_conn1);
    connection_array_add(arr, new_conn2);

    // Prioritize connections based on importance levels
    connection_array_prioritize(arr);

    UEConnectionStatus updated_conn = {"UE1234", 3, "ACTIVE"};
    connection_array_update(arr, updated_conn);

    // Log critical operations
    connection_array_log(arr);

    return 0;
}
