#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int status;
} UEConnectionStatus;

// Dynamic array to store UEConnectionStatus
typedef struct {
    UEConnectionStatus* data;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} UEArray;

// Create a new dynamic array
UEArray* ue_array_create(size_t initial_capacity) {
    UEArray* arr = (UEArray*)malloc(sizeof(UEArray));
    arr->data = (UEConnectionStatus*)calloc(initial_capacity, sizeof(UEConnectionStatus));
    arr->capacity = initial_capacity;
    arr->size = 0;
    pthread_mutex_init(&arr->lock, NULL);
    return arr;
}

// Add a new UEConnectionStatus to the array
void ue_array_add(UEArray* arr, UEConnectionStatus status) {
    pthread_mutex_lock(&arr->lock);
    if (arr->size == arr->capacity) {
        // Resize the array when it's full
        arr->data = (UEConnectionStatus*)realloc(arr->data, sizeof(UEConnectionStatus) * (arr->capacity * 2));
        arr->capacity *= 2;
    }
    arr->data[arr->size] = status;
    arr->size++;
    pthread_mutex_unlock(&arr->lock);
}

// Read integers from standard input and store them in the array
void read_integers(UEArray* arr) {
    int num;
    while (scanf("%d", &num) == 1) {
        ue_array_add(arr, (UEConnectionStatus){num});
    }
}

// Find the largest integer in the array
int find_largest(int* arr, size_t size) {
    int max = arr[0];
    for (size_t i = 1; i < size; i++) {
        if (arr[i] > max) {
            max = arr[i];
        }
    }
    return max;
}

// Function to read integers from standard input and store them in a thread-safe, dynamically expanding array
void read_and_store_integers(UEArray* arr) {
    pthread_mutex_lock(&arr->lock);
    int num;
    while (scanf("%d", &num) == 1) {
        ue_array_add(arr, (UEConnectionStatus){num});
    }
    pthread_mutex_unlock(&arr->lock);
}

int main() {
    UEArray* arr = ue_array_create(10);

    read_and_store_integers(arr);

    int max = find_largest((int*)arr->data, arr->size);

    printf("The largest integer is: %d\n", max);

    return 0;
}
