import logging
from flask import Flask, request, jsonify
from flask_sqlalchemy import SQLAlchemy
from datetime import datetime as dt
from collections import deque
from threading import Thread
import os
import json
import pickle

app = Flask(__name__)
app.config["SQLALCHEMY_DATABASE_URI"] = "sqlite:///logs.db"
db = SQLAlchemy(app)

class LogEntry(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    log_data = db.Column(db.String, nullable=False)

@app.route("/logs", methods=["POST"])
def process_logs():
    if request.is_json:
        data = request.get_json()
        for entry in data:
            log_entry = LogEntry(log_data=json.dumps(entry))
            db.session.add(log_entry)
            db.session.commit()

if __name__ == "__main__":
    app.run(debug=True)

class LogProcessor(Thread):
    def __init__(self, queue):
        super(LogProcessor, self).__init__()
        self.queue = queue

    def run(self):
        while True:
            log_entry = self.queue.get()
            if log_entry is None:
                break
            # process log entry here
            self.queue.task_done()

class LogQueue(deque):
    def put(self, item):
        super(LogQueue, self).append(item)

if __name__ == "__main__":
    queue = LogQueue()
    processor = LogProcessor(queue)
