    private static final int EVENT_SIZE = 12000; // in bytes
    private static final int NUM_WORKER_THREADS = Runtime.getRuntime().availableProcessors();
    private static final int DEFAULT_CACHE_SIZE = 1000;

    public void startPipeline() {
        ExecutorService executor = Executors.newFixedThreadPool(NUM_WORKER_THREADS);
        BlockingQueue<Runnable> queue = new LinkedBlockingQueue<>();

        // Initialize event filters, aggregators, and transformations
        EventFilter filter = new MyEventFilter();
        EventAggregator aggregator = new MyEventAggregator();
