type encryptionLib struct{}

func (el *encryptionLib) Encrypt(plainText []byte, key string, algo string, mode string) ([]byte, error) {
	// Check if the key is valid
	if !isValidKey(key) {
		return nil, fmt.Errorf("invalid key")
	}

	// Choose the correct encryption algorithm and mode based on the input
	var cipherBlock cipher.Block
	switch algo {
	case "AES-128-CBC":
		cipherBlock = aes.NewCipher([]byte(key))
	default:
		return nil, fmt.Errorf("unsupported algorithm: %s", algo)
	}

	switch mode {
	case "CBC":
		block, err := cbcEncrypt(plainText, cipherBlock)
		if err != nil {
			return nil, err
		}
		return block, nil
	default:
		return nil, fmt.Errorf("unsupported mode: %s", mode)
	}
}

func (el *encryptionLib) Decrypt(cipherText []byte, key string, algo string, mode string) ([]byte, error) {
	// Check if the key is valid
	if !isValidKey(key) {
		return nil, fmt.Errorf("invalid key")
	}

	// Choose the correct encryption algorithm and mode based on the input
	var cipherBlock cipher.Block
	switch algo {
	case "AES-128-CBC":
		cipherBlock = aes.NewCipher([]byte(key))
	default:
		return nil, fmt.Errorf("unsupported algorithm: %s", algo)
	}

	switch mode {
	case "CBC":
		block, err := cbcDecrypt(cipherText, cipherBlock)
		if err != nil {
			return nil, err
		}
		return block, nil
	default:
		return nil, fmt.Errorf("unsupported mode: %s", mode)
	}
}

