async function runTests(testConfigs) {
  const blueSlip = require('blueslip');
  const { logger } = require('logger-service');

  let concurrencyLimit = process.env.TEST_CONCURRENCY_LIMIT || 5;
  let maxRetries = process.env.TEST_MAX_RETRIES || 3;

  for (const config of testConfigs) {
    const { modulePath, testName, testFunction, timeout, retryCount, skip, dependencies } = config;
    if (skip) continue;

    try {
      const module = await import(modulePath);
      const test = module[testName];

      if (!test) throw new Error(`Test not found: ${testName} in ${modulePath}`);

      let retries = 0;
      while (retries < maxRetries) {
        try {
          await testFunction();
          break;
        } catch (error) {
          retries++;
          if (retries >= retryCount) throw error;
          // Log the failure and notify the team
          logger.error(`Test ${testName} failed: ${error}`);
          setTimeout(() => {
            // Alert the team via a configured alert service
            alertService.notify(`Test ${testName} failed`);
          }, 1000);
        }
      }

      if (retries >= maxRetries) {
        // If all retries fail, pause the test suite and provide a detailed report
        logger.error(`Test Suite Paused: Test ${testName} failed after ${maxRetries} retries`);
        await blueSlip.pause();
      }
    } catch (error) {
      // Handle fatal errors and log them
      logger.error(`Fatal Error in Test Suite: ${error}`);
    }
  }

  // Reset the blueslip instance before each new test run
  blueSlip.reset();

  // Synchronize logs from different modules to a centralized logging service
  await blueSlip.forwardLogs();
}
