function renderFooterScripts(scripts, config) {
  const { maxScriptLength, excludeKeys, debugMode, cdnEndpoints, minifyScripts, fallbackScripts, geolocationService, cacheTTL } = config;

  let renderedHTML = '';
  const cdnsUsed = new Set();

  // Iterate over scripts and filter out excluded or truncated scripts
  for (const script of scripts) {
    if (script.key in excludeKeys || script.code.length > maxScriptLength) {
      if (debugMode) {
        console.log(`Script ${script.key} excluded due to length (${script.code.length}) or key exclusion.`);
      }
      continue;
    }

    // Determine CDN endpoint based on user location
    const cdnEndpoint = geolocationService.getCDN();
    if (!cdnEndpoint) {
      console.error('Failed to determine CDNs. Using fallback CDN...');
      cdnEndpoint = 'fallback-cdn';
    }

    // Add script to rendered HTML, minifying when possible
    let scriptHTML;
    try {
      if (minifyScripts && script.mediaType === 'javascript') {
        const minifiedScript = jsMinify(script.code);
        scriptHTML = `<script>${minifiedScript}</script>`;
      } else {
        scriptHTML = `<script src="${cdnEndpoint}${script.url}" type="${script.mediaType}"></script>`;
      }
    } catch (error) {
      console.error(`Error processing script ${script.key}:`, error);
      if (fallbackScripts && fallbackScripts.includes(script.key)) {
        scriptHTML = `<script>${fallbackScripts[scripts.indexOf(script)]}</script>`;
      } else {
        scriptHTML = '';
      }
    }

    // Cache frequently requested scripts
    const cacheKey = `${script.key}:${cdnEndpoint}`;
    const cachedScript = getCache(cacheKey);
    if (cachedScript) {
      scriptHTML = cachedScript;
    }

    renderedHTML += scriptHTML;

    // Log metrics for each request
    console.log(`Requested script ${script.key} from CDN ${cdnEndpoint}`);
  }

  return renderedHTML;
}
