                {
                    // Process configuration value
                    string configData = param.Value;
                    // ...
                }
            }
        }

        private async Task RetryOperationAsync(Exception ex)
        {
            int retryCount = 0;
            while (retryCount < 3)
            {
                try
                {
                    await Task.Delay(100);
                    // Re-execute the operation
                    return;
                }
                catch (Exception innerEx)
                {
                    if (innerEx != ex)
                    {
                        // New error occurred, reset retry count
                        retryCount = 0;
                    }
                    else
                    {
                        // Same error occurred, increment retry count
                        retryCount++;
                    }
                }
            }

