import java.util.*;
import java.io.*;

public class NasPDUProcessor {
    private static final int MAX_PDU_SIZE = 1024;
    private static final int RNTI_RANGE = 65535;

    private Map<Integer, PDU> pduMap = new HashMap<>();
    private Queue<PDU> pduQueue = new LinkedList<>();
    private Map<String, String> cachedStrings = new HashMap<>();

    public void processPDU(PDU pdu) {
        if (pdu == null || pdu.getRNTI() < 1 || pdu.getRNTI() > RNTI_RANGE) {
            System.out.println("Invalid PDU: " + pdu);
            return;
        }

        // Append slash to string if necessary
        String formattedString = formatString(pdu.getString());
        if (formattedString != null) {
            pdu.setString(formattedString);

            // Check for duplicate RNTI and handle accordingly
            if (!pduMap.containsKey(pdu.getRNTI())) {
                pduMap.put(pdu.getRNTI(), pdu);
                pduQueue.offer(pdu);
            }
        } else {
            System.out.println("Failed to process PDU: " + pdu);
        }
    }

    public String formatString(String s) {
        if (s == null || s.length() >= MAX_PDU_SIZE) {
            return s;
        }

        return slashify(s, MAX_PDU_SIZE - 1);
    }

    private String slashify(String s, int maxLength) {
        if (s.length() > maxLength) {
            return null;
        }

        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (i == maxLength - 1) {
                sb.append('/').append(c);
                break;
            }
            sb.append(c);
        }
        return sb.toString();
    }

    public void handlePDUQueue() {
        while (!pduQueue.isEmpty()) {
            PDU pdu = pduQueue.poll();
            if (pdu != null) {
                processPDU(pdu);
            }
        }
    }

