CREATE PROCEDURE sp_GetEmployeeInfo
    @SupervisorID int
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @HR_API_URL nvarchar(255) = 'https://hr-system-api.com/api/employees';
    DECLARE @PAYROLL_API_URL nvarchar(255) = 'https://payroll-system.com/api/employee-status';

    BEGIN TRY
        -- Retrieve employee details and department information from HR system API
        DECLARE @HR_EmployeeInfo TABLE (EmployeeID int, Name nvarchar(50), City nvarchar(50), Address nvarchar(100), DepartmentName nvarchar(50));
        INSERT INTO @HR_EmployeeInfo
        SELECT * FROM OPENROWSET('JSON', @HR_API_URL + '?supervisorId=' + CONVERT(nvarchar, @SupervisorID)) AS HR_Employees;

        -- Verify employee status with payroll system API
        DECLARE @PayrollEmployeeStatus TABLE (EmployeeID int, Active bit);
        INSERT INTO @PayrollEmployeeStatus
        SELECT * FROM OPENROWSET('JSON', @PAYROLL_API_URL + '?employeeId=' + CONVERT(nvarchar, e.EmployeeID)) AS Payroll_EmployeeStatus
        CROSS APPLY (SELECT 1) AS Dummy;

        -- Merge data from HR and payroll systems, handling race conditions
        WITH MergedEmployeeInfo AS (
            SELECT e.*, pe.Active FROM @HR_EmployeeInfo e
            LEFT JOIN @PayrollEmployeeStatus pe ON e.EmployeeID = pe.EmployeeID
        )
        SELECT * FROM MergedEmployeeInfo;

    END TRY
    BEGIN CATCH
        -- Log error and provide feedback to caller
        DECLARE @ErrorMessage nvarchar(4000) = ERROR_MESSAGE();
        INSERT INTO audit_log (ErrorTimestamp, ErrorMessage)
        VALUES (GETDATE(), @ErrorMessage);

        THROW;
    END CATCH;
END;

GO

CREATE TABLE audit_log (
    ErrorTimestamp datetime,
    ErrorMessage nvarchar(4000),
    RequestMetadata nvarchar(255)
);
