class Octree {
public:
    static const int DEFAULT_MAX_DEPTH = 10;
    static const double DEFAULT_CELL_SIZE = 1.0;

    Octree(int maxDepth = DEFAULT_MAX_DEPTH, double cellSize = DEFAULT_CELL_SIZE) 
        :maxDepth(maxDepth), cellSize(cellSize), root(std::make_shared<Cell>(0)) {
        resizeStrategy = std::make_unique<FixedResizeStrategy>();
        evictionMechanism = std::make_unique<TTL(evictionTimeOutPeriod));
    }

    void insert(const std::vector<Vector3>& points) {
        for (const auto& point : points) {
            root->insert(point, maxDepth);
        }
    }

    bool query(const std::vector<Vector3>& points, const int depth) {
        for (const auto& point : points) {
            if (!root->query(point, depth)) {
                return false;
            }
        }
        return true;
    }

private:
    struct Cell {
        std::shared_ptr<Cell> topLeft, topRight, bottomLeft, bottomRight;
        Vector3 center;

        Cell(int level) 
            :center(Vector3(0, 0, 0)), level(level) {}

        void insert(const Vector3& point, int maxDepth) {
            if (level >= maxDepth || isLeaf()) {
                // Perform spatial query
                return;
            }

            double x = point.x - center.x;
            double y = point.y - center.y;
            double z = point.z - center.z;

            if (x > 0.5 && y > 0.5) {
                if (!topRight->insert(point, maxDepth)) {
                    return;
                }
            } else if (x > 0.5) {
                if (!topLeft->insert(point, maxDepth)) {
                    return;
                }
            } else if (y > 0.5) {
                if (!bottomRight->insert(point, maxDepth)) {
                    return;
                }
            } else {
                if (!bottomLeft->insert(point, maxDepth)) {
                    return;
                }
            }
        }

        bool query(const Vector3& point, int depth) {
            double x = point.x - center.x;
            double y = point.y - center.y;
            double z = point.z - center.z;

            if (x > 0.5 && y > 0.5) {
                return topRight->query(point, depth);
            } else if (x > 0.5) {
                return topLeft->query(point, depth);
            } else if (y > 0.5) {
                return bottomRight->query(point, depth);
            } else {
                return bottomLeft->query(point, depth);
            }
        }

        bool isLeaf() const {
            return level >= maxDepth;
        }
    };

    int maxDepth;
    double cellSize;
    std::shared_ptr<Cell> root;

    std::unique_ptr<ResizeStrategy> resizeStrategy;
    std::unique_ptr<EvictionMechanism> evictionMechanism;
};

