            _maxAttempts = maxAttempts;
            _initialBackoff = initialBackoff;
        }

        public void PerformAction(Action action)
        {
            for (int i = 0; i < _maxAttempts; i++)
            {
                try
                {
                    action();
                    return;
                }
                catch (Exception e)
                {
                    if (_initialBackoff.TotalMilliseconds > 0)
                    {
                        var backoffTime = TimeSpan.FromMilliseconds(_initialBackoff.TotalMilliseconds * (int)Math.Pow(2, i));
                        Thread.Sleep(backoffTime);
                    }
                    else
                    {
                        throw;
                    }
                }
            }
        }
    }

