        private readonly int _maxFailedAttempts;
        private readonly TimeSpan _initialOpenTime;

        public CircuitBreaker(int maxFailedAttempts, TimeSpan initialOpenTime)
        {
            _maxFailedAttempts = maxFailedAttempts;
            _initialOpenTime = initialOpenTime;
        }

        public void PerformAction(Action action)
        {
            if (IsOpen())
            {
                // perform the action
                return;
            }
            else
            {
                for (int i = 0; i < _maxFailedAttempts; i++)
                {
                    try
                    {
                        action();
                        Close();
                        return;
                    }
                    catch (Exception e)
                    {
                        if (_initialOpenTime.TotalSeconds > 0)
                        {
                            var openTime = TimeSpan.FromSeconds(_initialOpenTime.TotalSeconds * (int)Math.Pow(2, i));
                            Thread.Sleep(openTime);
                        }
                        else
                        {
                            throw;
                        }
                    }
                }
            }
        }

