using System;
using System.Security.Cryptography;
using System.Threading.Tasks;

namespace SecureHasher
{
    public class Hasher
    {
        private const int DefaultMaxConcurrency = 10000;
        private const int FallbackTimeoutMs = 5000; // 5 seconds

        private readonly object _syncLock = new();
        private readonly TaskFactory _taskFactory;

        public Hasher()
        {
            _taskFactory = new TaskFactory();
        }

        public async Task<string> ComputeHashAsync(string input, string algorithm)
        {
            if (string.IsNullOrEmpty(input))
                throw new ArgumentException("Input cannot be null or empty", nameof(input));

            if (!SupportedAlgorithms.Contains(algorithm))
                throw new InvalidOperationException($"Unsupported algorithm '{algorithm}'. Falling back to SHA-256.");

            using var hmac = GetHashAlgorithm(algorithm);
            byte[] hashBytes = hmac.ComputeHash(System.Text.Encoding.UTF8.GetBytes(input));
            return BitConverter.ToString(hashBytes).Replace("-", "").ToLower();
        }

        private HashAlgorithm GetHashAlgorithm(string algorithm)
        {
            if (algorithm == "MD5")
                return MD5.Create();

            if (algorithm == "SHA-256")
                return SHA256.Create();

            // Fallback to SHA-256
            return SHA256.Create();
        }
    }
}
