using System;
using System.Security.Cryptography;

namespace SecureHasher
{
    public class Aes256CbcCipher : IDisposable
    {
        private const int Iterations = 1000;

        private readonly byte[] _key;
        private readonly Aes aes;
        private readonly ICryptoTransform encryptor;
        private readonly ICryptoTransform decryptor;

        public Aes256CbcCipher(string password)
        {
            using var rfc2898DeriveBytes = new Rfc2898DeriveBytes(password, new byte[] { 0x00, 0x11, 0x22, 0x33 }, Iterations);
            _key = rfc2898DeriveBytes.GetBytes(32);

            aes = Aes.Create();
            aes.Key = _key;
            aes.BlockSize = 128;

            encryptor = aes.CreateEncryptor();
            decryptor = aes.CreateDecryptor();
        }

        public string Encrypt(string plaintext)
        {
            using var ms = new MemoryStream();
            using var cs = new CryptoStream(ms, encryptor, CryptoStreamMode.Write);
            byte[] bytes = System.Text.Encoding.UTF8.GetBytes(plaintext);
            cs.Write(bytes, 0, bytes.Length);
            return Convert.ToBase64String(ms.ToArray());
        }

        public string Decrypt(string ciphertext)
        {
            using var ms = new MemoryStream(Convert.FromBase64String(ciphertext));
            using var cs = new CryptoStream(ms, decryptor, CryptoStreamMode.Read);
            byte[] bytes = new byte[cs.Length];
            cs.Read(bytes, 0, bytes.Length);
            return System.Text.Encoding.UTF8.GetString(bytes);
        }

        public void Dispose()
        {
            aes.Dispose();
            encryptor.Dispose();
            decryptor.Dispose();
        }
    }
}
