```c
#include <stdio.h>
#include <stdlib.h>

typedef struct FsaState {
    int id;
    struct FsaState* next;
} FsaState;

FsaState* create_state_list(int* states, int num_states, FsaState* fsa, int last_state) {
    FsaState* state_list = (FsaState*)malloc((num_states + 1) * sizeof(FsaState));
    if (!state_list) return NULL;
    for (int i = 0; i < num_states; i++) {
        state_list[i].id = states[i];
        state_list[i].next = (i == last_state) ? NULL : &state_list[i + 1];
    }
    fsa->next = &state_list[last_state];
    return state_list;
}
