    StateList(int num_states) : states(new int[num_states]) {}

    ~StateList() { delete[] states; }

    void add_state(int state) { states[state] = 1; }

    int* get_states() { return states; }

private:
    int* states;
};

std::unique_ptr<StateList> create_state_list(int num_states, int last_state) {
    if (num_states > 0 && last_state >= 0) {
        return std::make_unique<StateList>(num_states);
    } else {
        return nullptr;
    }
}
