    public BinaryTree<T> Left { get; set; }
    public BinaryTree<T> Right { get; set; }

    public void Deserialize(byte[] buffer)
    {
        using (var stream = new MemoryStream(buffer))
        {
            using (var reader = new BinaryReader(stream))
            {
                Value = (T)reader.ReadObject();
                Left = (BinaryTree<T>)reader.ReadObject();
                Right = (BinaryTree<T>)reader.ReadObject();
            }
        }
    }

    public byte[] Serialize()
    {
        using (var stream = new MemoryStream())
        {
            using (var writer = new BinaryWriter(stream))
            {
                writer.WriteObject(Value);
                writer.WriteObject(Left);
                writer.WriteObject(Right);

                return stream.ToArray();
            }
        }
    }
}

public class BinaryTreeDeserializer
{
    public static void Deserialize(byte[] buffer, out BinaryTree<int> tree)
    {
        using (var stream = new MemoryStream(buffer))
        {
