// nodejs-service.js
const express = require('express');
const app = express();
const axios = require('axios');
const { Cache } = require('node-cache');
const { retry } = require('retry-requests');

// Set up caching with a 1-minute TTL
const cache = new Cache({ ttl: 60 });

app.use(express.json());

// API configuration (dynamic)
const apiConfig = {
  'api1': {
    url: 'https://api1.example.com',
    token: 'your-token-here',
    retryInterval: 500 // milliseconds
  },
  'api2': {
    url: 'https://api2.example.com',
    token: 'another-token-here',
    retryInterval: 1000 // milliseconds
  }
};

// Define a function to fetch user profiles from an API
async function getUserProfile(email, api) {
  const cachedResult = cache.get(email);
  if (cachedResult) return cachedResult;

  try {
    const response = await axios.get(`${api.url}/users/${email}`, {
      headers: { 'Authorization': `Bearer ${api.token}` }
    });
    cache.set(email, response.data); // store in cache
    return response.data;
  } catch (error) {
    if (error.code === 'ECONNREFUSED') {
      console.error(`API ${api.url} is down`);
      throw error; // propagate error for retry logic to handle
    }
    await retry({
      retries: 3,
      delay: api.retryInterval,
      onFail: () => {
        console.error(`Failed to fetch user profile from API ${api.url}`);
      },
      onSuccess: (result) => {
        console.info(`Fetched user profile from API ${api.url}:`, result);
      }
    }, getUserProfile, [email, api]);
  }
}

// Define a function to handle batch requests
async function handleBatchRequests(requests) {
  const results = [];
  for (const request of requests) {
    const { email } = request;
    try {
      const userProfile = await getUserProfile(email, apiConfig[request.api]);
      results.push({ ...request, result: userProfile });
    } catch (error) {
      console.error(`Error processing request for ${email}:`, error);
    }
  }
  return results;
}

// Define a route to handle batch requests
app.post('/batch', async (req, res) => {
  const requests = req.body.requests;
  try {
    const results = await handleBatchRequests(requests);
    res.json(results);
  } catch (error) {
    console.error(`Error processing batch request:`, error);
    res.status(500).send({ message: 'Internal Server Error' });
  }
});

// Start the service
const port = 3000;
app.listen(port, () => {
  console.info(`Service listening on port ${port}`);
});
```

