class UEConnectionStatus {
public:
    int connectionId;
    bool isConnected;

    UEConnectionStatus(int id, bool status) : connectionId(id), isConnected(status) {}
};

class UELibrary {
public:
    std::vector<UEConnectionStatus> connectionStatusList;
    std::mutex mtx;
    std::condition_variable cv;

    void addConnectionStatus(UEConnectionStatus status) {
        std::unique_lock<std::mutex> lock(mtx);
        connectionStatusList.push_back(status);
        lock.unlock();
        cv.notify_one();
    }

    UEConnectionStatus getLatestStatus() {
        UEConnectionStatus latestStatus;
        {
            std::unique_lock<std::mutex> lock(mtx);
            while (connectionStatusList.empty()) {
                cv.wait(lock);
            }
            latestStatus = connectionStatusList.back();
        }
        return latestStatus;
    }

    void resize(int newCapacity) {
        if (newCapacity < 0) {
            throw std::invalid_argument("Invalid capacity");
        }
        connectionStatusList.resize(newCapacity);
    }
};

class UEConnectionManager {
public:
    UELibrary library;

    void start() {
        while (true) {
            UEConnectionStatus status = library.getLatestStatus();
            // Process the status
            if (!status.isConnected) {
                // Handle disconnection
            } else {
                // Handle connection
            }
        }
    }

    void updateStatus(UEConnectionStatus status) {
        library.addConnectionStatus(status);
    }

    void setResizeCapacity(int capacity) {
        library.resize(capacity);
    }
};

