    pthread_cond_t cond;
    clock_t last_update;
    int auth_attempts;
} UECollection;

// Initialize the collection
UECollection* ue_collection_init() {
    UECollection* collection = (UECollection*)malloc(sizeof(UECollection));
    collection->data = (UEConnectionStatus*)calloc(UE_CONNECTION_STATUS_MAX, sizeof(UEConnectionStatus));
    collection->count = 0;
    pthread_mutex_init(&collection->mutex, NULL);
    pthread_cond_init(&collection->cond, NULL);
    collection->last_update = clock();
    collection->auth_attempts = 0;
    return collection;
}

// Add a new connection status
void ue_collection_add_status(UECollection* collection, UEConnectionStatus* status) {
    pthread_mutex_lock(&collection->mutex);
    if (collection->count >= UE_CONNECTION_STATUS_MAX) {
        // Evict outdated entries
        size_t i = 0;
        for (size_t j = 0; j < collection->count; j++) {
            if (clock() - collection->data[j].timestamp > TTL_DEFAULT * CLOCKS_PER_SEC) {
                continue;
            }
            collection->data[i] = collection->data[j];
            i++;
        }
        collection->count = i;
    }
    collection->data[collection->count] = *status;
    collection->count++;
    pthread_mutex_unlock(&collection->mutex);
}

