#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct UEConnectionStatus {
  int status;
  char* address;
  time_t timestamp;
} UEConnectionStatus;

#define MAX_CONNECTIONS 100
#define TTL 300 // seconds

// Thread-safe connection management
struct {
  pthread_mutex_t lock;
  UEConnectionStatus connections[MAX_CONNECTIONS];
  time_t lastCleanup;
} ueConnections = {
  .lock = PTHREAD_MUTEX_INITIALIZER,
};

void initUeConnections() {
  for (int i = 0; i < MAX_CONNECTIONS; i++) {
    ueConnections.connections[i].status = -1;
  }
}

void addConnection(UEConnectionStatus* connection) {
  pthread_mutex_lock(&ueConnections.lock);
  for (int i = 0; i < MAX_CONNECTIONS; i++) {
    if (ueConnections.connections[i].status == -1) {
      memcpy(&ueConnections.connections[i], connection, sizeof(UEConnectionStatus));
      break;
    }
  }
  pthread_mutex_unlock(&ueConnections.lock);
}

void removeConnection(int index) {
  pthread_mutex_lock(&ueConnections.lock);
  ueConnections.connections[index].status = -2;
  pthread_mutex_unlock(&ueConnections.lock);
}

int getTtl() { return TTL; }

time_t getLastCleanup() { return ueConnections.lastCleanup; }

// C function to compute MD5 hash of a string
#include <openssl/md5.h>

char* md5(const char* input) {
  unsigned char digest[MD5_DIGEST_LENGTH];
  MD5_CTX ctx;
  MD5_Init(&ctx);
  MD5_Update(&ctx, input, strlen(input));
  MD5_Final(digest, &ctx);

  // Convert to hexadecimal string
  char* result = malloc(MD5_DIGEST_LENGTH * 2 + 1);
  for (int i = 0; i < MD5_DIGEST_LENGTH; i++) {
    sprintf(result + i * 2, "%02x", digest[i]);
  }
  result[MD5_DIGEST_LENGTH * 2] = '\0';
  return result;
}

