    fs.readFile(`path/to/${docId}.pdf`, (err, data) => {
      if (err) reject(err);
      const pdf = new pdfjs.PDFDocument();
      pdf.loadFromBuffer(data);
      const section = pdf.getPage(sectionTitle).then((page) => {
        return page.getTextContent().then((textContent) => {
          // Analyze and process text content
          resolve({
            docId,
            sectionTitle,
            metadata,
            extractedText: textContent.toString(),
          });
        });
      }).catch((err) => reject(err));
    });
  });
}

app.post('/extract', (req, res) => {
  const { docId, sectionTitle, metadata } = req.body;
  extractSection(docId, sectionTitle, metadata).then((result) => {
    res.json(result);
  }).catch((err) => {
    console.error(err);
    res.status(500).send({ error: 'Failed to extract section' });
  });
});

app.listen(3000, () => {
  console.log('Server started on port 3000');
});
```

