    UEConnectionStatus *newEntry = (UEConnectionStatus *)malloc(sizeof(UEConnectionStatus));
    newEntry->status = status;
    newEntry->timestamp = time(NULL);
    pthread_mutex_lock(&ueConnectionStatusMutex);
    ueConnectionStatuses = realloc(ueConnectionStatuses, (ueConnectionStatusCount + 1) * sizeof(UEConnectionStatus));
    ueConnectionStatuses[ueConnectionStatusCount++] = newEntry;
    pthread_mutex_unlock(&ueConnectionStatusMutex);
}

// Evict outdated entries based on TTL
void evict_outdated_entries(int ttlSecs) {
    time_t now = time(NULL);
    for (int i = 0; i < ueConnectionStatusCount; i++) {
        if (now - ueConnectionStatuses[i]->timestamp > ttlSecs) {
            free(ueConnectionStatuses[i]);
            memmove(&ueConnectionStatuses[i], &ueConnectionStatuses[i + 1], sizeof(UEConnectionStatus) * (ueConnectionStatusCount - i - 1));
            ueConnectionStatusCount--;
        }
    }
}

