#include <stdbool.h>
#include <pthread.h>

// Define structures
typedef struct {
    int connection_id;
    char status;
} UEConnectionStatus;

typedef struct {
    int cell_id;
    float signal_strength;
    bool is_connected;
} CellMeasurementRecord;

// Define a dynamic collection type
typedef struct {
    size_t capacity;
    size_t size;
    UEConnectionStatus* connections;
    CellMeasurementRecord* measurements;
    pthread_mutex_t lock;
} DynamicCollection;

// Initialize the dynamic collection
void init_dynamic_collection(DynamicCollection* dc, size_t initial_capacity) {
    dc->capacity = initial_capacity;
    dc->size = 0;
    dc->connections = (UEConnectionStatus*)malloc(initial_capacity * sizeof(UEConnectionStatus));
    dc->measurements = (CellMeasurementRecord*)malloc(initial_capacity * sizeof(CellMeasurementRecord));
    pthread_mutex_init(&dc->lock, NULL);
}

// Add an element to the dynamic collection
void add_element(DynamicCollection* dc, UEConnectionStatus connection) {
    pthread_mutex_lock(&dc->lock);

    if (dc->size >= dc->capacity) {
        // Resize the array if it's full
        dc->capacity *= 2;
        dc->connections = (UEConnectionStatus*)realloc(dc->connections, dc->capacity * sizeof(UEConnectionStatus));
        dc->measurements = (CellMeasurementRecord*)realloc(dc->measurements, dc->capacity * sizeof(CellMeasurementRecord));
    }

    // Add the new element
    dc->connections[dc->size] = connection;
    dc->measurements[dc->size] = CellMeasurementRecord{0};  // Initialize measurement record

    dc->size++;

    pthread_mutex_unlock(&dc->lock);
}

// Concurrently access the dynamic collection
void* thread_function(void* arg) {
    DynamicCollection* dc = (DynamicCollection*)arg;
    UEConnectionStatus connection;

    // Thread-safe code to add elements
    for (int i = 0; i < 10; i++) {
        pthread_mutex_lock(&dc->lock);
        add_element(dc, UEConnectionStatus{1, 'A'});  // Simulate adding an element
        pthread_mutex_unlock(&dc->lock);
    }

    return NULL;
}

// Start threads to concurrently access the dynamic collection
int main() {
    DynamicCollection dc;
    init_dynamic_collection(&dc, 10);

    pthread_t threads[5];
    for (int i = 0; i < 5; i++) {
        pthread_create(&threads[i], NULL, thread_function, &dc);
    }

    // Wait for all threads to finish
    for (int i = 0; i < 5; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}

