typedef struct {
    UEConnectionStatus* connections;
    CellMeasurementRecord* measurements;
    int connection_count;
    int measurement_count;
    pthread_mutex_t lock;
} CollectionManager;

// Initialize collection manager
void initialize_collection_manager(CollectionManager* manager, int initial_capacity) {
    manager->connections = (UEConnectionStatus*)malloc(initial_capacity * sizeof(UEConnectionStatus));
    manager->measurements = (CellMeasurementRecord*)malloc(initial_capacity * sizeof(CellMeasurementRecord));
    manager->connection_count = 0;
    manager->measurement_count = 0;
    pthread_mutex_init(&manager->lock, NULL);
}

// Add a connection to the collection
void add_connection(CollectionManager* manager, UEConnectionStatus connection) {
    pthread_mutex_lock(&manager->lock);
    if (manager->connection_count >= manager->measurements->measurement_count) {
        // Resize array if necessary
        UEConnectionStatus* new_connections = (UEConnectionStatus*)realloc(manager->connections, (manager->connection_count + 1) * sizeof(UEConnectionStatus));
        manager->connections = new_connections;
    }
    manager->connections[manager->connection_count++] = connection;
    pthread_mutex_unlock(&manager->lock);
}

// Add a measurement to the collection
void add_measurement(CollectionManager* manager, CellMeasurementRecord measurement) {
    pthread_mutex_lock(&manager->lock);
    if (manager->measurement_count >= manager->measurements->measurement_count) {
        // Resize array if necessary
        CellMeasurementRecord* new_measurements = (CellMeasurementRecord*)realloc(manager->measurements, (manager->measurement_count + 1) * sizeof(CellMeasurementRecord));
