namespace XmlParserComponent
{
    public class XmlParserComponent : IXmlParserComponent
    {
        private readonly ConcurrentDictionary<string, XmlDocument> _xmlCache = new ConcurrentDictionary<string, XmlDocument>();
        private readonly HttpClient _httpClient = new HttpClient();
        private readonly S3Client _s3Client = new S3Client();
        private readonly string _awsSsmParameterStoreRegion;
        private readonly string _awsSsmParameterStoreName;

        public XmlParserComponent(string awsSsmParameterStoreRegion, string awsSsmParameterStoreName)
        {
            _awsSsmParameterStoreRegion = awsSsmParameterStoreRegion;
            _awsSsmParameterStoreName = awsSsmParameterStoreName;
        }

        public async Task<XmlDocument> GetXmlDocumentAsync(string xmlPath)
        {
            if (string.IsNullOrEmpty(xmlPath))
                throw new ArgumentException("Invalid XML path");

            string cachedXmlContent = _xmlCache.GetOrAdd(xmlPath, _ => LoadXmlDocumentFromS3Async(xmlPath).Result);

            return new XmlDocument(cachedXmlContent);
        }

        private async Task<string> LoadXmlDocumentFromS3Async(string xmlPath)
        {
            try
            {
                GetObjectResponse objectResponse = await _s3Client.GetObjectAsync(_awsSsmParameterStoreRegion, xmlPath);

                using (MemoryStream memoryStream = new MemoryStream())
                {
                    await objectResponse.ResponseInputStream.CopyToAsync(memoryStream);
                    memoryStream.Position = 0;
                    return await new StreamReader(memoryStream).ReadToEndAsync();
                }
            }
            catch (Exception ex)
            {
                // Handle exceptions and log error
                Console.WriteLine($"Error loading XML document: {ex.Message}");
            }

            return null;
        }
    }
}
