// Define UEConnectionStatus structure
typedef struct {
    int id;
    char status[16];
} UEConnectionStatus;

// Define a dynamic collection of UEConnectionStatus structures
typedef struct {
    UEConnectionStatus* connections;
    size_t capacity;
    pthread_mutex_t lock;
    size_t size;
    time_t ttl;
} ConnectionCollection;

// Initialize the connection collection with a given TTL value
void connection_collection_init(ConnectionCollection* cc, size_t capacity, time_t ttl) {
    cc->connections = (UEConnectionStatus*)malloc(capacity * sizeof(UEConnectionStatus));
    cc->capacity = capacity;
    pthread_mutex_init(&cc->lock, NULL);
    cc->size = 0;
    cc->ttl = ttl;
}

// Add a new UEConnectionStatus to the collection
void connection_collection_add(ConnectionCollection* cc, UEConnectionStatus status) {
    pthread_mutex_lock(&cc->lock);

    if (cc->size >= cc->capacity) {
        // Evict outdated entries based on TTL value
        size_t i = 0;
        for (; i < cc->size; i++) {
            if (time(NULL) - status.id > cc->ttl) {
                break;
            }
        }
        memmove(cc->connections, &cc->connections[i], sizeof(UEConnectionStatus) * (cc->size - i));
        cc->size -= i;
    }

    // Add the new connection
    memcpy(&cc->connections[cc->size++], &status, sizeof(UEConnectionStatus));

    pthread_mutex_unlock(&cc->lock);
}

// Update a UEConnectionStatus in the collection
void connection_collection_update(ConnectionCollection* cc, int id, char status[]) {
    pthread_mutex_lock(&cc->lock);

    // Find and update the corresponding connection
    size_t i = 0;
    for (; i < cc->size; i++) {
        if (cc->connections[i].id == id) {
            memcpy(cc->connections[i].status, status, sizeof(char) * 16);
            break;
        }
    }

    pthread_mutex_unlock(&cc->lock);
}

// Fetch a UEConnectionStatus from the collection
UEConnectionStatus connection_collection_get(ConnectionCollection* cc, int id) {
    pthread_mutex_lock(&cc->lock);

    // Find and return the corresponding connection
    size_t i = 0;
    for (; i < cc->size; i++) {
        if (cc->connections[i].id == id) {
            UEConnectionStatus status = cc->connections[i];
            pthread_mutex_unlock(&cc->lock);
            return status;
        }
    }

    // Connection not found
    pthread_mutex_unlock(&cc->lock);
    return (UEConnectionStatus){0};
}

