// Define the structure to represent UE Connection Status
typedef struct {
    int ue_id;
    char ip_addr[16];
    int latency;
} UEConnectionStatus;

// Define a dynamic array to store UE connection status
typedef struct {
    UEConnectionStatus* connections;
    int size;
    int capacity;
    pthread_mutex_t mutex;
} UEConnections;

// Function to initialize UEConnections structure
UEConnections* ue_connections_init(int initial_capacity) {
    UEConnections* connections = (UEConnections*)malloc(sizeof(UEConnections));
    connections->size = 0;
    connections->capacity = initial_capacity;
    connections->connections = (UEConnectionStatus*)calloc(initial_capacity, sizeof(UEConnectionStatus));
    pthread_mutex_init(&connections->mutex, NULL);
    return connections;
}

// Function to add a new UE connection status
void ue_connections_add(UEConnections* connections, int ue_id, char* ip_addr, int latency) {
    pthread_mutex_lock(&connections->mutex);

    if (connections->size >= connections->capacity) {
        // Adaptive resizing strategy: double the capacity when full
        connections->capacity *= 2;
        connections->connections = (UEConnectionStatus*)realloc(connections->connections, sizeof(UEConnectionStatus) * connections->capacity);
    }

    UEConnectionStatus new_connection = {ue_id, ip_addr, latency};
    connections->connections[connections->size] = new_connection;
    connections->size++;

    pthread_mutex_unlock(&connections->mutex);
}

// Function to remove a UE connection status
void ue_connections_remove(UEConnections* connections, int ue_id) {
    pthread_mutex_lock(&connections->mutex);

    for (int i = 0; i < connections->size; i++) {
        if (connections->connections[i].ue_id == ue_id) {
            // Shift elements to fill the gap
            UEConnectionStatus* temp = (UEConnectionStatus*)malloc(sizeof(UEConnectionStatus) * (connections->size - 1));
            memcpy(temp, &connections->connections[0], sizeof(UEConnectionStatus) * i);
            memcpy(&temp[i], &connections->connections[i+1], sizeof(UEConnectionStatus) * (connections->size - i - 1));
            free(connections->connections);
            connections->connections = temp;
            connections->size--;
            break;
        }
    }

    pthread_mutex_unlock(&connections->mutex);
}

// Function to check if UE connection status exists
int ue_connections_contains(UEConnections* connections, int ue_id) {
    pthread_mutex_lock(&connections->mutex);

    for (int i = 0; i < connections->size; i++) {
        if (connections->connections[i].ue_id == ue_id)
            return 1;
    }

    pthread_mutex_unlock(&connections->mutex);
    return 0;
}

// Function to integrate with external cloud-based data source
void update_ue_connections(UEConnections* connections) {
    // Connect to the external data source and fetch updated UE connection statuses
    // ...
}

