typedef struct {
    UEConnectionStatus* entries;
    size_t capacity, size;
    pthread_mutex_t lock;
} UEConnectionStatusCollection;

// Initialize the dynamic collection
UEConnectionStatusCollection* ue_collection_init(size_t capacity) {
    UEConnectionStatusCollection* collection = (UEConnectionStatusCollection*)malloc(sizeof(UEConnectionStatusCollection));
    collection->entries = (UEConnectionStatus*)calloc(capacity, sizeof(UEConnectionStatus));
    collection->capacity = capacity;
    collection->size = 0;
    pthread_mutex_init(&collection->lock, NULL);
    return collection;
}

// Add a UEConnectionStatus entry to the dynamic collection
void ue_collection_add_entry(UEConnectionStatusCollection* collection, UEConnectionStatus entry) {
    pthread_mutex_lock(&collection->lock);
    if (collection->size == collection->capacity) {
        // Reallocate with increased capacity if necessary
        size_t new_capacity = collection->capacity * 2;
        UEConnectionStatus** new_entries = (UEConnectionStatus**)realloc(collection->entries, new_capacity * sizeof(UEConnectionStatus));
        collection->entries = new_entries;
        collection->capacity = new_capacity;
    }
    collection->entries[collection->size] = entry;
    collection->size++;
    pthread_mutex_unlock(&collection->lock);
}

