    UEConnectionPool* pool = (UEConnectionPool*)malloc(sizeof(UEConnectionPool));
    pool->connections = (UEConnectionStatus*)calloc(initial_capacity, sizeof(UEConnectionStatus));
    pthread_mutex_init(&pool->lock, NULL);
    pool->capacity = initial_capacity;
