// Add a new UEConnectionStatus entry to the pool
void ue_connection_pool_add_entry(UEConnectionPool* pool, UEConnectionStatus* connection) {
    pthread_mutex_lock(&pool->lock);
    if (pool->count >= pool->capacity) {
        // Reallocate the connections array with double the capacity
        size_t new_capacity = pool->capacity * 2;
        UEConnectionStatus** new_connections = (UEConnectionStatus**)realloc(pool->connections, new_capacity * sizeof(UEConnectionStatus));
        pool->connections = new_connections;
        pool->capacity = new_capacity;
    }
    memcpy(&pool->connections[pool->count], connection, sizeof(UEConnectionStatus));
    pool->count++;
    pthread_mutex_unlock(&pool->lock);
}

// Remove a UEConnectionStatus entry from the pool
void ue_connection_pool_remove_entry(UEConnectionPool* pool, int id) {
    pthread_mutex_lock(&pool->lock);
    for (int i = 0; i < pool->count; i++) {
        if (pool->connections[i].id == id) {
            // Shift all entries down to fill the gap
            memmove(&pool->connections[i], &pool->connections[i + 1], sizeof(UEConnectionStatus) * (pool->count - i - 1));
            pool->count--;
            break;
