// Function to generate random NFAPI structures
std::vector<NFAPI_CRC_INDICATION_PDU_T> generateNFAPI(int numStructures) {
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<int> RX_UE_INFORMATION_TAG_dist(0, 255);
    std::uniform_int_distribution<int> RNTI_dist(1, 65535);
    std::uniform_int_distribution<int> CRC_INDICATION_REL8_TAG_dist(0, 255);
    std::bernoulli_distribution CRCFLAG_dist;

    std::vector<NFAPI_CRC_INDICATION_PDU_T> nfaPiStructures;
    for (int i = 0; i < numStructures; ++i) {
        NFAPI_CRC_INDICATION_PDU_T structure;
        structure.RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG_dist(gen);
        structure.RNTI = RNTI_dist(gen);
        structure.CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG_dist(gen);
        structure.CRCFLAG = CRCFLAG_dist(gen);

        nfaPiStructures.push_back(structure);
    }

