// Define the collection of UE connection statuses
typedef struct {
    UEConnectionStatus *entries;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} UEConnectionStatusCollection;

// Function to initialize a UE connection status collection
UEConnectionStatusCollection* ue_connection_status_collection_init(size_t initial_capacity) {
    UEConnectionStatusCollection *collection = malloc(sizeof(UEConnectionStatusCollection));
    collection->entries = malloc(initial_capacity * sizeof(UEConnectionStatus));
    collection->capacity = initial_capacity;
    collection->size = 0;
    pthread_mutex_init(&collection->lock, NULL);
    return collection;
}

// Function to add a new UE connection status entry
void ue_connection_status_collection_add_entry(UEConnectionStatusCollection *collection, UEConnectionStatus *entry) {
    pthread_mutex_lock(&collection->lock);
    if (collection->size >= collection->capacity) {
        // Evict outdated entries based on TTL value
        size_t i = 0;
        for (; i < collection->size; i++) {
            if (time(NULL) - entry[i].last_update > 300) { // 5-minute TTL
                free(entry[i]);
                break;
            }
        }
        UEConnectionStatus *new_entries = malloc((collection->capacity + 1) * sizeof(UEConnectionStatus));
        for (int j = i; j < collection->size; j++) {
            new_entries[j] = entry[i];
            i++;
        }
        free(entry);
        entry = new_entries;
        collection->capacity += 1;
    }
    if (collection->size < collection->capacity) {
        entry[collection->size].user_id = entry->user_id;
        strcpy(entry[collection->size].imei, entry->imei);
        entry[collection->size].signal_strength = entry->signal_strength;
        entry[collection->size].last_update = time(NULL);
    }
    collection->size++;
    pthread_mutex_unlock(&collection->lock);
}

// Function to remove a UE connection status entry
void ue_connection_status_collection_remove_entry(UEConnectionStatusCollection *collection, int user_id) {
    pthread_mutex_lock(&collection->lock);
    size_t i;
    for (i = 0; i < collection->size; i++) {
        if (entry[i].user_id == user_id) {
            free(entry[i]);
            break;
        }
    }
    if (i < collection->size) {
        UEConnectionStatus *new_entries = malloc((collection->size - 1) * sizeof(UEConnectionStatus));
        for (int j = i; j < collection->size - 1; j++) {
            new_entries[j] = entry[i + 1];
        }
        free(entry);
        entry = new_entries;
        collection->size--;
    }
    pthread_mutex_unlock(&collection->lock);
}

// Function to get a UE connection status entry
UEConnectionStatus* ue_connection_status_collection_get_entry(UEConnectionStatusCollection *collection, int user_id) {
    pthread_mutex_lock(&collection->lock);
    size_t i;
    for (i = 0; i < collection->size; i++) {
        if (entry[i].user_id == user_id) {
            UEConnectionStatus *entry_copy = malloc(sizeof(UEConnectionStatus));
            entry_copy->user_id = entry[i].user_id;
            strcpy(entry_copy->imei, entry[i].imei);
            entry_copy->signal_strength = entry[i].signal_strength;
            entry_copy->last_update = entry[i].last_update;
            pthread_mutex_unlock(&collection->lock);
            return entry_copy;
        }
    }
    pthread_mutex_unlock(&collection->lock);
    return NULL;
}

