typedef struct {
    size_t capacity;
    size_t size;
    UEConnectionStatus** connections;
    pthread_mutex_t lock;
    pthread_cond_t cond;
} UEConnectionCollection;

// Function to initialize the UE connection collection
UEConnectionCollection* ue_connection_collection_init(size_t initial_capacity) {
    UEConnectionCollection* collection = (UEConnectionCollection*)malloc(sizeof(UEConnectionCollection));
    collection->capacity = initial_capacity;
    collection->size = 0;
    collection->connections = (UEConnectionStatus**)calloc(initial_capacity, sizeof(UEConnectionStatus*));
    pthread_mutex_init(&collection->lock, NULL);
    pthread_cond_init(&collection->cond, NULL);
    return collection;
}

// Function to add a UE connection status to the collection
int ue_connection_collection_add(UEConnectionCollection* collection, UEConnectionStatus* connection) {
    pthread_mutex_lock(&collection->lock);

    // Check if there is available space in the collection
    if (collection->size >= collection->capacity) {
        size_t new_capacity = collection->capacity * 2;
        UEConnectionStatus** new_connections = (UEConnectionStatus**)realloc(collection->connections, new_capacity * sizeof(UEConnectionStatus*));
        pthread_mutex_unlock(&collection->lock);

        // Initialize the new connections array
        for (size_t i = 0; i < collection->capacity; i++) {
            new_connections[i] = NULL;
        }

        // Update the collection's capacity and connections array
        collection->connections = new_connections;
        collection->capacity = new_capacity;
    }

    // Add the new connection to the collection
    if (collection->size < collection->capacity) {
        collection->connections[collection->size] = connection;
        collection->size++;
    } else {
        pthread_cond_signal(&collection->cond);
    }

    pthread_mutex_unlock(&collection->lock);

    return 0;
}

// Function to remove a UE connection status from the collection
int ue_connection_collection_remove(UEConnectionCollection* collection, int id) {
    pthread_mutex_lock(&collection->lock);

    // Search for the connection with the given ID in the collection
    size_t i = 0;
    while (i < collection->size) {
        if (collection->connections[i]->id == id) {
            UEConnectionStatus* old_connection = collection->connections[i];

            // Shift all connections after the removed one down by one position
            for (size_t j = i; j < collection->size - 1; j++) {
                collection->connections[j] = collection->connections[j + 1];
            }

            // Remove the last connection in the array
            free(collection->connections[collection->size - 1]);
            collection->connections[collection->size - 1] = NULL;

            // Decrement the size of the collection
            collection->size--;

            // Wake up any thread waiting for a new connection
            pthread_cond_signal(&collection->cond);

            free(old_connection);
            break;
        }

        i++;
    }

    pthread_mutex_unlock(&collection->lock);

    return 0;
}

// Function to get the UE connection status with the given ID from the collection
UEConnectionStatus* ue_connection_collection_get(UEConnectionCollection* collection, int id) {
    pthread_mutex_lock(&collection->lock);

    // Search for the connection with the given ID in the collection
    size_t i = 0;
    while (i < collection->size) {
        if (collection->connections[i]->id == id) {
            UEConnectionStatus* connection = collection->connections[i];

            pthread_mutex_unlock(&collection->lock);

            return connection;
        }

        i++;
    }

    pthread_mutex_unlock(&collection->lock);

    return NULL;
}

// Function to free the UE connection collection
void ue_connection_collection_free(UEConnectionCollection* collection) {
    // Free each connection in the collection
    for (size_t i = 0; i < collection->size; i++) {
        free(collection->connections[i]);
    }

    // Free the connections array
    free(collection->connections);

    // Destroy the lock and condition variables
    pthread_mutex_destroy(&collection->lock);
    pthread_cond_destroy(&collection->cond);

    // Free the collection itself
    free(collection);
}

// Function to periodically update connection statuses from external services
void ue_connection_collection_update(UEConnectionCollection* collection) {
    // Call external service API or database query to retrieve updated connection statuses

    // Update each connection in the collection with the retrieved information
    for (size_t i = 0; i < collection->size; i++) {
        UEConnectionStatus* connection = collection->connections[i];

        // Update the connection status based on the received data

        // Store the updated connection in the collection
        ue_connection_collection_add(collection, connection);
    }
}

