**UEConnectionManager Library in C:**
```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int id;
    char* status;
} UEConnectionStatus;

struct {
    pthread_mutex_t lock;
    UEConnectionStatus** connections;
    size_t capacity;
    size_t count;
} ue_connection_manager = {
    .lock = PTHREAD_MUTEX_INITIALIZER,
    .connections = NULL,
    .capacity = 0,
    .count = 0
};

void ue_add_connection(UEConnectionStatus* connection) {
    pthread_mutex_lock(&ue_connection_manager.lock);
    if (ue_connection_manager.count >= ue_connection_manager.capacity) {
        // resize connections array
        size_t new_capacity = ue_connection_manager.capacity * 2;
        UEConnectionStatus** new_connections = realloc(
            ue_connection_manager.connections,
            sizeof(UEConnectionStatus*) * new_capacity
        );
        ue_connection_manager.connections = new_connections;
        ue_connection_manager.capacity = new_capacity;
    }
    // add connection to end of array
    ue_connection_manager.connections[ue_connection_manager.count++] = connection;
    pthread_mutex_unlock(&ue_connection_manager.lock);
}

void ue_remove_stale_connections(size_t ttl) {
    pthread_mutex_lock(&ue_connection_manager.lock);
    for (size_t i = 0; i < ue_connection_manager.count; i++) {
        UEConnectionStatus* connection = ue_connection_manager.connections[i];
        if (connection->status == NULL || connection->id == 0) {
            // stale connection, remove it
            memmove(&ue_connection_manager.connections[i], &ue_connection_manager.connections[i + 1], sizeof(UEConnectionStatus*) * (ue_connection_manager.count - i - 1));
            ue_connection_manager.count--;
        } else if (ttl <= time(NULL) - connection->timestamp) {
            // stale connection, remove it
            memmove(&ue_connection_manager.connections[i], &ue_connection_manager.connections[i + 1], sizeof(UEConnectionStatus*) * (ue_connection_manager.count - i - 1));
            ue_connection_manager.count--;
        }
    }
    pthread_mutex_unlock(&ue_connection_manager.lock);
}

