        printf("%02x", md5[i]);
    }
    printf("\n");
}

// Example usage
int main() {
    // Initialize a new ConnectionManager instance with an initial capacity of 8 and update callback function
    ConnectionManager *manager = connection_manager_init(8, (void (*)(UEConnectionStatus*))update_status_callback);

