```cpp
#include <mutex>
#include <condition_variable>
#include <thread>
#include <vector>
#include <unordered_map>
#include <functional>

class UserSession {
public:
    std::string username;
    std::string sessionID;
    long lastActivity;

    UserSession(const std::string& username, const std::string& sessionID, long lastActivity) 
        : username(username), sessionID(sessionID), lastActivity(lastActivity) {}
};

class SessionManager {
public:
    static constexpr int DEFAULT_SESSION_EXPIRATION_GRACE_PERIOD = 30; // seconds

    class SessionExpirationHandler {
    public:
        virtual ~SessionExpirationHandler() {}
        virtual void handleExpiredSession(const std::string& sessionID) = 0;
    };

private:
    std::mutex mtx_;
    std::condition_variable cv_;
    std::unordered_map<std::string, UserSession> sessions_;
    std::vector<SessionExpirationHandler*> expirationHandlers_;

public:
    SessionManager() {}

    void addSession(const UserSession& session) {
        std::lock_guard<std::mutex> lock(mtx_);
        sessions_[session.sessionID] = session;
    }

    void removeSession(const std::string& sessionID) {
        std::lock_guard<std::mutex> lock(mtx_);
        auto it = sessions_.find(sessionID);
        if (it != sessions_.end()) {
            sessions_.erase(it);
        }
    }

    bool hasSession(const std::string& sessionID) const {
        std::unique_lock<std::mutex> lock(mtx_);
        return sessions_.count(sessionID) > 0;
    }

    void expireSessions() {
        std::lock_guard<std::mutex> lock(mtx_);
        for (auto& pair : sessions_) {
            if ((time(nullptr) - pair.second.lastActivity) >= DEFAULT_SESSION_EXPIRATION_GRACE_PERIOD) {
                // Handle expired session
                for (const auto& handler : expirationHandlers_) {
                    handler->handleExpiredSession(pair.first);
                }
                removeSession(pair.first);
            }
        }
    }

    void registerExpirationHandler(SessionExpirationHandler* handler) {
        std::lock_guard<std::mutex> lock(mtx_);
        expirationHandlers_.push_back(handler);
    }
};

// Semaphore implementation
#include <semaphore.h>

sem_t createSemaphore(int initial_value) {
    sem_t semaphore;
    if (sem_init(&semaphore, 0, initial_value) == -1) {
        return nullptr;
    }
    return &semaphore;
}

void deleteSemaphore(sem_t* semaphore) {
    sem_destroy(*semaphore);
}
```

