// Define the structure to hold connection status information
typedef struct {
    int id;
    char* status;
} UEConnectionStatus;

// Define the type of list node
typedef struct _ListNode {
    UEConnectionStatus* data;
    struct _ListNode* next;
} ListNode;

// Define the list structure
typedef struct {
    ListNode* head;
    pthread_mutex_t lock;
    unsigned long size;
} ConnectionList;

// Function to create a new connection status node
ListNode* newNode(UEConnectionStatus* data) {
    ListNode* node = (ListNode*)malloc(sizeof(ListNode));
    node->data = data;
    node->next = NULL;
    return node;
}

// Function to add an element to the end of the list
void listAdd(ConnectionList* list, UEConnectionStatus* data) {
    ListNode* node = newNode(data);
    if(list->head == NULL) {
        list->head = node;
    } else {
        ListNode* current = list->head;
        while(current->next != NULL) {
            current = current->next;
        }
        current->next = node;
    }
    list->size++;
}

// Function to remove an element from the list
void listRemove(ConnectionList* list, UEConnectionStatus* data) {
    if(list->head == NULL) return;

    if(list->head->data == data) {
        ListNode* temp = list->head;
        list->head = list->head->next;
        free(temp);
        list->size--;
        return;
    }

    ListNode* current = list->head;
    while(current->next != NULL) {
        if(current->next->data == data) {
            ListNode* temp = current->next;
            current->next = current->next->next;
            free(temp);
            list->size--;
            return;
        }
        current = current->next;
    }
}

// Function to print the connection status list
void printList(ConnectionList* list) {
    ListNode* current = list->head;
    while(current != NULL) {
        printf("%d - %s\n", current->data->id, current->data->status);
        current = current->next;
    }
}

int main() {
    ConnectionList* list = (ConnectionList*)malloc(sizeof(ConnectionList));
    pthread_mutex_init(&list->lock, NULL);

    UEConnectionStatus* data1 = (UEConnectionStatus*)malloc(sizeof(UEConnectionStatus));
    data1->id = 1;
    data1->status = "Connected";

    UEConnectionStatus* data2 = (UEConnectionStatus*)malloc(sizeof(UEConnectionStatus));
    data2->id = 2;
    data2->status = "Disconnected";

    listAdd(list, data1);
    listAdd(list, data2);

    printList(list);

    return 0;
}
