#include <iostream>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <map>
#include <unordered_map>
#include <atomic>

// Caching strategy class to prioritize fresh data over volume
class Cache {
public:
    std::mutex mtx;
    std::condition_variable cv;
    std::atomic<std::chrono::time_point<std::chrono::system_clock>> last_update;
    std::map<std::string, std::pair<int, std::chrono::time_point<std::chrono::system_clock>>> cache;

    void add(const std::string& key, int value) {
        std::unique_lock<std::mutex> lock(mtx);
        auto it = cache.find(key);
        if (it == cache.end()) {
            cache[key] = {value, last_update.load()};
        } else {
            it->second.first = value;
            it->second.second = last_update.load();
        }
    }

