        std::vector<std::thread> threads;
        for (int i = 0; i < numThreads; ++i) {
            threads.emplace_back([this, &fileNames, i]() {
                int startRecordIndex = i * numRecordsPerThread;
                int endRecordIndex = (i + 1) * numRecordsPerThread;
