#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the structure to represent UE connection status
typedef struct {
    int status_code;
    char* status_message;
} UEConnectionStatus;

// Define a dynamically expanding array of UEConnectionStatus structures
typedef struct {
    UEConnectionStatus** connections;
    int size;
    int capacity;
    pthread_mutex_t mutex;
} UEConnections;

// Initialize the dynamic array with default capacity and size
UEConnections* ue_connections_init(int initial_capacity) {
    UEConnections* connections = malloc(sizeof(UEConnections));
    connections->connections = malloc(initial_capacity * sizeof(UEConnectionStatus*));
    connections->size = 0;
    connections->capacity = initial_capacity;
    pthread_mutex_init(&connections->mutex, NULL);
    return connections;
}

// Add a new connection status to the dynamic array
void ue_connections_add(UEConnections* connections, UEConnectionStatus* status) {
    if (connections->size >= connections->capacity) {
        // Dynamically resize the array when it's full
        connections->capacity *= 2;
        connections->connections = realloc(connections->connections, connections->capacity * sizeof(UEConnectionStatus*));
    }
    connections->connections[connections->size++] = status;
}

// Get the largest integer from the dynamic array of connection statuses
int ue_connections_get_largest(UEConnections* connections) {
    int max = 0;
    for (int i = 0; i < connections->size; i++) {
        if (connections->connections[i]->status_code > max) {
            max = connections->connections[i]->status_code;
        }
    }
    return max;
}

// Read integers from standard input and store them in the dynamic array
void read_integers(UEConnections* connections) {
    int num;
    while (scanf("%d", &num) == 1) {
        UEConnectionStatus* status = malloc(sizeof(UEConnectionStatus));
        status->status_code = num;
        status->status_message = NULL;
        ue_connections_add(connections, status);
    }
}

int main() {
    // Initialize the dynamic array
    UEConnections* connections = ue_connections_init(16);

    // Read integers from standard input and store them in the dynamic array
    read_integers(connections);

    // Get the largest integer from the dynamic array of connection statuses
    int max = ue_connections_get_largest(connections);
    printf("Largest integer: %d\n", max);

    return 0;
}
