// Create a dynamic array of UEConnectionStatus structures
typedef struct {
    UEConnectionStatus* data;
    int size;
    int capacity;
    pthread_mutex_t lock;
} UEConnectionList;

UEConnectionList* ue_connection_list_init(int initial_capacity) {
    UEConnectionList* list = (UEConnectionList*)malloc(sizeof(UEConnectionList));
    list->data = (UEConnectionStatus*)malloc(initial_capacity * sizeof(UEConnectionStatus));
    list->size = 0;
    list->capacity = initial_capacity;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void ue_connection_list_add(UEConnectionList* list, UEConnectionStatus* connection) {
    pthread_mutex_lock(&list->lock);
    if (list->size == list->capacity) {
        // Resize the array when it's full
        int new_capacity = list->capacity * 2;
        UEConnectionStatus* new_data = (UEConnectionStatus*)malloc(new_capacity * sizeof(UEConnectionStatus));
        memcpy(new_data, list->data, list->size * sizeof(UEConnectionStatus));
        free(list->data);
        list->data = new_data;
        list->capacity = new_capacity;
    }
    list->data[list->size++] = *connection;
    pthread_mutex_unlock(&list->lock);
}

