}

// Function to add a UE connection
int ue_connection_collection_add(UEConnectionCollection* collection, int session_id, const char* ip_address, int port) {
    if (pthread_mutex_lock(&collection->lock)) return -1; // Lock the mutex

    if (collection->count >= collection->capacity) {
        // Resize the array if necessary
        size_t new_capacity = collection->capacity * 2;
        UEConnectionStatus* new_connections = (UEConnectionStatus*)realloc(collection->connections, new_capacity * sizeof(UEConnectionStatus));

        if (!new_connections) {
            pthread_mutex_unlock(&collection->lock);
            return -1; // Memory allocation failed
        }

        collection->connections = new_connections;
        collection->capacity = new_capacity;
    }

    UEConnectionStatus* new_connection = &collection->connections[collection->count++];
    new_connection->session_id = session_id;
    new_connection->ip_address = (char*)malloc(strlen(ip_address) + 1);
    strcpy(new_connection->ip_address, ip_address);
    new_connection->port = port;

    pthread_mutex_unlock(&collection->lock); // Unlock the mutex
    return 0; // Connection added successfully
}

// Function to remove a UE connection
int ue_connection_collection_remove(UEConnectionCollection* collection, int session_id) {
    if (pthread_mutex_lock(&collection->lock)) return -1; // Lock the mutex

    for (size_t i = 0; i < collection->count; ++i) {
        if (collection->connections[i].session_id == session_id) {
            free(collection->connections[i].ip_address); // Free the memory
            memmove(&collection->connections[i], &collection->connections[i + 1], (collection->count - i - 1) * sizeof(UEConnectionStatus));
            collection->count--;
            break;
        }
    }

    pthread_mutex_unlock(&collection->lock); // Unlock the mutex
    return 0; // Connection removed successfully
}

// Function to print the UE connection collection
void ue_connection_collection_print(UEConnectionCollection* collection) {
    if (pthread_mutex_lock(&collection->lock)) return; // Lock the mutex

    for (size_t i = 0; i < collection->count; ++i) {
        printf("Session ID: %d, IP Address: %s, Port: %d\n", 
               collection->connections[i].session_id, 
               collection->connections[i].ip_address, 
               collection->connections[i].port);
    }

    pthread_mutex_unlock(&collection->lock); // Unlock the mutex
}

// Function to free the UE connection collection
void ue_connection_collection_free(UEConnectionCollection* collection) {
    for (size_t i = 0; i < collection->count; ++i) {
        free(collection->connections[i].ip_address); // Free the memory
    }

    free(collection->connections);
    pthread_mutex_destroy(&collection->lock);
    pthread_cond_destroy(&collection->cond);
    free(collection);
}

int main() {
    UEConnectionCollection* collection = ue_connection_collection_init(5);
    int session_id;
    const char* ip_address;
    int port;

    // Add some connections
    session_id = 1;
    ip_address = "192.168.0.100";
    port = 8080;
    if (ue_connection_collection_add(collection, session_id, ip_address, port) == -1) {
        printf("Error adding connection.\n");
        return -1;
    }

    session_id = 2;
    ip_address = "192.168.0.101";
    port = 8081;
    if (ue_connection_collection_add(collection, session_id, ip_address, port) == -1) {
        printf("Error adding connection.\n");
        return -1;
    }

    // Print the connections
    ue_connection_collection_print(collection);

    // Remove a connection
    session_id = 1;
    if (ue_connection_collection_remove(collection, session_id) == -1) {
        printf("Error removing connection.\n");
        return -1;
    }

    // Print the remaining connections
    ue_connection_collection_print(collection);

    // Free the collection
    ue_connection_collection_free(collection);
}

// Function to check for UE connection status updates from an external REST API
void check_ue_connection_status_updates() {

}
