class IoTTelemetryManager {
public:
    IoTTelemetryManager();
    ~IoTTelemetryManager();

    void addDevice(const std::string& deviceId);
    void removeDevice(const std::string& deviceId);

    void sendTelemetryData(const std::string& deviceId, const std::string& data);

    std::string getDeviceData(const std::string& deviceId);

private:
    struct Device {
        std::string id;
        std::string data;
        int ttl = 60; // Default TTL in seconds
    };

    std::unordered_map<std::string, Device> devices;
    std::mutex deviceMutex;
    std::mutex dbMutex;

    void processTelemetryData();
    void evictStaleDevices();

    void connectToDatabase();
    void disconnectFromDatabase();

    void sendTelemetryDataToDatabase(const std::string& deviceId, const std::string& data);

    void getDeviceDataFromDatabase(const std::string& deviceId);
};

IoTTelemetryManager::~IoTTelemetryManager() {
    // Disconnect from database and release resources
}

IoTTelemetryManager::IoTTelemetryManager() {
    connectToDatabase();
}

void IoTTelemetryManager::addDevice(const std::string& deviceId) {
    deviceMutex.lock();
    devices[deviceId] = Device{deviceId, ""};
    deviceMutex.unlock();
}

void IoTTelemetryManager::removeDevice(const std::string& deviceId) {
    deviceMutex.lock();
    devices.erase(deviceId);
    deviceMutex.unlock();

    // Evict stale devices
    evictStaleDevices();
}

void IoTTelemetryManager::sendTelemetryData(const std::string& deviceId, const std::string& data) {
    deviceMutex.lock();
    if (devices.find(deviceId) != devices.end()) {
        devices[deviceId].data = data;
        devices[deviceId].ttl = 60; // Reset TTL to default
    }
    deviceMutex.unlock();

    // Send telemetry data to database
    sendTelemetryDataToDatabase(deviceId, data);
}

std::string IoTTelemetryManager::getDeviceData(const std::string& deviceId) {
    deviceMutex.lock();
    if (devices.find(deviceId) != devices.end()) {
        return devices[deviceId].data;
    }
    deviceMutex.unlock();

    // Get device data from database
    return getDeviceDataFromDatabase(deviceId);
}

void IoTTelemetryManager::processTelemetryData() {
    while (true) {
        // Process telemetry data for all devices
        for (auto& device : devices) {
            if (device.second.ttl > 0) {
                device.second.ttl--;
            } else {
                removeDevice(device.first);
            }
        }

        std::this_thread::sleep_for(std::chrono::seconds(1));
    }
}

void IoTTelemetryManager::evictStaleDevices() {
    // Evict devices with TTL <= 0
    for (auto it = devices.begin(); it != devices.end();) {
        if (it->second.ttl <= 0) {
            removeDevice(it->first);
            it = devices.erase(it);
        } else {
            ++it;
        }
    }
}

