// Define structure for UE Connection Status
typedef struct {
    int id;
    char* ip;
    int port;
    // Add other relevant fields as needed
} UEConnectionStatus;

// Define a dynamic collection of UEConnectionStatus structures
typedef struct {
    UEConnectionStatus** status_list;
    int size;
    int capacity;
    pthread_mutex_t lock;
    int ttl;
    int is_backup_api;
    char* backup_api_url;
    char* primary_api_url;
} UEConnectionManager;

// Function to create a new UEConnectionManager instance
UEConnectionManager* ue_connection_manager_create(int initial_capacity, int ttl) {
    UEConnectionManager* manager = (UEConnectionManager*)malloc(sizeof(UEConnectionManager));
    manager->status_list = (UEConnectionStatus**)malloc(initial_capacity * sizeof(UEConnectionStatus*));
    manager->size = 0;
    manager->capacity = initial_capacity;
    pthread_mutex_init(&manager->lock, NULL);
    manager->ttl = ttl;
    manager->is_backup_api = 0;
    manager->backup_api_url = NULL;
    manager->primary_api_url = NULL;
    return manager;
}

// Function to add a new UEConnectionStatus entry
int ue_connection_manager_add_entry(UEConnectionManager* manager, UEConnectionStatus* status) {
    pthread_mutex_lock(&manager->lock);
    if (manager->size >= manager->capacity) {
        // Resize the list when it's full
        int new_capacity = manager->capacity * 2;
        UEConnectionStatus** new_list = (UEConnectionStatus**)malloc(new_capacity * sizeof(UEConnectionStatus*));
        memcpy(new_list, manager->status_list, manager->capacity * sizeof(UEConnectionStatus*));
        free(manager->status_list);
        manager->status_list = new_list;
        manager->capacity = new_capacity;
    }
    // Add the new entry
    status->id = ++manager->size;
    manager->status_list[manager->size - 1] = status;
    pthread_mutex_unlock(&manager->lock);
    return 0;
}

// Function to remove an outdated UEConnectionStatus entry
int ue_connection_manager_remove_outdated_entry(UEConnectionManager* manager) {
    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < manager->size; i++) {
        if (manager->status_list[i]->ttl <= 0) {
            // Evict the outdated entry
            free(manager->status_list[i]);
            memmove(&manager->status_list[i], &manager->status_list[i + 1], (manager->size - i - 1) * sizeof(UEConnectionStatus*));
            manager->size--;
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return 0;
}

