#include <openssl/aes.h>
#include <openssl/camellia.h>
#include <openssl/md5.h>
#include <openssl/sha.h>
#include <openssl/rsa.h>
#include <openssl/ssl.h>

// Thread-safe structure to manage UE connection status
typedef struct {
    pthread_mutex_t lock;
    size_t size;
    UEConnectionStatus **connections;
} UEConnectionManager;

// Initialize the UE connection manager with a specified initial capacity
void ue_connection_manager_init(UEConnectionManager *manager, size_t initial_capacity) {
    manager->size = initial_capacity;
    manager->connections = malloc(initial_capacity * sizeof(UEConnectionStatus *));
    pthread_mutex_init(&manager->lock, NULL);
}

// Insert a new UE connection status into the manager
int ue_connection_manager_insert(UEConnectionManager *manager, UEConnectionStatus *connection) {
    // Resize if necessary
    if (manager->size <= manager->connections) {
        manager->size *= 2;
        manager->connections = realloc(manager->connections, manager->size * sizeof(UEConnectionStatus *));
    }

    // Insert the connection at the next available index
    int index = manager->size - 1;
    while (index > 0 && !manager->connections[index]) {
        index--;
    }
    manager->connections[index] = connection;

    pthread_mutex_lock(&manager->lock);
    return 0; // Success
}

// Evict outdated entries based on the TTL value
int ue_connection_manager_evict(UEConnectionManager *manager, time_t ttl) {
    size_t i;
    for (i = manager->size - 1; i > 0; i--) {
        UEConnectionStatus *connection = manager->connections[i];
        if (!connection || connection->timestamp + ttl < time(NULL)) {
            free(connection);
            memmove(&manager->connections[i], &manager->connections[i-1], (i-1)*sizeof(UEConnectionStatus *));
            manager->size--;
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return 0; // Success
}

