#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define a structure to hold UE connection status information
typedef struct {
    int id;
    char* status;
} UEConnectionStatus;

// Create a dynamic array of UE connections with adaptive resizing and eviction strategy
UEConnectionStatus** ueConnections = NULL;
int ueConnectionsSize = 0;
int ueConnectionsCapacity = 10;
pthread_mutex_t ueConnectionsMutex = PTHREAD_MUTEX_INITIALIZER;
int connectionIdCounter = 0;

// Function to add a new UE connection
void addUEConnection(char* status) {
    pthread_mutex_lock(&ueConnectionsMutex);

    if (ueConnectionsSize == ueConnectionsCapacity) {
        // Resize the array when it's full
        UEConnectionStatus** tempArr = (UEConnectionStatus**)realloc(ueConnections, sizeof(UEConnectionStatus*) * (ueConnectionsCapacity * 2));
        ueConnections = tempArr;
        ueConnectionsCapacity *= 2;
    }

    UEConnectionStatus* connection = (UEConnectionStatus*)malloc(sizeof(UEConnectionStatus));
    connection->id = ++connectionIdCounter;
    connection->status = strdup(status);
    ueConnections[ueConnectionsSize++] = connection;

    pthread_mutex_unlock(&ueConnectionsMutex);
}

// Function to remove a UE connection
void removeUEConnection(int id) {
    pthread_mutex_lock(&ueConnectionsMutex);

    for (int i = 0; i < ueConnectionsSize; i++) {
        if (ueConnections[i]->id == id) {
            free(ueConnections[i]->status);
            free(ueConnections[i]);
            memmove(ueConnections + i, ueConnections + i + 1, sizeof(UEConnectionStatus*) * (ueConnectionsSize - i));
            ueConnectionsSize--;
            break;
        }
    }

    pthread_mutex_unlock(&ueConnectionsMutex);
}

// Function to get the status of a UE connection
char* getUEConnectionStatus(int id) {
    pthread_mutex_lock(&ueConnectionsMutex);

    for (int i = 0; i < ueConnectionsSize; i++) {
        if (ueConnections[i]->id == id) {
            char* status = strdup(ueConnections[i]->status);
            pthread_mutex_unlock(&ueConnectionsMutex);
            return status;
        }
    }

    pthread_mutex_unlock(&ueConnectionsMutex);
    return NULL;
}

// Function to update the status of a UE connection
void updateUEConnectionStatus(int id, char* status) {
    pthread_mutex_lock(&ueConnectionsMutex);

    for (int i = 0; i < ueConnectionsSize; i++) {
        if (ueConnections[i]->id == id) {
            free(ueConnections[i]->status);
            ueConnections[i]->status = strdup(status);
            break;
        }
    }

    pthread_mutex_unlock(&ueConnectionsMutex);
}

// Function to print the UE connection statuses
void printUEConnectionStatuses() {
    pthread_mutex_lock(&ueConnectionsMutex);

    for (int i = 0; i < ueConnectionsSize; i++) {
        printf("ID: %d, Status: %s\n", ueConnections[i]->id, ueConnections[i]->status);
    }

    pthread_mutex_unlock(&ueConnectionsMutex);
}

// Function to handle the command-line interface
void cli(int argc, char** argv) {
    if (argc == 1) {
        printf("UE Connection Manager CLI\n");
        printf("Available commands:\n");
        printf("add <status> - Add a new UE connection with the given status\n");
        printf("remove <id> - Remove a UE connection by its ID\n");
        printf("status <id> - Get the status of a UE connection by its ID\n");
        printf("update <id> <status> - Update the status of a UE connection by its ID\n");
        printf("list - List all UE connections and their statuses\n");
        return;
    }

    if (strcmp(argv[1], "add") == 0) {
        addUEConnection(argv[2]);
    } else if (strcmp(argv[1], "remove") == 0) {
        removeUEConnection(atoi(argv[2]));
    } else if (strcmp(argv[1], "status") == 0) {
        char* status = getUEConnectionStatus(atoi(argv[2]));
        printf("Status: %s\n", status);
        free(status);
    } else if (strcmp(argv[1], "update") == 0) {
        updateUEConnectionStatus(atoi(argv[2]), argv[3]);
    } else if (strcmp(argv[1], "list") == 0) {
        printUEConnectionStatuses();
    }
}

int main(int argc, char** argv) {
    // Initialize the UE connection array
    ueConnections = (UEConnectionStatus**)malloc(sizeof(UEConnectionStatus*) * ueConnectionsCapacity);

    while (1) {
        printf("UE Connection Manager CLI\n");
        printf("Enter a command: ");
        cli(argc, argv);
    }

    return 0;
}

