#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define structure to represent connection status
typedef struct {
    int id;
    char status[20];
} UEConnectionStatus;

// Define structure to represent connection manager data
typedef struct {
    UEConnectionStatus* connections;
    int num_connections;
    int capacity;
    int ttl; // Time-To-Live value
    pthread_mutex_t mutex;
} ConnectionManager;

// Initialize connection manager with given capacity and TTL
void init_connection_manager(ConnectionManager* cm, int capacity, int ttl) {
    cm->connections = (UEConnectionStatus*)malloc(capacity * sizeof(UEConnectionStatus));
    cm->num_connections = 0;
    cm->capacity = capacity;
    cm->ttl = ttl;
    pthread_mutex_init(&cm->mutex, NULL);
}

// Add a new connection status to the manager
void add_connection(ConnectionManager* cm, UEConnectionStatus* conn) {
    pthread_mutex_lock(&cm->mutex);
    if (cm->num_connections < cm->capacity) {
        cm->connections[cm->num_connections] = *conn;
        cm->num_connections++;
    } else {
        // Evict an old connection to make room for the new one
        int oldest_index = 0;
        for (int i = 1; i < cm->num_connections; i++) {
            if (cm->connections[i].id < cm->connections[oldest_index].id) {
                oldest_index = i;
            }
        }
        free(&cm->connections[oldest_index]);
        memmove(&cm->connections[oldest_index], &cm->connections[oldest_index + 1], sizeof(UEConnectionStatus*) * (cm->num_connections - oldest_index));
        cm->connections[--cm->num_connections] = *conn;
    }
    pthread_mutex_unlock(&cm->mutex);
}

// Remove a connection status from the manager
void remove_connection(ConnectionManager* cm, int id) {
    pthread_mutex_lock(&cm->mutex);
    for (int i = 0; i < cm->num_connections; i++) {
        if (cm->connections[i].id == id) {
            free(&cm->connections[i]);
            memmove(&cm->connections[i], &cm->connections[i + 1], sizeof(UEConnectionStatus*) * (cm->num_connections - i));
            cm->num_connections--;
            break;
        }
    }
    pthread_mutex_unlock(&cm->mutex);
}

// Update connection status from an external REST API
void update_connection_status(ConnectionManager* cm, UEConnectionStatus* conn) {
    // Implement API call logic here
    // For demonstration purposes, assume successful update
    add_connection(cm, conn);
}

int main() {
    ConnectionManager cm;
    init_connection_manager(&cm, 100, 300);

    while (1) {
        int id;
        char status[20];
        printf("Enter connection ID and status: ");
        scanf("%d %s", &id, status);
        UEConnectionStatus conn = {id, status};
        update_connection_status(&cm, &conn);
    }

    return 0;
}
