// Structure representing UE connection status
typedef struct {
    int offsets;
    int keys;
    int records;
} UEConnectionStatus;

// Dynamic collection of UE connection statuses
typedef struct {
    UEConnectionStatus* statuses;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} UEConnectionCollection;

// Initialize UE connection collection
UEConnectionCollection* ue_connection_collection_init(size_t initial_capacity) {
    UEConnectionCollection* collection = malloc(sizeof(UEConnectionCollection));
    collection->statuses = malloc(initial_capacity * sizeof(UEConnectionStatus));
    collection->capacity = initial_capacity;
    collection->size = 0;
    pthread_mutex_init(&collection->mutex, NULL);
    return collection;
}

// Add UE connection status to the collection
void ue_connection_collection_add_entry(UEConnectionCollection* collection, UEConnectionStatus entry) {
    if (collection->size >= collection->capacity) {
        // Resize the array when full
        size_t new_capacity = collection->capacity * 2;
        UEConnectionStatus* new_statuses = malloc(new_capacity * sizeof(UEConnectionStatus));
        memcpy(new_statuses, collection->statuses, collection->size * sizeof(UEConnectionStatus));
        free(collection->statuses);
        collection->statuses = new_statuses;
        collection->capacity = new_capacity;
    }
    pthread_mutex_lock(&collection->mutex);
    collection->statuses[collection->size] = entry;
    collection->size++;
    pthread_mutex_unlock(&collection->mutex);
}

// Get UE connection status from the collection
UEConnectionStatus* ue_connection_collection_get_entry(UEConnectionCollection* collection, size_t index) {
    pthread_mutex_lock(&collection->mutex);
    UEConnectionStatus* result = &collection->statuses[index];
    pthread_mutex_unlock(&collection->mutex);
    return result;
}

// Free UE connection collection
void ue_connection_collection_free(UEConnectionCollection* collection) {
    free(collection->statuses);
    free(collection);
}

