    // Constructor
    UEConnectionStatus(const std::string& conn_stat, int code) 
        : connection_status(conn_stat), status_code(code) {}
};

// Distributed shared memory system
class DMemorySystem {
private:
    sem_t memory_semaphore;
    std::mutex memory_mutex;

public:
    // Initialize the semaphore and mutex
    DMemorySystem() {
        if (sem_init(&memory_semaphore, 0, 1) != 0)
            std::cerr << "Error initializing semaphore!" << std::endl;
        memory_mutex = std::make_unique<std::mutex>();
    }

    ~DMemorySystem() {
        // Release the semaphore
        sem_destroy(&memory_semaphore);
    }

    void write_to_shared_memory(const UEConnectionStatus& conn_stat) {
        if (sem_wait(&memory_semaphore) != 0)
            std::cerr << "Error writing to shared memory!" << std::endl;

        // Perform operations on shared memory using the mutex
        *memory_mutex.lock() = conn_stat;

        sem_post(&memory_semaphore);
    }

    UEConnectionStatus read_from_shared_memory() {
        if (sem_wait(&memory_semaphore) != 0)
            std::cerr << "Error reading from shared memory!" << std::endl;

        // Perform operations on shared memory using the mutex
        UEConnectionStatus conn_stat = *memory_mutex.lock();

        sem_post(&memory_semaphore);
        return conn_stat;
    }
};

