#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

#define MAX_CONNECTIONS 1000
#define TTL 300 // Time-To-Live in seconds

typedef struct {
    int session_id;
    char* device_name;
    int status;
} UEConnectionStatus;

// Lock for concurrent access to the connection list
pthread_mutex_t connections_lock = PTHREAD_MUTEX_INITIALIZER;

// Dynamic array of UEConnectionStatus structures
UEConnectionStatus** connections = NULL;
int num_connections = 0;

void add_connection(UEConnectionStatus* connection) {
    pthread_mutex_lock(&connections_lock);

    // Resize the array if necessary
    if (num_connections >= MAX_CONNECTIONS) {
        MAX_CONNECTIONS *= 2;
        connections = realloc(connections, sizeof(UEConnectionStatus*) * MAX_CONNECTIONS);
    }

    connections[num_connections++] = connection;

    pthread_mutex_unlock(&connections_lock);
}

void remove_stale_connections() {
    int i = 0;
    pthread_mutex_lock(&connections_lock);

    for (i = 0; i < num_connections; i++) {
        if ((time(NULL) - connections[i]->timestamp) > TTL) {
            free(connections[i]);
            memmove(&connections[i], &connections[i+1], sizeof(UEConnectionStatus*) * (num_connections - i - 1));
            num_connections--;
            i--;
        }
    }

    pthread_mutex_unlock(&connections_lock);
}

int main() {
    // Initialize the connection list
    connections = malloc(sizeof(UEConnectionStatus*) * MAX_CONNECTIONS);

    return 0;
}
