#include <string.h>
#include <stdio.h>
#include <hashlib.h>

void md5_file_hash(const char* file_path) {
    FILE *file = fopen(file_path, "rb");
    if (file == NULL) {
        printf("Error opening file\n");
        return;
    }

    struct stat sb;
    fstat(fileno(file), &sb);

    unsigned char buffer[sb.st_size];
    size_t bytesRead = fread(buffer, 1, sb.st_size, file);
    fclose(file);

    MD5_CTX* md5_ctx = MD5_init();
    for (size_t i = 0; i < bytesRead; i += MD5_BLOCK_SIZE) {
        unsigned char block[MD5_BLOCK_SIZE];
        memcpy(block, buffer + i, MIN(bytesRead - i, MD5_BLOCK_SIZE));
        MD5_update(md5_ctx, block, MIN(bytesRead - i, MD5_BLOCK_SIZE));
    }
    MD5_finish(md5_ctx);

    printf("%x\n", MD5_final(md5_ctx));
}

