class UEConnectionStatus {
public:
    int64_t timestamp;
    std::string connection_status;

    UEConnectionStatus(int64_t _timestamp, const std::string& _connection_status) : 
        timestamp(_timestamp), connection_status(_connection_status) {}
};

class DynamicCollection {
private:
    std::mutex mtx;
    std::condition_variable cv;
    std::vector<UEConnectionStatus*> collection;

public:
    void add(const UEConnectionStatus* item) {
        std::unique_lock<std::mutex> lock(mtx);
        collection.push_back(item);
        lock.unlock();
        cv.notify_all();
    }

    UEConnectionStatus* get(int64_t timestamp) {
        std::unique_lock<std::mutex> lock(mtx);
        for (auto& item : collection) {
            if (item->timestamp == timestamp)
                return item;
        }
        return nullptr;
    }

    void resize(size_t capacity) {
        std::unique_lock<std::mutex> lock(mtx);
        if (collection.capacity() != capacity) {
            collection.resize(capacity);
            cv.notify_all();
        }
    }
};

class UEConnectionManager {
private:
    DynamicCollection connection_status_collection;

public:
    void update_connection_status(int64_t timestamp, const std::string& status) {
        auto item = new UEConnectionStatus(timestamp, status);
