// Function to count disjoint pairs using Union-Find data structure
int countDisjointPairs(std::vector<int> arr) {
    int n = arr.size();
    std::vector<int> parent(n);
    for (int i = 0; i < n; i++) parent[i] = i;

    // Function to find the root of a set using path compression
    int find(int x) {
        if (parent[x] != x)
            parent[x] = find(parent[x]);
        return parent[x];
    }

    // Function to union two sets using rank and path compression
    void unionSets(int x, int y) {
        int rootX = find(x);
        int rootY = find(y);

        if (rootX == rootY)
            return;

        parent[rootX] = rootY;
    }

    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            // Check if the elements are in different sets
            if (find(i) != find(j)) {
                unionSets(i, j);
                // Increment the count of disjoint pairs
                arr[i]++;
            }
        }
    }

    int count = 0;
    for (int i = 0; i < n; i++) count += arr[i];
    return count;
}

