void generateNFAPacketWithFSStateList(int* states, int num_states, struct FSA* pFsa) {
    // Initialize the state list
    NFAPI_CRC_INDICATION_PDU_T** state_list = (NFAPI_CRC_INDICATION_PDU_T**)malloc(num_states * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    for (int i = 0; i < num_states; i++) {
        state_list[i] = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }

    // Initialize the last state
    NFAPI_CRC_INDICATION_PDU_T* last_state = state_list[0];
    for (int i = 0; i < num_states; i++) {
        // Populate each state in the FSA
        state_list[i]->RX_UE_INFORMATION_TAG = pFsa->states[i].tag;
        state_list[i]->RNTI = pFsa->states[i].rnti;
        state_list[i]->CRCFLAG = rand() % 256; // Randomly generate CRC flag

        if (i < num_states - 1) {
            last_state->next = state_list[i + 1];
        }
        last_state = state_list[i];
    }

    // Free the memory
    for (int i = 0; i < num_states; i++) {
        free(state_list[i]);
    }
    free(state_list);
}
