// Initialize a new UEConnectionStatusCollection instance
UEConnectionStatusCollection* ue_collection_init(size_t initial_capacity) {
    UEConnectionStatusCollection* collection = (UEConnectionStatusCollection*)malloc(sizeof(UEConnectionStatusCollection));
    collection->connections = (UEConnectionStatus*)malloc(initial_capacity * sizeof(UEConnectionStatus));
    collection->capacity = initial_capacity;
    collection->size = 0;
    pthread_mutex_init(&collection->lock, NULL);
    return collection;
}

// Add a new UEConnectionStatus to the collection
void ue_collection_add(UEConnectionStatusCollection* collection, UEConnectionStatus connection) {
    pthread_mutex_lock(&collection->lock);
    if (collection->size >= collection->capacity) {
        // Reallocate with doubled capacity when necessary
        size_t new_capacity = collection->capacity * 2;
        UEConnectionStatus* new_connections = (UEConnectionStatus*)realloc(collection->connections, new_capacity * sizeof(UEConnectionStatus));
        collection->connections = new_connections;
        collection->capacity = new_capacity;
    }
    collection->connections[collection->size++] = connection;
    pthread_mutex_unlock(&collection->lock);
}

// Remove a UEConnectionStatus from the collection
void ue_collection_remove(UEConnectionStatusCollection* collection, int id) {
    pthread_mutex_lock(&collection->lock);
    for (int i = 0; i < collection->size; i++) {
        if (collection->connections[i].id == id) {
            // Shift remaining connections to fill the gap
            memmove(&collection->connections[i], &collection->connections[i + 1], (collection->size - i - 1) * sizeof(UEConnectionStatus));
