// Implement thread pool logic here
void CommandLineUtility::processFiles(const std::vector<std::string>& filenames) {
    for (const auto& filename : filenames) {
        FileMetadata file;
        file.filename = filename;

        // Fetch metadata from the RESTful API and cache it
