        for (int i = 0; i < cache_size; i++) {
            UEConnectionStatus* cached_ue_conn_status = &cache[i];
            if (cached_ue_conn_status->connection_id == ue_conn_status->connection_id) {
                // Update the cached connection status
                cached_ue_conn_status->status_code = ue_conn_status->status_code;
                return 1;
            }
        }
        return 0;
