// Function to create a new node
Node* create_node(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    Node *node = (Node*)malloc(sizeof(Node));
    node->pdu = pdu;
    node->prev = NULL;
    node->next = NULL;
    return node;
}

// Function to insert a new node at the beginning of the list
void insert_node_at_beginning(Node **head, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    Node *new_node = create_node(pdu);
    if (*head != NULL) {
        new_node->next = *head;
        (*head)->prev = new_node;
    }
    *head = new_node;
}

// Function to iterate over the list and print out the details of each NFAPI_CRC_INDICATION_PDU_T structure
void print_list(Node *head, FILE *output_file) {
    Node *current = head;
    while (current != NULL) {
        fprintf(output_file, "PDU ID: %d, UE Info Tag: %d, RNTI: %s\n",
                current->pdu->crc_ind_pdu_t_id,
                current->pdu->rx_ue_info_tag.rx_ue_info_tag,
                current->pdu->rx_ue_info_tag.rnti);
        current = current->next;
    }
}

// Function to iterate over the list and log any duplicate UE information tags
void detect_duplicates(Node *head) {
    Node *current = head;
    while (current != NULL) {
        RX_UE_INFORMATION_TAG rx_ue_info_tag = current->pdu->rx_ue_info_tag;
        Node *temp = current;
        while (temp->next != NULL) {
            if (!strcmp(temp->next->pdu->rx_ue_info_tag.rnti, rx_ue_info_tag.rnti)) {
                printf("Error: Duplicate UE information tag found. Skipping new node.\n");
                return;
            }
            temp = temp->next;
        }
        current = current->next;
    }
}

