    NFAPI_CRC_INDICATION_PDU_T* data;
    int size;
    int capacity;
    pthread_mutex_t lock;
} NFAPI_CRC_Indication_List;

// Function to create a new linked list
NFAPI_CRC_Indication_List* nfaapi_crc_indication_list_create() {
    NFAPI_CRC_Indication_List* list = (NFAPI_CRC_Indication_List*)malloc(sizeof(NFAPI_CRC_Indication_List));
    if (!list) return NULL;
    list->data = NULL;
    list->size = 0;
    list->capacity = 1;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

// Function to free a linked list
void nfaapi_crc_indication_list_free(NFAPI_CRC_Indication_List* list) {
    if (!list) return;
    for (int i = 0; i < list->size; i++) {
        free(list->data[i].RX_UE_INFORMATION_TAG);
    }
    free(list->data);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Function to append a new element to the linked list
int nfaapi_crc_indication_list_append(NFAPI_CRC_Indication_List* list, NFAPI_CRC_INDICATION_PDU_T* data) {
    if (!list || !data) return -1;
    pthread_mutex_lock(&list->lock);
    if (list->size >= list->capacity) {
        // Reallocate the array with double capacity
        list->data = realloc(list->data, sizeof(NFAPI_CRC_INDICATION_PDU_T*) * (list->capacity *= 2));
        for (int i = list->size; i < list->capacity; i++) {
            // Initialize new elements to NULL
            list->data[i] = NULL;
        }
    }
    list->data[list->size++] = data;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

// Function to serialize the linked list to a binary file
int nfaapi_crc_indication_list_serialize(NFAPI_CRC_Indication_List* list, const char* filename) {
    if (!list || !filename) return -1;
    FILE* file = fopen(filename, "wb");
    if (!file) return -1;
    for (int i = 0; i < list->size; i++) {
        fwrite(&list->data[i], sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
    }
    fclose(file);
    return 0;
}

// Function to deserialize the linked list from a binary file
int nfaapi_crc_indication_list_deserialize(NFAPI_CRC_Indication_List** list, const char* filename) {
    if (!list || !filename) return -1;
    FILE* file = fopen(filename, "rb");
    if (!file) return -1;
    *list = nfaapi_crc_indication_list_create();
    NFAPI_CRC_INDICATION_PDU_T temp;
    while (fread(&temp, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file)) {
        // Append the deserialized element to the linked list
        nfaapi_crc_indication_list_append(*list, &temp);
    }
    fclose(file);
    return 0;
}

// Function to print the contents of the linked list
void nfaapi_crc_indationation_list_print(NFAPI_CRC_Indationation_List* list) {
