void dlist_remove(DLinkedList* list, Node* node) {
    if (!node) return;
    if (node->prev != NULL) node->prev->next = node->next;
    else list->head = node->next;
    if (node->next != NULL) node->next->prev = node->prev;
    else list->tail = node->prev;
}

