        ILogger<UeConnectionStatusService> logger,
        IDocumentDBClient documentDbClient,
        ITimeSeriesDatabase timeSeriesDatabase,
        IMessageBroker messageBroker,
        IAnalyticsPlatform analyticsPlatform)
    {
        _logger = logger;
        _documentDbClient = documentDbClient;
        _timeSeriesDatabase = timeSeriesDatabase;
        _messageBroker = messageBroker;
        _analyticsPlatform = analyticsPlatform;
    }

    public async Task UpdateConnectionStatusAsync(UEConnectionStatus connectionStatus)
    {
        try
        {
            await _documentDbClient.UpdateDocumentAsync(connectionStatus);
            await _timeSeriesDatabase.UpdateDataPointAsync(connectionStatus);
            await _messageBroker.PublishMessageAsync(connectionStatus);
            await _analyticsPlatform.SendAnalyticsEventAsync(connectionStatus);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error updating UE connection status");
        }
    }

    public async Task<IList<UEConnectionStatus>> GetConnectionStatusesAsync()
    {
        try
        {
            return await _documentDbClient.GetDocumentsAsync<UEConnectionStatus>();
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error getting UE connection statuses");
            return new List<UEConnectionStatus>();
        }
    }

    public async Task PerformSchemaMigrationAsync()
    {
        try
        {
            await _documentDbClient.PerformSchemaMigrationAsync();
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error performing schema migration");
        }
    }
}

