// Define the payment gateway API
const paymentGateway = {
  processPayment: (amount) => new Promise((resolve, reject) => {
    // Simulate a delay for transaction processing
    setTimeout(() => {
      if (Math.random() < 0.5) {
        resolve({ success: true });
      } else {
        reject(new Error('Transaction failed'));
      }
    }, 1000);
  }),
  cancelPayment: (transactionId) => new Promise((resolve, reject) => {
    // Simulate a delay for transaction cancellation
    setTimeout(() => {
      if (Math.random() < 0.5) {
        resolve({ success: true });
      } else {
        reject(new Error('Transaction cancellation failed'));
      }
    }, 1000);
  }),
};

// Define the caching layer
const cache = {};

// Define the payment processing function
async function processPayment(amount, currency) {
  // Validate the amount and currency
  if (isNaN(parseFloat(amount))) {
    throw new Error('Invalid amount');
  }

  const transactionId = await paymentGateway.processPayment(amount);
  if (!transactionId.success) {
    throw new Error('Transaction failed');
  }

  // Store the transaction in the cache
  cache[transactionId] = { amount, currency };

  // Log the transaction for auditing purposes
  console.log(`Transaction ${transactionId} processed successfully`);
}

// Define the retry policy for payment processing
async function processPaymentRetry(amount, currency) {
  let attempts = 0;
  while (attempts < 3) {
    try {
      await processPayment(amount, currency);
      return;
    } catch (error) {
      if (error instanceof Error && error.message === 'Transaction failed') {
        attempts++;
        console.log(`Retrying transaction ${amount} in ${currency}`);
        await new Promise((resolve) => setTimeout(resolve, 2000));
      } else {
        throw error;
      }
    }
  }

  // Log the final failure
  console.error(`Transaction ${amount} in ${currency} failed after 3 attempts`);
}

// Define the payment cancellation function
async function cancelPayment(transactionId) {
  try {
    await paymentGateway.cancelPayment(transactionId);
    delete cache[transactionId];
    console.log(`Transaction ${transactionId} cancelled successfully`);
  } catch (error) {
    if (error instanceof Error && error.message === 'Transaction cancellation failed') {
      console.error(`Transaction ${transactionId} cancellation failed`);
    } else {
      throw error;
    }
  }
}

// Example usage
processPaymentRetry(100.00, 'USD');
cancelPayment('12345');
