// Define a struct to represent a UE connection status
typedef struct {
    int userId;
    int connectionStatus; // 0: disconnected, 1: connected
} UEConnectionStatus;

// Define the NetworkSessionManager structure
typedef struct {
    pthread_mutex_t lock; // Fine-grained locking mechanism
    UEConnectionStatus** connections; // Dynamic array of connection statuses
    size_t capacity; // Current capacity of the connections array
    size_t size; // Actual number of connections
} NetworkSessionManager;

// Function to create a new NetworkSessionManager instance
NetworkSessionManager* network_session_manager_create() {
    NetworkSessionManager* manager = (NetworkSessionManager*)malloc(sizeof(NetworkSessionManager));
    if (!manager) return NULL;
    manager->connections = NULL;
    manager->capacity = 0;
    manager->size = 0;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

// Function to add a new UE connection status
int network_session_manager_add(NetworkSessionManager* manager, int userId, int connectionStatus) {
    // Check if the connections array needs to be resized
    if (manager->size >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        UEConnectionStatus** new_connections = (UEConnectionStatus**)realloc(manager->connections, new_capacity * sizeof(UEConnectionStatus*));
        if (!new_connections) return -1; // Memory allocation failed
        manager->connections = new_connections;
        manager->capacity = new_capacity;
    }
    // Add the new connection status
    UEConnectionStatus** new_connection = (UEConnectionStatus**)malloc(sizeof(UEConnectionStatus*));
    *new_connection = (UEConnectionStatus*)malloc(sizeof(UEConnectionStatus));
    (*new_connection)->userId = userId;
    (*new_connection)->connectionStatus = connectionStatus;
    pthread_mutex_lock(&manager->lock);
    manager->connections[manager->size] = new_connection;
    manager->size++;
    pthread_mutex_unlock(&manager->lock);
    return 0; // Successful addition
}

// Function to get the MD5 hash of a given string
