    // Implement MD5 hashing using a standard library cryptographic hash function
    return md5_hash;
}

// Function to destroy a NetworkSessionManager instance
void network_session_manager_destroy(NetworkSessionManager* manager) {
    if (!manager) return;
    for (size_t i = 0; i < manager->size; i++) {
        free(manager->connections[i]);
    }
    free(manager->connections);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

